INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Im Anfang schuf Gott den Himmel und die Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Und die Erde war wüst und leer, und es lag Finsternis auf der Tiefe, und der Geist Gottes schwebte über den Wassern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Und Gott sprach: Es werde Licht! Und es ward Licht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah, daß das Licht gut war; da schied Gott das Licht von der Finsternis;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'und Gott nannte das Licht Tag, und die Finsternis Nacht. Und es ward Abend, und es ward Morgen: der erste Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Und Gott sprach: Es soll eine Feste entstehen inmitten der Wasser, die bilde eine Scheidewand zwischen den Gewässern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Und Gott machte die Feste und schied das Wasser unter der Feste von dem Wasser über der Feste, daß es so ward.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte die Feste Himmel. Und es ward Abend, und es ward Morgen: der zweite Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Und Gott sprach: Es sammle sich das Wasser unter dem Himmel an einen Ort, daß man das Trockene sehe! Und es geschah also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene Land; aber die Sammlung der Wasser nannte er Meer. Und Gott sah, daß es gut war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Und Gott sprach: Es lasse die Erde grünes Gras sprossen und Gewächs, das Samen trägt, fruchtbare Bäume, deren jeder seine besondere Art Früchte bringt, in welcher ihr Same sei auf Erden! Und es geschah also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Und die Erde brachte hervor Gras und Gewächs, das Samen trägt nach seiner Art, und Bäume, welche Früchte bringen, in welchen ihr Same ist nach ihrer Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Und es ward Abend, und es ward Morgen: der dritte Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Und Gott sprach: Es seien Lichter an der Himmelsfeste, zur Unterscheidung von Tag und Nacht, die sollen zur Bestimmung der Zeiten und der Tage und Jahre dienen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'und zu Leuchtern an der Himmelsfeste, daß sie die Erde beleuchten! Und es geschah also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Und Gott machte die zwei großen Lichter, das große Licht zur Beherrschung des Tages und das kleinere Licht zur Beherrschung der Nacht; dazu die Sterne.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott setzte sie an die Himmelsfeste, damit sie die Erde beleuchteten');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'und den Tag und die Nacht beherrschten und Licht und Finsternis unterschieden. Und Gott sah, daß es gut war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Und es ward Abend, und es ward Morgen: der vierte Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Und Gott sprach: Das Wasser soll wimmeln von einer Fülle lebendiger Wesen, und es sollen Vögel fliegen über die Erde, an der Himmelsfeste dahin!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Und Gott schuf die großen Fische und alles, was da lebt und webt, wovon das Wasser wimmelt, nach ihren Gattungen, dazu allerlei Vögel nach ihren Gattungen. Und Gott sah, daß es gut war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und füllet das Wasser im Meere, und das Geflügel mehre sich auf Erden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Und es ward Abend, und es ward Morgen: der fünfte Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Und Gott sprach: Die Erde bringe hervor lebendige Wesen nach ihrer Art, Vieh, Gewürm und Tiere des Feldes nach ihrer Art! Und es geschah also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Und Gott machte die Tiere des Feldes nach ihrer Art und das Vieh nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Und Gott sprach: Wir wollen Menschen machen nach unserm Bild uns ähnlich; die sollen herrschen über die Fische im Meer und über die Vögel des Himmels und über das Vieh auf der ganzen Erde, auch über alles, was auf Erden kriecht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen ihm zum Bilde, zum Bilde Gottes schuf er ihn; männlich und weiblich schuf er sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Und Gott segnete sie und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und machet sie euch untertan und herrschet über die Fische im Meer und über die Vögel des Himmels und über alles Lebendige, was auf Erden kriecht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: Siehe, ich habe euch alles Gewächs auf Erden gegeben, das Samen trägt, auch alle Bäume, an welchen Früchte sind, die Samen tragen; sie sollen euch zur Nahrung dienen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'aber allen Tieren der Erde und allen Vögeln des Himmels und allem, was auf Erden kriecht, allem, was eine lebendige Seele hat, habe ich alles grüne Kraut zur Nahrung gegeben. Und es geschah also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah an alles, was er gemacht hatte, und siehe, es war sehr gut. Und es ward Abend, und es ward Morgen: der sechste Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Also waren Himmel und Erde vollendet samt ihrem ganzen Heer,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'so daß Gott am siebenten Tage sein Werk vollendet hatte, das er gemacht; und er ruhte am siebenten Tage von allen seinen Werken, die er gemacht hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Und Gott segnete den siebenten Tag und heiligte ihn, denn an demselbigen ruhte er von all seinem Werk, das Gott schuf, als er es machte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dies ist die Entstehung des Himmels und der Erde, zur Zeit, als Gott der HERR Himmel und Erde schuf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Es war aber noch kein Strauch des Feldes auf Erden, noch irgend ein grünes Kraut auf dem Felde gewachsen; denn Gott der HERR hatte noch nicht regnen lassen auf Erden, und es war kein Mensch vorhanden, um das Land zu bebauen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Aber ein Dunst stieg auf von der Erde und befeuchtete die ganze Erdoberfläche.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Da bildete Gott der HERR den Menschen, Staub von der Erde, und blies den Odem des Lebens in seine Nase, und also ward der Mensch eine lebendige Seele.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Und Gott der HERR pflanzte einen Garten in Eden gegen Morgen und setzte den Menschen darein, den er gemacht hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Und Gott der HERR ließ allerlei Bäume aus der Erde hervorsprossen, lieblich anzusehen und gut zur Nahrung, und den Baum des Lebens mitten im Garten und den Baum der Erkenntnis des Guten und Bösen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Und ein Strom ging aus von Eden, zu wässern den Garten; von dort aber teilte er sich und ward zu vier Hauptströmen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Der erste heißt Pison; das ist der, welcher das ganze Land Chavila umfließt, woselbst das Gold ist;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'und das Gold desselbigen Landes ist gut; dort kommt auch das Bedolach vor und der Edelstein Schoham.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Der zweite Strom heißt Gichon; das ist der, welcher das ganze Land Kusch umfließt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Der dritte Strom heißt Hidekel; das ist der, welcher östlich von Assur fließt. Der vierte Strom ist der Euphrat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Und Gott der HERR nahm den Menschen und setzte ihn in den Garten Eden, daß er ihn bauete und bewahrete.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und Gott der HERR gebot dem Menschen und sprach: Du sollst essen von allen Bäumen des Gartens;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'aber von dem Baum der Erkenntnis des Guten und des Bösen sollst du nicht essen; denn welchen Tages du davon issest, mußt du unbedingt sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und Gott der HERR sprach: Es ist nicht gut, daß der Mensch allein sei; ich will ihm eine Gehilfin machen, die ihm entspricht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Und Gott der HERR bildete aus Erde alle Tiere des Feldes und alle Vögel des Himmels und brachte sie zu dem Menschen, daß er sähe, wie er sie nennen würde, und damit jedes lebendige Wesen den Namen trage, den der Mensch ihm gäbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Da gab der Mensch einem jeglichen Vieh und Vogel und allen Tieren des Feldes Namen; aber für den Menschen fand sich keine Gehilfin, die ihm entsprochen hätte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da ließ Gott der HERR einen tiefen Schlaf auf den Menschen fallen; und während er schlief, nahm er eine seiner Rippen und verschloß deren Stelle mit Fleisch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Und Gott der HERR baute aus der Rippe, die er von dem Menschen genommen hatte, ein Weib und brachte sie zu ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da sprach der Mensch: Das ist nun einmal Bein von meinem Bein und Fleisch von meinem Fleisch! Die soll Männin heißen; denn sie ist dem Mann entnommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum wird der Mensch seinen Vater und seine Mutter verlassen und seinem Weibe anhangen, daß sie zu einem Fleische werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und sie waren beide nackt, der Mensch und sein Weib, und schämten sich nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Aber die Schlange war listiger als alle Tiere des Feldes, die Gott der HERR gemacht hatte; und sie sprach zum Weibe: Hat Gott wirklich gesagt, ihr dürft nicht essen von jedem Baum im Garten?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Da sprach das Weib zur Schlange: Wir essen von der Frucht der Bäume im Garten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'aber von der Frucht des Baumes mitten im Garten hat Gott gesagt: Esset nicht davon und rührt sie auch nicht an, damit ihr nicht sterbet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Da sprach die Schlange zum Weibe: Ihr werdet sicherlich nicht sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Sondern Gott weiß: welchen Tages ihr davon esset, werden eure Augen aufgetan und ihr werdet sein wie Gott und wissen, was gut und böse ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Als nun das Weib sah, daß von dem Baume gut zu essen wäre und daß er eine Lust für die Augen und ein wertvoller Baum wäre, weil er klug machte, da nahm sie von dessen Frucht und aß und gab zugleich auch ihrem Mann davon, und er aß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da wurden ihrer beider Augen aufgetan, und sie wurden gewahr, daß sie nackt waren; und sie banden Feigenblätter um und machten sich Schürzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Und sie hörten die Stimme Gottes, des HERRN, der im Garten wandelte beim Wehen des Abendwindes; und der Mensch und sein Weib versteckten sich vor dem Angesicht Gottes des HERRN hinter die Bäume des Gartens.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Da rief Gott der HERR dem Menschen und sprach: Wo bist du?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Er sprach: Ich hörte deine Stimme im Garten und fürchtete mich; denn ich bin nackt, darum verbarg ich mich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Da sprach er: Wer hat dir gesagt, daß du nackt bist? Hast du etwa von dem Baum gegessen, davon ich dir gebot, du sollest nicht davon essen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Da sprach der Mensch: Das Weib, das du mir zugesellt hast, die gab mir von dem Baum, und ich aß!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sprach Gott der HERR zum Weibe: Warum hast du das getan? Das Weib antwortete: Die Schlange verführte mich, daß ich aß!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sprach Gott der HERR zur Schlange: Weil du solches getan hast, so seist du verflucht vor allem Vieh und vor allen Tieren des Feldes! Auf deinem Bauch sollst du kriechen und Erde essen dein Leben lang!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und ich will Feindschaft setzen zwischen dir und dem Weibe, zwischen deinem Samen und ihrem Samen; derselbe soll dir den Kopf zertreten, und du wirst ihn in die Ferse stechen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Und zum Weibe sprach er: Ich will dir viele Schmerzen durch häufige Empfängnis bereiten; mit Schmerzen sollst du Kinder gebären; und du sollst nach deinem Manne verlangen, er aber soll herrschen über dich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zu Adam sprach er: Dieweil du gehorcht hast der Stimme deines Weibes und von dem Baum gegessen, davon ich dir gebot und sprach: »Du sollst nicht davon essen«, verflucht sei der Erdboden um deinetwillen, mit Mühe sollst du dich davon nähren dein Leben lang;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Dornen und Disteln soll er dir tragen, und du sollst das Gewächs des Feldes essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiße deines Angesichtes sollst du dein Brot essen, bis daß du wieder zur Erde kehrst, von der du genommen bist; denn du bist Staub und kehrst wieder zum Staub zurück!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Und Adam nannte sein Weib Eva; denn sie wurde die Mutter aller Lebendigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und Gott der HERR machte Adam und seinem Weibe Pelzröcke und bekleidete sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Gott der HERR sprach: Siehe, der Mensch ist geworden wie unsereiner, insofern er weiß, was gut und böse ist; nun soll er nicht auch noch seine Hand ausstrecken und vom Baume des Lebens nehmen und essen und ewiglich leben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Deswegen schickte ihn Gott der HERR aus dem Garten Eden, damit er den Erdboden bearbeite, von dem er genommen war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Und er vertrieb den Menschen und ließ östlich vom Garten Eden die Cherubim lagern mit dem gezückten flammenden Schwert, zu bewahren den Weg zum Baume des Lebens.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Und Adam erkannte sein Weib Eva; sie aber empfing und gebar den Kain. Und sie sprach: Ich habe einen Mann bekommen mit der Hilfe des HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Und weiter gebar sie seinen Bruder Abel. Und Abel ward ein Schäfer, Kain aber ein Ackersmann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Es begab sich aber nach Verfluß von Jahren, daß Kain dem HERRN ein Opfer brachte von den Früchten der Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Und Abel, auch er brachte dar von den Erstgebornen seiner Schafe und von ihren Fettesten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Und der HERR sah an Abel und sein Opfer; aber Kain und sein Opfer sah er gar nicht an. Da ergrimmte Kain sehr und ließ den Kopf hängen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Da sprach der HERR zu Kain: Warum bist du so zornig und lässest den Kopf hängen? Ist\'s nicht also: Wenn du gut bist, so darfst du dein Haupt erheben?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Bist du aber nicht gut, so lauert die Sünde vor der Tür, und ihre Begierde ist auf dich gerichtet; du aber herrsche über sie!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Da redete Kain mit seinem Bruder Abel. Es begab sich aber, als sie auf dem Felde waren, da erhob sich Kain wider seinen Bruder Abel und schlug ihn tot.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sprach der HERR zu Kain: Wo ist dein Bruder Abel? Er sprach: Ich weiß es nicht! Soll ich meines Bruders Hüter sein?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Er aber sprach: Was hast du getan? Die Stimme des Blutes deines Bruders schreit zu mir von der Erde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun sollst du verbannt sein aus dem Land, das seinen Mund aufgetan hat, das Blut deines Bruders zu empfangen von deiner Hand!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du das Land bebaust, soll es dir fortan sein Vermögen nicht mehr geben; unstät und flüchtig sollst du sein auf Erden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Kain sprach zum HERRN: Meine Schuld ist zu groß zum Tragen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Siehe, du treibst mich heute aus dem Lande, und ich muß mich vor deinem Angesicht verbergen und unstät und flüchtig sein auf Erden. Und es wird geschehen, daß mich totschlägt, wer mich findet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Da sprach der HERR: Fürwahr, wer Kain totschlägt, zieht sich siebenfache Rache zu! Und der Herr gab dem Kain ein Zeichen, daß ihn niemand erschlüge, der ihn fände.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Und Kain ging aus von dem Angesicht des HERRN und wohnte im Lande Nod, östlich von Eden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain erkannte sein Weib; die empfing und gebar den Hanoch. Und da er eben eine Stadt baute, so nannte er sie nach seines Sohnes Namen Hanoch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Dem Hanoch aber ward Irad geboren, und Irad zeugte Mehujael; Mehujael zeugte Metusael, Metusael zeugte Lamech.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamech aber nahm sich zwei Weiber: die eine hieß Ada, die andere Zilla.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Und Ada gebar Jabal; derselbe wurde der Vater der Zeltbewohner und Herdenbesitzer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Und sein Bruder hieß Jubal; derselbe wurde der Vater aller Harfen und Flötenspieler.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Und Zilla, auch sie gebar den Tubal-Kain, den Meister in allerlei Erz und Eisenwerk. Und die Schwester Tubal-Kains war Naama.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Und Lamech sprach zu seinen Weibern: »Ada und Zilla, hört meine Stimme, ihr Weiber Lamechs, vernehmt meinen Spruch! Einen Mann erschlug ich, weil er mich verwundet, einen Jüngling, weil er mich geschlagen hat;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'denn Kain soll siebenfach gerächt werden, Lamech aber siebenundsiebzigfach!«');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Und Adam erkannte sein Weib abermal; die gebar einen Sohn und nannte ihn Seth; denn Gott hat mir für Abel einen andern Samen gesetzt, weil Kain ihn umgebracht hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Und auch dem Seth ward ein Sohn geboren, den hieß er Enosch. Damals fing man an, den Namen des HERRN anzurufen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dies ist das Buch von Adams Geschlecht: Am Tage, da Gott den Menschen schuf, machte er ihn Gott ähnlich;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'männlich und weiblich schuf er sie und segnete sie und nannte ihren Namen Adam, am Tage, da er sie schuf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Und Adam war 130 Jahre alt, als er einen Sohn zeugte, ihm selbst gleich, nach seinem Bilde, und nannte ihn Seth.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Und nachdem er den Seth gezeugt, lebte Adam noch 800 Jahre und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'also daß Adams ganzes Alter 930 Jahre betrug, als er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Seth war 105 Jahre alt, als er den Enosch zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'und Seth, nachdem er den Enosch gezeugt, lebte 807 Jahre und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'also daß Seths ganzes Alter 912 Jahre betrug, als er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enosch war 90 Jahre alt, als er den Kenan zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'und Enosch, nachdem er den Kenan gezeugt, lebte 815 Jahre und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'also daß Enoschs ganzes Alter 905 Jahre betrug, als er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan war 70 Jahre alt, als er den Mahalaleel zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'und Kenan, nachdem er den Mahalaleel gezeugt, lebte 840 Jahre und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'also daß Kenans ganzes Alter 910 Jahre betrug, da er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel war 65 Jahre alt, als er den Jared zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'und Mahalaleel, nachdem er den Jared gezeugt, lebte 830 Jahre und hat Söhne und Töchter gezeugt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'also daß Mahalaleels ganzes Alter 895 Jahre betrug, als er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared war 162 Jahre alt, als er den Henoch zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'und Jared, nachdem er den Henoch gezeugt, lebte 800 Jahre und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'also daß Jareds ganzes Alter 962 Jahre betrug, da er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoch war 65 Jahre alt, als er den Methusalah zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'und Henoch, nachdem er den Methusalah gezeugt, wandelte er mit Gott 300 Jahre lang und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'also daß Henochs ganzes Alter 365 Jahre betrug.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Und Henoch wandelte mit Gott und war nicht mehr, weil Gott ihn zu sich genommen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Methusalah war 187 Jahre alt, als er den Lamech zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'und Methusalah, nachdem er den Lamech gezeugt, lebte 782 Jahre und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'also daß Methusalahs ganzes Alter 969 Jahre betrug, da er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamech war 182 Jahre alt, als er einen Sohn zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'den nannte er Noah, indem er sprach: Der wird uns trösten ob unserer Hände Arbeit und Mühe, die herrührt von dem Erdboden, den der HERR verflucht hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Und Lamech, nachdem er den Noah gezeugt, lebte 590 Jahre lang und zeugte Söhne und Töchter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'also daß Lamechs ganzes Alter 772 Jahre betrug, da er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Und Noah war 500 Jahre alt, da er den Sem, Ham und Japhet zeugte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Als sich aber die Menschen zu mehren begannen auf Erden und ihnen Töchter geboren wurden,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'sahen die Söhne Gottes, daß die Töchter der Menschen schön waren und nahmen sich von allen diejenigen zu Weibern, welche ihnen gefielen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sprach der HERR: Mein Geist soll den Menschen nicht ewig darum strafen, daß auch er Fleisch ist, sondern seine Tage sollen hundertundzwanzig Jahre betragen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Die Riesen waren auf Erden in jenen Tagen, und zwar daraufhin, daß die Söhne Gottes zu den Töchtern der Menschen kamen und diese ihnen gebaren. Das sind die Helden, die von alters her berühmt gewesen sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Als aber der HERR sah, daß des Menschen Bosheit sehr groß war auf Erden und alles Gebilde der Gedanken seines Herzens nur böse allezeit,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'da reute es den HERRN, daß er den Menschen gemacht hatte auf Erden, und es bekümmerte ihn in seinem Herzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Und der HERR sprach: Ich will den Menschen, den ich erschaffen habe, vom Erdboden vertilgen, vom Menschen an bis auf das Vieh und bis auf das Gewürm und bis auf die Vögel des Himmels; denn es reut mich, daß ich sie gemacht habe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noah aber fand Gnade vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist die Geschichte Noahs: Noah, ein gerechter Mann, war untadelig unter seinen Zeitgenossen; mit Gott wandelte Noah.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und Noah hatte drei Söhne gezeugt: Sem, Ham und Japhet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Aber die Erde war verderbt vor Gott und mit Frevel erfüllt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Und Gott sah die Erde, und siehe, sie war verderbt; denn alles Fleisch hatte seinen Weg auf Erden verderbt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Da sprach Gott zu Noah: Alles Fleisches Ende ist vor mich gekommen; denn die Erde ist durch sie mit Frevel erfüllt, und siehe, ich will sie samt der Erde vertilgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Mache dir eine Arche von Tannenholz; in Räume sollst du die Arche teilen und sie innen und außen mit Pech verpichen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und du sollst sie also machen: Dreihundert Ellen lang, fünfzig Ellen breit, dreißig Ellen hoch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Ein Fenster sollst du der Arche machen; bis zu einer Elle unterhalb des Daches darf es reichen; aber die Tür der Arche sollst du an ihre Seite setzen. Du sollst ihr ein unterstes, mittleres und oberstes Stockwerk machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Denn siehe, ich will eine Wasserflut über die Erde bringen, um alles Fleisch, das lebendigen Odem in sich hat, unter dem ganzen Himmel zu vertilgen; alles, was auf Erden ist, soll untergehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Aber mit dir will ich meinen Bund aufrichten, und du sollst in die Arche gehen, du und deine Söhne und dein Weib und deiner Söhne Weiber mit dir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und von allem, was da lebt, von allem Fleisch, sollst du je zwei in die Arche führen, daß sie mit dir am Leben bleiben, und zwar sollen es ein Männchen und ein Weibchen sein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'aller Art Vögel und aller Art Vieh und von allem, was auf Erden kriecht, sollen je zwei von jeder Art zu dir kommen, damit sie am Leben bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Du aber nimm dir von allerlei Speise, die man zu essen pflegt, und sammle sie bei dir an, daß sie dir und ihnen zur Nahrung diene!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noah tat es; er machte alles genau so, wie ihm Gott befahl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Und der HERR sprach zu Noah: Geh in die Arche, du und dein ganzes Haus! Denn dich habe ich gerecht ersehen unter diesem Geschlecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Nimm von allem reinen Vieh zu dir je sieben und sieben, das Männchen und sein Weibchen; von dem unreinen Vieh aber je ein Paar, das Männchen und sein Weibchen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'auch von den Vögeln des Himmels je sieben und sieben, Männchen und Weibchen, um auf dem ganzen Erdboden Samen am Leben zu erhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Denn es sind nur noch sieben Tage, so will ich auf Erden regnen lassen vierzig Tage lang und alles Bestehende von dem Erdboden vertilgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Und Noah machte alles, wie ihm der HERR gebot.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Und Noah war sechshundert Jahre alt, da die Wasser der Sündflut auf die Erde kamen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Er ging aber samt seinen Söhnen, seinem Weib und seiner Söhne Weibern in die Arche vor dem Gewässer der Sündflut.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von dem reinen Vieh und von dem Vieh, das nicht rein war, und von den Vögeln und von allem, was auf der Erde kriecht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'gingen paarweise in die Arche, Männchen und Weibchen, wie Gott dem Noah geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und es begab sich nach den sieben Tagen, daß die Wasser der Sündflut auf die Erde kamen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Im sechshundertsten Lebensjahre Noahs, am siebzehnten Tage des zweiten Monats, an dem Tage brachen alle Quellen der großen Tiefe auf, und die Fenster des Himmels öffneten sich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Und es regnete auf die Erde vierzig Tage und vierzig Nächte lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An ebendemselben Tage war Noah in die Arche gegangen mit Sem, Ham und Japhet, seinen Söhnen, und seinem Weibe und den drei Weibern seiner Söhne;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'sie und alle Arten der Tiere und des Viehs und allerlei Kriechendes, was auf Erden kriecht, von jeglicher Art, auch aller Art Geflügel, Vögel und Federvieh;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'die kamen zu Noah in die Arche, je zwei und zwei, von allem Fleisch, das lebendigen Odem in sich hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Und die hineingingen, Männchen und Weibchen von allem Fleisch, kamen herbei, wie Gott ihm geboten hatte; und der HERR schloß hinter ihm zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Da sich aber die Sündflut vierzig Tage auf die Erde ergoß, wuchsen die Wasser und hoben die Arche, daß sie über der Erde schwebte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und die Wasser wurden so groß und nahmen so sehr zu, daß die Arche auf dem Wasserspiegel dahinfuhr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Ja, das Gewässer nahm so sehr überhand, daß alle hohen Berge unter dem ganzen Himmel bedeckt wurden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'fünfzehn Ellen höher stieg das Wasser, nachdem die Berge schon zugedeckt waren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da ging alles Fleisch zugrunde, das auf Erden sich bewegte, Vögel, Vieh und wilde Tiere und alles, was sich auf Erden regte, samt allen Menschen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'und es starb alles, was auf dem trockenen Lande einen lebendigen Odem in der Nase hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Er vertilgte alles Bestehende auf dem Erdboden, vom Menschen an bis auf das Vieh, bis auf das Kriechende und bis auf die Vögel des Himmels; es ward alles von der Erde vertilgt; nur Noah blieb übrig und was mit ihm in der Arche war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und das Wasser blieb hoch über der Erde, hundertundfünfzig Tage lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da gedachte Gott an Noah und an alle Tiere und an alles Vieh, das bei ihm in der Arche war; und Gott ließ einen Wind über die Erde wehen, daß die Wasser fielen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Und die Brunnen der Tiefe wurden verstopft samt den Fenstern des Himmels, und dem Regen vom Himmel ward gewehrt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Und die Wasser über der Erde nahmen mehr und mehr ab, so daß sie nach hundertundfünfzig Tagen sich vermindert hatten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Und die Arche ließ sich am siebzehnten Tage des siebenten Monats auf dem Gebirge Ararat nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Und das Gewässer nahm immerfort ab bis zum zehnten Monat; am ersten Tage des zehnten Monats konnte man die Spitzen der Berge sehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Und es geschah nach Verfluß von vierzig Tagen, daß Noah das Fenster öffnete an der Arche, das er gemacht hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Und er sandte den Raben aus; der flog hin und her, bis das Wasser auf Erden vertrocknet war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Darnach sandte er die Taube aus, daß er sähe, ob des Wassers auf Erden weniger geworden wäre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Aber die Taube fand keinen Ort, da ihr Fuß ruhen konnte. Da kehrte sie zu ihm zur Arche zurück; denn es war noch Wasser auf der ganzen Erdoberfläche. Da streckte er seine Hand aus und ergriff sie und nahm sie wieder zu sich in die Arche.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Und er wartete noch weitere sieben Tage; dann sandte er die Taube wieder von der Arche aus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Und die Taube kam zur Abendzeit wieder zu ihm und siehe, sie hatte ein frisches Ölblatt in ihrem Schnabel! Da merkte Noah, daß des Wassers auf Erden weniger geworden war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Und nachdem er noch weitere sieben Tage gewartet hatte, sandte er die Taube wieder aus; da kam sie nicht mehr zu ihm zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Im sechshundertundersten Jahre, am ersten Tage des ersten Monats, waren die Wasser auf Erden vertrocknet. Und Noah entfernte das Dach von der Arche und schaute, und siehe, der Erdboden war trocken!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Und im zweiten Monat, am siebenundzwanzigsten Tage des Monats, war die Erde ausgetrocknet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Da redete Gott zu Noah und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Geh aus der Arche, du und dein Weib und deine Söhne und deiner Söhne Weiber mit dir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Alle Tiere, die bei dir sind, von allem Fleisch: Vögel, Vieh und alles Kriechende, was auf Erden kriecht, sollen mit dir hinausgehen und sich regen auf Erden und sollen fruchtbar sein und sich mehren auf Erden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Also ging Noah hinaus samt seinen Söhnen und seinem Weib und seiner Söhne Weibern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Alle Tiere, alles, was kriecht und fliegt, alles, was sich auf Erden regt, nach seinen Gattungen, das verließ die Arche.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noah aber baute dem HERRN einen Altar und nahm von allerlei reinem Vieh und von allerlei reinem Geflügel und opferte Brandopfer auf dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Und der HERR roch den befriedigenden Geruch, und der HERR sprach zu seinem Herzen: Ich will fortan die Erde nicht mehr verfluchen um des Menschen willen, wiewohl das Dichten des menschlichen Herzens böse ist von seiner Jugend an; auch will ich fortan nicht mehr alles Lebendige schlagen, wie ich getan habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Solange die Erde steht, soll nicht aufhören Saat und Ernte, Frost und Hitze, Sommer und Winter, Tag und Nacht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Und Gott segnete Noah und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehret euch und erfüllet die Erde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Furcht und Schrecken vor euch soll kommen über alle Tiere der Erde und über alle Vögel des Himmels, über alles, was auf Erden kriecht, und über alle Fische im Meer; in eure Hände seien sie gegeben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles, was sich regt und lebt, soll euch zur Nahrung dienen; wie das grüne Kraut habe ich es euch alles gegeben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur esset das Fleisch nicht, während seine Seele, sein Blut, noch in ihm ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Für euer Blut aber, für eure Seelen, will ich Rechenschaft fordern, von der Hand aller Tiere will ich sie fordern und von des Menschen Hand, von seines Bruders Hand will ich des Menschen Seele fordern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer Menschenblut vergießt, des Blut soll auch durch Menschen vergossen werden; denn Gott hat den Menschen nach seinem Bild gemacht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ihr aber seid fruchtbar und mehret euch und reget euch auf Erden, daß euer viele werden darauf!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Und Gott sprach zu Noah und zu seinen Söhnen mit ihm:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Siehe, ich richte meinen Bund auf mit euch und mit euren Nachkommen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'auch mit allen lebendigen Wesen bei euch, mit Vögeln, Vieh und allen Tieren der Erde bei euch, mit allen, die aus der Arche gegangen sind, was für Tiere es seien auf Erden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'und zwar will ich meinen Bund mit euch dafür aufrichten, daß forthin nie mehr alles Fleisch von dem Wasser der Sündflut ausgerottet werden, und daß auch keine Sündflut mehr kommen soll, um die Erde zu verderben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: Dies ist das Zeichen des Bundes, welchen ich stifte zwischen mir und euch und allen lebendigen Wesen, die bei euch sind, auf ewige Zeiten:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Meinen Bogen setze ich in die Wolken, der soll ein Zeichen des Bundes sein zwischen mir und der Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Wenn es nun geschieht, daß ich Wolken über der Erde sammle, und der Bogen in den Wolken erscheint,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'dann will ich an meinen Bund gedenken, welcher zwischen mir und euch und allen lebendigen Wesen von allem Fleisch besteht, daß forthin die Wasser nicht mehr zur Sündflut werden sollen, die alles Fleisch verderbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Darum soll der Bogen in den Wolken sein, daß ich ihn ansehe und gedenke an den ewigen Bund zwischen Gott und allen lebendigen Wesen von allem Fleisch, das auf Erden ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott sprach zu Noah: Das ist das Zeichen des Bundes, welchen ich aufgerichtet habe zwischen mir und allem Fleisch, das auf Erden ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Die drei Söhne Noahs aber, welche die Arche verließen, waren Sem, Ham und Japhet. Ham ist der Vater Kanaans.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Von diesen drei Söhnen Noahs ward die ganze Erde bevölkert.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noah aber begann und legte als Landmann einen Weinberg an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Da er aber von dem Weine trank, ward er betrunken und entblößte sich in seiner Hütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Da nun Ham, Kanaans Vater, die Blöße seines Vaters sah, verriet er es seinen beiden Brüdern draußen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da nahmen Sem und Japhet das Kleid und legten es auf ihre Schultern und gingen rücklings und deckten ihres Vaters Blöße zu und wandten ihre Angesichter ab, daß sie ihres Vaters Blöße nicht sahen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Als nun Noah von dem Wein erwachte und erfuhr, was ihm sein jüngster Sohn getan,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'da sprach er: Verflucht sei Kanaan! Er sei ein Knecht der Knechte seiner Brüder!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Und weiter sprach er: Gepriesen sei der HERR, der Gott Sems, und Kanaan sei sein Knecht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Gott breite Japhet aus und lasse ihn wohnen in Sems Hütten, und Kanaan sei sein Knecht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Noah aber lebte nach der Sündflut noch 350 Jahre lang,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'also daß Noahs ganzes Alter 950 Jahre betrug, als er starb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Dies ist das Geschlechtsregister der Söhne Noahs: Sem, Ham und Japhet; und nach der Sündflut wurden ihnen Kinder geboren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Söhne Japhets waren: Gomer, Magog, Madai, Javan, Tubal, Mesech und Tiras.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Die Söhne Gomers aber: Aschkenas, Riphat und Togarma.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Und die Söhne Javans: Elischa, Tarsis, Kittim und Rodanim.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Sie haben sich auf die Inseln der Heiden verteilt, in ihre Länder, ein jedes nach seiner Sprache; in ihre Völkerschaften, ein jedes nach seiner Abstammung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Und dies sind die Söhne Hams: Kusch, Mizraim, Put und Kanaan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Und die Söhne Kuschs: Seba, Chavila, Sabta, Raema, Sabteka und Dedan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Auch zeugte Kusch den Nimrod; der fing an ein Gewaltiger zu sein auf Erden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Er war ein gewaltiger Jäger vor dem HERRN; daher sagt man: Ein gewaltiger Jäger vor dem HERRN wie Nimrod.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Und der Anfang seines Königreiches war Babel, Erek, Akkad und Kalne im Lande Sinear.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Land zog er nach Assur aus und baute Ninive, Rechobot-Ir und Kelach,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'dazu Resen, zwischen Ninive und Kelach; das ist die große Stadt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim aber zeugte die Luditer, Anamiter, Lehabiter und Naphtuchiter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'auch die Patrusiter und die Kasluchiter, von welchen die Philister und die Kaphtoriter ausgegangen sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan aber zeugte Zidon, seinen Erstgebornen und Het;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'auch die Jebusiter, Amoriter und Girgasiter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'die Heviter, Arkiter und Siniter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'die Arvaditer, Zemariter und die Chamatiter; und darnach breiteten sich die Geschlechter der Kanaaniter aus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Und der Kanaaniter Gebiet erstreckte sich von Zidon an bis dahin, wo man von Gerar nach Gaza kommt; desgleichen bis dahin, wo man von Sodom und Gomorra, Adama und Zeboim nach Lascha kommt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Das sind die Söhne Hams nach ihren Geschlechtern und Sprachen, in ihren Ländern und Völkerschaften.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Auch Sem wurden Kinder geboren, ihm, dem Vater aller Söhne Ebers, Japhets älterem Bruder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Sems Söhne waren Elam, Assur, Arpakschad, Lud und Aram.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Und Arams Söhne: Uz, Chul, Geter und Masch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpakschad aber zeugte den Schelach, und Schelach zeugte den Eber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Und dem Eber wurden zwei Söhne geboren; der eine hieß Peleg, weil in seinen Tagen das Land verteilt ward; sein Bruder aber hieß Joktan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Und Joktan zeugte Almodad, Schaleph, Chazarmavet, Jarach,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikla,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Scheba,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Chavila und Jobad; diese alle sind Söhne Joktans.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Und ihre Wohnsitze erstreckten sich von Mesa an, bis man gen Sephar kommt, zum östlichen Gebirge.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Das sind die Söhne Sems nach ihren Geschlechtern und Sprachen, in ihren Ländern und Völkerschaften.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Das sind die Geschlechter der Söhne Noahs nach ihrer Abstammung in ihren Völkern; und von ihnen haben sich nach der Sündflut die Völker auf der Erde verteilt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Es hatte aber die ganze Welt einerlei Sprache und einerlei Rede.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Da sie nun gen Osten zogen, fanden sie eine Ebene im Lande Sinear, und sie ließen sich daselbst nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Und sie sprachen zueinander: Wohlan, laßt uns Ziegel streichen und sie feuerfest brennen! Und sie brauchten Ziegel für Steine und Asphalt für Kalk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Und sie sprachen: Wohlan, laßt uns eine Stadt und einen Turm bauen, dessen Spitze bis an den Himmel reicht, daß wir uns einen Namen machen, damit wir ja nicht über die ganze Erde zerstreuet werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Da fuhr der HERR herab, daß er die Stadt und den Turm sähe, den die Menschenkinder bauten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Und der HERR sprach: Siehe, es ist nur ein einziges Volk, und sie sprechen alle nur eine Sprache, und dies ist der Anfang ihres Unternehmens! Nun wird es ihnen nicht unmöglich sein, alles auszuführen, was sie sich vorgenommen haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Wohlan, laßt uns hinabfahren und daselbst ihre Sprache verwirren, daß keiner des andern Sprache verstehe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Also zerstreute sie der HERR von dannen über die ganze Erde, daß sie aufhörten die Stadt zu bauen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Daher gab man ihr den Namen Babel, weil der HERR daselbst die Sprache der ganzen Welt verwirrte und sie von dannen über die ganze Erde zerstreute.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies ist das Geschlechtsregister Sems: Als Sem hundert Jahre alt war, zeugte er den Arpakschad, zwei Jahre nach der Flut;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'und nachdem Sem den Arpakschad gezeugt, lebte er noch fünfhundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arpakschad war fünfunddreißig Jahre alt, als er den Schelach zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'und nachdem Arpakschad den Schelach gezeugt hatte, lebte er noch 403 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Schelach war dreißig Jahre alt, da er den Eber zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'und nachdem Schelach den Eber gezeugt hatte, lebte er noch 403 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber war vierunddreißig Jahre alt, da er den Peleg zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'und nachdem Eber den Peleg gezeugt, lebte er noch 430 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg war dreißig Jahre alt, da er den Regu zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'und nachdem Peleg den Regu gezeugt, lebte er noch 207 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu war zweiunddreißig Jahre alt, da er den Serug zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'und nachdem Regu den Serug gezeugt, lebte er noch 207 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug war dreißig Jahre alt, da er den Nahor zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'und nachdem Serug den Nahor gezeugt, lebte er noch 200 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahor war neunundzwanzig Jahre alt, da er den Terach zeugte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'und nachdem Nahor den Terach gezeugt, lebte er noch 119 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Terach war siebzig Jahre alt, da er den Abram, Nahor und Haran zeugte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Und dies ist Terachs Geschlechtsregister: Terach zeugte den Abram, Nahor und Haran; Haran aber zeugte den Lot.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Und Haran starb vor seinem Vater Terach im Lande seiner Geburt zu Ur in Chaldäa.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram aber und Nahor nahmen Weiber; Abrams Weib hieß Sarai, Nahors Weib hieß Milka, eine Tochter Harans, des Vaters der Milka und der Jisla.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sarai aber war unfruchtbar; sie hatte kein Kind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Und Terach nahm seinen Sohn Abram, dazu den Lot, Harans Sohn, seinen Enkel, auch Sarai, seine Schwiegertochter, das Weib seines Sohnes Abram, und sie zogen miteinander aus von Ur in Chaldäa, um ins Land Kanaan zu gehen. Als sie aber nach Haran kamen, blieben sie daselbst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Und Terach ward 205 Jahre alt und starb in Haran.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Und der HERR sprach zu Abram: Geh aus von deinem Land und von deiner Verwandtschaft und von deines Vaters Hause in das Land, das ich dir zeigen will!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'So will ich dich zu einem großen Volke machen und dich segnen und dir einen großen Namen machen, und du sollst ein Segen sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Ich will segnen, die dich segnen, und verfluchen, die dir fluchen; und durch dich sollen alle Geschlechter auf Erden gesegnet werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Da ging Abram, wie der HERR zu ihm gesagt hatte, und Lot ging mit ihm; Abram aber war fünfundsiebzig Jahre alt, da er von Haran auszog.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Und Abram nahm sein Weib Sarai und Lot, seines Bruders Sohn, samt aller ihrer Habe, die sie erworben, und den Seelen, die sie in Haran gewonnen hatten; und sie zogen aus, um ins Land Kanaan zu gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Und als sie ins Land Kanaan kamen, durchzog Abram das Land bis zur Ortschaft Sichem, bis zur Eiche Mores; und damals waren die Kanaaniter im Lande.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da erschien der HERR dem Abram und sprach: Deinem Samen will ich dies Land geben! Und er baute daselbst einen Altar dem HERRN, der ihm erschienen war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Von da rückte er weiter vor aufs Gebirge, östlich von Bethel, und schlug sein Zelt also auf, daß er Bethel im Westen und Ai im Osten hatte; und er baute daselbst dem HERRN einen Altar und rief den Namen des HERRN an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Darnach brach Abram auf und zog immer weiter nach Süden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Da aber Hungersnot im Lande herrschte, reiste Abram nach Ägypten hinab, um sich daselbst aufzuhalten; denn die Hungersnot lastete auf dem Land.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Und als er sich Ägypten näherte, sprach er zu seinem Weib Sarai: Siehe doch, ich weiß, daß du ein Weib bist von schöner Gestalt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Wenn dich nun die Ägypter sehen, so werden sie sagen: Das ist sein Weib! Und sie werden mich töten und dich leben lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'So sage doch, du seiest meine Schwester, daß es mir um deinetwillen wohl gehe, und meine Seele um deinetwillen am Leben bleibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Als nun Abram nach Ägypten kam, sahen die Ägypter das Weib, daß sie sehr schön war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Und als die Fürsten des Pharao sie sahen, priesen sie dieselbe dem Pharao an. Da ward das Weib in Pharaos Haus gebracht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Und es ging Abram gut um ihretwillen; und er bekam Schafe, Rinder und Esel, Knechte und Mägde, Eselinnen und Kamele.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Aber der HERR schlug den Pharao und sein Haus mit großen Plagen um Sarais, des Weibes Abrams, willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da rief der Pharao den Abram und sprach: Was hast du mir da angerichtet! Warum hast du mir nicht angezeigt, daß sie dein Weib ist?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum hast du gesagt, sie sei deine Schwester, so daß ich sie mir zum Weibe nehmen wollte? Und nun siehe, da ist dein Weib; nimm sie und geh!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und der Pharao bot seinethalben Mannschaft auf, damit sie ihm und seinem Weib und allem, was er hatte, das Geleite gäben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Und Abram zog mit seinem Weib und mit allem, was er hatte, auch mit Lot, von Ägypten hinauf in das südliche Kanaan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Und Abram war sehr reich an Vieh, Silber und Gold.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und er kam auf seinen Nomadenzügen von Süden her bis nach Bethel, bis zu dem Ort, da sein Zelt zuerst gestanden hatte, zwischen Bethel und Ai,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'an die Stätte des Altars, welchen er in der ersten Zeit gemacht hatte; und Abram rief daselbst den Namen des HERRN an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Aber auch Lot, der mit Abram ging, hatte Schafe, Rinder und Zelte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Und das Land mochte es nicht ertragen, daß sie beieinander wohnten; denn ihre Habe war groß, und sie konnten nicht beieinander bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Und es entstand Streit zwischen den Hirten über Abrams Vieh und den Hirten über Lots Vieh; auch wohnten zu der Zeit die Kanaaniter und Pheresiter im Lande.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sprach Abram zu Lot: Es soll doch nicht Zank sein zwischen mir und dir, zwischen meinen Hirten und deinen Hirten! Denn wir sind Brüder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Steht dir nicht das ganze Land offen? Trenne dich von mir! Willst du zur Linken, so gehe ich zur Rechten; und willst du zur Rechten, so gehe ich zur Linken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da hob Lot seine Augen auf und besah die ganze Jordanaue; denn sie war allenthalben bewässert, wie ein Garten des HERRN, wie Ägyptenland, bis nach Zoar hinab, ehe der HERR Sodom und Gomorra verderbte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Darum erwählte sich Lot die ganze Jordanaue und zog gegen Osten. Also trennte sich ein Bruder von dem andern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram wohnte im Lande Kanaan und Lot in den Städten der Aue und zeltete bis nach Sodom hin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Aber die Leute zu Sodom waren schlecht und sündigten sehr wider den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Der HERR aber sprach zu Abram, nachdem sich Lot von ihm getrennt hatte: Hebe doch deine Augen auf und schaue von dem Orte, da du wohnst, nach Norden, Süden, Osten und Westen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Denn das ganze Land, das du siehst, will ich dir und deinem Samen geben auf ewig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Und ich will deinen Samen machen wie den Staub auf Erden; wenn ein Mensch den Staub auf Erden zählen kann, so soll man auch deinen Samen zählen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Mache dich auf, durchziehe das Land seiner Länge und Breite nach! Denn dir will ich es geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Da brach Abram auf, kam und wohnte bei den Eichen Mamres zu Hebron und baute daselbst dem HERRN einen Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Und es begab sich zur Zeit des Königs Amraphel von Sinear, Ariochs, des Königs von Ellasar, Kedor-Laomers, des Königs von Elam, und Tideals, des Königs der Gojim,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'daß sie kriegeten mit Bera, dem König von Sodom, und mit Birsa, dem König von Gomorra, und mit Sinab, dem König von Adama, und mit Semeber, dem König von Zeboim, und mit dem König von Bela, das ist Zoar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Diese vereinigten sich im Tal Siddim, wo jetzt das Salzmeer ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Sie waren zwölf Jahre lang Kedor-Laomer untertan gewesen, aber im dreizehnten Jahre fielen sie von ihm ab.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Darum kamen Kedor-Laomer und die Könige, die es mit ihm hielten, im vierzehnten Jahre und schlugen die Rephaiter zu Astarot-Karnaim, und die Susiter zu Ham und die Emiter in der Ebene Kirjataim;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'auch die Horiter auf ihrem Gebirge Seir, bis nach El-Paran, welches an der Wüste liegt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Darnach kehrten sie um und kamen zum Brunnen Mischpat, das ist Kadesch, und schlugen das ganze Land der Amalekiter, dazu die Amoriter, die zu Hazezon-Tamar wohnten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Da zogen aus der König von Sodom, der König von Gomorra, der König von Adama, der König von Zeboim und der König von Bela, die Zoar heißt, und rüsteten sich');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'zu streiten im Tal Siddim mit Kedor-Laomer, dem Könige von Elam, und mit Tideal, dem Könige der Gojim, und mit Amraphel, dem König von Sinear, und mit Arioch, dem Könige von Ellasar; vier Könige gegen fünf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Und das Tal Siddim hatte viele Asphaltgruben. Aber die Könige von Sodom und Gomorra flohen und fielen daselbst, und was übrigblieb, floh ins Gebirge.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Und jene nahmen alle Habe zu Sodom und Gomorra und alle ihre Nahrung, und machten sich davon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Sie nahmen auch mit sich Lot, Abrams Bruder, und seine Habe (denn er wohnte zu Sodom) und gingen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Es kam aber ein Entronnener und sagte es Abram, dem Ebräer, der bei den Eichen Mamres, des Amoriters, wohnte, welcher ein Bruder war von Eschkol und Aner; diese waren Abrams Bundesgenossen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Als nun Abram hörte, daß sein Bruderssohn gefangen sei, bewaffnete er seine erprobten Knechte, dreihundertundachtzehn, die in seinem Hause geboren waren, und jagte jenen nach bis gen Dan,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'verteilte sich und überfiel sie heimlich bei Nacht mit seinen Knechten und schlug sie und verfolgte sie bis gen Hoba, das zur Linken von Damaskus liegt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Und er brachte alle Habe wieder; auch seinen Bruderssohn Lot und dessen Habe, die Weiber und das Volk brachte er wieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Als aber Abram von der Schlacht gegen Kedor-Laomer und die Könige, die mit ihm waren, zurückkehrte, ging ihm der König von Sodom entgegen in das Tal Schaveh, welches Königstal genannt wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Aber Melchisedek, der König von Salem, brachte Brot und Wein herbei. Und er war ein Priester Gottes, des Allerhöchsten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und er segnete ihn und sprach: Gesegnet sei Abram vom allerhöchsten Gott, dem Besitzer des Himmels und der Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Und gelobt sei Gott, der Allerhöchste, der deine Feinde in deine Hand geliefert hat! Und Abram gab ihm den Zehnten von allem.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Da sprach der König von Sodom zu Abram: Gib mir die Seelen, die Habe behalte für dich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram sprach zum König von Sodom: Ich hebe meine Hand auf zu dem HERRN, dem allerhöchsten Gott, dem Besitzer des Himmels und der Erde,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'daß ich von allem, was dein ist, nicht einen Faden noch Schuhriemen nehmen will, daß du nicht sagest: »Ich habe Abram reich gemacht«;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'ausgenommen, was die Jünglinge gegessen haben, und den Teil der Männer Aner, Eschkol und Mamre, die mit mir gezogen sind; sie sollen ihren Anteil erhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nach diesen Geschichten begab es sich, daß des HERRN Wort an Abram in einem Gesicht also erging: Fürchte dich nicht, Abram, ich bin dein Schild; dein Lohn ist sehr groß!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram aber sprach: O Herr, HERR, was willst du mir geben, da ich doch kinderlos dahingehe, Erbe meines Hauses aber dieser Elieser von Damaskus ist?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach weiter: Siehe, du hast mir keinen Samen gegeben, und siehe, ein Knecht, der in meinem Hause geboren ist, soll mein Erbe sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Aber des HERRN Wort geschah zu ihm: Dieser soll nicht dein Erbe sein, sondern der von dir selbst kommen wird, der soll dein Erbe sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und er führte ihn hinaus und sprach: Siehe doch gen Himmel und zähle die Sterne, wenn du sie zählen kannst! Und er sprach zu ihm: Also soll dein Same werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Und Abram glaubte dem HERRN, und das rechnete er ihm zur Gerechtigkeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Und er sprach zu ihm: Ich bin der HERR, der ich dich von Ur in Chaldäa ausgeführt habe, daß ich dir dieses Land erblich zu besitzen gebe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Abram aber sprach: Herr, HERR, wobei soll ich merken, daß ich es erblich besitzen werde?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Und er sprach zu ihm: Bringe mir eine dreijährige Kuh und eine dreijährige Ziege und einen dreijährigen Widder und eine Turteltaube und eine junge Taube.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Und er brachte solches alles und zerteilte es mitten voneinander, und legte einen Teil dem andern gegenüber. Aber die Vögel zerteilte er nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Und es fielen Raubvögel über die Opfer her; aber Abram verscheuchte sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Da nun die Sonne anfing sich zu neigen, fiel ein tiefer Schlaf auf Abram, und siehe, Schrecken und große Finsternis überfielen ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Da ward zu Abram gesagt: Du sollst für gewiß wissen, daß dein Same fremd sein wird in einem Lande, das nicht ihm gehört; und daselbst wird man sie zu dienen zwingen und demütigen vierhundert Jahre lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Aber auch das Volk, dem sie dienen müssen, will ich richten; darnach sollen sie mit großer Habe ausziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Und du sollst in Frieden zu deinen Vätern hinfahren und in gutem Alter begraben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Sie aber sollen im vierten Geschlechte wieder hierherkommen; denn das Maß der Sünden der Amoriter ist noch nicht voll.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Als nun die Sonne untergegangen und es finster geworden war, siehe, da rauchte ein Ofen, und eine Feuerfackel fuhr zwischen den Stücken hin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An dem Tage machte der HERR einen Bund mit Abram und sprach: Deinem Samen habe ich dieses Land gegeben, vom Fluß Ägyptens bis an den großen Strom, den Euphrat:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'die Keniter, die Kenisiter, die Kadmoniter,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'die Hetiter, die Pheresiter, die Rephaiter,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'die Amoriter, die Kanaaniter, die Girgasiter und die Jebusiter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai aber, Abrams Weib, gebar ihm nicht; aber sie hatte eine ägyptische Magd, die hieß Hagar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Und Sarai sprach zu Abram: Siehe doch, der HERR hat mich verschlossen, daß ich nicht gebären kann. Gehe doch zu meiner Magd, ob ich mich vielleicht aus ihr erbauen kann! Abram gehorchte Sarais Stimme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Da nahm Sarai, Abrams Weib, ihre ägyptische Magd Hagar, nachdem Abram zehn Jahre lang im Lande Kanaan gewohnt hatte, und gab sie Abram, ihrem Manne, zum Weibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und als er zu Hagar kam, empfing sie. Da sie nun sah, daß sie empfangen hatte, ward ihre Herrin verächtlich in ihren Augen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Da sprach Sarai zu Abram: Das Unrecht, das mir zugefügt wird, treffe dich! Ich habe dir meine Magd an den Busen gelegt. Nun sie aber sieht, daß sie guter Hoffnung ist, muß ich in ihren Augen verachtet sein. Der HERR sei Richter zwischen mir und dir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram aber sprach zu Sarai: Siehe, deine Magd ist in deiner Gewalt, tue mit ihr, wie dir gefällt! Da nun Sarai sie demütigte, floh sie von ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Aber der Engel des HERRN fand sie bei einem Wasserbrunnen in der Wüste, beim Brunnen am Wege Schur.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Er sprach zu ihr: Hagar, Sarais Magd, wo kommst du her, und wo willst du hin? Sie sprach: Ich bin von meiner Herrin Sarai geflohen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Und der Engel des HERRN sprach zu ihr: Kehre wieder zu deiner Herrin zurück, und demütige dich unter ihre Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Und der Engel des HERRN sprach zu ihr: Siehe, ich will deinen Samen also mehren, daß er vor großer Menge unzählbar sein soll.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Weiter sprach der Engel des HERRN zu ihr: Siehe, du hast empfangen und wirst einen Sohn gebären, den sollst du Ismael nennen, weil der HERR dein Jammern erhört hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Er wird ein wilder Mensch sein, seine Hand wider jedermann und jedermanns Hand wider ihn; und er wird gegenüber von allen seinen Brüdern wohnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Und sie nannte den Namen des HERRN, der mit ihr redete: Du bist »der Gott, der mich sieht«! Denn sie sprach: Habe ich hier nicht den gesehen, der mich gesehen hat?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Darum nannte sie den Brunnen einen »Brunnen des Lebendigen, der mich sieht«. Siehe, er ist zwischen Kadesch und Bared.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar Abram einen Sohn; und Abram nannte seinen Sohn, den ihm Hagar gebar, Ismael.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Und Abram war sechsundachtzig Jahre alt, als Hagar ihm den Ismael gebar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Als nun Abram neunundneunzig Jahre alt war, erschien ihm der HERR und sprach zu ihm: Ich bin der allmächtige Gott. Wandle vor mir und sei tadellos!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Und ich will meinen Bund stiften zwischen mir und dir und will dich über alle Maßen mehren!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da fiel Abram auf sein Angesicht. Und Gott redete weiter mit ihm und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Siehe, ich bin der, welcher im Bunde mit dir steht; und du sollst ein Vater vieler Völker werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Darum sollst du nicht mehr Abram heißen, sondern Abraham soll dein Name sein; denn ich habe dich zu einem Vater vieler Völker gemacht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Und ich will dich sehr, sehr fruchtbar machen und will dich zu Völkern machen, auch Könige sollen von dir herkommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und ich will meinen Bund aufrichten zwischen mir und dir und deinem Samen nach dir von Geschlecht zu Geschlecht, daß es ein ewiger Bund sei; also, daß ich dein Gott sei und deines Samens nach dir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und ich will dir und deinem Samen nach dir das Land geben, darin du ein Fremdling bist, nämlich das ganze Land Kanaan, zur ewigen Besitzung, und ich will ihr Gott sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach weiter zu Abraham: So bewahre nun meinen Bund, du und dein Same nach dir, von Geschlecht zu Geschlecht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Das ist aber mein Bund, den ihr bewahren sollt, zwischen mir und euch und deinem Samen nach dir: Alles, was männlich ist unter euch, soll beschnitten werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Ihr sollt aber die Vorhaut eures Fleisches beschneiden. Das soll ein Zeichen des Bundes sein zwischen mir und euch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Jedes Knäblein von euren Geschlechtern, wenn es acht Tage alt ist, sollt ihr beschneiden, sei es im Haus geboren oder um Geld erkauft von irgend einem Ausländer, der nicht deines Samens ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Was in deinem Hause geboren oder um Geld erkauft wird, soll beschnitten werden. Also soll mein Bund an eurem Fleische sein, ein ewiger Bund.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Und wenn ein Knäblein an der Vorhaut seines Fleisches nicht beschnitten wird, dessen Seele soll aus seinem Volke ausgerottet werden, weil es meinen Bund gebrochen hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und Gott sprach abermal zu Abraham: Du sollst dein Weib Sarai nicht mehr Sarai nennen, sondern Sarah soll ihr Name sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Denn ich will sie segnen und will dir auch von ihr einen Sohn geben. Ich will sie segnen, und sie soll zu Nationen werden, und Könige von Völkern sollen von ihr kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da fiel Abraham auf sein Angesicht und lachte und sprach in seinem Herzen: Soll mir Hundertjährigem ein Kind geboren werden, und Sarah, neunzig Jahre alt, gebären!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: Ach, daß Ismael vor dir leben sollte!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Da sprach Gott: Nein, sondern Sarah, dein Weib, soll dir einen Sohn gebären, den sollst du Isaak nennen; denn ich will mit ihm einen Bund aufrichten als einen ewigen Bund für seinen Samen nach ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Wegen Ismael habe ich dich auch erhört. Siehe, ich habe ihn reichlich gesegnet und will ihn fruchtbar machen und sehr mehren. Er wird zwölf Fürsten zeugen, und ich will ihn zum großen Volke machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Meinen Bund aber will ich mit Isaak aufrichten, den dir Sarah um diese bestimmte Zeit im andern Jahre gebären soll.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Und da er mit ihm ausgeredet hatte, fuhr Gott auf von Abraham.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Da nahm Abraham seinen Sohn Ismael und alle, die in seinem Hause geboren, und alle, die um sein Geld erkauft waren, alles, was männlich war unter seinen Hausgenossen, und beschnitt die Vorhaut ihres Fleisches an ebendemselben Tage, wie Gott ihm gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Und Abraham war neunundneunzig Jahre alt, als das Fleisch seiner Vorhaut beschnitten ward.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Ismael aber, sein Sohn, war dreizehn Jahre alt, als das Fleisch seiner Vorhaut beschnitten ward.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'An ebendemselben Tag ließen sich Abraham und sein Sohn Ismael beschneiden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'und alles, was männlich war in seinem Hause, daheim geboren und von Fremdlingen um Geld erkauft, ward mit ihm beschnitten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Und der HERR erschien ihm bei den Eichen Mamres, da er an der Tür seiner Hütte saß, als der Tag am heißesten war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Als er nämlich seine Augen aufhob und sich umsah, siehe, da standen drei Männer ihm gegenüber. Und als er sie sah, eilte er ihnen entgegen von der Türe seiner Hütte, bückte sich zur Erde nieder');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'und sprach: Mein Herr, habe ich Gnade vor deinen Augen gefunden, so gehe doch nicht an deinem Knechte vorüber!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man soll ein wenig Wasser bringen, daß ihr eure Füße waschet; und lagert euch unter dem Baum,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'so will ich einen Bissen Brot bringen, daß ihr euer Herz stärket; darnach mögt ihr weiterziehen, denn darum seid ihr bei eurem Knechte vorbeigekommen. Sie sprachen: Tue also, wie du gesagt hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Und Abraham eilte in die Hütte zu Sarah und sprach: Nimm eilends drei Maß Semmelmehl, knete sie und backe Kuchen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Er aber eilte zu den Rindern und holte ein zartes und gutes Kalb und gab es dem Knaben, der eilte und rüstete es zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Und er trug Butter und Milch auf und von dem Kalbe, das er gerüstet hatte, und setzte es ihnen vor. Und er stand bei ihnen unter dem Baum; und sie aßen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da sprachen sie zu ihm: Wo ist dein Weib Sarah? Er antwortete: Drinnen in der Hütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sprach er: Gewiß will ich um diese Zeit im künftigen Jahre wieder zu dir kommen, und siehe, dein Weib Sarah soll einen Sohn haben! Sarah aber horchte unter der Tür der Hütte, welche hinter ihm war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Und Abraham und Sarah waren alt und wohlbetagt, also daß es Sarah nicht mehr nach der Weiber Weise ging.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Darum lachte sie in ihrem Herzen und sprach: Nachdem ich verblüht bin, soll mir noch Wonne zuteil werden! Dazu ist mein Herr ein alter Mann!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Da sprach der HERR zu Abraham: Warum lacht Sarah und spricht: »Sollte ich wirklich noch gebären, so alt ich bin?«');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Sollte denn dem HERRN etwas zu wunderbar sein? Zur bestimmten Zeit will ich wieder zu dir kommen im künftigen Jahre, und Sarah soll einen Sohn haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Da leugnete Sarah und sprach: Ich habe nicht gelacht! denn sie fürchtete sich. Er aber sprach: Doch, du hast gelacht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Da brachen die Männer auf und wandten sich gen Sodom. Und Abraham ging mit ihnen, um sie zu begleiten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Da sprach der HERR: Sollte ich Abraham verbergen, was ich tun will,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'da Abraham gewiß ein großes und starkes Volk werden soll, und alle Völker auf Erden in ihm sollen gesegnet werden?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Denn ich habe ihn dafür erkoren, daß er seinen Kindern und seinem Hause nach ihm befehle, des HERRN Weg zu halten und zu tun, was recht und billig ist, damit der HERR auf Abraham bringe, was er ihm verheißen hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Und der HERR sprach: Das Geschrei über Sodom und Gomorra ist groß, und ihre Sünde ist sehr schwer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Darum will ich hinabfahren und sehen, ob sie wirklich ganz nach dem Geschrei, das vor mich gekommen ist, getan haben; wo aber nicht, daß ich es wisse.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Und die Männer wandten ihr Angesicht und gingen gen Sodom; aber Abraham blieb noch stehen vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Und Abraham trat näher und sprach: Willst du auch den Gerechten mit dem Gottlosen wegraffen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht möchten fünfzig Gerechte in der Stadt sein, willst du die wegraffen und den Ort nicht verschonen um fünfzig Gerechter willen, die darinnen wären?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Das sei ferne von dir, daß du eine solche Sache tuest und tötest den Gerechten mit dem Gottlosen, daß der Gerechte sei wie der Gottlose. Das sei ferne von dir! Der aller Welt Richter ist, sollte der nicht recht richten?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Der HERR sprach: Finde ich fünfzig Gerechte zu Sodom in der Stadt, so will ich um ihretwillen den ganzen Ort verschonen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Und Abraham antwortete und sprach: Ach siehe, ich habe mich unterwunden, mit meinem Herrn zu reden, obwohl ich nur Staub und Asche bin!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht möchten fünf weniger als fünfzig Gerechte darinnen sein, willst du denn die ganze Stadt verderben um der fünfe willen? Er sprach: Finde ich fünfundvierzig darinnen, so will ich sie nicht verderben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Und er fuhr weiter fort mit ihm zu reden und sprach: Man möchte vielleicht vierzig darin finden. Er aber sprach: Ich will ihnen nichts tun, um der vierzig willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Und Abraham sprach: Möge es meinen Herrn nicht erzürnen, wenn ich noch weiter rede! Man möchte vielleicht dreißig darin finden. Er aber sprach: Finde ich dreißig darinnen, so will ich ihnen nichts tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Und er sprach: Ach siehe, ich habe mich unterwunden, mit meinem Herrn zu reden: Man möchte vielleicht zwanzig darin finden. Er antwortete: Ich will sie nicht verderben, um der zwanzig willen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Und er sprach: Ach, zürne nicht, mein Herr, daß ich nur noch diesmal rede: Man möchte vielleicht zehn darin finden. Er aber sprach: Ich will sie nicht verderben, um der zehn willen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Und der HERR ging hin, da er mit Abraham ausgeredet hatte; Abraham aber kehrte wieder an seinen Ort zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Und die zwei Engel kamen am Abend nach Sodom. Lot aber saß zu Sodom unter dem Tor; und als er sie sah, stand er auf, ging ihnen entgegen und verneigte sich, das Angesicht zur Erde gewandt,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'und sprach: Siehe da, meine Herren! Kehrt ein in das Haus eures Knechtes und bleibet über Nacht und lasset euch die Füße waschen; so steht ihr am Morgen frühe auf und zieht euren Weg! Sie aber sprachen: Nein, sondern wir wollen auf der Gasse übernachten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Er aber nötigte sie ernstlich. Da kehrten sie bei ihm ein und kamen in sein Haus. Und er bereitete ihnen ein Mahl und machte ungesäuerte Kuchen; und sie aßen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Aber ehe sie sich legten, umringten die Männer der Stadt das Haus, die Männer von Sodom, jung und alt, das ganze Volk aus allen Enden,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'und riefen Lot und sprachen zu ihm: Wo sind die Männer, die diese Nacht zu dir gekommen sind? Bringe sie heraus zu uns, daß wir sie erkennen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Da ging Lot zu ihnen hinaus und schloß die Tür hinter sich zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Und sprach: Ach, meine Brüder, tut doch nicht so übel!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Siehe, ich habe zwei Töchter, die haben noch keinen Mann erkannt, die will ich zu euch hinausführen, daß ihr mit ihnen tut, was euch gut dünkt; nur diesen Männern tut nichts, weil sie doch unter den Schatten meines Daches gekommen sind!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Sie aber sprachen: Mach, daß du fortkommst! Darnach sprachen sie: Der ist der einzige Fremdling hier und will den Richter spielen! Nun wollen wir dir\'s noch ärger machen als ihnen! Und sie drangen hart auf den Mann, auf Lot ein und machten sich daran, die Türe aufzubrechen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Da streckten die Männer ihre Hände hinaus und zogen Lot zu sich hinein und schlossen die Türe zu');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'und schlugen die Männer vor der Haustüre mit Blindheit, beide klein und groß, daß sie müde wurden, die Tür zu suchen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Und die Männer sprachen zu Lot: Hast du noch jemand hier, einen Tochtermann oder Söhne oder Töchter? Wer dir in der Stadt zugehört, den führe hinaus von diesem Ort!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wir werden diesen Ort verderben, weil das Geschrei über sie groß ist vor dem HERRN; und der HERR hat uns gesandt, sie zu verderben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da ging Lot hinaus und redete mit seinen Tochtermännern, die seine Töchter nehmen sollten, und sprach: Machet euch auf, gehet aus von diesem Ort; denn der HERR wird diese Stadt verderben! Aber es kam seinen Tochtermännern vor, als scherze er.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Da nun die Morgenröte aufging, hießen die Engel Lot eilen und sprachen: Mache dich auf, nimm dein Weib und deine beiden Töchter, die vorhanden sind, damit du nicht in der Missetat dieser Stadt umkommest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Als er aber verzog, ergriffen die Männer ihn und sein Weib und seine beiden Töchter bei der Hand, weil der HERR ihn verschonen wollte, und führten ihn hinaus und ließen ihn draußen vor der Stadt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Und als sie dieselben hinausgeführt hatten, sprach er: Errette deine Seele und siehe nicht hinter dich; stehe auch nicht still in dieser ganzen Umgegend! Auf den Berg rette dich, daß du nicht weggerafft werdest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Aber Lot sprach zu ihnen: Ach nein, mein Herr!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Siehe doch, dein Knecht hat vor deinen Augen Gnade gefunden, und du hast mir große Barmherzigkeit erwiesen, daß du meine Seele am Leben erhieltest. Aber auf den Berg kann ich mich nicht retten; das Unglück könnte mich ereilen, daß ich stürbe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe, jene Stadt ist so nahe, daß ich dahin fliehen könnte; und sie ist klein. Ach, laß mich dahin fliehen! Ist sie nicht eine kleine Stadt? Nur daß meine Seele lebendig bleibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Da sprach er zu ihm: Siehe, ich habe dich auch in diesem Stück erhört, daß ich die Stadt nicht umkehre, von welcher du geredet hast.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Eile, rette dich daselbst hin; denn ich kann nichts tun, bis du hineingekommen bist! Daher wird die Stadt Zoar genannt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Und die Sonne war auf Erden aufgegangen, als Lot nach Zoar kam.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Da ließ der HERR Schwefel und Feuer regnen auf Sodom und Gomorra, vom HERRN, vom Himmel herab,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'und kehrte die Städte um und die ganze Umgebung und alle Einwohner der Städte und was auf dem Lande gewachsen war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Und sein Weib sah hinter sich und ward zur Salzsäule.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham aber machte sich am Morgen früh auf an den Ort, da er vor dem HERRN gestanden hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Und er wandte sein Angesicht gen Sodom und Gomorra und gegen das ganze Land jener Gegend und sah sich um, und siehe, ein Rauch ging auf von dem Lande, wie ein Rauch vom Kalkofen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Und als Gott die Städte in jener Ebene verderbte, da gedachte Gott an Abraham, und er führte Lot mitten aus dem Verderben, als er die Städte umkehrte, darinnen Lot gewohnt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Und Lot ging von Zoar hinauf und blieb mit seinen beiden Töchtern auf dem Berge; denn er fürchtete sich in Zoar zu bleiben; und er wohnte mit seinen Töchtern in einer Höhle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sprach die ältere zu der jüngeren: Unser Vater ist alt, und es ist kein Mann mehr auf Erden, der zu uns kommen möge nach aller Welt Weise.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'So komm, wir wollen unsern Vater mit Wein tränken und bei ihm liegen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Also tränkten sie ihren Vater mit Wein in derselben Nacht. Und die ältere ging und legte sich zu ihrem Vater, und er gewahrte es nicht, weder als sie sich legte, noch als sie aufstand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Am Morgen sprach die ältere zu der jüngern: Siehe, ich bin gestern bei meinem Vater gelegen; wir wollen ihn auch diese Nacht mit Wein tränken, daß du hingehest und dich zu ihm legest, daß wir Samen von unserm Vater erhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Also tränkten sie ihren Vater dieselbe Nacht mit Wein. Und die jüngere machte sich auf und legte sich zu ihm, und er merkte es nicht, weder als sie sich legte, noch als sie aufstand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Also wurden die beiden Töchter Lots schwanger von ihrem Vater.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die ältere gebar einen Sohn, den hieß sie Moab; der ward der Vater der Moabiter von heutzutage.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Und die jüngere gebar auch einen Sohn, den hieß sie Ben-Ammi; der ward der Vater der Kinder Ammon von heutzutage.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraham aber zog von dannen in den südlichen Landesteil und wohnte zwischen Kadesch und Schur und war ein Fremdling zu Gerar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Und Abraham sprach von seinem Weibe Sarah: Sie ist meine Schwester. Da ließ Abimelech, der König zu Gerar, Sarah holen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Aber Gott kam des Nachts im Traum zu Abimelech und sprach zu ihm: Siehe da, du bist des Todes um des Weibes willen, das du genommen hast; denn sie ist eines Mannes Eheweib!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech aber hatte sie noch nicht berührt und sprach: Herr, willst du denn auch ein gerechtes Volk umbringen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Hat er nicht zu mir gesagt: »Sie ist meine Schwester?« Und sie hat auch gesagt: »Er ist mein Bruder!« Habe ich doch das mit einfältigem Herzen und unschuldigen Händen getan!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Und Gott sprach zu ihm im Traum: Ich weiß, daß du solches mit einfältigem Herzen getan hast; darum habe ich dich auch behütet, daß du nicht wider mich sündigtest, und darum habe ich es dir nicht gestattet, daß du sie berührtest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'So gib nun dem Manne sein Weib wieder, denn er ist ein Prophet; und er soll für dich bitten, so wirst du am Leben bleiben; wenn du sie aber nicht zurückgibst, so wisse, daß du gewiß sterben mußt samt allem, was dein ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Da stand Abimelech am Morgen frühe auf und rief allen seinen Knechten und sagte ihnen dieses alles vor ihren Ohren; und die Leute fürchteten sich sehr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Und Abimelech rief Abraham und sprach zu ihm: Warum hast du uns das getan, und was habe ich an dir gesündigt, daß du eine so große Sünde auf mich und mein Reich bringen wolltest? Du hast nicht mit mir gehandelt, wie man handeln soll.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Und Abimelech fragte Abraham: In welcher Absicht hast du solches getan?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham sprach: Weil ich dachte: Es ist gar keine Gottesfurcht an diesem Ort, darum werden sie mich um meines Weibes willen erwürgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Auch ist sie wahrhaftig meine Schwester; denn sie ist meines Vaters Tochter, aber nicht meiner Mutter Tochter, und sie ist mein Weib geworden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Da mich aber Gott aus meines Vaters Haus führte, sprach ich zu ihr: Das mußt du mir zuliebe tun, daß du überall, wo wir hinkommen, von mir sagest: Er ist mein Bruder!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Schafe und Rinder, Knechte und Mägde und schenkte sie Abraham und gab ihm sein Weib Sarah zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Und Abimelech sprach: Siehe da, mein Land steht dir offen; wo es dir gefällt, da laß dich nieder!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Aber zu Sarah sprach er: Siehe da, ich gebe deinem Bruder tausend Silberlinge; siehe da, das soll dir eine Decke der Augen sein für alles, was mit dir vorgegangen ist, und damit du in jeder Weise gerechtfertigst seist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Abraham aber legte Fürbitte ein bei Gott. Da heilte Gott Abimelech und sein Weib und seine Mägde, daß sie gebaren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Denn der HERR hatte zuvor jeden Mutterleib im Hause Abimelechs fest verschlossen, um Sarahs, des Weibes Abrahams willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Und der HERR suchte Sarah heim, wie er verheißen hatte, und der HERR tat an Sarah, wie er geredet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Und Sarah empfing und gebar dem Abraham einen Sohn in seinem Alter, zur bestimmten Zeit, wie ihm Gott versprochen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham nannte seinen Sohn, der ihm geboren ward, den ihm Sarah gebar, Isaak.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Und Abraham beschnitt Isaak, seinen Sohn, da er acht Tage alt war, wie ihm Gott geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Hundert Jahre war Abraham alt, da ihm sein Sohn Isaak geboren ward.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Und Sarah sprach: Gott hat mir ein Lachen bereitet; wer es hören wird, der wird meiner lachen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sie sprach: Wer verkündigt das dem Abraham, daß Sarah Kinder säugt, daß ich ihm in seinem Alter einen Sohn geboren habe?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und das Kind wuchs und ward entwöhnt. Und Abraham machte ein großes Mahl des Tages, da Isaak entwöhnt ward.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Und Sarah sah, daß der Sohn der Hagar, der ägyptischen Magd, den sie dem Abraham geboren hatte, Mutwillen trieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Da sprach sie zu Abraham: Treibe diese Magd mit ihrem Sohne aus; denn der Sohn dieser Magd soll nicht erben mit meinem Sohn Isaak!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dieses Wort mißfiel Abraham sehr um seines Sohnes willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Aber Gott sprach zu Abraham: Es soll dir das nicht mißfallen! Höre auf alles, was Sarah dir sagt wegen des Knaben und deiner Magd; denn in Isaak soll dir ein Same berufen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Doch ich will auch den Sohn der Magd zum Volke machen, weil er deines Samens ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Da stand Abraham am Morgen frühe auf und nahm Brot und einen Schlauch voll Wasser, gab es Hagar und legte es auf ihre Schulter; er gab ihr auch den Knaben und schickte sie fort. Sie ging und irrte in der Wüste Beer-Seba umher.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Da nun das Wasser im Schlauch ausgegangen war, warf sie den Knaben unter einen Strauch,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'ging hin und setzte sich gegenüber, einen Bogenschuß weit entfernt; denn sie sprach: Ich kann nicht sehen des Knaben Sterben! Und sie saß ihm gegenüber, erhob ihre Stimme und weinte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Da erhörte Gott die Stimme des Knaben, und der Engel Gottes rief der Hagar vom Himmel her und sprach zu ihr: Was ist dir, Hagar? Fürchte dich nicht, denn Gott hat erhört die Stimme des Knaben, da, wo er liegt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Steh auf, nimm den Knaben und fasse ihn mit deiner Hand, denn ich will ihn zu einem großen Volke machen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott öffnete ihr die Augen, daß sie einen Wasserbrunnen sah. Da ging sie hin und füllte den Schlauch mit Wasser und tränkte den Knaben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben; der wuchs und wohnte in der Wüste und ward ein Bogenschütze.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Und er wohnte in der Wüste Paran, und seine Mutter nahm ihm ein Weib aus Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Zu derselben Zeit redete Abimelech und sein Feldhauptmann Pichol mit Abraham und sprach: Gott ist mit dir in allem, was du tust.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'So schwöre mir nun hier bei Gott, daß du weder an mir, noch an meinen Kindern, noch an meinen Kindeskindern treulos handeln, sondern die Freundschaft, die ich dir bewiesen habe, auch an mir beweisen willst und an dem Lande, darinnen du ein Fremdling bist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da sprach Abraham: Ich will schwören!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Und Abraham rechtete mit Abimelech um des Wasserbrunnens willen, den Abimelechs Knechte mit Gewalt genommen hatten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Da antwortete Abimelech: Ich weiß nichts davon; wer hat das getan? Du hast mir gar nichts angezeigt, und ich habe auch nichts davon gehört bis auf diesen Tag!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da nahm Abraham Schafe und Rinder und gab sie Abimelech, und sie machten beide einen Bund miteinander.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Und Abraham stellte sieben Lämmer besonders.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Da sprach Abimelech zu Abraham: Was sollen die sieben Lämmer hier, die du besonders gestellt hast?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Er antwortete: Du sollst sieben Lämmer von meiner Hand nehmen, damit sie mir zum Zeugnis seien, daß ich diesen Brunnen gegraben habe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Daher wird der Ort Beer-Seba genannt, weil sie beide daselbst einander geschworen haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Als sie aber den Bund zu Beer-Seba geschlossen, machten sich Abimelech und Pichol, sein Feldhauptmann, auf und zogen wieder in der Philister Land.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham aber pflanzte eine Tamariske zu Beer-Seba und rief daselbst den Namen des HERRN, des ewigen Gottes, an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Und Abraham hielt sich lange Zeit als Fremdling im Lande der Philister auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Nach diesen Geschichten versuchte Gott den Abraham und sprach zu ihm: Abraham! Und er antwortete: Siehe, hier bin ich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Und er sprach: Nimm doch deinen Sohn, deinen einzigen, den du lieb hast, Isaak, und gehe hin in das Land Morija und opfere ihn daselbst zum Brandopfer auf einem Berge, den ich dir nennen werde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Da stand Abraham am Morgen früh auf und sattelte seinen Esel, und nahm zwei Knechte und seinen Sohn Isaak mit sich und spaltete Holz zum Brandopfer, machte sich auf und ging hin an den Ort, davon ihm Gott gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage erhob Abraham seine Augen und sah den Ort von ferne.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Da sprach Abraham zu seinen Knechten: Bleibet ihr hier mit dem Esel, ich aber und der Knabe wollen dorthin gehen, und wenn wir angebetet haben, wollen wir wieder zu euch kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Und Abraham nahm das Holz zum Brandopfer und legte es auf seinen Sohn Isaak. Er aber nahm das Feuer und das Messer in seine Hand, und sie gingen beide miteinander.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da sprach Isaak zu seinem Vater Abraham: Mein Vater! Abraham antwortete: Siehe, hier bin ich, mein Sohn! Und er sprach: Siehe, hier ist Feuer und Holz; wo ist aber das Lämmlein zum Brandopfer?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Und Abraham antwortete: Mein Sohn, Gott wird sich ein Lämmlein zum Brandopfer ersehen! Und sie gingen beide miteinander.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Und als sie an den Ort kamen, den Gott ihm genannt hatte, baute Abraham daselbst einen Altar und legte das Holz ordentlich darauf, band seinen Sohn Isaak und legte ihn auf den Altar, oben auf das Holz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Und Abraham streckte seine Hand aus und faßte das Messer, seinen Sohn zu schlachten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm der Engel des HERRN vom Himmel und sprach: Abraham! Abraham! Und er antwortete: Siehe, hier bin ich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Er sprach: Lege deine Hand nicht an den Knaben und tue ihm nichts; denn nun weiß ich, daß du Gott fürchtest und hast deinen einzigen Sohn nicht verschont um meinetwillen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Da erhob Abraham seine Augen und sah hinter sich einen Widder mit den Hörnern in den Hecken verwickelt. Und Abraham ging hin und nahm den Widder und opferte ihn zum Brandopfer an Stelle seines Sohnes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham nannte den Ort: Der HERR wird dafür sorgen! So daß man noch heute sagt: Auf dem Berge wird der HERR dafür sorgen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Und der Engel des HERRN rief Abraham zum zweitenmal vom Himmel');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'und sprach: Ich habe bei mir selbst geschworen, spricht der HERR, weil du solches getan und deines einzigen Sohnes nicht verschont hast,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'will ich dich gewiß segnen und deinen Samen mächtig mehren, wie die Sterne am Himmel und wie den Sand am Rande des Meeres, und dein Same soll die Tore seiner Feinde besitzen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'und in deinem Samen sollen alle Völker auf Erden gesegnet werden, weil du meiner Stimme gehorcht hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Und Abraham kehrte wieder zu seinen Knechten zurück; und sie machten sich auf und zogen miteinander gen Beer-Seba, denn Abraham wohnte zu Beer-Seba.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Nach diesen Geschichten ward Abraham die Kunde gebracht: Siehe, Milka hat deinem Bruder Nahor auch Kinder geboren:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uz, den Erstgeborenen, und Bus, seinen Bruder, und Kemuel, den Vater des Aram,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'und Kesed und Chaso und Pildasch und Jidlaph und Bethuel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bethuel aber hatte die Rebekka gezeugt. Milka gebar diese acht dem Nahor, Abrahams Bruder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Und sein Kebsweib mit Namen Rehuma, gebar auch, nämlich Tebach, Gaham, Tachasch und Maacha.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sarah ward hundertsiebenundzwanzig Jahre alt; so lange lebte sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Und Sarah starb in Kirjat-Arba, das ist Hebron, im Lande Kanaan. Da ging Abraham hin, daß er um Sarah klagte und sie beweinte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Darnach stand Abraham auf von seiner Leiche und redete mit den Söhnen Hets und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Ich bin ein Fremdling und Beisaße bei euch, gebt mir ein Erbbegräbnis bei euch, daß ich meine Tote von meinem Angesicht entfernt begraben kann!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Da antworteten die Hetiter dem Abraham und sprachen zu ihm:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Höre uns, mein Herr, du bist ein Fürst Gottes mitten unter uns, begrabe deine Tote in dem besten unsrer Gräber. Niemand von uns wird dir sein Grab verweigern, daß du deine Tote darin begrabest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da stand Abraham auf und bückte sich vor dem Volke des Landes, vor den Hetitern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Und er redete mit ihnen und sprach: Ist es euer Wille, daß ich meine Tote von meinem Angesicht entfernt begrabe, so höret mich und bittet für mich Ephron, den Sohn Zohars,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'daß er mir die Höhle Machpelah gebe, die er am Ende seines Ackers hat; um den vollen Betrag soll er sie mir in eurer Mitte zum Begräbnis geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Und Ephron saß mitten unter den Hetitern. Da antwortete Ephron, der Hetiter, dem Abraham vor den Söhnen Hets, vor allen, die durch das Tor seiner Stadt aus und eingingen, und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nein, mein Herr, sondern höre mir zu: Ich schenke dir den Acker, und die Höhle darin schenke ich dir dazu, und schenke dir sie vor meinem Volke; begrabe deine Tote!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da bückte sich Abraham vor dem Volke des Landes');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'und redete mit Ephron, daß das Volk des Landes zuhörte, und sprach: Wohlan, wenn du geneigt bist, so höre mich: Nimm von mir das Geld, das ich dir für den Acker gebe, so will ich meine Tote daselbst begraben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron antwortete Abraham und sprach zu ihm:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mein Herr, höre mich: Das Feld ist vierhundert Schekel Silber wert; was ist aber das zwischen mir und dir? Begrabe nur deine Tote!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Als nun Abraham solches hörte, wog er Ephron das Geld dar, das er gesagt hatte, vor den Ohren der Hetiter, nämlich vierhundert Schekel Silber, das im Kauf gangbar und gültig war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Also ward Ephrons Acker bei Machpelah, der Mamre gegenüber liegt, der Acker und die Höhle, die darin ist, auch alle Bäume auf dem Acker und innert aller seiner Grenzen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abraham zum Eigentum bestätigt vor den Augen der Hetiter und aller, die zum Tor seiner Stadt eingingen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Darnach begrub Abraham die Sarah, sein Weib, in der Höhle des Ackers Machpelah, Mamre gegenüber, zu Hebron, im Lande Kanaan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Also ward der Acker und die Höhle darin dem Abraham von den Hetitern zum Erbbegräbnis bestätigt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Und Abraham war alt und wohlbetagt, und der HERR hatte Abraham in allem gesegnet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Und Abraham sprach zu dem ältesten Knechte seines Hauses, der aller seiner Güter Verwalter war: Lege doch deine Hand unter meine Hüfte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'daß ich dich schwören lasse bei dem HERRN, dem Gott des Himmels und der Erde, daß du meinem Sohne kein Weib nehmest von den Töchtern der Kanaaniter, unter welchen ich wohne,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sondern daß du in mein Vaterland und zu meiner Verwandtschaft ziehest und meinem Sohn Isaak ein Weib nehmest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Da sprach der Knecht zu ihm: Wie? wenn das Weib mir nicht in dieses Land folgen wollte, soll ich alsdann deinen Sohn wieder in das Land zurückbringen, daraus du gezogen bist?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sprach zu ihm: Da hüte dich wohl, meinen Sohn wieder dahin zu bringen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Der HERR, der Gott des Himmels, der mich von meines Vaters Hause und aus dem Lande meiner Geburt genommen und mit mir geredet und mir auch geschworen und gesagt hat: »Dieses Land will ich deinem Samen geben«, der wird seinen Engel vor dir her senden, daß du meinem Sohn von dort ein Weib nehmest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Wenn das Weib dir aber nicht folgen will, so bist du entbunden von dem Eid, den du mir geschworen hast; nur bring meinen Sohn nicht wieder dorthin!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da legte der Knecht seine Hand unter Abrahams, seines Herrn, Hüfte und schwur solches.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Und der Knecht nahm zehn Kamele von den Kamelen seines Herrn und allerlei Güter seines Herrn, und machte sich auf und zog nach Mesopotamien, zu der Stadt Nahors.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Da ließ er die Kamele draußen vor der Stadt sich lagern bei einem Wasserbrunnen am Abend, zur Zeit, da die Jungfrauen herauszugehen pflegten, um Wasser zu schöpfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Und er sprach: O HERR, du Gott meines Herrn Abraham, laß es mir doch heute gelingen und tue Barmherzigkeit an meinem Herrn Abraham!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Siehe, ich stehe hier bei dem Wasserbrunnen, und die Töchter der Leute dieser Stadt werden herauskommen, Wasser zu schöpfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Wenn nun eine Tochter kommt, zu der ich spreche: Neige doch deinen Krug, daß ich trinke, und sie spricht: Trinke, ich will deine Kamele auch tränken. So möge sie diejenige sein, die du deinem Diener Isaak bestimmt hast, und ich will daran erkennen, daß du an meinem Herrn Barmherzigkeit getan habest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Und ehe er ausgeredet hatte, siehe, da kam heraus Rebekka, die Tochter Bethuels, der ein Sohn der Milka, des Weibes Nahors, des Bruders Abrahams war; die trug einen Krug auf ihrer Achsel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Und sie war von Angesicht eine sehr schöne Tochter, eine Jungfrau, und kein Mann hatte sie erkannt; die stieg zum Brunnen hinab und füllte ihren Krug und stieg herauf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da lief der Knecht ihr entgegen und sprach: Laß mich doch ein wenig Wasser aus deinem Kruge trinken!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Und sie sprach: Trinke, mein Herr! Und sie ließ den Krug eilend auf ihre Hand hernieder und tränkte ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Und da sie ihn getränkt hatte, sprach sie: Ich will deinen Kamelen auch schöpfen, bis sie genug getrunken haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und sie eilte und leerte den Krug aus in die Tränke und lief abermal zum Brunnen, um zu schöpfen, und schöpfte allen seinen Kamelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Und der Mann verwunderte sich über sie, schwieg aber stille, bis er erkannt hatte, ob der HERR seine Reise habe gelingen lassen oder nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Als nun die Kamele alle getrunken hatten, nahm er einen goldenen Ring, einen halben Schekel schwer, und zwei Armbänder an ihre Hände, zehn Schekel Goldes schwer,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'und sprach: Sage mir doch, wessen Tochter bist du? Haben wir in deines Vaters Hause auch Platz zu herbergen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Sie sprach zu ihm: Ich bin Bethuels Tochter, des Sohnes der Milka, den sie dem Nahor geboren hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Und sie sagte weiter zu ihm: Es ist auch viel Stroh und Futter bei uns und Platz genug zum Herbergen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da neigte sich der Mann und betete an vor dem HERRN');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'und sprach: Gelobet sei der HERR, der Gott meines Herrn Abraham, der seine Gnade und Treue meinem Herrn nicht entzogen hat, denn der HERR hat mich den Weg zum Hause des Bruders meines Herrn geführt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Und die Tochter lief und sagte solches alles im Hause ihrer Mutter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Und Rebekka hatte einen Bruder, der hieß Laban. Und Laban lief geschwind zu dem Manne draußen bei dem Brunnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Und es geschah, als er den Ring und die Armbänder an den Händen seiner Schwester sah und die Worte seiner Schwester Rebekka hörte, die sprach: Also hat der Mann zu mir geredet! da kam er zu dem Manne, und siehe, der stand bei den Kamelen am Brunnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Und er sprach: Komm herein, du Gesegneter des HERRN, warum stehst du draußen? Ich habe das Haus geräumt und für die Kamele Platz gemacht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Also führte er den Mann ins Haus und zäumte die Kamele ab und gab ihnen Stroh und Futter und Wasser, um seine Füße und die Füße der Männer, die mit ihm waren, zu waschen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'und setzte ihm zu essen vor. Er aber sprach: Ich will nicht essen, bevor ich meine Sache vorgetragen habe. Er antwortete: Sage an!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Er sprach: Ich bin ein Knecht Abrahams.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Und der HERR hat meinen Herrn reichlich gesegnet, daß er groß geworden ist, denn er hat ihm Schafe und Ochsen, Silber und Gold, Knechte und Mägde, Kamele und Esel gegeben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Dazu hat Sarah, meines Herrn Weib, in ihrem Alter meinem Herrn einen Sohn geboren, demselben hat er alles, was sein ist, gegeben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Und mein Herr hat einen Eid von mir genommen und gesagt: Du sollst meinem Sohne kein Weib nehmen von den Töchtern der Kanaaniter, in deren Lande ich wohne;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sondern ziehe hin zu meines Vaters Haus und zu meinem Geschlecht; daselbst nimm meinem Sohn ein Weib.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ich sprach aber zu meinem Herrn: Wie? wenn mir das Weib nicht folgen will?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da sprach er zu mir: Der HERR, vor dem ich wandle, wird seinen Engel mit dir senden und deinen Weg gelingen lassen, daß du meinem Sohne von meiner Verwandtschaft und von meines Vaters Hause ein Weib nehmest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Alsdann sollst du des Eides entbunden sein, wenn du zu meiner Verwandtschaft kommst und sie dir dieselbe nicht geben; so sollst du des Eides entbunden sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Also kam ich heute zum Wasserbrunnen und sprach: O HERR, Gott, meines Herrn Abraham, wenn du doch zu meiner Reise Glück gäbest, welche ich gemacht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Siehe, ich stehe hier bei dem Wasserbrunnen. Wenn nun eine Jungfrau herauskommt zu schöpfen und ich spreche: »Gib mir aus deinem Krug ein wenig Wasser zu trinken«,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'und sie zu mir sagen wird: »Trinke, ich will deinen Kamelen auch schöpfen«, so möge doch diese das Weib sein, welches der HERR dem Sohn meines Herrn bestimmt hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ehe ich nun solche Worte in meinem Herzen ausgeredet hatte, siehe, da kommt Rebekka mit einem Krug auf ihrer Achsel und geht zum Brunnen hinab und schöpft. Da sprach ich zu ihr: »Gib mir zu trinken!«');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Und sie nahm den Krug eilend von ihrer Achsel und sprach: »Trink, ich will deine Kamele auch tränken!« Also trank ich, und sie tränkte die Kamele auch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Und ich fragte sie und sprach: »Wessen Tochter bist du?« Sie antwortete: »Ich bin Bethuels Tochter, des Sohnes Nahors, den ihm Milka geboren hat.« Da legte ich einen Ring an ihre Nase und Armbänder an ihre Hände');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'und neigte mich und betete an vor dem HERRN und lobte den HERRN, den Gott meines Herrn Abraham, der mich den rechten Weg geführt hat, daß ich seinem Sohne die Tochter des Bruders meines Herrn nehme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Wollt ihr nun meinem Herrn Liebe und Treue erweisen, so sagt mir\'s, wo nicht, so sagt es mir ebenfalls, daß ich mich zur Rechten oder zur Linken wende!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antworteten Laban und Bethuel und sprachen: Das ist vom HERRN gekommen, darum können wir nichts wider dich reden, weder Böses noch Gutes!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Da ist Rebekka vor dir, nimm sie und ziehe hin, daß sie das Weib des Sohnes deines Herrn sei, wie der HERR geredet hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Als nun Abrahams Knecht ihre Worte hörte, bückte er sich vor dem HERRN zur Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Und er zog hervor silberne und goldene Kleinode und Kleider und gab sie Rebekka; auch ihrem Bruder und ihrer Mutter gab er Kostbarkeiten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Da aßen und tranken sie, er samt den Männern, die mit ihm waren, und blieben daselbst über Nacht. Aber am Morgen standen sie auf, und er sprach: Lasset mich zu meinem Herrn ziehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Aber ihr Bruder und ihre Mutter sprachen: Laß doch die Tochter etliche Tage lang, zum wenigsten zehn, bei uns bleiben, darnach magst du ziehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Da sprach er zu ihnen: Haltet mich nicht auf, denn der HERR hat meinen Weg gelingen lassen; lasset mich zu meinem Herrn ziehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Da sprachen sie: Lasset uns die Tochter rufen und fragen, was sie dazu sage!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Und sie riefen Rebekka und sprachen zu ihr: Willst du mit diesem Manne ziehen? Sie antwortete: Ja, ich will mit ihm ziehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Also ließen sie Rebekka, ihre Schwester, mit ihrer Amme, samt dem Knecht Abrahams und seinen Leuten ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebekka und sprachen zu ihr: Du bist unsre Schwester, werde zu vieltausendmal Tausenden, und dein Same besitze die Tore seiner Feinde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Also machten sich Rebekka und ihre Mägde auf und setzten sich auf die Kamele und zogen dem Manne nach. Und der Knecht nahm Rebekka und zog hin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber kam vom »Brunnen des Lebendigen, der mich sieht«; denn er wohnte im Süden des Landes;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'und er war zur Abendzeit auf das Feld gegangen, um zu beten, und hob seine Augen auf und sah Kamele daherkommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Und Rebekka hob ihre Augen auf und sah den Isaak. Da sprang sie vom Kamel');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'und sprach zu dem Knecht: Wer ist jener Mann, der uns auf dem Felde entgegenkommt? Der Knecht sprach: Das ist mein Herr! Da nahm sie den Schleier und verhüllte sich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Und der Knecht erzählte dem Isaak alles, was er ausgerichtet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Da führte sie Isaak in die Hütte seiner Mutter Sarah und nahm die Rebekka, und sie ward sein Weib, und er gewann sie lieb. Also ward Isaak getröstet nach seiner Mutter Tod.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Und Abraham nahm wieder ein Weib, die hieß Ketura.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Die gebar ihm den Simran und den Jokschan, den Medan und den Midian, den Jischbak und den Schuach.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jokschan aber zeugte den Scheba und den Dedan. Die Kinder aber von Dedan waren die Assuriter, Letusiter und Leumiter');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'und die Kinder Midians waren Epha, Epher, Hanoch, Abida und Eldaa. Diese alle sind Kinder der Ketura.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Und Abraham gab sein ganzes Gut dem Isaak.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Aber den Kindern, die er von den Kebsweibern hatte, gab er Geschenke und schickte sie von seinem Sohne Isaak hinweg gegen Aufgang in das Morgenland, während er noch lebte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Dies ist aber die Zahl der Lebensjahre Abrahams: hundertfünfundsiebzig Jahre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Und Abraham nahm ab und starb in gutem Alter, da er alt und lebenssatt war, und ward zu seinem Volk gesammelt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Und seine Söhne Isaak und Ismael begruben ihn in der Höhle Machpelah auf dem Acker des Ephron, des Sohnes Zoars, des Hetiters, Mamre gegenüber,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'im Acker, welchen Abraham von den Hetitern gekauft hat. Daselbst sind Abraham und sein Weib Sarah begraben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Und nach dem Tode Abrahams segnete Gott seinen Sohn Isaak. Und Isaak wohnte bei dem »Brunnen des Lebendigen, der mich sieht«.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dies ist das Geschlecht Ismaels, des Sohnes Abrahams, den ihm Hagar, der Sarah ägyptische Magd, gebar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Und dieses sind die Namen der Kinder Ismaels, davon ihre Geschlechter genannt sind: Der erstgeborne Sohn Ismaels, Nebajoth, dann Kedar, Abdeel, Mibsam,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Massa,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, Tema, Jethur, Naphis und Kedma.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Das sind die Kinder Ismaels mit ihren Namen, in ihren Höfen und Zeltlagern, zwölf Fürsten in ihren Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und Ismael ward hundertsiebenunddreißig Jahre alt, und er nahm ab und starb und ward zu seinem Volk gesammelt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Sie wohnten aber von Chavila an bis gen Schur, das vor Ägypten liegt; und bis man nach Assyrien kommt; gegenüber von allen seinen Brüdern ließ er sich nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dies ist die Geschichte Isaaks, des Sohnes Abrahams. Abraham zeugte Isaak.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Isaak aber war vierzig Jahre alt, da er die Tochter Bethuels, des Syrers von Mesopotamien, die Schwester des Syrers Laban, zum Weibe nahm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaak aber bat den HERRN für sein Weib, denn sie war unfruchtbar; und der HERR ließ sich von ihm erbitten, und sein Weib Rebekka ward guter Hoffnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Und die Kinder stießen sich in ihrem Schoß. Da sprach sie: Wenn es so gehen soll, warum bin ich denn in diesen Zustand gekommen? Und sie ging hin, den HERRN zu fragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Und der HERR sprach zu ihr: Zwei Völker sind in deinem Schoß, und zwei Stämme werden sich aus deinen Eingeweiden scheiden, und ein Volk wird dem andern überlegen sein, und der Ältere wird dem Jüngeren dienen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Da nun die Zeit kam, daß sie gebären sollte, siehe, da waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Der erste, der herauskam, war rothaarig, ganz wie ein härenes Kleid, und sie nannte ihn Esau.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Darnach kam sein Bruder heraus, und seine Hand hielt die Ferse Esaus; da nannte sie ihn Jakob. Und Isaak war sechzig Jahre alt, da sie geboren wurden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Und als die Knaben groß wurden, ward Esau ein Waidmann, der sich auf die Jagd verstand; Jakob aber war ein sittsamer Mann, der bei den Zelten blieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Und Isaak hatte Esau lieb, weil ihm das Wildbret mundete; Rebekka aber hatte Jakob lieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Und Jakob kochte ein Gericht. Da kam Esau vom Feld und war müde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Und Esau sprach zu Jakob: Laß mich das rote Gericht versuchen, denn ich bin müde! Daher heißt er Edom.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Aber Jakob sprach: Verkaufe mir heute deine Erstgeburt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Und Esau sprach zu Jakob: Siehe, ich muß doch sterben; was soll mir die Erstgeburt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob sprach: So schwöre mir heute! Und er schwur ihm und verkaufte also dem Jakob seine Erstgeburt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Da gab Jakob dem Esau Brot und das Linsengericht. Und er aß und trank und stand auf und ging davon. Also verachtete Esau die Erstgeburt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Es kam aber eine Teuerung in das Land; außer der vorigen Teuerung, die zu Abrahams Zeiten gewesen. Und Isaak zog gen Gerar zu Abimelech, dem König der Philister.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Da erschien ihm der HERR und sprach: Reise nicht nach Ägypten hinab, sondern bleib in dem Lande, das ich dir sage!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Sei ein Fremdling in diesem Lande, und ich will mit dir sein und dich segnen; denn dir und deinem Samen will ich dieses ganze Land geben und will den Eid bestätigen, den ich deinem Vater Abraham geschworen habe,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'und will deinen Samen mehren wie die Sterne des Himmels und will deinem Samen das ganze Land geben, und durch deinen Samen sollen alle Völker auf Erden gesegnet werden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'weil Abraham meiner Stimme gehorsam gewesen und meine Rechte, meine Gebote, meine Sitten und meine Gesetze gehalten hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Also wohnte Isaak zu Gerar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Und da die Leute desselben Ortes nach seinem Weibe fragten, so sprach er: Sie ist meine Schwester. Denn er fürchtete sich zu sagen: Sie ist mein Weib, weil er dachte: Die Leute an diesem Ort möchten mich um Rebekkas willen töten; denn sie war schön von Angesicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Da er sich aber längere Zeit daselbst aufhielt, sah Abimelech, der Philister König, durchs Fenster und bemerkte, daß Isaak scherzte mit seinem Weibe Rebekka.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da rief Abimelech den Isaak und sprach: Siehe, sie ist dein Weib! Wie durftest du sagen: »Sie ist meine Schwester?« Isaak antwortete ihm: Ich dachte, ich möchte vielleicht sterben müssen um ihretwillen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelech sprach: Warum hast du uns das getan? Wie leicht hätte jemand vom Volk sich zu deinem Weibe legen können, so hättest du eine Schuld auf uns gebracht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Da gebot Abimelech dem ganzen Volke und sprach: Wer diesen Mann oder sein Weib antastet, der soll des Todes sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Und Isaak säte in dem Lande und erntete in demselben Jahr hundertfältig; denn der HERR segnete ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Und der Mann ward reich und immer reicher, bis er sehr reich war;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'und er hatte Schaf und Rinderherden und eine große Dienerschaft. Darum beneideten ihn die Philister.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Und die Philister verstopften alle Brunnen, die seines Vaters Knechte gegraben hatten zu Abrahams, seines Vaters, Zeiten, und füllten sie mit Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Und Abimelech sprach zu Isaak: Geh fort von uns; denn du bist uns viel zu mächtig geworden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Da zog Isaak von dannen und lagerte sich im Tale Gerar und wohnte daselbst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Und Isaak ließ die Wasserbrunnen aufgraben, die sie zu Abrahams, seines Vaters, Zeiten gegraben, und nannte sie mit denselben Namen, mit welchen sein Vater sie benannt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Auch gruben Isaaks Knechte im Tal und fanden daselbst einen Brunnen lebendigen Wassers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Aber die Hirten von Gerar zankten mit den Hirten Isaaks und sprachen: Das Wasser gehört uns! Da hieß er den Brunnen Esek, weil sie daselbst sich mit ihm gezankt hatten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Da gruben sie einen andern Brunnen, um den stritten sie auch; darum hieß er ihn Sithna.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Da brach er von dort auf und grub einen andern Brunnen, um den zankten sie nicht, darum hieß er ihn Rechobot und sprach: Nun hat uns der HERR einen weiten Raum gemacht, daß wir im Lande wachsen können.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Von dort zog er hinauf nach Beerseba.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Und der HERR erschien ihm in derselben Nacht und sprach: Ich bin der Gott deines Vaters Abraham. Fürchte dich nicht! Denn ich bin mit dir, und ich will dich segnen und deinen Samen mehren um Abrahams, meines Knechtes, willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Da baute er einen Altar daselbst und rief den Namen des HERRN an und richtete daselbst seine Hütte auf; und Isaaks Knechte gruben daselbst einen Brunnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Und Abimelech kam zu ihm von Gerar, mit Achussat, seinem Freund, und Pichol, seinem Feldhauptmann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Aber Isaak sprach zu ihnen: Warum kommt ihr zu mir, da ihr mich doch hasset und mich von euch getrieben habt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Sie sprachen: Wir haben deutlich gesehen, daß der HERR mit dir ist, darum sprachen wir: Es soll ein Eid zwischen uns sein, zwischen uns und dir, und wir wollen einen Bund mit dir machen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'daß du uns keinen Schaden zufügest, wie wir dich auch nicht angetastet und dir nur Gutes getan und dich im Frieden haben ziehen lassen. Du bist nun einmal der Gesegnete des HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Da machte er ihnen ein Mahl, und sie aßen und tranken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Und am Morgen früh standen sie auf und schwuren einer dem andern. Da ließ Isaak sie gehen, und sie zogen in Frieden von ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'An demselben Tage kamen Isaaks Knechte und sagten ihm von dem Brunnen, den sie gegraben hatten, und sprachen zu ihm: Wir haben Wasser gefunden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Und er nannte ihn Scheba. Daher heißt der Ort Beer-Scheba bis auf den heutigen Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Als Esau vierzig Jahre alt war, nahm er Weiber, Judith, die Tochter Beris, des Hetiters, und Basmath, die Tochter Elons, des Hetiters;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'die machten Isaak und Rebekka viel Verdruß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Und es begab sich, als Isaak alt war und seine Augen dunkel wurden, daß er nicht mehr sehen konnte, da rief er Esau, seinen älteren Sohn, und sprach zu ihm: Mein Sohn! Er aber antwortete ihm: Hier bin ich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Und er sprach: Siehe, ich bin alt und weiß nicht, wann ich sterbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'So nimm nun dein Jagdgerät, deinen Köcher und deinen Bogen und geh aufs Feld und jage mir ein Wildbret');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'und bereite mir ein schmackhaftes Essen, wie ich es gern habe, und bring mir\'s herein, daß ich esse, auf daß dich meine Seele segne, ehe denn ich sterbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebekka aber hörte zu, da Isaak solche Worte zu seinem Sohn Esau sagte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Während nun Esau aufs Feld ging, ein Wildbret zu jagen, daß er es heimbrächte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'sprach Rebekka zu ihrem Sohne Jakob: Siehe, ich habe gehört, wie dein Vater mit deinem Bruder Esau redete und sagte: »Bring mir ein Wildbret und bereite mir ein schmackhaftes Gericht, daß ich esse und dich segne vor dem HERRN, vor meinem Tod!«');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'So gehorche nun, mein Sohn, meiner Stimme und tue, was ich dich heiße:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Geh hin zur Herde und hole mir von dort zwei gute Ziegenböcklein, daß ich deinem Vater ein schmackhaftes Gericht bereite, wie er es gern hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Das sollst du deinem Vater hineintragen, daß er es esse und dich vor seinem Tode segne.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jakob aber sprach zu seiner Mutter Rebekka: Siehe, mein Bruder Esau ist rauh, und ich bin glatt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht könnte mein Vater mich betasten, da würde ich in seinen Augen als ein Betrüger erscheinen und brächte so einen Fluch über mich und nicht einen Segen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Da sprach seine Mutter zu ihm: Dein Fluch sei auf mir, mein Sohn! gehorche du nur meiner Stimme, geh hin und hole es mir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da ging er hin und holte es und brachte es seiner Mutter. Und seine Mutter machte ein schmackhaftes Essen, wie es sein Vater gern hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Rebekka nahm auch Esaus, ihres älteren Sohnes, köstliche Kleider, die sie bei sich im Hause hatte, und legte sie Jakob, ihrem jüngeren Sohne, an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Aber die Felle von den Ziegenböcklein tat sie ihm um die Hände, und wo er am Halse glatt war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'und gab also das schmackhafte Essen, wie sie es gemacht hatte, und das Brot in ihres Sohnes Jakobs Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Und er kam hinein zu seinem Vater und sprach: Mein Vater! Er antwortete: Hier bin ich! Wer bist du, mein Sohn?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob sprach zu seinem Vater: Ich bin Esau, dein Erstgeborener; ich habe getan, wie du mir gesagt hast. Stehe auf, setze dich und iß von meinem Wildbret, daß mich deine Seele segne!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Isaak aber sprach zu seinem Sohn: Mein Sohn, wie hast du es so bald gefunden? Er antwortete: Der HERR, dein Gott, bescherte es mir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sprach Isaak zu Jakob: Tritt herzu, mein Sohn, daß ich dich anrühre, ob du mein Sohn Esau seiest oder nicht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jakob trat zu seinem Vater Isaak. Und als er ihn betastet hatte, sprach er: Die Stimme ist Jakobs Stimme, aber die Hände sind Esaus Hände!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Aber er erkannte ihn nicht, denn seine Hände waren rauh, wie die Hände seines Bruders Esau. Und er segnete ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Und er fragte ihn: Bist du mein Sohn Esau? Er antwortete: Ja, ich bin\'s!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sprach er: So bringe mir her, mein Sohn, von deinem Wildbret zu essen, daß dich meine Seele segne! Da brachte er es ihm, und er aß; er reichte ihm auch Wein, und er trank.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Und Isaak, sein Vater, sprach zu ihm: Komm her, mein Sohn, und küsse mich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Und er trat hinzu und küßte ihn. Und als er den Geruch seiner Kleider roch, segnete er ihn und sprach: Siehe, der Geruch meines Sohnes ist wie ein Geruch des Feldes, das der HERR gesegnet hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Gott gebe dir vom Tau des Himmels und vom fettesten Boden und Korn und Most die Fülle;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Völker müssen dir dienen und Geschlechter sich vor dir bücken; sei ein Herr über deine Brüder, und deiner Mutter Kinder müssen sich vor dir bücken. Verflucht sei, wer dir flucht, und gesegnet sei, wer dich segnet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Als nun Isaak den Segen über Jakob vollendet hatte, und Jakob kaum von seinem Vater Isaak hinausgegangen war, da kam sein Bruder Esau von der Jagd.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Der machte auch ein schmackhaftes Essen und trug es zu seinem Vater hinein und sprach zu ihm: Steh auf, mein Vater, und iß von dem Wildbret deines Sohnes, daß mich deine Seele segne!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Da antwortete ihm sein Vater Isaak: Wer bist du? Er sprach: Ich bin Esau, dein Erstgeborener.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da entsetzte sich Isaak über die Maßen sehr und sprach: Wer ist denn der Jäger, der ein Wildbret gejagt und mir aufgetragen hat? Ich habe von allem gegessen, ehe du kamst, und habe ihn gesegnet; er wird auch gesegnet bleiben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Als Esau diese Rede seines Vaters hörte, schrie er laut und ward über die Maßen betrübt und sprach zu seinem Vater: Segne mich auch, mein Vater!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Er aber sprach: Dein Bruder ist mit List gekommen und hat deinen Segen vorweggenommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sprach er: Er heißt mit Recht Jakob; denn er hat mich nun zweimal überlistet: Meine Erstgeburt hat er weggenommen, und siehe, nun nimmt er auch meinen Segen! Und er sprach: Hast du mir nicht auch einen Segen vorbehalten?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaak antwortete und sprach zu Esau: Siehe, ich habe ihn zum Herrn über dich gesetzt, und alle seine Brüder habe ich ihm zu Knechten gegeben; mit Korn und Most habe ich ihn versehen. Was soll ich nun dir tun, mein Sohn?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Esau sprach zu seinem Vater: Hast du denn nur einen Segen, mein Vater? Segne mich auch, mein Vater! Und Esau erhob seine Stimme und weinte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da antwortete Isaak, sein Vater, und sprach zu ihm: Siehe, ohne fetten Boden wird dein Wohnsitz sein und ohne Tau des Himmels von oben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Von deinem Schwert wirst du leben und deinem Bruder dienen. Es wird aber geschehen, wenn du dich befreien kannst, daß du sein Joch von deinem Halse reißen wirst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Und Esau ward dem Jakob feind um des Segens willen, womit sein Vater ihn gesegnet hatte; und Esau sprach in seinem Herzen: Die Zeit, da man um meinen Vater trauern wird, ist nicht mehr weit; dann will ich meinen Bruder Jakob umbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Es wurden aber der Rebekka die Worte Esaus, ihres älteren Sohnes, hinterbracht. Da schickte sie hin und ließ Jakob, ihren jüngeren Sohn, rufen und sprach zu ihm: Siehe, dein Bruder Esau will an dir Rache nehmen und dich töten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Und nun gehorche meiner Stimme, mein Sohn: Mache dich auf und flieh zu meinem Bruder Laban, nach Haran,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'und bleib eine Zeitlang bei ihm, bis sich deines Bruders Grimm gelegt hat');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'und bis sich sein Zorn von dir wendet und er vergißt, was du ihm angetan hast; so will ich dann nach dir schicken und dich von dannen holen lassen. Warum sollte ich euer beider beraubt werden auf einen Tag?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Und Rebekka sprach zu Isaak: Es verdrießt mich zu leben mit den Töchtern Hets; wenn Jakob ein Weib nimmt von den Töchtern Hets, wie diese da, von den Töchtern des Landes, was soll mir das Leben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da rief Isaak den Jakob, segnete ihn und gebot ihm und sprach zu ihm: Nimm kein Weib von den Töchtern Kanaans.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mache dich auf und ziehe nach Mesopotamien, in das Haus Bethuels, des Vaters deiner Mutter, und nimm dir von dort ein Weib von den Töchtern Labans, des Bruders deiner Mutter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Und der allmächtige Gott segne dich und mache dich fruchtbar und mehre dich, daß du zu einer Völkergemeinde werdest,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'und gebe dir den Segen Abrahams, dir und deinem Samen mit dir, daß du besitzest das Land, darin du ein Fremdling bist, das Gott dem Abraham gegeben hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Also fertigte Isaak den Jakob ab, daß er nach Mesopotamien zog zu Laban, Bethuels Sohn, dem Syrer, dem Bruder der Rebekka, der Mutter Jakobs und Esaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Als nun Esau sah, daß Isaak den Jakob gesegnet und ihn nach Mesopotamien abgefertigt hatte, daß er sich von dort ein Weib hole, und daß er, indem er ihn segnete, ihm gebot und sprach: »Du sollst kein Weib von den Töchtern Kanaans nehmen«;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und daß Jakob seinem Vater und seiner Mutter gehorsam war und nach Mesopotamien zog;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'als Esau auch sah, daß Isaak, sein Vater, die Töchter Kanaans nicht gerne sah,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'da ging Esau hin zu Ismael und nahm zu seinen Weibern noch Maalath hinzu, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths, zum Weibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jakob aber zog von Beerseba aus und wanderte gen Haran.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Und er kam an einen Ort, wo er über Nacht blieb; denn die Sonne war untergegangen. Und er nahm von den Steinen jenes Orts und legte sie unter sein Haupt und legte sich an dem Ort schlafen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Und ihm träumte; und siehe, eine Leiter war auf die Erde gestellt, die rührte mit der Spitze an den Himmel. Und siehe, die Engel Gottes stiegen daran auf und nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Und siehe, der HERR stand oben darauf und sprach: Ich bin der HERR, der Gott deines Vaters Abraham und der Gott Isaaks; das Land, darauf du liegst, will ich dir und deinem Samen geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Und dein Same soll werden wie der Staub auf Erden, und gegen Abend und Morgen und Mitternacht und Mittag sollst du dich ausbreiten, und durch dich und deinen Samen sollen alle Geschlechter auf Erden gesegnet werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Und siehe: Ich bin mit dir, und ich will dich behüten allenthalben, wo du hinziehst, und dich wieder in dieses Land bringen. Denn ich will dich nicht verlassen, bis ich getan, was ich dir gesagt habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Da nun Jakob von seinem Schlaf erwachte, sprach er: Gewiß ist der HERR an diesem Ort, und ich wußte es nicht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Und er fürchtete sich und sprach: Wie heilig ist diese Stätte! Hier ist nichts anderes als Gottes Haus, und dies ist die Pforte des Himmels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Und Jakob stand am Morgen früh auf und nahm den Stein, den er unter sein Haupt gelegt hatte, und richtete ihn auf zu einer Denksäule und goß Öl oben darauf,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'und nannte diesen Ort Beth-El; zuvor aber hieß die Stadt Lus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob tat ein Gelübde und sprach: Wenn Gott mit mir sein und mich behüten will auf dem Wege, den ich reise, und mir will Brot zu essen geben und Kleider anzuziehen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und mich wieder mit Frieden heim zu meinem Vater bringt, so soll der HERR mein Gott sein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'und dieser Stein, den ich zur Säule aufgerichtet habe, soll ein Haus Gottes werden, und von allem, was du mir gibst, will ich dir den Zehnten geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Da machte sich Jakob wieder auf den Weg und ging ins Morgenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Und er sah sich um und siehe, da war ein Brunnen auf dem Felde, und siehe, drei Herden Schafe lagen dabei; denn von dem Brunnen mußten die Herden trinken. Und ein großer Stein lag über dem Loch des Brunnens.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und sie pflegten alle Herden daselbst zu versammeln und den Stein von dem Loch des Brunnens zu wälzen und die Schafe zu tränken, und taten alsdann den Stein wieder an seinen Ort, über das Loch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Und Jakob sprach zu ihnen: Meine Brüder, woher seid ihr? Sie antworteten: Wir sind von Haran.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Er sprach zu ihnen: Kennt ihr auch Laban, den Sohn Nahors? Sie antworteten: Wir kennen ihn wohl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Er sprach zu ihnen: Geht es ihm gut? Sie antworteten: Es geht ihm gut; und siehe, da kommt seine Tochter Rahel mit den Schafen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Er sprach: Siehe, es ist noch hoch am Tag und noch nicht Zeit, das Vieh einzutreiben; tränket die Schafe und gehet hin, weidet sie!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Sie antworteten: Wir können es nicht, ehe alle Herden zusammengebracht sind und sie den Stein von dem Loch des Brunnens wälzen; dann können wir die Schafe tränken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Als er noch mit ihnen redete, kam Rahel mit ihres Vaters Schafen; denn sie hütete die Schafe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Als aber Jakob Rahel sah, die Tochter Labans, des Bruders seiner Mutter, trat er hinzu und wälzte den Stein von dem Loch des Brunnens und tränkte die Schafe Labans, des Bruders seiner Mutter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Und Jakob küßte Rahel und erhob seine Stimme und weinte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Da sagte Jakob der Rahel, daß er ihres Vaters Bruder und der Rebekka Sohn wäre. Da lief sie und sagte es ihrem Vater.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Als nun Laban die Nachricht von Jakob, seiner Schwester Sohn, hörte, lief er ihm entgegen, umarmte und küßte ihn und führte ihn in sein Haus. Da erzählte er Laban diese ganze Geschichte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Da sprach Laban zu ihm: Wohlan, du bist mein Gebein und mein Fleisch! Und er blieb bei ihm einen Monat lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Darnach sprach Laban zu Jakob: Solltest du mir darum umsonst dienen, weil du mein Neffe bist? Sage an, was soll dein Lohn sein?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Laban aber hatte zwei Töchter; die ältere hieß Lea und die jüngere Rahel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Und Lea hatte matte Augen, Rahel aber war schön von Gestalt und schön von Angesicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Und Jakob gewann Rahel lieb und sprach: Ich will dir sieben Jahre lang um Rahel, deine jüngere Tochter, dienen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban antwortete: Es ist besser, ich gebe sie dir, als einem andern Mann; bleibe bei mir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Also diente Jakob um Rahel sieben Jahre lang, und sie kamen ihm vor wie einzelne Tage, so lieb hatte er sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Und Jakob sprach zu Laban: Gib mir mein Weib, daß ich zu ihr komme, denn meine Zeit ist abgelaufen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da lud Laban alle Leute des Ortes und machte ein Mahl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Aber am Abend nahm er seine Tochter Lea und brachte sie zu ihm hinein; und er kam zu ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab seine Magd Silpa seiner Tochter Lea zur Magd.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Am Morgen aber, siehe, da war es Lea! Und er sprach zu Laban: Warum hast du mir das getan? Habe ich dir nicht um Rahel gedient? Warum hast du mich denn betrogen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban antwortete: Man tut nicht also in unserm Lande, daß man die Jüngere vor der Älteren weggibt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Halte die Woche aus mit dieser, so wird dir jene auch gegeben, um den Dienst, den du mir noch andere sieben Jahre lang leisten sollst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob tat also und hielt die Woche aus. Da gab er ihm Rahel, seine Tochter, zum Weibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und Laban gab seine Magd Bilha seiner Tochter Rahel zur Magd.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Also kam er auch zu Rahel und hatte Rahel lieber denn Lea, und diente ihm noch andere sieben Jahre lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Als aber der HERR sah, daß Lea verhaßt war, machte er sie fruchtbar und Rahel unfruchtbar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Und Lea empfing und gebar einen Sohn, den hieß sie Ruben. Denn sie sprach: Weil der HERR mein Elend angesehen hat, so wird mich nun mein Mann lieben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Und sie empfing abermal und gebar einen Sohn und sprach: Weil der HERR gehört hat, daß ich verhaßt bin, so hat er mir auch diesen gegeben, und sie hieß ihn Simeon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Sie empfing abermal und gebar einen Sohn und sprach: Nunmehr wird mein Mann mir anhänglich sein, denn ich habe ihm drei Söhne geboren; darum nannte sie ihn Levi.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Sie empfing wieder und gebar einen Sohn und sprach: Nun will ich den HERRN preisen! Darum hieß sie ihn Juda; und sie hielt inne mit Gebären.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Als aber Rahel sah, daß sie dem Jakob keine Kinder gebar, ward sie eifersüchtig auf ihre Schwester und sprach zu Jakob: Schaffe mir auch Kinder, wo nicht, so sterbe ich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakob aber ward sehr zornig auf Rahel und sprach: Bin ich denn an Gottes Statt, der dir Leibesfrucht versagt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Sie aber sprach: Siehe, da ist meine Magd Bilha, komm zu ihr, daß sie in meinen Schoß gebäre, und ich doch durch sie Nachkommen erhalte!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Und sie gab ihm ihre Magd Bilha zum Weibe, und Jakob kam zu ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha aber empfing und gebar dem Jakob einen Sohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Da sprach Rahel: Gott hat mir Recht verschafft und meine Stimme erhört und mir einen Sohn gegeben; darum hieß sie ihn Dan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Und Bilha, die Magd Rahels, empfing abermal und gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sprach Rahel: Ich habe mit meiner Schwester gerungen, als ränge ich mit Gott, und habe auch gewonnen! Darum hieß sie ihn Naphtali.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Als nun Lea sah, daß sie innehielt mit Gebären, nahm sie ihre Magd Silpa und gab sie Jakob zum Weibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Und Silpa, Leas Magd, gebar dem Jakob einen Sohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sprach Lea: Ich habe Glück! und hieß ihn Gad.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Darnach gebar Silpa, Leas Magd, dem Jakob einen zweiten Sohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sprach Lea: Die Töchter werden mich glücklich preisen! Und sie hieß ihn Asser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben aber ging aus zur Zeit der Weizenernte und fand Liebesäpfel auf dem Felde und brachte sie heim zu seiner Mutter Lea. Da sprach Rahel zu Lea: Gib mir einen Teil der Liebesäpfel deines Sohnes!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Sie antwortete ihr: Ist das ein Geringes, daß du mir meinen Mann genommen hast? Und willst du auch die Liebesäpfel meines Sohnes nehmen? Rahel sprach: Er soll dafür diese Nacht bei dir schlafen zum Entgelt für die Liebesäpfel deines Sohnes!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Da nun Jakob am Abend vom Felde kam, ging ihm Lea entgegen und sprach: Du sollst zu mir kommen, denn ich habe dich erkauft um die Liebesäpfel meines Sohnes. Und er schlief in jener Nacht bei ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Und Gott erhörte Lea, und sie empfing und gebar dem Jakob den fünften Sohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sprach Lea: Gott hat mir gelohnt, daß ich meinem Mann meine Magd gegeben habe, und hieß ihn Issaschar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lea empfing abermal und gebar dem Jakob den sechsten Sohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Und Lea sprach: Gott hat mich mit einer guten Gabe beschenkt! Nun wird mein Mann wieder bei mir wohnen, denn ich habe ihm sechs Söhne geboren, und sie hieß ihn Sebulon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Darnach gebar sie eine Tochter, welche sie Dina hieß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Aber Gott gedachte an Rahel, und Gott erhörte ihr Gebet und machte sie fruchtbar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Und sie empfing und gebar einen Sohn und sprach: Gott hat meine Schmach von mir genommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Und sie hieß ihn Joseph und sprach: Gott wolle mir noch einen Sohn dazu geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Da nun Rahel den Joseph geboren hatte, sprach Jakob zu Laban: Entlasse mich, daß ich an meinen Ort und in mein Land ziehe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Weiber und Kinder, um welche ich dir gedient habe, daß ich gehen kann! Denn du weißt, welche Dienste ich dir geleistet habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban antwortete: Ach, daß ich doch in deinen Augen Gnade fände! Ich habe es geahnt; und doch hat mich der HERR um deinetwillen gesegnet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Und er sprach: Bestimme mir deinen Lohn, so will ich ihn dir geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Jakob sprach: Du weißt, wie ich dir gedient habe, und was aus deinem Vieh unter meiner Pflege geworden ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Denn es war wenig, was du vor meiner Ankunft hattest, nun aber ist viel daraus geworden, und der HERR hat dich gesegnet, wo ich hingekommen bin; und nun, wann soll ich auch für mein Haus sorgen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Er sprach: Was soll ich dir denn geben? Jakob sprach: Du brauchst mir gar nichts zu geben! Wenn du mir nur tun willst, was ich jetzt sage, so will ich deine Herden wieder weiden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ich will heute durch alle deine Herden gehen, und du sollst daraus absondern alle gesprenkelten und gefleckten Schafe, auch alle schwarzen Schafe unter den Lämmern und alle gefleckten und gesprenkelten Ziegen; und das soll mein Lohn sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'So wird alsdann meine Gerechtigkeit für mich sprechen am künftigen Tag vor deinen Augen, wenn du zu meinem Lohn kommst; alles, was weder gesprenkelt noch gefleckt ist unter den Ziegen und was nicht schwarz ist unter den Lämmern bei mir, das soll als gestohlen gelten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Da sprach Laban: Gut, es sei so, wie du gesagt hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Und er sonderte noch am gleichen Tag die gestreiften und gefleckten Böcke aus und alle gesprenkelten Ziegen, alles, woran etwas Weißes war, und alles, was schwarz war unter den Lämmern, und tat es unter die Hand seiner Söhne.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Und er machte einen Abstand von drei Tagereisen zwischen sich und Jakob; dieser aber weidete die übrigen Schafe Labans.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Da nahm Jakob frische Ruten von Pappeln, Mandel und Platanenbäumen und schälte weiße Streifen dran, indem er das Weiße an den Ruten bloßlegte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'und legte die Ruten, die er abgeschält hatte, in die Tränkrinnen, wohin die Schafe zum Trinken kamen, gerade vor die Schafe hin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Wenn sie dann beim Kommen zur Tränke brünstig wurden, so empfingen sie angesichts der Ruten und warfen Gestreifte, Gesprenkelte und Gefleckte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Die Lämmer aber sonderte Jakob ab und richtete das Angesicht der Schafe gegen die gefleckten und schwarzen in der Herde Labans; und er machte sich besondere Herden und tat sie nicht zu Labans Schafen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Und jedesmal, wenn die Zeit kam, wo die kräftigen Schafe brünstig wurden, legte Jakob die Ruten in die Tränkrinnen vor die Augen der Schafe, damit sie über den Ruten empfingen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'wenn aber die Schwachen brünstig wurden, legte er sie nicht hinein. So erhielt Laban die schwachen und Jakob die starken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Und der Mann wurde außerordentlich reich und bekam viele Schafe, Knechte und Mägde, Kamele und Esel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Er vernahm aber die Reden der Söhne Labans, die sagten: Jakob hat alles genommen, was unserm Vater gehört; und mit dem, was unserm Vater gehört, hat er all diesen Reichtum zuwege gebracht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Und Jakob sah, daß Labans Angesicht gegen ihn nicht mehr war wie gestern und vorgestern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Da sprach der HERR zu Jakob: Kehre in das Land deiner Väter und zu deiner Verwandtschaft zurück; ich will mit dir sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Und Jakob ließ Rahel und Lea zu seiner Herde aufs Feld hinaus rufen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'und sprach zu ihnen: Ich sehe, daß eures Vaters Angesicht gegen mich nicht mehr ist wie gestern und vorgestern; aber der Gott meines Vaters ist mit mir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Und ihr wisset, wie ich eurem Vater gedient habe mit meiner ganzen Kraft.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Euer Vater aber hat mich betrogen und mir meinen Lohn zehnmal verändert; doch hat ihm Gott nicht zugelassen, daß er mir schaden durfte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Sagte er: Die Gesprenkelten sollen dein Lohn sein, so warf die ganze Herde Gesprenkelte; sagte er aber: Die Gestreiften sollen dein Lohn sein, so warf die ganze Herde Gestreifte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'So hat Gott eurem Vater die Herde entwendet und sie mir gegeben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Es begab sich nämlich zu der Zeit, wo die Schafe brünstig werden, daß ich meine Augen aufhob und im Traume sah und siehe, die Böcke sprangen auf die gestreiften, gesprenkelten und scheckigen Schafe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und der Engel Gottes sprach zu mir im Traum: Jakob! Und ich antwortete: Hier bin ich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Er aber sprach: Hebe doch deine Augen auf und siehe: Alle Böcke, welche die Schafe bespringen, sind gestreift, gesprenkelt und scheckig! Denn ich habe alles gesehen, was dir Laban antut.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott von Bethel, wo du die Säule gesalbt und mir ein Gelübde getan hast; nun mache dich auf, geh aus von diesem Land und kehre zurück in das Land deiner Geburt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da antworteten Rahel und Lea und sprachen zu ihm: Haben wir auch noch ein Teil oder Erbe im Hause unsres Vaters?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Werden wir nicht von ihm angesehen, als wären wir fremd? Er hat uns ja verkauft und sogar unser Geld verzehrt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Darum gehört auch all der Reichtum, den Gott unserm Vater entwendet hat, uns und unsern Kindern. So tue du nun alles, was Gott dir gesagt hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Da machte sich Jakob auf und lud seine Kinder und seine Weiber auf Kamele');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'und führte all sein Vieh weg und seine ganze Habe, die er erworben hatte, seine eigene Herde, die er in Mesopotamien erworben hatte, um zu seinem Vater Isaak ins Land Kanaan zu ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban aber war ausgegangen, seine Schafe zu scheren; und Rahel stahl die Hausgötzen, die ihrem Vater gehörten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jakob aber täuschte Labans, des Syrers Herz, indem er ihm nicht anzeigte, daß er sich davonmachte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Und er entfloh mit allem, was er hatte, machte sich auf und setzte über den Euphrat und wandte sein Angesicht dem Gebirge Gilead zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Am dritten Tag ward Laban angezeigt, daß Jakob geflohen sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Da nahm er seine Brüder mit sich und jagte ihm nach, sieben Tagereisen weit und holte ihn ein auf dem Gebirge Gilead.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Aber Gott kam zu Laban, dem Syrer, des Nachts im Traum und sprach zu ihm: Hüte dich davor, mit Jakob anders als freundlich zu reden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Als nun Laban den Jakob einholte, hatte Jakob sein Zelt auf dem Berge aufgeschlagen; da schlug auch Laban mit seinen Brüdern sein Zelt auf dem Gebirge Gilead auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Und Laban sprach zu Jakob: Warum hast du dich weggestohlen und meine Töchter entführt, als wären sie Kriegsgefangene?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich geflohen und hast mich getäuscht und es mir nicht angezeigt? Ich hätte dich mit Freuden begleitet, mit Gesang, mit Pauken und Harfen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Du hast mich nicht einmal meine Söhne und Töchter küssen lassen; da hast du töricht gehandelt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Es stünde in meiner Macht, euch Übles zu tun; aber der Gott eures Vaters hat gestern zu mir gesagt: Hüte dich, daß du mit Jakob anders als freundlich redest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Und nun bist du ja gegangen, weil du dich so sehr sehntest nach deines Vaters Haus; warum hast du aber meine Götter gestohlen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Da antwortete Jakob und sprach zu Laban: Ich fürchtete, du würdest mir deine Töchter entreißen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Was aber deine Götter betrifft, bei welchem du sie findest, der soll nicht am Leben bleiben! In Gegenwart unsrer Brüder sieh dir alles an, was bei mir ist, und nimm, was dir gehört! Jakob wußte nämlich nicht, daß Rahel sie gestohlen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Da ging Laban in Jakobs Zelt und in Leas Zelt und in das Zelt der beiden Mägde, fand aber nichts. Und von Leas Zelt ging er in Rahels Zelt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rahel aber hatte die Hausgötzen genommen und sie in den Kamelssattel gelegt und sich daraufgesetzt. Und Laban durchstöberte das ganze Zelt, fand sie aber nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Da sprach sie zu ihrem Vater: Mein Herr möge nicht so grimmig dreinsehen, weil ich vor dir nicht aufstehen kann; es geht mir eben nach der Frauen Weise! Er aber suchte eifrig und fand die Hausgötzen nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Da ward Jakob zornig und haderte mit Laban; und Jakob antwortete und sprach zu ihm: Was habe ich verbrochen, was habe ich gesündigt, daß du mir so hitzig nachgejagt bist?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Da du nun allen meinen Hausrat durchstöbert hast, was hast du von all deinem Hausrat gefunden? Lege es hier vor meine und deine Brüder, damit sie schlichten zwischen uns!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Diese zwanzig Jahre bin ich bei dir gewesen; deine Mutterschafe und Ziegen wurden nie ihrer Jungen beraubt, und die Widder deiner Herde habe ich nicht gegessen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Was zerrissen ward, habe ich dir nicht gebracht; ich mußte es ersetzen, du fordertest es von meiner Hand, ob es bei Tag oder bei Nacht gestohlen war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Des Tages verschmachtete ich vor Hitze und des Nachts vor Frost, und der Schlaf floh meine Augen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Diese zwanzig Jahre lang habe ich dir in deinem Hause gedient, vierzehn Jahre um deine beiden Töchter und sechs Jahre um deine Schafe, und du hast mir meinen Lohn zehnmal verändert!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wenn nicht der Gott meines Vaters, der Gott Abrahams und der Gefürchtete Isaaks für mich gewesen wäre, du hättest mich jetzt leer ziehen lassen; aber Gott hat mein Elend und die Arbeit meiner Hände angesehen und dich diese Nacht gestraft!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban antwortete und sprach: Die Töchter sind meine Töchter und die Kinder sind meine Kinder und die Herden sind meine Herden, und alles, was du siehst, ist mein! Was kann ich nun heute diesen meinen Töchtern oder ihren Kindern tun, die sie geboren haben?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Komm, wir wollen nun einen Bund machen, ich und du; der soll ein Zeuge sein zwischen mir und dir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Da nahm Jakob einen Stein und stellte ihn als Denkmal auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Und Jakob sprach zu seinen Brüdern: Sammelt Steine! Da nahmen sie Steine und machten einen Wall und aßen daselbst auf dem Wall.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban nannte ihn Jegar-Sahaduta; Jakob aber hieß ihn Galed.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Und Laban sprach: dieser Wall sei heute Zeuge zwischen mir und dir; darum wird er Galed genannt');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'und Mizpa, indem er sprach: Der HERR wache zwischen mir und dir, wenn wir einander nicht mehr sehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Wenn du meine Töchter mißhandelst und wenn du zu meinen Töchtern hinzu andere Frauen nimmst und kein Mensch dazwischen tritt, siehe, so ist doch Gott Zeuge zwischen mir und dir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Weiter sprach Laban zu Jakob: Siehe, dieser Wall und dieses Denkmal, das ich errichtet habe zwischen mir und dir');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'dieser Wall sei Zeuge und dieses Denkmal ein Zeugnis dafür, daß ich niemals über diesen Wall hinaus zu dir kommen will und daß auch du niemals in böser Absicht über diesen Wall oder über dieses Denkmal hinaus zu mir kommen sollst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nahors sei Richter zwischen uns, der Gott ihrer Väter! Jakob aber schwur bei der Furcht seines Vaters Isaak.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Und Jakob brachte ein Opfer auf dem Berge und lud seine Brüder ein zu essen; und sie aßen und übernachteten auf dem Berg.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Und Laban stand am Morgen früh auf, küßte seine Söhne und Töchter, segnete sie, ging und kehrte wieder an seinen Ort zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Jakob aber ging seines Weges; da begegneten ihm Engel Gottes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Und als er sie sah, sprach Jakob: Das ist das Heerlager Gottes! Und er nannte jenen Ort Mahanaim.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Und Jakob sandte Boten vor sich her zu seinem Bruder Esau ins Land Seir, das Gefilde Edom.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Diesen gebot er und sprach: Also sollt ihr zu meinem Herrn Esau sagen: Solches läßt dir dein Knecht Jakob melden: Ich bin bei Laban in der Fremde gewesen und habe mich bisher bei ihm aufgehalten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'und ich habe Rinder, Esel und Schafe, Knechte und Mägde bekommen und lasse dir solches anzeigen, damit ich Gnade vor deinen Augen finde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Die Boten kehrten wieder zu Jakob zurück und berichteten ihm: Wir sind zu deinem Bruder Esau gekommen; der zieht dir auch entgegen und vierhundert Mann mit ihm!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Da fürchtete sich Jakob sehr und es ward ihm bange; und er teilte das Volk, das bei ihm war, und die Schafe, Rinder und Kamele in zwei Lager;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'denn er sprach: Wenn Esau gegen das eine Lager kommt und es schlägt, so kann doch das andere entrinnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Und Jakob sprach: Gott meines Vaters Abraham und Gott meines Vaters Isaak, HERR, der du zu mir gesagt hast: Kehre wieder in dein Land und zu deiner Verwandtschaft zurück; ich will dir wohltun!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Ich bin zu gering aller Barmherzigkeit und Treue, die du an deinem Knechte bewiesen hast! Denn ich hatte nur einen Stab, als ich über diesen Jordan ging, und nun bin ich zu zwei Heeren geworden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Errette mich doch aus der Hand meines Bruders, aus der Hand Esaus; denn ich fürchte ihn; er könnte kommen und mich schlagen, die Mutter samt den Kindern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Du aber hast gesagt: Ich will dir wohltun und deinen Samen machen wie den Sand am Meere, der vor Menge nicht zu zählen ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Und er brachte die Nacht daselbst zu und nahm von dem, was ihm in die Hände kam, als Geschenk für seinen Bruder Esau:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'zweihundert Ziegen, zwanzig Böcke, zweihundert Schafe, zwanzig Widder,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'dreißig säugende Kamele mit ihren Füllen, vierzig Kühe und zehn Stiere, zwanzig Eselinnen und zehn Eselsfüllen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Und er gab sie in die Hand seiner Knechte, eine jegliche Herde besonders, und sprach zu seinen Knechten: Geht vor mir hinüber und lasset Raum zwischen den einzelnen Herden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Und er befahl dem ersten und sprach: Wenn mein Bruder Esau dir begegnet und dich fragt: Wem gehörst du und wo willst du hin und wem gehört das, was du vor dir her treibst?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'So sollst du antworten: Deinem Knecht Jakob! Es ist ein Geschenk, das er seinem Herrn Esau sendet, und siehe, er kommt selbst hinter uns her.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Desgleichen befahl er auch dem zweiten und dem dritten und allen, die hinter den Herden hergingen, und sprach: So sollt ihr mit Esau reden, wenn ihr ihn antrefft;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'und ihr sollt sagen: Siehe, dein Knecht Jakob kommt auch hinter uns her! Denn er gedachte: Ich will sein Angesicht versöhnen mit dem Geschenk, das vor mir hergeht; darnach will ich sein Angesicht sehen; vielleicht wird er mich gnädig ansehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Und das Geschenk zog vor ihm hinüber; er aber blieb in jener Nacht im Lager.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Er stand aber noch in derselben Nacht auf und nahm seine beiden Weiber und seine beiden Mägde samt seinen elf Kindern und überschritt mit ihnen die Furt Jabbok;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'er nahm sie und führte sie über den Fluß und ließ alles, was er hatte, hinübergehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Jakob aber blieb allein zurück. Da rang ein Mann mit ihm, bis die Morgenröte anbrach.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und da dieser sah, daß er ihn nicht übermochte, schlug er ihn auf das Hüftgelenk, so daß Jakobs Hüftgelenk verrenkt ward über dem Ringen mit ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Und der Mann sprach: Laß mich gehen; denn die Morgenröte bricht an! Jakob aber sprach: Ich lasse dich nicht, du segnest mich denn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Da fragte er ihn: Wie heißest du? Er antwortete: Jakob!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Da sprach er: Du sollst nicht mehr Jakob heißen, sondern Israel; denn du hast mit Gott und Menschen gekämpft und hast gewonnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jakob aber bat und sprach: Tue mir doch deinen Namen kund! Er aber antwortete: Warum fragst du nach meinem Namen? Und er segnete ihn daselbst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Jakob aber nannte den Ort Pniel; denn er sprach: Ich habe Gott von Angesicht zu Angesicht gesehen, und meine Seele ist gerettet worden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Und die Sonne ging ihm auf, als er an Pniel vorüberzog; und er hinkte wegen seiner Hüfte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Darum essen die Kinder Israel bis auf den heutigen Tag die Sehne nicht, welche über das Hüftgelenk läuft, weil er Jakobs Hüftgelenk, die Hüftensehne, geschlagen hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Und Jakob erhob seine Augen und schaute, und siehe, Esau kam und vierhundert Mann mit ihm. Da verteilte er die Kinder zu Lea und zu Rahel und zu den beiden Mägden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Und er stellte die Mägde mit ihren Kindern voran, und Lea mit ihren Kindern hernach, und Rahel mit Joseph zuletzt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Er selbst aber ging ihnen voraus und verneigte sich siebenmal zur Erde, bis er nahe zu seinem Bruder kam.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Da lief ihm Esau entgegen, umarmte ihn, fiel ihm um den Hals und küßte ihn; und sie weinten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Als aber Esau seine Augen erhob, sah er die Weiber und die Kinder und sprach: Gehören diese dir? Er antwortete: Es sind die Kinder, mit welchen Gott deinen Knecht begnadigt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Da traten die Mägde herzu samt ihren Kindern und verneigten sich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Auch Lea kam herbei mit ihren Kindern, und sie verneigten sich; darnach kam Joseph mit Rahel herbei, und auch sie verneigten sich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Und er fragte: Was willst du denn mit jenem ganzen Heer, dem ich begegnet bin? Jakob antwortete: Ich wollte Gnade finden in den Augen meines Herrn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Esau antwortete: Ich habe genug, mein Bruder; behalte, was du hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob antwortete: O nein! Habe ich Gnade vor deinen Augen gefunden, so nimm doch das Geschenk an von meiner Hand; denn deshalb habe ich dein Angesicht gesehen, als sähe ich Gottes Antlitz, und du warst so freundlich gegen mich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch den Segen von mir an, der dir überbracht worden ist; denn Gott hat mich begnadigt und ich bin mit allem versehen. Also drang er in ihn, daß er es annahm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Und Esau sprach: Laß uns aufbrechen und gehen; ich will neben dir herziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Er aber antwortete: Mein Herr weiß, daß die Kinder noch zart sind; dazu habe ich säugende Schafe und Kühe bei mir; wenn sie einen einzigen Tag übertrieben würden, so würde mir die ganze Herde sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mein Herr gehe doch seinem Knechte voraus, ich aber will gemächlich hintennach ziehen, wie eben das Vieh vor mir her und die Kinder gehen mögen, bis ich zu meinem Herrn nach Seir komme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Da sprach Esau: So will ich doch etliche von meinen Leuten bei dir lassen. Er sprach: Warum sollte ich solche Gunst finden vor den Augen meines Herrn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Also kehrte Esau am gleichen Tag wieder nach Seir zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jakob aber brach auf nach Sukkot und baute sich daselbst ein Haus und errichtete für seine Herden Schutzhütten; daher wurde der Ort Sukkot genannt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Und Jakob kam wohlbehalten bis zur Stadt Sichem, die im Lande Kanaan liegt, nachdem er aus Mesopotamien gekommen war; und er lagerte sich der Stadt gegenüber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Und er kaufte das Grundstück, auf welchem er sein Zelt aufschlug, von der Hand der Kinder Hemors, des Vaters Sichems, um hundert Kesitha');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'und errichtete daselbst einen Altar; den nannte er »Der starke Gott Israels«.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina aber, Leas Tochter, welche sie dem Jakob geboren hatte, ging aus, um die Töchter des Landes zu sehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Als nun Sichem, der Sohn Hemors, des hevitischen Landesfürsten, sie sah, nahm er sie und tat ihr Gewalt an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Und er wurde anhänglich an Dina, die Tochter Jakobs, und gewann das Mädchen lieb und redete ihr zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Und Sichem sprach zu seinem Vater Hemor: Nimm mir dieses Mägdlein zum Weibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob aber hatte vernommen, daß man seine Tochter Dina entehrt hatte; weil aber seine Söhne beim Vieh auf dem Felde waren, so schwieg er, bis sie kamen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Inzwischen kam Hemor, Sichems Vater, zu Jakob, um mit ihm zu reden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Als aber die Söhne Jakobs solches hörten, kamen sie vom Felde; und die Männer waren schwer beleidigt und sehr entrüstet, daß man eine solche Schandtat an Israel begangen und Jakobs Tochter beschlafen hatte; denn so pflegte man nicht zu tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Hemor aber redete mit ihnen und sprach: Mein Sohn Sichem hängt an eurer Tochter; gebt sie ihm doch zum Weibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Verschwägert euch mit uns; gebt uns eure Töchter und nehmt ihr unsere Töchter!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Bleibt bei uns; das Land soll euch offenstehen; siedelt euch an, bewegt euch frei darin und erwerbt Grundbesitz!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Und Sichem sprach zu ihrem Vater und zu ihren Brüdern: Laßt mich Gnade finden vor euren Augen; was ihr von mir fordert, das will ich geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Mögt ihr von mir noch so viel Morgengabe und Geschenke verlangen, ich will es geben, sobald ihr es fordert; gebt mir nur das Mädchen zum Weibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da antworteten die Söhne Jakobs dem Sichem und seinem Vater Hemor in trügerischer Weise, weil er ihre Schwester Dina entehrt hatte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'und sprachen zu ihnen: Wir können das nicht tun, daß wir unsre Schwester einem unbeschnittenen Manne geben; denn das wäre eine Schande für uns;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'nur unter einer Bedingung können wir euch willfahren, daß ihr nämlich werdet wie wir, indem ihr alles, was männlich ist, beschneiden lasset.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Dann wollen wir euch unsre Töchter geben und uns eure Töchter nehmen und mit euch zusammenwohnen und zu einem Volke werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wollt ihr uns aber nicht gehorchen, daß ihr euch beschneiden lasset, so nehmen wir unsere Tochter und gehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ihre Rede gefiel Hemor und seinem Sohne Sichem wohl;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'und der Jüngling zögerte nicht, solches zu tun; denn er hatte Lust zu der Tochter Jakobs und war der Angesehenste von seines Vaters Hause.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Als nun Hemor und sein Sohn Sichem zum Tor ihrer Stadt kamen, redeten sie mit den Bürgern ihrer Stadt und sprachen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Diese Leute meinen es gut mit uns; sie sollen im Lande wohnen und verkehren! Hat doch das Land Raum genug für sie. Wir wollen uns ihre Töchter zu Weibern nehmen und ihnen unsre Töchter geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Nur das verlangen sie von uns, wenn sie unter uns wohnen und sich mit uns zu einem Volke verschmelzen sollen, daß wir alles, was männlich ist unter uns, beschneiden, gleichwie auch sie beschnitten sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ihre Herden und ihre Habe und all ihr Vieh werden dann unser sein; lasset uns ihnen nur willfahren, damit sie bei uns bleiben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Da gehorchten dem Hemor und seinem Sohne Sichem alle, die im Tore seiner Stadt aus und eingingen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Es begab sich aber am dritten Tag, da sie wundkrank waren, daß die beiden Söhne Jakobs, Simeon und Levi, Dinas Brüder, ein jeder sein Schwert nahmen und unversehens in die Stadt eindrangen und alles Männliche umbrachten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Auch Hemor und dessen Sohn Sichem töteten sie mit des Schwertes Schärfe und holten Dina aus dem Hause Sichems und verließen die Stadt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Die Söhne Jakobs aber fielen über die Erschlagenen her und plünderten die Stadt, weil man ihre Schwester entehrt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ihre Schafe, Rinder und Esel nahmen sie, samt allem, was in der Stadt und auf dem Felde war;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'dazu führten sie ihre ganze Habe, alle ihre Kinder und Weiber gefangen und raubten alles, was in den Häusern war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Jakob aber sprach zu ihnen: Ihr bringt mich ins Unglück dadurch, daß ihr mich verhaßt macht bei den Einwohnern des Landes, bei den Kanaanitern und Pheresitern, da ich doch nur wenig Leute habe; sie aber werden sich wider mich sammeln und mich schlagen und mich vertilgen samt meinem Haus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Sie aber antworteten: Soll man denn unsere Schwester wie eine Dirne behandeln?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Und Gott sprach zu Jakob: Mache dich auf, ziehe hinauf nach Bethel und wohne daselbst und baue dort einen Altar dem Gott, der dir erschienen ist, da du vor deinem Bruder Esau flohest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da sprach Jakob zu seinem Haus und zu allen, die bei ihm waren: Tut von euch weg die fremden Götter, die unter euch sind, und reinigt euch und wechselt eure Kleider!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'So wollen wir uns aufmachen und nach Bethel hinaufziehen, daß ich daselbst einen Altar errichte dem Gott, der mir geantwortet hat zur Zeit meiner Not, und der mit mir gewesen ist auf dem Wege, den ich gezogen bin!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Da lieferten sie Jakob alle fremden Götter aus, die in ihren Händen waren, samt den Ringen, die sie an ihren Ohren trugen, und Jakob verbarg sie unter der Eiche, die bei Sichem steht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Darnach brachen sie auf; und der Schrecken Gottes fiel auf die umliegenden Städte, daß sie die Söhne Jakobs nicht verfolgten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Als nun Jakob nach Lus kam, das im Lande Kanaan liegt (das ist Bethel), er und alles Volk, das bei ihm war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'baute er daselbst einen Altar und nannte den Ort »El-Bethel«, weil sich Gott ihm daselbst geoffenbart hatte, als er vor seinem Bruder floh.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Da starb Debora, die Amme der Rebekka, und ward begraben unterhalb von Bethel, unter der Eiche, die man Klageeiche nennt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Und Gott erschien Jakob zum zweitenmal, seitdem er aus Mesopotamien gekommen war, und segnete ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Und Gott sprach zu ihm: Dein Name ist Jakob, aber du sollst nicht mehr Jakob heißen, sondern Israel soll dein Name sein! Und so nannte er sich Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Und Gott sprach zu ihm: Ich bin der allmächtige Gott, sei fruchtbar und mehre dich! Ein Volk und eine Völkergemeinde soll von dir kommen, und Könige sollen aus deinen Lenden hervorgehen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'das Land aber, das ich Abraham und Isaak gegeben habe, das will ich dir und deinem Samen nach dir geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Und Gott fuhr auf von ihm an dem Ort, da er mit ihm geredet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Da richtete Jakob eine Säule auf an dem Ort, wo er mit ihm geredet hatte, einen Denkstein, und goß ein Trankopfer darauf aus und schüttete Öl darüber;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'und Jakob nannte den Ort, wo Gott mit ihm geredet hatte, Bethel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Darnach brachen sie von Bethel auf; und als sie nur noch ein Stück Weges bis Ephrata zu gehen hatten, gebar Rahel; und sie hatte eine schwere Geburt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Als ihr aber die Geburt so schwer fiel, sprach die Geburtshelferin: Fürchte dich nicht; du hast auch diesmal einen Sohn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Als ihr aber die Seele entschwand, weil sie am Sterben war, nannte sie seinen Namen Benoni; sein Vater aber nannte ihn Benjamin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Und Rahel starb und ward begraben am Wege nach Ephrata, das ist Bethlehem.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Und Jakob stellte eine Denksäule auf über ihrem Grab; das ist Rahels Grabmal geblieben bis auf diesen Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Und Israel zog weiter und schlug sein Zelt jenseits des Herdenturmes auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Es begab sich aber, während Israel in dem Lande wohnte, daß Ruben sich mit seines Vaters Kebsweib Bilha verging; und Israel vernahm es.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Jakob aber hatte zwölf Söhne. Die Söhne Leas waren diese: Ruben, der erstgeborne Sohn Jakobs, Simeon, Levi, Juda, Issaschar und Sebulon;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'die Söhne Rahels waren Joseph und Benjamin;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'die Söhne Bilhas, Rahels Magd: Dan und Naphtali;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'die Söhne Silpas, Leas Magd: Gad und Asser. Das sind die Söhne Jakobs, die ihm in Mesopotamien geboren wurden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Und Jakob kam zu seinem Vater Isaak gen Mamre, bei Kirjath-Arba, das ist Hebron, woselbst Abraham und Isaak Fremdlinge gewesen sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Und Isaak ward hundertundachtzig Jahre alt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Und Isaak nahm ab, starb und ward zu seinem Volk versammelt, alt und lebenssatt; und seine Söhne Esau und Jakob begruben ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Dies ist das Geschlecht Esaus, welcher Edom heißt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau nahm seine Weiber von den Töchtern Kanaans: Ada, die Tochter Elons, des Hetiters, und Oholibama, die Tochter der Ana, der Tochter Zibeons, des Heviters;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'dazu Basmath, die Tochter Ismaels, Nebajots Schwester.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Und Ada gebar dem Esau den Eliphas. Aber Basmath gebar den Reguel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibama gebar Jehusch und Jaelam und Korah. Das sind die Söhne Esaus, welche ihm im Lande Kanaan geboren wurden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Und Esau nahm seine Weiber und seine Söhne und seine Töchter und alle Seelen seines Hauses, auch seine Habe und all sein Vieh und alle Güter, die er im Lande Kanaan erworben hatte, und zog von seinem Bruder Jakob weg in ein anderes Land.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihre Habe war zu groß, daß sie nicht beieinander wohnen konnten; und das Land, darin sie Fremdlinge waren, mochte sie nicht ertragen wegen ihrer Herden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Also wohnte Esau auf dem Gebirge Seir; Esau ist der Edom.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Dies ist das Geschlecht Esaus, der ein Vater ist der Edomiter auf dem Gebirge Seir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Und also hießen die Söhne Esaus: Eliphas, der Sohn Anas, des Weibes Esaus; Reguel, der Sohn Basmaths, des Weibes Esaus;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Eliphas Söhne aber waren diese: Teman, Omar, Zepho, Gaetam und Kenas.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Und Timna war ein Kebsweib Eliphas, des Sohnes Esaus, die gebar dem Eliphas den Amalek. Das sind die Kinder von Ada, dem Weibe Esaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Aber die Kinder Reguels sind diese: Nahath, Serah, Schamma und Missa. Das sind die Kinder von Basmath, dem Weibe Esaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Die Kinder aber von Oholibama, dem Weibe Esaus, der Tochter der Ana, der Tochter Zibeons, die sie Esau gebar, sind diese: Jehusch, Jaelam und Korah.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Das sind die Fürsten unter den Söhnen Esaus. Die Söhne Eliphas, des ersten Sohnes Esaus, waren diese: Der Fürst Teman, der Fürst Omar, der Fürst Zepho, der Fürst Kenas,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'der Fürst Korah, der Fürst Gaetam, der Fürst Amalek. Das sind die Fürsten von Eliphas im Lande Edom und sind Söhne der Ada.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und das sind die Kinder Reguels, des Sohnes Esaus: Der Fürst Nahat, der Fürst Serah, der Fürst Schamma, der Fürst Missa. Das sind die Fürsten von Reguel im Lande Edom und die Söhne der Basmath, des Weibes Esaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Dies sind die Söhne Oholibamas, des Weibes Esaus: Der Fürst Jehusch, der Fürst Jaelam, der Fürst Korah. Das sind die Fürsten von Oholibama, der Tochter der Ana, des Weibes Esaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Das sind die Kinder Esaus und ihre Fürsten. Er ist der Edom.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Die Söhne Seirs aber, des Horiters, die im Lande wohnten, sind diese: Lotan, Sobal, Zibeon, Ana,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Ezer und Disan. Das sind die Fürsten der Horiter, Kinder des Seir im Lande Edom.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Aber Lotans Kinder waren diese: Hori und Hemam; und Lotans Schwester hieß Timna.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Die Söhne Sobals waren diese: Alwan, Manabath, Ebal, Sepho und Onam.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Die Söhne Zibeons waren: Aja und Ana. Das ist Ana, der in der Wüste die heißen Quellen fand, als er die Esel seines Vaters Zibeon hütete.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Die Kinder Anas waren: Dison und Oholibama, diese ist die Tochter Anas.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Die Söhne Disons waren: Hemdan, Esban, Jithran und Cheran.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Die Söhne Ezers waren: Bilhan, Saewan und Akan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Die Söhne Disans waren: Uz und Aran.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Das sind die Fürsten der Horiter: Der Fürst Lotan, der Fürst Sobal, der Fürst Zibeon, der Fürst Ana,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'der Fürst Dison, der Fürst Ezer, der Fürst Disan. Das sind die Fürsten der Horiter nach ihren Fürstentümern im Lande Seir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Die Könige aber, welche im Lande Edom regiert haben, ehe ein König über die Kinder Israel regierte, sind diese:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, ein Sohn Beors, war König in Edom, und seine Stadt hieß Dinhaba.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Und als Bela starb, ward an seiner Statt König: Jobab, ein Sohn Serahs aus Bozra.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Als Jobab starb, ward Husam aus der Temaniter Land König an seiner Statt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Als Husam starb, ward an seiner Statt König: Hadad, ein Sohn Bedads, welcher die Midianiter auf der Moabiter Gefilde schlug; und seine Stadt hieß Awith.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Als Hadad starb, ward Samla von Masreka König an seiner Statt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Als Samla starb, ward Saul von Rechobot am Flusse König an seiner Statt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Als Saul starb, ward Baal-Hanan, ein Sohn Achbors, König an seiner Statt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Als Baal-Hanan, Achbors Sohn, starb, ward Hadar König an seiner Statt; und seine Stadt hieß Pahu, sein Weib hieß Mehethabeel; eine Tochter der Mathred, der Tochter Mezahabs.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Also hießen die Fürsten von Esau nach ihren Geschlechtern, Orten und Namen: Der Fürst Timna, der Fürst Alwa, der Fürst Jetet,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Fürst Oholibama, der Fürst Ela, der Fürst Pinon,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Fürst Kenas, der Fürst Teman, der Fürst Mibzar,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Fürst Magdiel, der Fürst Iram. Das sind die Fürsten in Edom, wie sie im Lande ihrer Besitzung gewohnt haben. Und Esau ist der Vater der Edomiter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob aber wohnte im Lande, darin sein Vater ein Fremdling war, im Lande Kanaan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Dies ist die Familiengeschichte Jakobs: Joseph war siebzehn Jahre alt, als er mit seinen Brüdern das Vieh hütete, und er war als Knabe bei den Söhnen Bilhas und Silpas, der Weiber seines Vaters; und Joseph brachte die Klagen über sie vor ihren Vater.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel aber hatte Joseph lieber als alle seine Söhne, weil er ihn in seinem Alter bekommen hatte; und er machte ihm einen langen Rock.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Als nun seine Brüder sahen, daß ihr Vater ihn lieber hatte als alle seine Brüder, haßten sie ihn und mochten ihn nicht mehr grüßen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Joseph aber hatte einen Traum und verkündigte ihn seinen Brüdern; da haßten sie ihn noch mehr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Er sprach nämlich zu ihnen: Hört doch, was für einen Traum ich gehabt:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Siehe, wir banden Garben auf dem Feld, und siehe, da richtete sich meine Garbe auf und blieb stehen; eure Garben aber umringten sie und warfen sich vor meiner Garbe nieder!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sprachen seine Brüder zu ihm: Willst du etwa gar unser König werden? Willst du über uns herrschen? Darum haßten sie ihn noch mehr wegen seiner Träume und wegen seiner Reden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Er hatte aber noch einen andern Traum, den erzählte er seinen Brüdern auch und sprach: Seht, ich habe wieder geträumt, und siehe, die Sonne und der Mond und elf Sterne verneigten sich vor mir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Als er aber das seinem Vater und seinen Brüdern erzählte, schalt ihn sein Vater und sprach zu ihm: Was ist das für ein Traum, den du geträumt hast? Sollen etwa ich und deine Mutter und deine Brüder kommen und uns vor dir bis zur Erde verneigen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Und seine Brüder beneideten ihn; sein Vater aber behielt das Wort im Gedächtnis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Als aber seine Brüder nach Sichem gegangen waren, um ihres Vaters Schafe zu weiden,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'sprach Israel zu Joseph: Weiden nicht deine Brüder zu Sichem? Komm, ich will dich zu ihnen senden! Er aber sprach: Siehe, hier bin ich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Da sprach er zu ihm: Geh doch und sieh, ob es wohl stehe um deine Brüder und um die Schafe, und bringe mir Bescheid! Also sandte er ihn aus dem Tale Hebron, und er wanderte nach Sichem.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Da fand ihn ein Mann, als er irreging auf dem Gefilde; der fragte ihn und sprach: Was suchst du?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Er antwortete: Ich suche meine Brüder; sage mir doch, wo sie weiden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Der Mann antwortete: Sie sind von hier fortgezogen; denn ich hörte sie sagen: Kommt, laßt uns gen Dotan ziehen! Da ging Joseph seinen Brüdern nach und fand sie zu Dotan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Als sie ihn nun von ferne sahen, ehe er in ihre Nähe kam, beschlossen sie, ihn meuchlings umzubringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Und sie sprachen zueinander: Seht, da kommt der Träumer her!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Jetzt wollen wir ihn doch töten und in eine Zisterne werfen und sagen, ein böses Tier habe ihn gefressen; so wollen wir sehen, was aus seinen Träumen wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Als Ruben solches hörte, rettete er ihn aus ihren Händen, indem er sprach: Wir wollen ihn nicht ums Leben bringen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Und weiter sprach Ruben zu ihnen: Vergießet kein Blut! Werft ihn in die Zisterne dort in der Wüste, aber legt nicht Hand an ihn! Er wollte ihn aber aus ihrer Hand erretten und ihn wieder zu seinem Vater bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Da nun Joseph zu seinen Brüdern kam, zogen sie ihm den Rock aus, den langen Rock, welchen er trug.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Darnach nahmen sie ihn und warfen ihn in die Zisterne; die Zisterne aber war leer, und es war kein Wasser drin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Darauf setzten sie sich nieder, um zu essen. Als sie aber ihre Augen aufhoben und sich umsahen, siehe, da kam eine Karawane von Ismaelitern vom Gebirge Gilead daher, deren Kamele trugen Tragakanth, Balsam und Ladanum, und zogen hinab nach Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sprach Juda zu seinen Brüdern: Was gewinnen wir damit, daß wir unsern Bruder töten und sein Blut verbergen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt, wir wollen ihn den Ismaelitern verkaufen und nicht selbst Hand an ihn legen; denn er ist unser Bruder, unser Fleisch! Und seine Brüder stimmten zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Als nun die midianitischen Kaufleute vorbeikamen, zogen sie Joseph aus der Zisterne herauf und verkauften ihn den Ismaelitern um zwanzig Silberlinge; die brachten Joseph nach Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Als nun Ruben zur Zisterne zurückkam, siehe, da war kein Joseph mehr in der Zisterne! Da zerriß er sein Kleid,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'kehrte zu seinen Brüdern zurück und sprach: Der Knabe ist verschwunden! Wo soll ich hin?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Sie aber nahmen Josephs Rock und schlachteten einen Ziegenbock, tauchten den Rock in das Blut,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'schickten den langen Rock ihrem Vater und ließen ihm sagen: Das haben wir gefunden; sieh doch, ob es deines Sohnes Rock ist oder nicht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Und er erkannte ihn und sprach: Es ist meines Sohnes Rock! Ein böses Tier hat ihn gefressen! Joseph ist gewiß zerrissen worden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriß seine Kleider und legte einen Sack um seine Lenden und trug Leid um seinen Sohn lange Zeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Da machten sich alle seine Söhne und Töchter auf, um ihn zu trösten; er aber wollte sich nicht trösten lassen, sondern sprach: Ich höre nicht auf zu trauern, bis ich zu meinem Sohn hinabfahre ins Totenreich! Also beweinte ihn sein Vater.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Aber die Midianiter verkauften ihn nach Ägypten, an Potiphar, einen Kämmerer des Pharao, den Obersten der Leibwache.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Es begab sich um jene Zeit, daß Juda von seinen Brüdern hinabzog und sich zu einem Adullamiter wandte, der Hira hieß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Und Juda sah daselbst die Tochter eines Kanaaniters, der Schua hieß, und er nahm sie und kam zu ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Und sie empfing und gebar einen Sohn, den hieß sie Er.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Und sie empfing abermal und gebar einen Sohn, den hieß sie Onan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Sie fuhr fort und gebar einen Sohn, den hieß sie Sela. Er war aber zu Kesib, als sie denselben gebar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Und Juda gab seinem erstgebornen Sohn Er ein Weib, die hieß Tamar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Aber Er, der Erstgeborne Judas, war böse vor dem HERRN, darum tötete ihn der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sprach Juda zu Onan: Komm zu deines Bruders Weib und vollziehe mit ihr die Pflichtehe, daß du deinem Bruder Samen erweckest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Da aber Onan wußte, daß der Same nicht sein eigen sein sollte, ließ er es, wenn er zu seines Bruders Weib ging, auf die Erde fallen und verderbte es, um seinem Bruder keinen Samen zu geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Es gefiel aber dem HERRN übel, was er tat; da tötete er ihn auch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sprach Juda zu Tamar, seines Sohnes Weib: Bleib als Witwe in deines Vaters Hause, bis mein Sohn Sela erwachsen ist! Denn er dachte, vielleicht könnte er auch sterben, wie seine Brüder. Also ging Tamar hin und blieb in ihres Vaters Hause.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Als nun viele Tage verflossen waren, starb Schuas Tochter, Judas Weib. Und nachdem Juda ausgetrauert hatte, ging er hinauf zu seinen Schafherden gen Timna, er und Hira, sein Freund von Adullam.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Da ward der Tamar angesagt: Siehe, dein Schwiegervater geht hinauf nach Timna, seine Schafe zu scheren!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Da legte sie die Witwenkleider von sich, die sie trug, bedeckte sich mit einem Schleier und verhüllte sich und setzte sich ans Tor von Enaim, am Wege nach Timna. Denn sie sah, daß Sela erwachsen war und sie ihm nicht zum Weibe gegeben wurde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Als nun Juda sie sah, glaubte er, sie sei eine Dirne; denn sie hatte ihr Angesicht bedeckt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Und er machte sich zu ihr am Wege und sprach: Laß mich doch zu dir kommen! Denn er wußte nicht, daß sie seines Sohnes Weib war. Sie antwortete: Was willst du mir geben, daß du zu mir kommest?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Er sprach: Ich will dir einen Ziegenbock von der Herde schicken! Sie antwortete: So gib mir ein Pfand, bis du mir ihn schickst!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Er sprach: Was willst du, daß ich dir zum Pfand gebe? Sie antwortete: Deinen Ring und deine Schnur und deinen Stab, den du in deinen Händen hast! Da gab er es ihr und ging zu ihr, und sie ward von ihm schwanger.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Und sie machte sich auf und ging hin und tat ihren Schleier ab und legte wieder ihre Witwenkleider an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda aber sandte den Ziegenbock durch seinen Freund, den Adullamiter, um das Pfand von dem Weibe zurückzuerhalten; aber er fand sie nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Da fragte er die Leute an jenem Ort und sprach: Wo ist die Dirne, die bei Enaim am Wege saß? Sie antworteten: Es ist keine Dirne hier gewesen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Und er kam wieder zu Juda und sprach: Ich habe sie nicht gefunden; dazu sagen die Leute an jenem Ort, es sei keine Dirne dort gewesen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda sprach: So soll sie das Pfand für sich behalten, damit wir nicht zuschanden werden! Siehe, ich habe den Bock geschickt, aber du hast sie nicht gefunden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Aber nach drei Monaten ward Juda angezeigt: Deine Sohnsfrau Tamar hat gehurt, dazu siehe, ist sie von Hurerei schwanger geworden! Juda sprach: Führt sie hinaus, daß sie verbrannt werde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Und als man sie hinausführte, schickte sie zu ihrem Schwiegervater und sprach: Von dem Manne bin ich schwanger geworden, dem das gehört. Und sie sprach: Untersuche doch, wem gehört dieser Ring und die Schnur und der Stab?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda sah genauer zu und sprach: Sie ist gerechter als ich; denn ich habe sie nicht meinem Sohn Sela gegeben! Doch erkannte er sie nicht mehr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Und als sie gebären sollte, siehe, da waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Und als sie gebar, kam eine Hand heraus; da nahm die Hebamme einen roten Faden und band ihn darum und sprach: Der ist zuerst herausgekommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Als dieser aber seine Hand wieder hineinzog, siehe, da kam sein Bruder heraus. Und sie sprach: Warum hast du dir einen solchen Riß gemacht? Und man hieß ihn Perez.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Darnach kam sein Bruder heraus, der den roten Faden um die Hand hatte; man hieß ihn Serach.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Joseph aber war nach Ägypten hinabgeführt worden, und Potiphar, ein ägyptischer Kämmerer des Pharao, der Oberste der Leibwache, hatte ihn von der Hand der Ismaeliter erworben, die ihn dorthin gebracht hatten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Und der HERR war mit Joseph, und er hatte Glück und durfte bleiben im Hause seines ägyptischen Herrn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Und als sein Gebieter sah, daß der HERR mit ihm war, und daß der HERR in seiner Hand alles gelingen ließ, was er unternahm,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'da fand Joseph Gnade in seinen Augen und durfte ihn bedienen; und er setzte ihn zum Aufseher über sein Haus und vertraute ihm alles an, was er hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und von der Zeit an, da er ihn über sein Haus und über alle seine Güter gesetzt hatte, segnete der HERR des Ägypters Haus um Josephs willen, also daß der Segen des HERRN in allem war, was er hatte, im Hause und auf dem Felde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Da überließ er alles, was er hatte, Josephs Hand und kümmerte sich um gar nichts mehr als um das Brot, das er aß. Joseph aber war von schöner Gestalt und hübschem Aussehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Es begab sich aber nach diesen Geschichten, daß seines Herrn Weib ihre Augen auf Joseph warf und zu ihm sprach: Schlaf bei mir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er aber weigerte sich und sprach zu dem Weibe seines Herrn: Siehe, mein Herr verläßt sich auf mich und kümmert sich um nichts, was im Hause vorgeht, und hat mir alles anvertraut, was ihm gehört;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'es ist niemand größer in diesem Hause, als ich, und es gibt nichts, das er mir vorenthalten hätte, ausgenommen dich, weil du sein Weib bist! Wie sollte ich nun ein solch großes Übel tun und wider Gott sündigen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Und wiewohl sie ihm Tag für Tag zuredete, hörte er doch nicht auf sie, daß er sich zu ihr gelegt oder sich mit ihr vergangen hätte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Es begab sich aber an einem solchen Tage, als er ins Haus kam, um sein Geschäft zu besorgen, und niemand von den Hausgenossen zugegen war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'daß sie ihn bei seinem Kleide ergriff und zu ihm sprach: Schlaf bei mir! Er aber ließ das Kleid in ihrer Hand und floh und lief zum Hause hinaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Als sie nun sah, daß er das Kleid in ihrer Hand gelassen hatte und entflohen war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'rief sie die Hausgenossen herbei und sprach zu ihnen: Seht, er hat uns den Hebräer ins Haus gebracht, daß er Mutwillen mit uns triebe! Er kam zu mir herein, um bei mir zu schlafen; ich aber habe aus Leibeskräften geschrieen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Als er nun hörte, daß ich meine Stimme erhob und schrie, ließ er sein Kleid neben mir liegen und floh zur Tür hinaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Und sie ließ sein Kleid neben sich liegen, bis sein Herr nach Hause kam.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Dem erzählte sie die gleiche Geschichte und sprach: Der hebräische Knecht, den du uns gebracht hast, ist zu mir hereingekommen, um Mutwillen mit mir zu treiben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'als ich aber meine Stimme erhob und schrie, ließ er sein Kleid neben mir liegen und entfloh!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Als nun sein Herr die Rede seines Weibes hörte, daß sie sprach: So und so hat mir dein Knecht getan! da entbrannte sein Zorn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Und Josephs Herr nahm ihn und warf ihn ins Gefängnis, dorthin, wo die Gefangenen des Königs lagen; so war er daselbst im Gefängnis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Aber der HERR war mit Joseph und verschaffte ihm Gunst und schenkte ihm Gnade vor den Augen des Kerkermeisters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Und der Kerkermeister gab alle Gefangenen, die im Kerker waren, in Josephs Hand, und alles, was es dort zu tun gab, das besorgte dieser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der Kerkermeister kümmerte sich nicht im geringsten um irgend etwas, das er in die Hand nahm; denn der HERR war mit ihm, und der HERR ließ alles gelingen, was er unternahm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Nach diesen Geschichten begab es sich, daß der Mundschenk des Königs von Ägypten und der oberste Bäcker sich gegen ihren Herrn, den König von Ägypten, versündigten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Da ward der Pharao zornig über seine beiden Höflinge, den obersten Mundschenk und den obersten Bäcker,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'und ließ sie in Gewahrsam legen im Hause des Obersten der Leibwache, in den Kerker, in welchem Joseph gefangen lag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Oberste der Leibwache übertrug Joseph die Sorge für sie, und er diente ihnen, und sie waren längere Zeit im Gefängnis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Und es träumte ihnen beiden in einer Nacht, einem jeden ein Traum von besonderer Bedeutung, dem Mundschenken und dem Bäcker des Königs von Ägypten, die in dem Kerker gefangen lagen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Als nun Joseph am Morgen zu ihnen kam, sah er sie an und siehe, sie waren verdrießlich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Da fragte er diese Höflinge des Pharao, die mit ihm im Gefängnis seines Herrn waren, und sprach: Warum macht ihr heute ein so finsteres Gesicht?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Sie antworteten ihm: Uns hat geträumt; und nun ist kein Ausleger da! Joseph sprach zu ihnen: Kommen nicht die Auslegungen von Gott? Erzählt mir\'s doch!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzählte der oberste Mundschenk dem Joseph seinen Traum und sprach: In meinem Traum, siehe, da war ein Weinstock vor mir,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'und an dem Weinstock waren drei Schosse; und er grünte und blühte und seine Trauben wurden reif.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ich aber hatte den Becher des Pharao in der Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Joseph sprach zu ihm: Dies ist die Bedeutung: Die drei Schosse sind drei Tage;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'in drei Tagen wird der Pharao dein Haupt erheben und dich wieder in dein Amt einsetzen, daß du dem Pharao den Becher reichest, wie du früher zu tun pflegtest, da du noch sein Mundschenk warst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Solltest du dann etwa an mich denken, wenn es dir gut geht, so tue Barmherzigkeit an mir und empfiehl mich dem Pharao, daß er mich aus diesem Hause entlasse;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'denn ich bin aus dem Lande der Hebräer gestohlen worden und habe auch hier gar nichts getan, wofür man mich einzusperren brauchte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Da nun der oberste Bäcker sah, daß Joseph eine gute Auslegung gegeben hatte, sprach er zu ihm: Siehe, in meinem Traum trug ich drei Körbe auf meinem Kopf,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'und im obersten Korb war allerlei Backwerk für den Pharao; und die Vögel fraßen es mir aus dem Korb, der auf meinem Haupte war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Da antwortete Joseph und sprach: Dies ist die Bedeutung: Die drei Körbe sind drei Tage;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'in drei Tagen wird der Pharao dich hinrichten und ans Holz hängen lassen, daß die Vögel dein Fleisch fressen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Und es begab sich am dritten Tag, dem Geburtstag des Pharao, als er für alle seine Knechte ein Mahl veranstaltete, daß er das Haupt des obersten Mundschenken und des obersten Bäckers unter allen seinen Knechten erhob;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'und den obersten Mundschenken setzte er wieder ein in sein Schenkamt, daß er dem Pharao den Becher in die Hand geben durfte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'aber den obersten Bäcker ließ er hängen; wie Joseph ihnen gedeutet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Aber der oberste Mundschenk dachte nicht an Joseph, sondern vergaß ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Es begab sich aber nach zwei Jahren, da hatte der Pharao einen Traum, und siehe, er stand am Nil.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Und siehe, aus dem Nil stiegen sieben schöne und wohlgenährte Kühe herauf, die im Nilgras weideten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Nach diesen aber stiegen sieben andere Kühe aus dem Nil herauf, von häßlicher Gestalt und magerem Leib; die traten neben die Kühe am Ufer des Nils.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Und die sieben häßlichen, mageren Kühe fraßen die sieben schönen, wohlgenährten Kühe. Da erwachte der Pharao.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Er schlief aber wieder ein und träumte zum zweitenmal, und siehe, da wuchsen sieben Ähren auf einem einzigen Halm, die waren voll und gut;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'nach denselben aber siehe, da sproßten sieben dünne und vom Ostwind versengte Ähren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Und die sieben dünnen Ähren verschlangen die sieben schweren und vollen Ähren. Da erwachte der Pharao und siehe, es war ein Traum!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Da sich aber sein Geist beunruhigte, ließ er am Morgen alle ägyptischen Wahrsager und Weisen rufen und erzählte ihnen seinen Traum; aber da war keiner, der ihn dem Pharao auslegen konnte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da sprach der oberste Mundschenk zum Pharao: Ich gedenke heute meiner Sünde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Als der Pharao über seine Knechte zornig war und mich im Hause des Obersten der Leibwache in Gewahrsam legte, mitsamt dem obersten Bäcker,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'da träumte uns in der gleichen Nacht, mir und ihm, einem jeden ein Traum von besonderer Bedeutung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Und daselbst war ein hebräischer Jüngling bei uns, ein Knecht des Obersten der Leibwache; dem erzählten wir es, und er legte uns unsre Träume aus, einem jeden ganz genau.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und so wie er es uns auslegte, so ist es gekommen; mich hat man wieder in mein Amt eingesetzt, und ihn hat man gehängt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte der Pharao hin und ließ Joseph rufen. Und sie entließen ihn eilends aus dem Loch. Er aber ließ sich scheren und wechselte seine Kleider und ging zum Pharao hinein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Und der Pharao sprach zu Joseph: Ich habe einen Traum gehabt, aber es kann ihn niemand auslegen; nun vernahm ich von dir, wenn du einen Traum hörest, so legest du ihn auch aus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph antwortete dem Pharao und sprach: Nicht mir steht dies zu. Möge Gott antworten, was dem Pharao Heil bringt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Da sprach der Pharao zu Joseph: Siehe, in meinem Traum stand ich am Ufer des Nils;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'und siehe, da stiegen aus dem Nil sieben wohlgenährte Kühe von schöner Gestalt herauf, die im Nilgras weideten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Und siehe, nach ihnen stiegen sieben andere Kühe herauf, geringe Ware, und von sehr häßlicher Gestalt und magerem Leib, wie ich in ganz Ägyptenland keine so häßlichen gesehen habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Und diese mageren, häßlichen Kühe fraßen die sieben ersten wohlgenährten Kühe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Als sie aber die verschlungen hatten, merkte man nichts davon; denn sie waren so häßlich wie zuvor. Da erwachte ich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Und ich sah weiter in meinem Traum, und siehe, sieben volle und gute Ähren wuchsen an einem einzigen Halme auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Und siehe, nach denselben sproßten sieben dürre, magere und vom Ostwind versengte Ähren hervor;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'und die sieben mageren Ähren verschlangen die sieben guten. Solches habe ich den Schriftkundigen erzählt, aber keiner kann es mir erklären.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Da sprach Joseph zum Pharao: Was dem Pharao geträumt hat, ist eins: Gott hat dem Pharao angezeigt, was er tun will.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben guten Kühe sind sieben Jahre, und die sieben guten Ähren sind auch sieben Jahre; es ist einerlei Traum.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Die sieben mageren und häßlichen Kühe, die nach jenen heraufkamen, sind sieben Jahre; desgleichen die sieben leeren, vom Ostwind versengten Ähren; es werden sieben Hungerjahre sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Darum sagte ich zu dem Pharao, Gott habe dem Pharao gezeigt, was er tun will.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Siehe, es kommen sieben Jahre, da wird großer Überfluß in ganz Ägyptenland herrschen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'aber nach denselben werden sieben Hungerjahre eintreten, da man all diesen Überfluß im Lande Ägypten vergessen wird;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'und die Hungersnot wird das Land aufzehren, daß man nichts mehr merken wird von dem Überfluß, infolge der Hungersnot, die hernach kommt; denn sie wird sehr drückend sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Daß es aber dem Pharao zum zweitenmal geträumt hat, das bedeutet, daß das Wort gewiß von Gott kommt, und daß Gott es eilends ausführen wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Und nun sehe der Pharao nach einem verständigen und weisen Mann und setze ihn über Ägyptenland;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'der Pharao verschaffe und setze Aufseher über das Land und lasse in den sieben Jahren des Überflusses den fünften Teil der Ernte vom Lande Ägypten erheben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Also soll man alle Nahrung dieser sieben künftigen guten Jahre sammeln und Getreide aufspeichern zur Verfügung des Pharaos, und solche Nahrung in den Städten verwahren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Und diese Nahrung soll dem Land als Vorrat dienen für die sieben Hungerjahre, welche in Ägyptenland eintreten werden, daß das Land durch die Hungersnot nicht entvölkert werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Diese Rede gefiel dem Pharao und allen seinen Knechten wohl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Und der Pharao sprach zu seinen Knechten: Können wir einen Mann finden wie diesen, in welchem der Geist Gottes ist?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Der Pharao sprach zu Joseph: Nachdem Gott dir solches alles kundgetan hat, ist keiner so verständig und weise wie du!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst über mein Haus sein, und deinem Befehl soll mein ganzes Volk gehorchen; nur um den Thron will ich höher sein als du.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Weiter sprach der Pharao zu Joseph: Siehe, ich habe dich über ganz Ägyptenland gesetzt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Und der Pharao nahm den Siegelring von seiner Hand und steckte ihn an Josephs Hand und bekleidete ihn mit weißer Leinwand und legte eine goldene Kette um seinen Hals');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'und ließ ihn auf seinem zweiten Wagen fahren; und man rief vor ihm aus: »Beugt eure Knie!« Und also wurde er über ganz Ägyptenland gesetzt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und der Pharao sprach zu Joseph: Ich bin der Pharao, und ohne dich soll niemand in ganz Ägyptenland die Hand oder den Fuß erheben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und der Pharao nannte den Joseph Zaphenat-Paneach und gab ihm Asnath, die Tochter Potipheras, des Priesters zu On, zum Weibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Und Joseph zog aus durch ganz Ägyptenland. Er war aber dreißig Jahre alt, da er vor dem Pharao stand. Und er ging vom Pharao aus und bereiste ganz Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Und das Land trug in den sieben Jahren des Überflusses haufenweise.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Und er sammelte allen Ertrag der sieben Jahre, in denen in Ägyptenland Überfluß herrschte, und tat die Nahrungsmittel in die Städte; nämlich den Ertrag der Felder rings um die Städte brachte er in diese.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Und Joseph speicherte Getreide auf wie Sand am Meer, bis er es nicht mehr messen konnte; denn es war unermeßlich viel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Ehe aber die teure Zeit kam, wurden Joseph zwei Söhne geboren; die gebar ihm Asnath, die Tochter Potipheras, des Priesters zu On.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Und Joseph nannte den Erstgebornen Manasse; denn er sprach: Gott hat mich vergessen lassen alle meine Mühsal und das ganze Haus meines Vaters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den zweiten aber nannte er Ephraim; denn er sprach: Gott hat mich fruchtbar gemacht im Lande meines Elends.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Als nun die sieben Jahre des Überflusses im Lande Ägypten verflossen waren,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'da brachen die sieben Hungerjahre an, wie Joseph vorausgesagt hatte. Und es entstand eine Hungersnot in allen Ländern; aber in ganz Ägyptenland war Brot.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Und als Ägypten Hunger litt und das Volk zum Pharao um Brot schrie, da sprach der Pharao zu allen Ägyptern: Geht hin zu Joseph; was er euch sagen wird, das tut!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Und da die Hungersnot im ganzen Lande herrschte, tat Joseph alle Kornspeicher auf und verkaufte den Ägyptern Getreide; denn die Hungersnot nahm überhand in Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Und alle Welt kam nach Ägypten, um bei Joseph Korn zu kaufen; denn es herrschte allenthalben große Hungersnot.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Als aber Jakob sah, daß Korn in Ägypten war, sprach er zu seinen Söhnen: Was sehet ihr einander an?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Siehe, ich höre, es gebe in Ägypten Korn; reiset dort hinab und kauft uns daselbst Getreide, daß wir leben und nicht sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Also machten sich zehn Brüder Josephs auf den Weg, um in Ägypten Getreide zu kaufen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Benjamin aber, Josephs Bruder, sandte Jakob nicht mit den Brüdern; denn er sprach: Es könnte ihm ein Unfall begegnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'So kamen nun die Söhne Israels, Getreide zu kaufen, mit andern, die auch gingen, weil im Lande Kanaan Hungersnot war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Joseph aber war Regent über das Land; er verkaufte allem Volk des Landes Korn. Darum kamen Josephs Brüder und fielen vor ihm nieder, das Angesicht zur Erde gewandt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Da nun Joseph seine Brüder sah, erkannte er sie, verstellte sich aber und redete hart mit ihnen und fragte sie: Wo kommt ihr her? Sie antworteten: Aus dem Lande Kanaan, um Speise zu kaufen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Aber wiewohl Joseph seine Brüder kannte, kannten sie ihn doch nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Und Joseph gedachte der Träume, die er von ihnen geträumt hatte, und sprach zu ihnen: Kundschafter seid ihr; zu sehen, wo das Land offen ist, darum seid ihr gekommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie antworteten ihm: Nein, mein Herr; deine Knechte sind gekommen, um Speise zu kaufen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir sind alle eines Mannes Söhne; wir sind redlich; deine Knechte sind niemals Kundschafter gewesen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Er aber sprach zu ihnen: Doch, ihr seid gekommen zu sehen, wo das Land offen ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie antworteten: Wir, deine Knechte, sind zwölf Brüder, eines einzigen Mannes Söhne im Lande Kanaan, und siehe, der jüngste ist gegenwärtig bei unserm Vater, und einer ist nicht mehr vorhanden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Aber Joseph sprach zu ihnen: Es ist so, wie ich euch gesagt habe: Ihr seid Kundschafter!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran will ich euch prüfen; so wahr der Pharao lebt, sollt ihr von hier nicht fortgehen, es komme denn euer jüngster Bruder her!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Schickt einen von euch hin, daß er euren Bruder hole, ihr aber sollt in Haft behalten werden; so wird es sich herausstellen, ob ihr mit der Wahrheit umgeht; wo aber nicht, dann seid ihr Kundschafter, so wahr der Pharao lebt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Und er tat sie alle zusammen in Verwahrung, drei Tage lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Am dritten Tag aber sprach Joseph zu ihnen: Um euer Leben zu fristen, macht es so; denn ich fürchte Gott:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Wenn ihr aufrichtig seid, so lasset einen von euch Brüdern hier gebunden im Gefängnis zurück; ihr andern aber geht hin und bringet heim, was eure Familien zur Stillung des Hungers bedürfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Euren jüngsten Bruder aber bringet zu mir, so wird man euren Worten glauben und ihr sollt nicht sterben. Und sie taten also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Sie sagten aber zueinander: Wahrlich, das haben wir an unserm Bruder verschuldet, dessen Seelenangst wir sahen, als er uns um Erbarmen anflehte; wir aber hörten nicht auf ihn. Darum ist diese Not über uns gekommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben antwortete und sprach zu ihnen: Habe ich es euch nicht gesagt, ihr solltet euch an dem Knaben nicht versündigen? Aber ihr wolltet ja nicht hören! Darum seht, nun wird sein Blut gefordert!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie wußten aber nicht, daß Joseph sie verstand; denn er verkehrte mit ihnen durch einen Dolmetscher.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Und er wandte sich von ihnen und weinte, kehrte aber wieder zu ihnen zurück und redete mit ihnen. Darauf nahm er Simeon von ihnen weg und band ihn vor ihren Augen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Und Joseph gab Befehl, daß man ihre Säcke mit Getreide fülle und einem jeden sein Geld wieder in seinen Sack lege und ihnen auch Zehrung mit auf die Reise gebe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Und man tat ihnen also. Da luden sie ihr Getreide auf ihre Esel und gingen davon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Als aber einer seinen Sack öffnete, um in der Herberge seinem Esel Futter zu geben, da sah er sein Geld, und siehe, es lag oben im Sack!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Und er sprach zu seinen Brüdern: Mein Geld ist mir zurückgegeben worden; seht, es ist in meinem Sack! Da verging ihnen aller Mut; und sie sprachen zitternd einer zum andern: Ach, warum hat uns Gott das getan?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Als sie aber zu ihrem Vater Jakob ins Land Kanaan kamen, erzählten sie ihm alles, was ihnen begegnet war und sprachen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Der Mann, der des Landes Herr ist, redete hart mit uns und behandelte uns als Kundschafter des Landes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Wir aber sagten: Wir sind aufrichtig und sind keine Kundschafter;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'wir sind unser zwölf Brüder, Söhne unsres Vaters; einer ist nicht mehr da, der jüngste aber ist gegenwärtig bei unserm Vater im Lande Kanaan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Da sprach der Mann, des Landes Herr, zu uns: Daran will ich erkennen, ob ihr aufrichtig seid: Laßt einen eurer Brüder bei mir zurück und geht und nehmt die Notdurft für eure Haushaltungen mit;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'und bringet euren jüngeren Bruder zu mir, damit ich erkenne, daß ihr keine Kundschafter, sondern aufrichtig seid. Dann will ich euch euren Bruder herausgeben und ihr könnt ungehindert im Lande verkehren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Als sie aber ihre Säcke ausleerten, siehe, da hatte jeder sein Bündlein Geld in seinem Sack! Als sie und ihr Vater ihre Bündlein Geld sahen, erschraken sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Und ihr Vater Jakob sprach zu ihnen: Ihr habt mich meiner Kinder beraubt! Joseph ist nicht mehr, Simeon ist nicht mehr, und Benjamin wollt ihr nehmen; es geht alles über mich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Da sprach Ruben zu seinem Vater: Du kannst meine beiden Söhne töten, wenn ich ihn dir nicht wiederbringe; übergib ihn nur meiner Hand, ich will ihn dir wiederbringen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Er aber sprach: Mein Sohn soll nicht mit euch hinabziehen; denn sein Bruder ist tot, und er ist allein übriggeblieben. Sollte ihm ein Unfall begegnen auf dem Wege, den ihr geht, so würdet ihr meine grauen Haare vor Kummer ins Totenreich hinunterbringen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Aber die Hungersnot drückte das Land.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Und als sie alles Korn aufgezehrt hatten, das sie aus Ägypten hergebracht, sprach ihr Vater zu ihnen: Geht und kauft uns wieder ein wenig Getreide zur Speise!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Aber Juda antwortete und sprach zu ihm: Der Mann hat uns ernstlich bezeugt und gesagt: Ihr sollt mein Angesicht nicht sehen, es sei denn euer Bruder mit euch!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Sendest du nun unsern Bruder mit uns, so wollen wir hinabziehen und dir Getreide zur Speise kaufen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Lässest du ihn aber nicht gehen, so reisen wir nicht hinab; denn der Mann hat zu uns gesagt: Ihr sollt mein Angesicht nicht sehen, es sei denn euer Bruder mit euch!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Da sprach Israel: Warum habt ihr mir das zuleid getan, daß ihr dem Mann verrietet, daß ihr noch einen Bruder habt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Sie sprachen: Der Mann forschte so genau nach uns und unsrer Verwandtschaft und sprach: Lebt euer Vater noch? Habt ihr noch einen Bruder? Da gaben wir ihm Auskunft, wie es sich verhielte. Konnten wir denn wissen, daß er sagen würde: Bringt euren Bruder herab?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Und Juda sprach zu seinem Vater Israel: Gib mir den Knaben mit, so wollen wir uns auf den Weg machen, daß wir leben und nicht sterben, wir und du und unsre Kinder!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich will für ihn bürgen, von meiner Hand sollst du ihn fordern; wenn ich ihn dir nicht wiederbringe und ihn vor dein Angesicht stelle, so habe ich mein ganzes Leben verwirkt vor dir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Wenn wir nicht gezögert hätten, so wären wir jetzt schon zum zweitenmal zurück!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da sprach ihr Vater Israel zu ihnen: Muß es denn doch sein, so macht es so: Nehmt in eure Säcke von den berühmtesten Erzeugnissen des Landes und bringt sie dem Mann zum Geschenk: ein wenig Balsam, ein wenig Honig, Tragakanth und Ladanum, Pistazien und Mandeln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Nehmt auch den doppelten Betrag Geld in eure Hände und erstattet das zurückerhaltene Geld, das oben in euren Säcken war, eigenhändig wieder; vielleicht ist da ein Irrtum geschehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Und nehmt euren Bruder mit, macht euch auf und kehrt zu dem Manne zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Und der allmächtige Gott gebe euch Barmherzigkeit vor dem Manne, daß er euch euren andern Bruder wieder mitgebe und Benjamin! Ich aber, wenn ich doch der Kinder beraubt sein soll, so sei ich ihrer beraubt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Da nahmen die Männer das Geschenk und doppelt soviel Geld in ihre Hand, und auch Benjamin, machten sich auf und reisten nach Ägypten und traten vor Joseph.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Als nun Joseph den Benjamin bei ihnen sah, sprach er zu seinem Hofmeister: Führe die Männer ins Haus hinein, schlachte und richte zu; denn sie sollen mit mir zu Mittag essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Der Mann tat, wie ihm Joseph gesagt hatte, und führte die Männer in Josephs Haus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Da fürchteten sich die Männer, weil sie in Josephs Haus geführt wurden und sprachen: Man führt uns hinein um des Geldes willen, welches das erstemal wieder in unsre Säcke gekommen ist, daß man über uns herfalle und uns überwältige und uns zu Sklaven mache samt unsern Eseln!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Darum wandten sie sich an den Mann, der über Josephs Haus war und redeten vor der Haustür mit ihm');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'und sprachen: Bitte, mein Herr, wir sind schon einmal hier gewesen, um Korn zu kaufen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'da ist es uns begegnet, als wir in die Herberge kamen und unsre Säcke öffneten, daß eines jeglichen Geld oben in seinem Sacke lag, unser Geld nach seinem vollen Gewicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Nun haben wir es wieder mit uns gebracht und anderes Geld dazu, um Getreide zu kaufen; wir wissen nicht, wer unser Geld in unsre Säcke gelegt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Er sprach zu ihnen: Friede sei mit euch! Fürchtet euch nicht! Euer Gott und eures Vaters Gott hat euch einen Schatz in eure Säcke gegeben! Euer Geld ist mir zugekommen. Und er führte Simeon zu ihnen hinaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Und der Mann führte die Männer in Josephs Haus und gab ihnen Wasser, daß sie ihre Füße wuschen, und gab ihren Eseln Futter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Sie aber richteten das Geschenk zu, bis Joseph kam zur Mittagszeit; denn sie hatten gehört, daß sie dort essen sollten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Als nun Joseph nach Hause kam, brachten sie ihm das Geschenk, das in ihren Händen war, ins Haus und fielen vor ihm zur Erde nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Und er fragte sie, wie es ihnen gehe und sprach: Geht es auch eurem alten Vater wohl, von dem ihr mir sagtet? Lebt er noch?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Sie antworteten: Es geht deinem Knechte, unsrem Vater, wohl; er lebt noch! Und sie verbeugten sich und fielen vor ihm nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Als er aber seine Augen erhob und seinen Bruder Benjamin sah, seiner Mutter Sohn, fragte er: Ist das euer jüngerer Bruder, von dem ihr mir gesprochen habt? Und er sprach: Gott sei dir gnädig, mein Sohn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Darnach aber zog sich Joseph zurück; denn sein Herz entbrannte gegen seinen Bruder; und er suchte einen Ort auf, wo er weinen konnte, und ging in sein Gemach und weinte daselbst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Dann aber wusch er sein Angesicht, ging hinaus, nahm sich zusammen und sprach: Tragt das Essen auf!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Und man trug ihm und ihnen besonders auf, desgleichen den Ägyptern, die mit ihm aßen, auch besonders; denn die Ägypter dürfen nicht mit den Hebräern zusammen essen, es ist ihnen ein Greuel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Sie mußten aber vor ihm sitzen, der Erstgeborene zu oberst und der jüngste zu unterst, so daß die Männer einander verwundert anschauten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Und man trug ihnen von dem auf, was vor seinem Angesichte gestanden hatte; dem Benjamin aber ward fünfmal mehr aufgetragen als ihnen allen. Und sie tranken und wurden fröhlich mit ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Und Joseph befahl seinem Hofmeister und sprach: Fülle den Männern die Säcke mit Speise, soviel sie tragen mögen, und lege eines jeden Geld oben in seinen Sack;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'meinen Becher aber, den silbernen Becher, lege oben in den Sack des Jüngsten samt dem Geld für das Korn! Er tat, wie Joseph ihm gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Und als der Morgen anbrach, ließ man die Männer samt ihren Eseln ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Als sie aber zur Stadt hinaus und noch nicht weit gekommen waren, sprach Joseph zu seinem Hofmeister: Mache dich auf, jage den Männern nach, und wenn du sie eingeholt hast, sprich zu ihnen: Warum habt ihr Gutes mit Bösem vergolten?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist\'s nicht das, woraus mein Herr trinkt und wodurch er zu weissagen pflegt? Da habt ihr übel getan!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Als er sie nun eingeholt hatte, redete er mit ihnen also.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Sie aber sprachen: Warum redet mein Herr also mit uns? Das sei ferne von deinen Knechten, so etwas zu tun!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Siehe, wir haben dir das Geld, das wir oben in unsren Säcken fanden, aus dem Lande Kanaan wieder zurückgebracht; wie sollten wir denn aus dem Hause deines Herrn Silber oder Gold gestohlen haben?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Bei welchem von deinen Knechten aber etwas gefunden wird, der soll sterben, und wir andern wollen deines Herrn Knechte sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Er aber sprach: Sollte es jetzt gar noch nach euren Worten gehen? Nein, sondern bei wem er gefunden wird, der sei mein Knecht; ihr andern aber sollt ungestraft bleiben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Da ließen sie eilends ein jeder seinen Sack zur Erde gleiten und öffneten ein jeder seinen Sack.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Er aber fing an zu suchen beim Ältesten und kam bis zum Jüngsten. Da fand sich der Becher in Benjamins Sack!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da zerrissen sie ihre Kleider und legten ein jeder seine Last auf seinen Esel und kehrten wieder in die Stadt zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Und Juda ging mit seinen Brüdern in Josephs Haus (denn er war noch daselbst) und sie fielen vor ihm auf die Erde nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph aber sprach zu ihnen: Was ist das für eine Tat, die ihr begangen habt? Wußtet ihr nicht, daß ein solcher Mann, wie ich bin, erraten kann?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda antwortete: Was sollen wir meinem Herrn sagen? Was sollen wir reden, und wie sollen wir uns rechtfertigen? Gott hat die Missetat deiner Knechte gefunden! Siehe, wir sind unsres Herrn Knechte, wir und der, in dessen Hand der Becher gefunden worden ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Er aber sprach: Das sei ferne von mir, solches zu tun! Der Mann, in dessen Hand der Becher gefunden worden ist, soll mein Knecht sein; ihr aber zieht in Frieden zu eurem Vater hinauf!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda näher zu ihm hinzu und sprach: Bitte, mein Herr, laß deinen Knecht ein Wort reden vor den Ohren meines Herrn, und dein Zorn entbrenne nicht über deine Knechte; denn du bist wie der Pharao!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herr fragte seine Knechte und sprach: Habt ihr noch einen Vater oder Bruder?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Da antworteten wir meinem Herrn: Wir haben einen alten Vater und einen jungen Knaben, der ihm in seinem Alter geboren ist, und dessen Bruder ist tot, und er ist allein übriggeblieben von seiner Mutter, und sein Vater hat ihn lieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Da sprachst du zu deinen Knechten: Bringt ihn zu mir herab, damit ich ihn sehen kann!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Da sprachen wir zu meinem Herrn: Der Knabe kann seinen Vater nicht verlassen; wenn er seinen Vater verließe, so würde dieser sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Du aber sprachst zu deinen Knechten: Wenn euer jüngster Bruder nicht mit euch herabkommt, so sollt ihr mein Angesicht nicht mehr sehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Als wir nun zu deinem Knechte, unsrem Vater, kamen, verkündigten wir ihm die Worte unsres Herrn;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'und als unser Vater sprach: Geht hin und kaufet uns wieder etwas zu essen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'da antworteten wir: Wir können nicht hinabziehen! Wenn unser jüngster Bruder bei uns ist, dann können wir gehen; denn wir dürfen das Angesicht des Mannes nicht sehen, wenn unser jüngster Bruder nicht bei uns ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Da sprach dein Knecht, unser Vater zu uns: Ihr wisset, daß mir mein Weib zwei Söhne geboren hat;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'einer ist von mir weggegangen, und ich habe ihn bis heute nicht mehr gesehen, so daß ich denken muß, ein wildes Tier habe ihn zerrissen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Nehmt ihr nun diesen auch von mir und es begegnet ihm ein Unfall, so werdet ihr meine grauen Haare durch ein solches Unglück ins Totenreich hinunterbringen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Käme ich nun zu deinem Knechte, meinem Vater, und der Knabe wäre nicht bei mir, an dessen Seele doch seine Seele gebunden ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'so würde es geschehen, wenn er sähe, daß der Knabe nicht da ist, daß er stürbe; und so würden wir, deine Knechte, die grauen Haare deines Knechtes, unsres Vaters, durch den Kummer ins Totenreich hinunterbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Denn dein Knecht hat sich bei meinem Vater für den Knaben verbürgt und versprochen: Wenn ich ihn dir nicht wiederbringe, so habe ich meinem Vater gegenüber mein ganzes Leben verwirkt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Darum will nun dein Knecht als Sklave meines Herrn hier bleiben anstatt des Knaben; der Knabe aber soll mit seinen Brüdern hinaufziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Denn wie könnte ich zu meinem Vater hinaufziehen, ohne daß der Knabe bei mir wäre? Ich möchte das Leid nicht sehen, das meinen Vater träfe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da konnte sich Joseph vor allen, die um ihn herstanden, nicht länger enthalten, sondern rief: Tut jedermann von mir hinaus! Und es stand kein Mensch bei ihm, als Joseph sich seinen Brüdern zu erkennen gab.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Und er weinte laut, so daß die Ägypter und das Haus des Pharao es hörten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Und Joseph sprach zu seinen Brüdern: Ich bin Joseph! Lebt mein Vater noch? Aber seine Brüder konnten ihm nicht antworten, so bestürzt waren sie vor ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Da sprach Joseph zu seinen Brüdern: Tretet doch her zu mir! Als sie nun näher kamen, sprach er zu ihnen: Ich bin Joseph, euer Bruder, den ihr nach Ägypten verkauft habt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Und nun bekümmert euch nicht und ärgert euch nicht darüber, daß ihr mich hierher verkauft habt; denn zur Lebensrettung hat mich Gott vor euch her gesandt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Denn dies ist das zweite Jahr, daß die Hungersnot im Lande herrscht, und es werden noch fünf Jahre ohne Pflügen und Ernten sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Aber Gott hat mich vor euch hergesandt, damit ihr auf Erden überbleibt, und um euch am Leben zu erhalten zu einer großen Errettung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Und nun, nicht ihr habt mich hierher gesandt, sondern Gott: er hat mich dem Pharao zum Vater gesetzt und zum Herrn über sein ganzes Haus und zum Herrscher über ganz Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Zieht eilends zu meinem Vater hinauf und sagt ihm: So spricht dein Sohn Joseph: Gott hat mich zum Herrn über ganz Ägypten gesetzt; komm zu mir herab, säume nicht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du sollst im Lande Gosen wohnen und nahe bei mir sein, du und deine Kinder und deine Kindeskinder, dein kleines und großes Vieh und alles, was dein ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ich will dich daselbst mit Nahrung versorgen (denn es sind noch fünf Jahre Hungersnot), damit du nicht verarmest, du und dein Haus und alles, was dein ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Und siehe, eure Augen sehen es und die Augen meines Bruders Benjamin, daß ich mündlich mit euch rede.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Darum verkündiget meinem Vater alle meine Herrlichkeit in Ägypten und alles, was ihr gesehen habt, und bringet meinen Vater eilends herab hierher!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Und er fiel seinem Bruder Benjamin um den Hals und weinte, und Benjamin weinte auch an seinem Halse.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Und er küßte alle seine Brüder und weinte über ihnen, und darnach redeten seine Brüder mit ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Und als man im Hause des Pharao die Nachricht vernahm: Josephs Brüder sind gekommen! gefiel solches dem Pharao und seinen Knechten wohl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Und der Pharao sprach zu Joseph: Sage deinen Brüdern: Tut das: Beladet eure Tiere und macht euch auf den Weg;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'und wenn ihr ins Land Kanaan kommt, so nehmt euren Vater und eure Familien und kommt zu mir, so will ich euch das Beste des Landes Ägypten geben, und ihr sollt das Fett des Landes essen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Und du, ordne solches an: Tut also: Nehmt euch Wagen mit aus Ägyptenland für eure Kinder und Weiber und führet euren Vater und kommt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'und euer Hausrat darf euch nicht reuen; denn das Beste des ganzen Landes Ägypten soll euer sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Die Söhne Israels taten also; und Joseph gab ihnen Wagen nach dem Befehl des Pharao, auch gab er ihnen Zehrung auf den Weg,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'und schenkte ihnen allen, einem jeden, ein Feierkleid; Benjamin aber schenkte er dreihundert Silberlinge.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Und seinem Vater sandte er folgendes: zehn Esel, beladen mit ägyptischen Gütern, und zehn Eselinnen, welche Korn, Brot und Speise trugen für seinen Vater auf den Weg.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Damit entließ er seine Brüder, und sie gingen, und er sprach zu ihnen: Zankt euch nicht auf dem Wege!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Also reisten sie von Ägypten hinauf und kamen ins Land Kanaan zu ihrem Vater Jakob;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'und sie verkündigten ihm und sprachen: Joseph lebt noch und ist Herrscher über ganz Ägyptenland! Aber sein Herz blieb kalt; denn er glaubte ihnen nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Da sagten sie ihm alle Worte Josephs, die er zu ihnen geredet hatte; und als er die Wagen sah, die Joseph gesandt hatte, ihn zu führen, ward der Geist ihres Vaters Jakob lebendig;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'und Israel sprach: Ich habe genug, daß mein Sohn Joseph noch lebt! Ich will hingehen und ihn sehen, ehe denn ich sterbe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Und Israel brach auf mit allem, was er hatte; und als er nach Beerseba kam, opferte er daselbst dem Gott seines Vaters Isaak.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Und Gott sprach zu Israel im Nachtgesicht: Jakob, Jakob! Er sprach: Hier bin ich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Da sprach er: Ich bin der starke Gott, der Gott deines Vaters; fürchte dich nicht, nach Ägypten hinabzuziehen; denn daselbst will ich dich zu einem großen Volke machen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich will mit dir hinab nach Ägypten ziehen, und ich führe dich gewiß auch wieder hinauf; und Joseph soll dir die Augen zudrücken!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da machte sich Jakob von Beerseba auf, und die Kinder Israels führten ihren Vater Jakob samt ihren Kindern und Weibern auf den Wagen, welche der Pharao gesandt hatte, um ihn hinzuführen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Sie nahmen auch ihr Vieh und ihre Habe, die sie im Lande Kanaan erworben hatten, und kamen nach Ägypten, Jakob und all sein Same mit ihm:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'seine Söhne und Enkel, seine Töchter und Enkelinnen, kurz allen seinen Samen brachte er mit sich nach Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Dieses aber sind die Namen der Kinder Israels, die nach Ägypten kamen: Jakob und seine Söhne. Der erstgeborne Sohn Jakobs: Ruben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Die Kinder Rubens: Hanoch, Pallu, Hezron und Karmi.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Die Kinder Simeons: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn von dem kanaanäischen Weibe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Die Kinder Levis: Gerson, Kahath und Merari.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Die Kinder Judas: Er, Onan, Perez und Serah. Aber Er und Onan starben im Lande Kanaan. Die Kinder des Perez aber waren Hezron und Hamul.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Die Kinder Issaschars: Thola, Puva, Job und Simron.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Die Kinder Sebulons: Sered, Elon und Jahleel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Das sind die Kinder von Lea, die sie dem Jakob in Mesopotamien gebar, samt seiner Tochter Dina. Diese machen zusammen, mit Söhnen und Töchtern, dreiunddreißig Seelen aus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Die Kinder Gads: Ziphion, Haggi, Suni, Ezbon, Eri, Arodi und Areli.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Die Kinder Assers: Jimna, Jiswa, Jiswi, Beria und Serah, ihre Schwester. Und die Kinder Berias: Heber und Malkiel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Das sind die Kinder von Silpa, welche Laban seiner Tochter Lea gab; sie gebar dem Jakob diese sechzehn Seelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Kinder Rahels, des Weibes Jakobs: Joseph und Benjamin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Und dem Joseph wurden in Ägypten Manasse und Ephraim geboren, die ihm Asnath, die Tochter Potipheras, des Priesters zu On, gebar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Die Kinder Benjamins: Bela, Becher, Asbel, Gera, Naaman, Ehi, Rosch, Mupim, Hupim und Ard.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Das sind die Kinder von Rahel, die dem Jakob geboren wurden, alle zusammen vierzehn Seelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Die Kinder Dans: Husim.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Die Kinder Naphtalis: Jahzeel, Guni, Jezer und Sillem.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Das sind die Kinder von Bilha, die Laban seiner Tochter Rahel gab; sie gebar dem Jakob in allem sieben Seelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alle Seelen, die mit Jakob nach Ägypten kamen, welche von seinen Lenden ausgegangen waren, ausgenommen die Weiber der Söhne Jakobs, sind zusammen sechsundsechzig Seelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Und die Kinder Josephs, die ihm in Ägypten geboren sind, waren zwei Seelen, also daß alle Seelen des Hauses Jakobs, die nach Ägypten kamen, siebzig waren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Er hatte aber den Juda vor sich her zu Joseph gesandt, daß er ihn zur Begegnung nach Gosen weise.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Als sie nun ins Land Gosen kamen, spannte Joseph seinen Wagen an und fuhr seinem Vater nach Gosen entgegen. Und als er ihn sah, fiel er ihm um den Hals und weinte lange an seinem Halse.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Und Israel sprach zu Joseph: Nun will ich gerne sterben, nachdem ich dein Angesicht geschaut habe und sehe, daß du noch lebst!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph aber sprach zu seinen Brüdern und zu seines Vaters Hause: Ich will hinaufgehen und es dem Pharao anzeigen und ihm sagen: Meine Brüder und meines Vaters Haus, die in Kanaan waren, sind zu mir gekommen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'und die Männer sind Schafhirten, sie sind Viehzüchter und haben ihre Schafe und Rinder und alles, was ihnen gehört, mitgebracht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Wenn euch dann der Pharao rufen läßt und euch fragt: Was treibt ihr?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'So sollt ihr sagen: Deine Knechte sind Viehzüchter gewesen von ihrer Jugend auf bisher, wir und unsre Väter! Dann werdet ihr im Lande Gosen wohnen dürfen, weil alle Hirten den Ägyptern ein Greuel sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Und Joseph kam und zeigte es dem Pharao an und sprach: Mein Vater und meine Brüder sind aus dem Lande Kanaan gekommen samt ihren Schafen und Rindern, und siehe, sie sind im Lande Gosen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Er hatte aber aus der Zahl seiner Brüder fünf mitgenommen und stellte sie dem Pharao vor.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Und der Pharao fragte seine Brüder: Was treibt ihr? Sie antworteten ihm: Deine Knechte sind Schafhirten, wir und unsre Väter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Und sie sprachen zum Pharao: Wir sind gekommen, um uns im Lande aufzuhalten; denn deine Knechte haben keine Weide für ihr Vieh, so hart beschwert die Hungersnot das Land Kanaan; und nun möchten deine Knechte gerne im Lande Gosen wohnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sprach der Pharao zu Joseph: Dein Vater und deine Brüder sind zu dir gekommen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'das Land Ägypten steht dir offen; laß deinen Vater und deine Brüder am besten Ort des Landes wohnen, im Lande Gosen sollen sie wohnen; und wenn du weißt, daß unter ihnen tüchtige Leute sind, so setze sie zu Aufsehern über mein Vieh!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Joseph brachte auch seinen Vater Jakob hinein und stellte ihn dem Pharao vor; und Jakob segnete den Pharao.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Und der Pharao fragte Jakob: Wie alt bist du?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob sprach zum Pharao: Die ganze Zeit meiner Pilgrimschaft beträgt hundertunddreißig Jahre; wenig und böse sind meine Lebensjahre gewesen und erreichen nicht die Zahl der Lebensjahre meiner Väter in den Tagen ihrer Pilgrimschaft.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Und Jakob segnete den Pharao und ging hinaus von Pharaos Angesicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Und Joseph wies seinem Vater und seinen Brüdern Wohnsitz an und gab ihnen ein Besitztum im Lande Ägypten, am besten Orte des Landes, in der Landschaft Ramses, wie der Pharao befohlen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Brot nach der Zahl der Kinder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Es war aber im ganzen Lande kein Brot; denn die Hungersnot war sehr schwer und Ägyptenland war erschöpft, ebenso das Land Kanaan, wegen der Hungersnot.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Und Joseph brachte alles Geld zusammen, das in Ägypten und im Lande Kanaan gefunden ward, um Korn zu kaufen; und Joseph brachte das Geld in das Haus des Pharao.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Da nun das Geld ausgegangen war in Ägyptenland und in Kanaan, kamen alle Ägypter zu Joseph und sprachen: Gib uns Brot! Warum sollen wir vor dir sterben, weil wir kein Brot haben?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph sprach: Bringet euer Vieh her, so will ich euch geben als Entgelt für euer Vieh, wenn ihr ohne Geld seid!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Da brachten sie ihr Vieh zu Joseph; und er gab ihnen Brot um Pferde, Schafe, Rinder und Esel, und versorgte sie also in jenem Jahre mit Brot um den Preis ihres Viehs.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Als nun jenes Jahr verflossen war, kamen sie zu ihm im andern Jahr und sprachen: Wir wollen unserm Herrn nicht verhehlen, daß, weil das Geld ausgegangen ist und das Vieh unserm Herrn gehört, nunmehr nichts mehr übrigbleibt vor unserm Herrn als unser Leib und unser Feld!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum sollen wir umkommen vor deinen Augen, wir und unser Feld? Kaufe uns samt unserm Feld um Brot, daß wir und unser Feld dem Pharao dienstbar seien! Gib uns Samen, daß wir leben und nicht sterben, und daß das Land nicht zur Wüste werde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Also kaufte Joseph alles Ackerland der Ägypter für den Pharao auf, denn die Ägypter verkauften ein jeder sein Feld; denn die Hungersnot zwang sie dazu; und so ward das Land des Pharao Eigentum.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Das Volk aber machte er zu leibeigenen Knechten, von einem Ende Ägyptens bis zum andern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur die Äcker der Priester kaufte er nicht; denn die Priester bekamen ihr Bestimmtes vom Pharao und nährten sich von ihrem festen Einkommen, das ihnen der Pharao gab; darum brauchten sie ihre Äcker nicht zu verkaufen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Und Joseph sprach zum Volk: Ich habe euch heute samt eurem Land für den Pharao gekauft; hier ist Samen für euch, besäet das Land.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Aber vom Ertrag habt ihr dem Pharao den Fünften zu geben, und vier Teile sollen euer sein zum Besäen der Felder und zum Unterhalt für euch selbst und euer Gesinde und zur Nahrung für eure Kinder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Da sprachen sie: Du hast uns das Leben erhalten! Finden wir Gnade in deinen Augen, so wollen wir des Pharao Knechte sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Da machte Joseph solches zum Gesetz bis auf den heutigen Tag, daß vom Ertrag des Ackerlandes der Ägypter dem Pharao der Fünfte zu geben sei; nur die Äcker der Priester wurden nicht des Pharao Eigentum.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Und Israel wohnte in Ägypten, im Lande Gosen, und sie nahmen es in Besitz, waren fruchtbar und mehrten sich sehr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Und Jakob lebte noch siebzehn Jahre in Ägyptenland, also daß seine ganze Lebenszeit hundertundsiebenundvierzig Jahre betrug.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Als nun die Zeit kam, daß Israel sterben sollte, rief er seinen Sohn Joseph und sprach zu ihm: Habe ich Gnade vor deinen Augen gefunden, so lege doch deine Hand unter meine Hüfte und erweise mir Liebe und Treue: Begrabe mich doch ja nicht in Ägypten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Sondern ich will bei meinen Vätern liegen; darum sollst du mich aus Ägypten führen und mich in ihrem Grabe begraben. Er sprach: Ich will tun, wie du gesagt hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Er aber sprach: So schwöre mir! Da schwur er ihm. Und Israel verbeugte sich vor dem Haupt des Stammes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Darnach ward dem Joseph gesagt: Siehe, dein Vater ist krank! Und er nahm mit sich seine zwei Söhne, Manasse und Ephraim.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Da ward dem Jakob angezeigt und gesagt: Siehe, dein Sohn Joseph kommt zu dir! Und Israel machte sich stark und setzte sich auf im Bett.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Und Jakob sprach zu Joseph: Der allmächtige Gott erschien mir zu Lus im Lande Kanaan und segnete mich');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'und sprach zu mir: Siehe, ich will dich fruchtbar machen und dich mehren und dich zu einer Völkergemeinde machen, und ich will deinem Samen nach dir dieses Land zur Besitzung geben ewiglich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'So sollen nun deine beiden Söhne, Ephraim und Manasse, die dir in Ägypten geboren sind, ehe ich zu dir nach Ägypten gekommen bin, mein sein; wie Ruben und Simeon sollen sie mein sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Die Kinder aber, welche du nach ihnen zeugest, sollen dein sein und sollen in ihrem Erbteil nach ihrer Brüder Namen genannt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Und als ich aus Mesopotamien kam, starb Rahel bei mir im Lande Kanaan, auf dem Wege, als wir nur ein Stück Weges von Ephrata entfernt waren, und ich begrub sie daselbst an dem Wege gen Ephrata, die jetzt Bethlehem heißt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Als aber Israel Josephs Söhne sah, fragte er: Wer sind diese?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph antwortete: Es sind meine Söhne, die mir Gott hier geschenkt hat! Er sprach: Bring sie doch her zu mir, daß ich sie segne!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Denn Israels Augen waren vom Alter kurzsichtig geworden, daß er nicht mehr sehen konnte. Als er sie nun zu ihm brachte, küßte und umarmte er sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Und Israel sprach zu Joseph: Daß ich dein Angesicht noch sehen dürfte, darum hätte ich nicht zu bitten gewagt; und nun, siehe, hat mich Gott sogar deine Kinder sehen lassen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Und Joseph nahm sie von seinen Knien und warf sich auf sein Angesicht zur Erde nieder.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Darnach nahm er sie beide, Ephraim in seine Rechte, zur Linken Israels, und Manasse in seine Linke, zur Rechten Israels, und brachte sie zu ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Da streckte Israel seine Rechte aus und legte sie auf Ephraims Haupt, obschon er der jüngere war, seine Linke aber auf Manasses Haupt, indem er also seine Hände verschränkte, wiewohl Manasse der Erstgeborene war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Und er segnete Joseph und sprach: Der Gott, vor dessen Angesicht meine Väter Abraham und Isaak gewandelt haben; der Gott, der mich behütet hat, seitdem ich bin, bis auf diesen Tag;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der mich erlöset hat von allem Übel, der segne die Knaben, und durch sie werde mein Name genannt und der Name meiner Väter Abraham und Isaak, und sie sollen zu einer großen Menge werden auf Erden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Als aber Joseph sah, daß sein Vater die rechte Hand auf Ephraims Haupt legte, gefiel es ihm übel; darum ergriff er seines Vaters Hand, um sie von Ephraims Haupt auf Manasses Haupt zu wenden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Dabei sprach Joseph zu seinem Vater: Nicht also, mein Vater; denn dieser ist der Erstgeborene; lege deine Rechte auf sein Haupt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Aber sein Vater weigerte sich und sprach: Ich weiß es, mein Sohn, ich weiß es wohl! Auch er soll zu einem Volk, und auch er soll groß werden; aber doch soll sein jüngerer Bruder größer werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Also segnete er sie an jenem Tag und sprach: Mit dir wird Israel segnen und sagen: Gott mache dich wie Ephraim und Manasse! Also setzte er Ephraim dem Manasse voran.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Und Israel sprach zu Joseph: Siehe, ich sterbe; aber Gott wird mit euch sein und wird euch in das Land eurer Väter zurückbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Und ich schenke dir einen Bergesrücken, den du vor deinen Brüdern voraushaben sollst; ich habe ihn den Amoritern mit meinem Schwert und meinem Bogen aus der Hand genommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Und Jakob berief seine Söhne und sprach: Kommt zusammen, daß ich euch kundtue, was euch in künftigen Tagen begegnen wird!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Versammelt euch und merket auf, ihr Söhne Jakobs, höret auf euren Vater Israel!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, du bist mein erstgeborner Sohn, meine Kraft und der Anfang meiner Stärke, von hervorragender Würde und vorzüglicher Kraft.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Du warst wie kochendes Wasser, du sollst nicht den Vorzug haben; denn du bist auf deines Vaters Bett gestiegen, hast dazumal mein Lager entweiht; er stieg hinauf!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Die Brüder Simeon und Levi Mordwerkzeuge sind ihre Messer!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Meine Seele komme nicht in ihren Kreis und meine Ehre vereine sich nicht mit ihrer Versammlung! Denn in ihrem Zorn haben sie Männer gemordet und in ihrer Willkür Ochsen verstümmelt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht sei ihr Zorn, weil er so heftig, und ihr Grimm, weil er so hartnäckig ist! Ich will sie verteilen unter Jakob und zerstreuen unter Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Dich, Juda, werden deine Brüder loben! Deine Hand wird auf dem Nacken deiner Feinde sein; vor dir werden deines Vaters Kinder sich neigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda ist ein junger Löwe; mit Beute beladen stiegst du, mein Sohn, empor! Er ist niedergekniet und hat sich gelagert wie ein Löwe und wie eine Löwin; wer darf ihn aufwecken?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Es wird das Zepter nicht von Juda weichen, noch der Herrscherstab von seinen Füßen, bis daß der Schilo kommt und ihm die Völkerschaften unterworfen sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er wird sein Füllen an den Weinstock binden; und der Eselin Junges an die Edelrebe; er wird sein Kleid im Weine waschen und seinen Mantel in Traubenblut;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'seine Augen sind dunkel vom Wein und seine Zähne weiß von Milch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon wird an der Anfurt des Meeres wohnen und den Schiffen zur Anfurt dienen, und er lehnt sich an Sidon an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issaschar ist ein knochiger Esel, der zwischen den Hürden liegt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'und weil er sah, daß die Ruhe gut und das Land lieblich war, so neigte er seine Schultern zum Tragen und wurde ein fronpflichtiger Knecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan wird sein Volk richten als einer der Stämme Israels');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan wird eine Schlange am Wege sein, eine Otter auf dem Pfad, die das Roß in die Fersen beißt, daß der Reiter rücklings stürzt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'O HERR, ich warte auf dein Heil!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Den Gad drängt eine Schar; aber er drängt sie zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Für Asser ist sein Brot zu fett; aber er gibt königliche Leckerbissen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphtali ist eine ausgelassene Hirschkuh und kann schöne Worte machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph ist ein junger Fruchtbaum, ein junger Fruchtbaum an der Quelle; seine Zweige klettern über die Mauer hinaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Es haben ihn zwar die Schützen heftig beschossen und bekämpft;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'aber sein Bogen blieb unerschütterlich und seine Arme und seine Hände wurden gelenkt von den Händen des Mächtigen Jakobs, vom Namen des Hirten, des Felsens Israels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Von deines Vaters Gott werde dir geholfen, und Gott der Allmächtige segne dich mit Segnungen vom Himmel herab, mit Segnungen der Tiefe, die unten liegt, mit Segnungen von Brüsten und Mutterschoß!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segnungen deines Vaters überragen die Segnungen meiner Eltern, sie reichen bis an die ewigen Hügel; mögen sie kommen auf Josephs Haupt, auf den Scheitel des Fürsten unter seinen Brüdern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein reißender Wolf; am Morgen verzehrt er Raub und am Abend teilt er sich in die Beute.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Diese alle sind Stämme Israels, ihrer zwölf; und das ist\'s, was ihr Vater zu ihnen geredet und womit er sie gesegnet hat; und zwar segnete er einen jeden mit einem besonderen Segen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er gebot ihnen und sprach: Ich werde zu meinem Volk versammelt werden; begrabet mich bei meinen Vätern in der Höhle auf dem Acker Ephrons, des Hetiters,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in der Höhle Machpelah, Mamre gegenüber im Lande Kanaan, wo Abraham den Acker gekauft hat von Ephron, dem Hetiter, zum Erbbegräbnis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Daselbst hat man Abraham und sein Weib Sarah begraben, desgleichen Isaak und sein Weib Rebekka, und dort habe ich auch Lea begraben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'der Acker und seine Höhle wurde den Hetitern abgekauft.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Als aber Jakob seine Befehle an seine Söhne vollendet hatte, zog er seine Füße aufs Bett zurück, verschied und ward zu seinem Volke versammelt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Da fiel Joseph auf seines Vaters Angesicht und weinte über ihm und küßte ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Darnach befahl Joseph den Ärzten, die ihm dienten, daß sie seinen Vater einbalsamierten; und die Ärzte balsamierten Israel ein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Und sie verwendeten darauf volle vierzig Tage; denn so lange dauert die Einbalsamierung; aber beweint haben ihn die Ägypter siebzig Tage lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Als aber die Tage der Trauer um ihn vorüber waren, redete Joseph mit dem Hause des Pharao und sprach: Habe ich Gnade gefunden in euren Augen, so redet doch vor Pharaos Ohren und sprechet:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat einen Eid von mir genommen und zu mir gesagt: Siehe, ich sterbe; begrabe mich in meinem Grab, das ich mir im Lande Kanaan angelegt habe! So laß mich nun hinaufziehen, daß ich meinen Vater begrabe und darnach wiederkomme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Der Pharao sprach: Zieh hinauf und begrabe deinen Vater, wie er dich hat schwören lassen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Da zog Joseph hinauf, seinen Vater zu begraben; und es zogen mit ihm hinauf alle Knechte des Pharao, alle Ältesten seines Hauses und alle Ältesten des Landes Ägypten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'dazu das ganze Haus Josephs und seine Brüder und seines Vaters Haus; nur ihre Kinder, Schafe und Rinder ließen sie im Lande Gosen zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Es begleiteten ihn auch Wagen und Reiter, so daß es ein großes Heer gab.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Als sie nun zur Tenne Atad kamen, welche jenseits des Jordan liegt, hielten sie daselbst eine große und feierliche Totenklage; denn er veranstaltete für seinen Vater eine siebentägige Trauer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Als aber die Bewohner des Landes, die Kanaaniter, die Trauer bei der Tenne Atad sahen, sprachen sie: Die Ägypter halten da eine große Klage! Daher wurde der Ort, welcher jenseits des Jordan liegt, »der Ägypter Klage« genannt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Seine Söhne aber machten es so, wie er ihnen befohlen hatte:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'sie führten ihn ins Land Kanaan und begruben ihn in der Höhle des Ackers Machpelah, weil Abraham den Acker zum Erbbegräbnis gekauft hatte von Ephron, dem Hetiter, gegenüber von Mamre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Joseph aber kehrte nach dem Begräbnis seines Vaters wieder nach Ägypten zurück, er und seine Brüder und alle, die mit ihm hinaufgezogen waren, seinen Vater zu begraben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Als nun Josephs Brüder sahen, daß ihr Vater gestorben war, sprachen sie: Joseph könnte uns angreifen und uns all die Bosheit vergelten, die wir an ihm verübt haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Darum ließen sie Joseph sagen: Dein Vater befahl vor seinem Tode und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Also sollt ihr zu Joseph sagen: Bitte, vergib doch deinen Brüdern die Missetat und ihre Sünde, daß sie so übel an dir getan! So vergib nun den Dienern des Gottes deines Vaters ihre Missetat! Aber Joseph weinte, als sie ihm das sagen ließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Da gingen seine Brüder selbst hin und fielen vor ihm nieder und sprachen: Siehe, wir sind deine Knechte!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Aber Joseph sprach zu ihnen: Fürchtet euch nicht! Bin ich denn an Gottes Statt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr gedachtet zwar Böses wider mich; aber Gott gedachte es gut zu machen, daß er täte, wie es jetzt am Tage ist, um viel Volk am Leben zu erhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'So fürchtet euch nun nicht; ich will euch und eure Kinder versorgen! Und er tröstete sie und redete freundlich mit ihnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Und Joseph blieb in Ägypten, er und seines Vaters Haus; und Joseph lebte hundertundzehn Jahre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und Joseph sah Ephraims Kinder bis in das dritte Glied; auch die Kinder Machirs, des Sohnes Manasses, saßen noch auf seinen Knien.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Und Joseph sprach zu seinen Brüdern: Ich sterbe; aber Gott wird euch gewiß heimsuchen und aus diesem Lande hinaufführen in das Land, das er Abraham, Isaak und Jakob geschworen hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Und er nahm einen Eid von den Kindern Israels und sprach: Wenn Gott euch heimsuchen wird, so sollt ihr meine Gebeine von hier hinaufbringen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Und Joseph starb, hundertundzehn Jahre alt; und man balsamierte ihn ein und legte ihn in einen Sarg in Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Dies sind die Namen der Söhne Israels, die mit Jakob nach Ägypten gekommen sind, ein jeglicher mit seinem Haus:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Juda;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issaschar, Sebulon und Benjamin;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naphtali, Gad und Asser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Die ganze Nachkommenschaft Jakobs aber betrug damals siebzig Seelen, Joseph inbegriffen, der schon in Ägypten war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Als aber Joseph gestorben war und alle seine Brüder und jenes ganze Geschlecht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'wuchsen die Kinder Israel, regten und mehrten sich und wurden so zahlreich, daß das Land von ihnen voll ward.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da kam ein neuer König auf über Ägypten, der nichts von Joseph wußte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Der sprach zu seinem Volk: Siehe, das Volk der Kinder Israel ist zahlreicher und stärker als wir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, laßt uns kluge Maßnahmen gegen sie ergreifen, daß ihrer nicht zuviele werden; sie könnten sonst, falls sich ein Krieg wider uns erhöbe, zu unsern Feinden übergehen und wider uns kämpfen und aus dem Lande ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Darum setzte man Fronvögte über sie, um sie durch Lasten zu drücken; man baute nämlich dem Pharao die Vorratsstädte Pitom und Raemses.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Je mehr sie aber das Volk drückten, desto zahlreicher wurde es und desto mehr breitete es sich aus, also daß ihnen graute vor den Kindern Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Darum zwangen die Ägypter die Kinder Israel durch Mißhandlungen zum Dienst');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'und verbitterten ihnen das Leben mit harter Zwangsarbeit an Lehm und Ziegeln und mit allerlei Feldarbeit, lauter Arbeiten, zu welchen man sie unter Mißhandlungen zwang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Und der König von Ägypten redete mit den hebräischen Hebammen, deren eine Schiphra, die andere Pua hieß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Er sprach: Wenn ihr die Hebräerinnen entbindet, so sehet auf der Stelle nach; ist es ein Sohn, so tötet ihn, ist es aber eine Tochter, so lasset sie leben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Aber die Hebammen fürchteten Gott und taten nicht, wie ihnen der ägyptische König befohlen hatte, sondern ließen die Kinder leben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da ließ der König die Hebammen rufen und fragte sie: Warum tut ihr das, daß ihr die Kinder leben lasset?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Hebammen antworteten dem Pharao: Weil die hebräischen Frauen nicht sind wie die ägyptischen; sie sind lebhafter; ehe die Hebamme zu ihnen kommt, haben sie geboren!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Dafür segnete Gott die Hebammen; das Volk aber vermehrte sich und nahm gewaltig zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und weil die Hebammen Gott fürchteten, so baute er ihnen Häuser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Da gebot der Pharao all seinem Volk und sprach: Werfet alle Söhne, die geboren werden, in den Nil; aber alle Töchter lasset leben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Und es ging hin ein Mann von dem Hause Levis und nahm eine Tochter Levis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Und das Weib empfing und gebar einen Sohn. Und als sie sah, daß er schön war, verbarg sie ihn drei Monate lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Als sie ihn aber nicht länger verbergen konnte, nahm sie ein Kästlein von Rohr, und verklebte es mit Lehm und Pech, tat das Kind darein, und legte es in das Schilf am Gestade des Flusses.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Aber seine Schwester stellte sich in einiger Entfernung hin, damit sie erführe, wie es ihm ergehen würde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Da kam die Tochter des Pharao herab, um im Flusse zu baden, und ihre Jungfrauen gingen an das Gestade des Flusses; und als sie das Kästlein mitten im Schilf sah, sandte sie ihre Magd hin und ließ es holen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Und als sie es öffnete, sah sie das Kind. Und siehe, es war ein weinendes Knäblein! Da erbarmte sie sich über dasselbe und sprach: Es ist eines der hebräischen Kinder!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Da sprach seine Schwester zu der Tochter des Pharao: Soll ich hingehen und eine hebräische Säugamme rufen, daß sie dir das Kindlein säuge?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Die Tochter des Pharao sprach zu ihr: Geh hin! Die Jungfrau ging hin und rief des Kindes Mutter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Da sprach des Pharao Tochter zu ihr: Nimm das Kindlein hin und säuge es mir, ich will dir deinen Lohn geben! Das Weib nahm das Kind und säugte es.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Und als das Kind groß geworden, brachte sie es der Tochter des Pharao, und es ward ihr Sohn, und sie hieß ihn Mose. Denn sie sprach: Ich habe ihn aus dem Wasser gezogen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Zu der Zeit aber, als Mose groß geworden, ging er aus zu seinen Brüdern und sah ihre Lasten und sah, daß ein Ägypter einen Hebräer, einen seiner Brüder, schlug.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Und er wandte sich hin und her, und als er sah, daß kein Mensch zugegen war, erschlug er den Ägypter und verscharrte ihn im Sand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Am zweiten Tag ging er auch aus, und siehe, zwei hebräische Männer zankten miteinander, und er sprach zu dem Schuldigen: Warum schlägst du deinen Nächsten?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Er aber sprach: Wer hat dich zum Obersten und Richter über uns gesetzt? Gedenkst du mich auch zu erwürgen, wie du den Ägypter erwürgt hast? Da fürchtete sich Mose und sprach: Wahrlich, das ist ruchbar geworden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Und es kam vor den Pharao; der suchte Mose umzubringen. Aber Mose floh vor dem Pharao und hielt sich im Lande Midian auf und setzte sich an einen Brunnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Aber der Priester in Midian hatte sieben Töchter; die kamen, um Wasser zu schöpfen, und füllten die Tränkrinnen, um ihres Vaters Schafe zu tränken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Da kamen die Hirten und jagten sie fort. Aber Mose machte sich auf und half ihnen und tränkte ihre Schafe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Und als sie zu ihrem Vater Reguel kamen, sprach er: Warum seid ihr heute so bald wiedergekommen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Sie sprachen: Ein ägyptischer Mann errettete uns von der Hand der Hirten und schöpfte uns Wasser genug und tränkte die Schafe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Er sprach zu seinen Töchtern: Wo ist er? Warum habt ihr den Mann stehen lassen? Ruft ihn her, daß er mit uns esse!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Mose willigte ein, bei dem Mann zu bleiben; der gab ihm seine Tochter Zippora.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Die gebar einen Sohn, den hieß er Gersom; denn er sprach: Ich bin ein Fremdling geworden in einem fremden Land.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Aber viele Tage darnach starb der König in Ägypten. Und die Kinder Israel seufzten über ihre Knechtschaft und schrieen. Und ihr Geschrei über ihre Knechtschaft kam vor Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott erhörte ihr Wehklagen, und Gott gedachte an seinen Bund mit Abraham, Isaak und Jakob.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott sah die Kinder Israel an, und Gott nahm Kenntnis davon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mose aber hütete die Schafe Jethros, seines Schwiegervaters, des Priesters in Midian, und trieb die Schafe hinten in die Wüste und kam an den Berg Gottes Horeb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Und der Engel des HERRN erschien ihm in einer Feuerflamme mitten aus dem Dornbusch. Und als er sich umsah, siehe, da brannte der Dornbusch im Feuer, und der Dornbusch ward doch nicht verzehrt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Da sprach Mose: Ich will doch hinzutreten und diese große Erscheinung besehen, warum der Dornbusch nicht verbrennt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Als aber der HERR sah, daß er hinzutrat, um zu sehen, rief ihm Gott mitten aus dem Dornbusch und sprach: Mose, Mose! Er antwortete: Hier bin ich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Da sprach er: Komm nicht näher herzu! Ziehe deine Schuhe aus von deinen Füßen; denn der Ort, darauf du stehest, ist heiliges Land!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Und er sprach: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs! Da verdeckte Mose sein Angesicht; denn er fürchtete sich, Gott anzuschauen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Und der HERR sprach: Ich habe das Elend meines Volkes in Ägypten angesehen und habe ihr Geschrei gehört über die, welche sie treiben; ja ich kenne ihre Schmerzen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'und ich bin herabgefahren, daß ich sie errette von der Ägypter Hand und sie ausführe aus diesem Land in ein gutes und weites Land, in ein Land, das von Milch und Honig fließt, an den Ort der Kanaaniter, Hetiter, Amoriter, Pheresiter, Heviter und Jebusiter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Und nun siehe, das Geschrei der Kinder Israel ist vor mich gekommen, und ich habe auch ihre Bedrückung gesehen, wie die Ägypter sie bedrücken!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'So geh nun hin, ich will dich zu dem Pharao senden, daß du mein Volk, die Kinder Israel, aus Ägypten führest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mose sprach zu Gott: Wer bin ich, daß ich zum Pharao gehe, und daß ich die Kinder Israel aus Ägypten führe?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Er sprach: Ich will mit dir sein; und dies soll dir das Zeichen sein, daß ich dich gesandt habe: Wenn du das Volk aus Ägypten geführt hast, werdet ihr auf diesem Berge Gott dienen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mose sprach zu Gott: Siehe, wenn ich zu den Kindern Israel komme und zu ihnen sage: Der Gott eurer Väter hat mich zu euch gesandt, und sie mich fragen werden: Wie heißt sein Name? Was soll ich ihnen sagen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Gott sprach zu Mose: »Ich bin, der ich bin!« Und er sprach: Also sollst du zu den Kindern Israel sagen: »Ich bin«, der hat mich zu euch gesandt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und nochmals sprach Gott zu Mose: Also sollst du zu den Kindern Israel sagen: Der HERR, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, hat mich zu euch gesandt; das ist mein Name ewiglich und meine Benennung für und für.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Geh hin und versammle die Ältesten von Israel und sprich zu ihnen: Der HERR, der Gott eurer Väter, der Gott Abrahams, Isaaks und Jakobs, ist mir erschienen und hat gesagt: Ich habe achtgegeben auf euch und auf das, was euch in Ägypten widerfahren ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'und ich sage euch: Ich will euch aus dem Elend Ägyptens herausführen in das Land der Kanaaniter, Hetiter, Amoriter, Pheresiter, Heviter und Jebusiter, in das Land, das von Milch und Honig fließt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und wenn sie auf dich hören, so sollst du und die Ältesten von Israel zum König von Ägypten hineingehen und zu ihm sagen: Der HERR, der Hebräer Gott, ist uns begegnet. So laß uns nun drei Tagereisen weit in die Wüste gehen, daß wir dem HERRN, unserm Gott, opfern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Aber ich weiß, daß euch der König von Ägypten nicht wird ziehen lassen, wenn er nicht gezwungen wird durch eine starke Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Aber ich werde meine Hand ausstrecken und Ägypten mit allen meinen Wundern schlagen, die ich darin tun will; darnach wird er euch ziehen lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Und ich will diesem Volk Gunst verschaffen bei den Ägyptern, daß, wenn ihr auszieht, ihr nicht leer ausziehen müßt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'sondern ein jedes Weib soll von ihrer Nachbarin und Hausgenossin silberne und goldene Geschirre und Kleider fordern; die sollt ihr auf eure Söhne und Töchter legen und Ägypten berauben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Da antwortete Mose und sprach: Und wenn sie mir nicht glauben und nicht auf mich hören, sondern sagen: Der HERR ist dir nicht erschienen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Der HERR sprach zu ihm: Was hast du in deiner Hand? Er sprach: Einen Stab!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da sprach er: Wirf ihn von dir auf die Erde! Und er warf ihn auf die Erde; da ward er zur Schlange. Und Mose floh vor ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Aber der HERR sprach zu Mose: Strecke deine Hand aus und ergreife sie beim Schwanz! Da streckte er seine Hand aus und hielt sie. Und sie ward zum Stab in seiner Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Darum werden sie glauben, daß der HERR, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, dir erschienen ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Und der HERR sprach weiter zu ihm: Stecke doch deine Hand in deinen Busen! Da steckte er seine Hand in seinen Busen; und als er sie herauszog, siehe, da war seine Hand aussätzig wie Schnee.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Und er sprach: Tue deine Hand wieder in deinen Busen! Und er tat seine Hand wieder in seinen Busen; und als er sie aus seinem Busen herauszog, siehe, da war sie wieder geworden wie sein übriges Fleisch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Wenn sie nun dir nicht glauben und nicht auf das erste Zeichen hören, so werden sie doch der Stimme des andern Zeichens glauben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Wenn sie aber auch diesem Zeichen nicht glauben, so nimm Wasser aus dem Fluß und gieß es auf das trockene Land, so wird das Wasser, das du aus dem Flusse genommen hast, auf dem trockenen Lande zu Blut werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mose aber sprach zum HERRN: Ach mein Herr, ich bin kein Mann, der reden kann; ich bin es weder gestern noch vorgestern gewesen und auch nicht, seitdem du mit deinem Knechte geredet hast; denn ich habe einen schwerfälligen Mund und eine schwere Zunge!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Da sprach der HERR zu ihm: Wer hat dem Menschen den Mund erschaffen, oder wer hat den Stummen, oder Tauben, oder Sehenden, oder Blinden gemacht? Habe nicht ich es getan, der HERR?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'So geh nun hin: Ich will mit deinem Munde sein und dich lehren, was du sagen sollst!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Da sprach Mose: Bitte, Herr, sende doch, wen du senden willst!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da ward der HERR sehr zornig über Mose und sprach: Weiß ich denn nicht, daß dein Bruder Aaron, der Levit, wohl reden kann? Und siehe, er kommt sogar heraus, dir entgegen, und wenn er dich sieht, so wird er sich von Herzen freuen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Du sollst mit ihm reden und die Worte in seinen Mund legen; so will ich mit deinem Munde und mit seinem Munde sein und euch lehren, was ihr tun sollt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Und er soll für dich zum Volke reden und soll dein Mund sein, und du sollst für ihn an Gottes Statt sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und nimm diesen Stab in deine Hand, damit du die Zeichen tun sollst!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Da ging Mose hin und kehrte zu Jethro, seinem Schwiegervater, zurück und sprach zu ihm: Ich möchte zu meinen Brüdern zurückkehren, die in Ägypten sind, und sehen, ob sie noch leben. Jethro sprach zu ihm: Geh hin im Frieden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Und der HERR sprach zu Mose in Midian: Geh nach Ägypten zurück; denn die Leute sind alle tot, die nach deinem Leben trachteten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Also nahm Mose sein Weib und seine Söhne und ließ sie auf einem Esel reiten und zog wieder nach Ägypten. Mose nahm auch den Stab Gottes in die Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Und der HERR sprach zu Mose: Siehe zu, wenn du wieder nach Ägypten kommst, daß du vor dem Pharao alle die Wunder tuest, welche ich in deine Hand gegeben habe. Ich aber will sein Herz verstocken, daß er das Volk nicht wird ziehen lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Und du sollst zum Pharao sagen: So spricht der HERR: »Israel ist mein erstgeborener Sohn;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'darum sage ich dir: Laß meinen Sohn gehen, daß er mir diene; wirst du dich aber weigern, ihn ziehen zu lassen, siehe, so will ich deinen eigenen erstgebornen Sohn erwürgen!«');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Als er aber unterwegs in der Herberge war, griff ihn der HERR an und wollte ihn töten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Zippora einen scharfen Stein und beschnitt ihrem Sohn die Vorhaut und warf sie ihm vor die Füße und sprach: Du bist mir ein Blutbräutigam!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da ließ er von ihm ab. Sie sagte aber »Blutbräutigam« um der Beschneidung willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Und der HERR sprach zu Aaron: Gehe hin, Mose entgegen in die Wüste! Da ging er hin und traf ihn am Berge Gottes und küßte ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Und Mose tat Aaron alle Worte des HERRN kund, womit er ihn beauftragt hatte, auch alle Zeichen, die er ihm befohlen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Da gingen Mose und Aaron hin und versammelten alle Ältesten der Kinder Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aaron redete alle Worte, die der HERR mit Mose geredet hatte; und er tat die Zeichen vor dem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Und das Volk glaubte. Und als sie hörten, daß der HERR sich der Kinder Israel angenommen und daß er ihr Elend angesehen habe, neigten sie sich und beteten an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Darnach gingen Mose und Aaron hinein und redeten mit dem Pharao: So spricht der HERR, der Gott Israels: Laß mein Volk ziehen, daß es mir in der Wüste ein Fest halte!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Der Pharao antwortete: Wer ist der HERR, dessen Stimme ich hören soll, um Israel ziehen zu lassen? Ich weiß nichts von dem HERRN, ich will auch Israel nicht ziehen lassen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Sie sprachen: Der Hebräer Gott ist uns begegnet; wir wollen hingehen drei Tagereisen weit in die Wüste und dem HERRN, unserm Gott, opfern, daß er uns nicht mit Pestilenz oder mit dem Schwerte schlage.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Da sprach der König von Ägypten zu ihnen: Du, Mose und Aaron, warum zieht ihr das Volk von ihren Pflichten ab? Geht hin an eure Arbeit!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Weiter sprach der Pharao: Siehe, des Volks ist schon zuviel im Lande; und ihr wollt sie noch von ihrer Arbeit feiern heißen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Und der Pharao befahl an demselben Tage den Treibern des Volks und seinen Amtleuten und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ihr sollt dem Volk kein Stroh mehr geben zum Ziegelstreichen, wie gestern und vorgestern. Laßt sie selbst hingehen und sich Stroh zusammensuchen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Ihr sollt ihnen aber gleichwohl die bestimmte Zahl Ziegel, die sie gestern und vorgestern gemacht haben, auferlegen und davon nichts nachlassen; denn sie gehen müßig. Darum schreien sie und sprechen: Wir wollen hingehen und unserm Gott opfern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Man erschwere den Leuten die Arbeit, daß sie damit zu schaffen haben und sich nicht an falsche Worte kehren!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da gingen die Treiber des Volks und seine Amtleute aus, redeten mit dem Volk und sprachen: So spricht der Pharao: »Man gibt euch kein Stroh mehr;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'geht ihr selbst hin, nehmt euch Stroh, wo ihr es findet, aber von eurem Tagewerk wird euch nichts erlassen!«');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Da zerstreute sich das Volk in das ganze Land Ägypten, daß es Stoppeln statt Stroh sammelte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Und die Treiber trieben sie und sprachen: Erfüllt euer bestimmtes Tagewerk, wie als ihr noch Stroh hattet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Und die Amtleute der Kinder Israel, welche die Treiber des Pharao über sie gesetzt hatten, wurden geschlagen, und es ward zu ihnen gesagt: Warum habt ihr weder heute noch gestern euer bestimmtes Tagewerk getan wie zuvor?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Da gingen die Amtleute der Kinder Israel hinein und schrieen zu dem Pharao und sprachen: Warum willst du mit deinen Knechten also verfahren?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Man gibt deinen Knechten kein Stroh und spricht zu uns: Machet die Ziegel! Und siehe, deine Knechte werden geschlagen; womit hat sich dein Volk versündigt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Er sprach: Ihr seid müßig, müßig seid ihr; darum sprechet ihr: Wir wollen hingehen und dem HERRN opfern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'So geht nun hin, arbeitet; Stroh soll man euch nicht geben, aber die bestimmte Anzahl Ziegel sollt ihr liefern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Da sahen die Amtleute der Kinder Israel, daß es mit ihnen übel stand, weil man sagte: Ihr sollt nichts nachlassen von der Zahl der Ziegel, die ihr täglich zu liefern habt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Und als sie von dem Pharao ausgingen, trafen sie Mose und Aaron an, die dort standen und auf sie warteten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Da sprachen sie zu ihnen: Der HERR sehe auf euch und richte es, daß ihr uns vor dem Pharao und seinen Knechten verhaßt gemacht und ihnen das Schwert in die Hand gegeben habt, uns zu töten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Da wandte sich Mose an den HERRN und sprach: Herr, warum lässest du dein Volk so schlecht behandeln? Warum hast du mich hergesandt?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Denn seitdem ich hineingegangen bin, um mit dem Pharao in deinem Namen zu reden, hat er dieses Volk schlecht behandelt, und du hast dein Volk gar nicht errettet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Der HERR sprach zu Mose: Nun sollst du sehen, was ich dem Pharao tun will! Denn durch eine starke Hand gezwungen wird er sie ziehen lassen, und durch eine starke Hand gezwungen wird er sie aus seinem Lande treiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Und Gott redete mit Mose und sprach zu ihm: Ich bin der HERR;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'ich bin Abraham, Isaak und Jakob erschienen als der allmächtige Gott; aber nach meinem Namen »HERR« habe ich mich ihnen nicht geoffenbart.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Auch habe ich meinen Bund mit ihnen aufgerichtet, daß ich ihnen das Land Kanaan geben will, das Land ihrer Pilgrimschaft, darin sie Fremdlinge gewesen sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Und ich habe auch das Seufzen der Kinder Israel gehört, weil die Ägypter sie zu Knechten machen, und habe an meinen Bund gedacht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Darum sage den Kindern Israel: Ich bin der HERR und will euch aus den Lasten Ägyptens herausführen und will euch von ihrer Knechtschaft erretten und will euch durch einen ausgestreckten Arm und große Gerichte erlösen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Und ich will euch mir zum Volk annehmen und will euer Gott sein; daß ihr erfahren sollt, daß ich, der HERR, euer Gott bin, der euch aus den Lasten Ägyptens herausführt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Und ich will euch in das Land bringen, darüber ich meine Hand aufgehoben habe, daß ich es Abraham, Isaak und Jakob gebe. Das will ich euch zu besitzen geben, ich, der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mose sagte solches den Kindern Israel. Sie aber hörten nicht auf ihn vor Mißmut und harter Arbeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Da redete der HERR mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Geh hinein, sage dem Pharao, dem König von Ägypten, daß er die Kinder Israel aus seinem Lande ziehen lasse!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mose aber redete vor dem HERRN und sprach: Siehe, die Kinder Israel hören mich nicht, wie sollte mich denn der Pharao hören? Dazu bin ich von unbeschnittenen Lippen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Also redete der HERR mit Mose und Aaron und gab ihnen Befehl an die Kinder Israel und an den Pharao, den König von Ägypten, daß sie die Kinder Israel aus Ägypten führeten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind die Häupter ihrer Vaterhäuser. Die Kinder Rubens, des erstgeborenen Sohnes Israels, sind diese: Hanoch, Pallu, Hezron, Karmi. Das sind die Geschlechter von Ruben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Die Kinder Simeons sind diese: Jemuel, Jamin, Ohad, Jachim, Zohar und Saul, der Sohn des kanaanäischen Weibes. Das sind die Geschlechter Simeons.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Dies sind die Namen der Kinder Levis in ihren Geschlechtern: Gerson, Kahath und Merari; und Levi ward hundertsiebenunddreißig Jahre alt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Kinder Gersons sind diese: Libni und Simei in ihren Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Die Kinder Kahaths sind diese: Amram, Jizhar, Hebron, Ussiel. Kahath aber ward hundertdreiunddreißig Jahre alt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Die Kinder Meraris sind diese: Machli und Musi. Das sind die Geschlechter Levis nach ihrer Abstammung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Und Amram nahm seine Base Jochebed zum Weibe, die gebar ihm den Aaron und den Mose. Und Amram ward hundertsiebenunddreißig Jahre alt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Die Kinder Jizhars sind diese: Korah, Nepheg und Sichri.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Die Kinder Ussiels sind diese: Misael, Elzaphan und Sitri.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron aber nahm zum Weibe Eliseba, die Tochter Amminadabs, Nahassons Schwester, die gebar ihm den Nadab und den Abihu, den Eleasar und den Itamar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Die Kinder Korahs sind diese: Assir, Elkana und Abiasaph. Das sind die Geschlechter der Korahiter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar aber, Aarons Sohn, nahm sich ein Weib von den Töchtern Putiels, die gebar ihm den Pinehas. Das sind die Häupter unter den Vätern der Leviten nach ihren Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Das ist der Aaron und der Mose, zu denen der HERR sprach: Führet die Kinder Israel nach ihren Heerscharen aus Ägypten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Sie sind es, die mit dem Pharao, dem König von Ägypten, redeten, daß sie die Kinder Israel aus Ägypten führeten, nämlich Mose und Aaron.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Und an demselben Tag redete der HERR mit Mose in Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Da nun der HERR mit Mose redete und sprach: Ich bin der HERR, rede mit dem Pharao, dem König von Ägypten, alles, was ich mit dir rede;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'da antwortete Mose vor dem HERRN: Siehe, ich bin von unbeschnittenen Lippen, wie wird mich denn der Pharao hören?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Der HERR sprach zu Mose: Siehe zu, ich habe dich dem Pharao zum Gott gesetzt, und dein Bruder Aaron soll dein Prophet sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst alles reden, was ich dir gebieten werde, daß er die Kinder Israel aus seinem Lande ziehen lasse.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Aber ich will das Herz des Pharao verhärten, daß ich viele meiner Zeichen und Wunder tue im Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Aber der Pharao wird euch nicht hören, so daß ich meine Hand an Ägypten legen und mein Heer, mein Volk, die Kinder Israel, durch große Gerichte aus dem Lande Ägypten führen werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Und die Ägypter sollen erfahren, daß ich der HERR bin, wenn ich meine Hand über Ägypten ausstrecken und die Kinder Israel von ihnen ausführen werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mose und Aaron taten solches; wie ihnen der HERR geboten hatte, also taten sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Und Mose war achtzig Jahre alt und Aaron dreiundachtzig Jahre alt, als sie mit dem Pharao redeten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Und der HERR sprach zu Mose und Aaron:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Wenn der Pharao zu euch sagen wird: Tut ein Zeichen! so sollst du zu Aaron sagen: Nimm deinen Stab und wirf ihn vor den Pharao hin, so wird er zur Schlange werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Da gingen Mose und Aaron zum Pharao und taten also, wie der HERR ihnen geboten hatte. Und Aaron warf seinen Stab vor den Pharao und vor seine Knechte hin, und er ward zur Schlange.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Da berief der Pharao die Weisen und Zauberer. Und auch sie, die ägyptischen Zauberer, taten also mit ihrem Beschwören.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Und ein jeder warf seinen Stab vor sich hin, und es wurden Schlangen daraus; aber Aarons Stab verschlang ihre Stäbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Also ward das Herz des Pharao verstockt, und er hörte nicht auf sie, wie denn der HERR gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Und der HERR sprach zu Mose: Das Herz des Pharao ist hart; er weigert sich, das Volk ziehen zu lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Geh am Morgen hin zum Pharao; siehe, er wird hinaus ans Wasser gehen; tritt ihm entgegen am Gestade des Flusses und nimm den Stab, der zur Schlange geworden, in deine Hand');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'und sprich zu ihm: Der HERR, der Hebräer Gott, hat mich zu dir gesandt, um dir zu sagen: Laß mein Volk gehen, daß es mir in der Wüste diene! Aber siehe, du hast bisher nicht hören wollen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Darum spricht der HERR also: Daran sollst du erfahren, daß ich der HERR bin: Siehe, ich will mit dem Stabe, den ich in meiner Hand habe, das Wasser schlagen, das in dem Flusse ist, und es soll in Blut verwandelt werden,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'so daß die Fische im Flusse sterben müssen und der Fluß stinken, und es die Ägypter ekeln wird, das Wasser aus dem Flusse zu trinken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Und der HERR sprach zu Mose: Sage zu Aaron: Nimm deinen Stab und strecke deine Hand aus über die Wasser in Ägypten, über ihre Flüsse, über ihre Bäche und über ihre Seen und über alle Wasserbehälter, daß sie zu Blut werden und daß in ganz Ägyptenland Blut sei in hölzernen und steinernen Geschirren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mose und Aaron taten, wie ihnen der HERR geboten hatte. Und er hob den Stab auf und schlug vor dem Pharao und seinen Knechten das Wasser, das im Flusse war; da ward alles Wasser im Nil in Blut verwandelt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Und die Fische im Nil starben, und der Nil ward stinkend, so daß die Ägypter das Nilwasser nicht trinken konnten; denn dasselbe ward zu Blut in ganz Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Aber die ägyptischen Zauberer taten auch also mit ihrem Beschwören. Und so ward das Herz des Pharao verstockt, und er hörte nicht auf sie, wie denn der HERR geredet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Und der Pharao wandte sich und ging heim und kehrte sein Herz auch daran nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Aber alle Ägypter gruben um den Fluß her nach Trinkwasser; denn das Nilwasser konnten sie nicht trinken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Und das währte sieben Tage lang, nachdem der HERR den Fluß geschlagen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'Der HERR sprach zu Mose: Geh hinein zum Pharao und sprich zu ihm: So spricht der HERR: Laß mein Volk gehen, daß es mir diene!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Weigerst du dich aber, dasselbe ziehen zu lassen, siehe, so will ich alle deine Landmarken mit Fröschen plagen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'daß der Fluß von Fröschen wimmle; die sollen heraufkommen in dein Haus und in deine Schlafkammer und auf dein Bett; auch in die Häuser deiner Knechte, unter dein Volk, in deine Backöfen und in deine Backtröge;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'und die Frösche sollen auf dich und auf dein Volk und auf alle deine Knechte kriechen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Und der HERR sprach zu Mose: Sage Aaron: Strecke deine Hand und deinen Stab aus über die Flüsse, über die Bäche und Seen, und laß Frösche über Ägyptenland kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Und Aaron streckte seine Hand über die Wasser in Ägypten; und die Frösche kamen herauf und bedeckten das Land Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Da taten die Zauberer mit ihrem Beschwören auch also und ließen Frösche über das Land Ägypten kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Da berief der Pharao den Mose und Aaron und sprach: Bittet den HERRN, daß er die Frösche von mir nehme und von meinem Volk, so will ich das Volk ziehen lassen, daß es dem HERRN opfere!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mose sprach zum Pharao: Du sollst die Ehre haben zu bestimmen, auf wann ich für dich, für deine Knechte und für dein Volk erbitten soll, daß die Frösche von dir und deinen Häusern vertrieben werden und nur im Flusse bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Er sprach: Auf morgen! Da sprach Mose: Wie du gesagt hast; auf daß du erfahrest, daß niemand ist wie der HERR, unser Gott!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'So sollen die Frösche von dir und von deinen Häusern, von deinen Knechten und von deinem Volke genommen werden; nur im Flusse sollen sie bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Also gingen Mose und Aaron vom Pharao; und Mose schrie zum HERRN der Frösche wegen, die er dem Pharao auferlegt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Und der HERR tat, wie Mose gesagt hatte. Die Frösche starben in den Häusern, in den Höfen und auf dem Felde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Und sie häuften dieselben zusammen, hier einen Haufen und dort einen Haufen; und das Land stank davon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Da aber der Pharao sah, daß er Luft gekriegt hatte, verhärtete er sein Herz und hörte nicht auf sie, wie denn der HERR gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Da sprach der HERR zu Mose: Sage zu Aaron: Strecke deinen Stab aus und schlage den Staub auf der Erde, daß er in ganz Ägyptenland zu Mücken werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Sie taten also. Und Aaron streckte seine Hand aus mit seinem Stabe und schlug in den Staub auf der Erde, und er wurde zu Mücken in ganz Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Die Zauberer versuchten mit ihrem Beschwören auch Mücken hervorzubringen; aber sie konnten es nicht. Und die Mücken kamen über die Menschen und das Vieh.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Da sprachen die Zauberer zu Pharao: Das ist Gottes Finger! Aber das Herz des Pharao war verstockt, daß er nicht auf sie hörte, wie der HERR gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Da sprach der HERR zu Mose: Mache dich morgen frühe auf und tritt zum Pharao (siehe, er wird ans Wasser gehen!) und sprich zu ihm: So spricht der HERR: Laß mein Volk gehen, daß es mir diene!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Denn wenn du mein Volk nicht ziehen lässest, siehe, so will ich über dich und über deine Knechte und über dein Volk und über deine Häuser Hundsfliegen kommen lassen, daß der Ägypter Häuser und das Feld, darauf sie sind, voller Hundsfliegen werden sollen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Und ich will an demselben Tage mit dem Lande Gosen, da mein Volk wohnt, etwas Besonderes tun, daß keine Hundsfliegen daselbst seien, damit du erfahrest, daß ich, der HERR, inmitten des Landes bin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'So will ich eine Scheidung setzen zwischen meinem und deinem Volk. Morgen soll das Zeichen geschehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und der HERR tat also. Und eine Menge Hundsfliegen kamen in das Haus des Pharao und in die Häuser seiner Knechte, ja über ganz Ägyptenland; und das Land ward von den Hundsfliegen verseucht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Da berief der Pharao Mose und Aaron und sprach: Gehet hin, opfert eurem Gott in diesem Lande!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mose sprach: Das schickt sich nicht, daß wir also tun; denn wir würden dem HERRN, unserm Gott, der Ägypter Greuel opfern! Siehe, wenn wir dann der Ägypter Greuel vor ihren Augen opferten, würden sie uns nicht steinigen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Drei Tagereisen weit wollen wir in die Wüste ziehen und dem HERRN, unserm Gott, opfern, wie er uns befehlen wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Da sprach der Pharao: Ich will euch ziehen lassen, daß ihr dem HERRN, eurem Gott, in der Wüste opfert; aber ziehet ja nicht weiter! Bittet für mich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Mose sprach: Siehe, ich gehe hinaus von dir und will den HERRN bitten, daß die Hundsfliegen morgen vom Pharao, von seinen Knechten und von seinem Volke genommen werden; nur daß der Pharao uns nicht mehr täusche, indem er das Volk doch nicht ziehen läßt, dem HERRN zu opfern!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Und Mose ging hinaus vom Pharao und bat den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Und der HERR tat, wie Mose gesagt hatte, also daß die Hundsfliegen vom Pharao, von seinen Knechten und von seinem Volke wichen, so daß nicht eine übrigblieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Aber der Pharao verhärtete sein Herz auch diesmal und ließ das Volk nicht ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Da sprach der HERR zu Mose: Gehe hinein zum Pharao und sprich zu ihm: So spricht der HERR, der Gott der Hebräer: Laß mein Volk gehen, daß es mir diene!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Denn wenn du dich weigerst, sie ziehen zu lassen und sie weiter aufhältst,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'siehe, so wird die Hand des HERRN kommen über dein Vieh auf dem Felde, über Pferde, Esel, Kamele, Rinder und Schafe, mit einer sehr schweren Viehseuche.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Und der HERR wird einen Unterschied machen zwischen dem Vieh der Israeliten und dem Vieh der Ägypter, daß aus allem, was den Kindern Israel gehört, kein einziges sterbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Und der HERR bestimmte eine Zeit und sprach: Morgen wird der HERR solches im Lande tun!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und der HERR tat solches am Morgen, und alles Vieh der Ägypter starb, aber von dem Vieh der Kinder Israel starb kein einziges.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Und der Pharao sandte Boten hin, und siehe, von dem Vieh Israels war nicht eines gestorben. Gleichwohl blieb das Herz des Pharao verhärtet, daß er das Volk nicht gehen ließ.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Da sprach der HERR zu Mose und Aaron: Nehmet eure Hände voll Ofenruß, und Mose sprenge ihn vor dem Pharao gen Himmel,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'daß er über ganz Ägyptenland stäube und zu Geschwüren werde, die als Blattern aufbrechen an Menschen und Vieh in ganz Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Da nahmen sie Ofenruß und standen vor dem Pharao, und Mose sprengte ihn gen Himmel. Da wurden Geschwüre daraus, die als Blattern aufbrachen an Menschen und Vieh,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'also daß die Zauberer wegen der Geschwüre nicht vor Mose stehen konnten. Denn an den Zauberern und an allen Ägyptern waren Geschwüre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Aber der HERR verstockte das Herz des Pharao, daß er nicht auf sie hörte, wie denn der HERR zu Mose gesagt hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Da sprach der HERR zu Mose: Mache dich am Morgen früh auf und tritt vor den Pharao und sprich zu ihm: So spricht der HERR, der Gott der Hebräer: Laß mein Volk gehen, daß es mir diene!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Sonst will ich diesmal alle meine Plagen gegen dein Herz richten und gegen deine Knechte und gegen dein Volk, damit du erfahrest, daß auf der ganzen Erde nicht meinesgleichen ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Denn ich hätte meine Hand schon ausstrecken und dich und dein Volk mit Pestilenz schlagen können, daß du von der Erde vertilgt worden wärest;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'aber ich habe dich deswegen bestehen lassen, daß ich dir meine Macht zeige, und daß mein Name auf der ganzen Erde verkündigt werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Stellst du dich aber meinem Volk noch weiter entgegen und willst es nicht ziehen lassen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'siehe, so will ich morgen um diese Zeit einen sehr schweren Hagel regnen lassen, desgleichen in Ägypten bisher nicht gewesen, seit der Zeit, da es gegründet wurde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Und nun laß dein Vieh und alles, was du auf dem Felde hast, in Sicherheit bringen; denn auf alle Menschen und alles Vieh, die sich auf dem Felde befinden und nicht in den Häusern versammelt sind, auf die wird der Hagel fallen, und sie werden umkommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer nun von den Knechten des Pharao des HERRN Wort fürchtete, der ließ seine Knechte und sein Vieh in die Häuser fliehen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'welcher Herz sich aber nicht an des HERRN Wort kehrte, die ließen ihre Knechte und ihr Vieh auf dem Felde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Da sprach der HERR zu Mose: Strecke deine Hand aus gen Himmel, damit es über ganz Ägyptenland hagle, über die Menschen und über das Vieh und über alles Gewächs auf dem Felde in Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Also streckte Mose seinen Stab gen Himmel. Und der HERR ließ donnern und hageln, daß das Feuer auf die Erde schoß. Und der HERR ließ Hagel regnen auf Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Es war aber zugleich Hagel und ein unaufhörliches Blitzen mitten in den Hagel hinein, so stark, daß desgleichen in ganz Ägypten niemals gewesen, seitdem es bevölkert ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel erschlug in ganz Ägyptenland alles, was auf dem Felde war, Menschen und Vieh. Auch zerschlug der Hagel alles Gewächs auf dem Felde und zerbrach alle Bäume auf dem Lande.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur im Lande Gosen, wo die Kinder Israel waren, hagelte es nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da schickte der Pharao hin und ließ Mose und Aaron rufen und sprach zu ihnen: Diesmal habe ich mich versündigt! Der HERR ist gerecht; ich aber und mein Volk sind schuldig!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Bittet aber den HERRN, daß des Donners Gottes und des Hagels genug sei, so will ich euch ziehen lassen, damit ihr nicht länger hier bleibet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mose sprach zu ihm: Wenn ich zur Stadt hinaus komme, so will ich meine Hände gegen den HERRN ausstrecken; so wird der Donner ablassen und kein Hagel mehr sein, damit du erfahrest, daß die Erde des HERRN ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Ich weiß aber, daß du und deine Knechte euch vor Gott, dem HERRN, noch nicht fürchtet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Es waren aber der Flachs und die Gerste zerschlagen; denn die Gerste hatte Ähren und der Flachs Knospen getrieben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Aber der Weizen und der Spelt waren nicht zerschlagen; denn die kommen später.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Nun ging Mose vom Pharao weg zur Stadt hinaus und streckte seine Hand aus gegen den HERRN, und der Donner und der Hagel ließen nach, und der Regen fiel nicht mehr auf die Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Da aber der Pharao sah, daß der Regen, der Hagel und der Donner nachließen, versündigte er sich weiter und verhärtete sein Herz, er und seine Knechte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Also ward das Herz des Pharao verstockt, daß er die Kinder Israel nicht ziehen ließ, wie der HERR durch Mose geredet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Da sprach der HERR zu Mose: Gehe zum Pharao, denn ich habe sein und seiner Knechte Herz verstockt, daß ich diese meine Zeichen unter ihnen tue,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und daß du vor den Ohren deiner Kinder und Kindeskinder verkündigest, was ich in Ägypten ausgerichtet und wie ich meine Zeichen unter ihnen bewiesen habe, auf daß ihr erkennet, daß ich der HERR bin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Also gingen Mose und Aaron zum Pharao und sprachen zu ihm: So spricht der HERR, der Gott der Hebräer: Wie lange willst du dich vor mir nicht demütigen? Laß mein Volk gehen, daß es mir diene!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Wenn du dich aber weigerst, mein Volk ziehen zu lassen, siehe, so lasse ich morgen Heuschrecken in dein Land kommen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'und sie sollen das Land so bedecken, daß man die Erde nicht sehen kann, und sie sollen den Rest auffressen, der gerettet worden und von dem Hagel übriggeblieben ist, und sollen alle eure grünenden Bäume auf dem Felde kahl fressen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'und sollen dein Haus und aller deiner Knechte Häuser und aller Ägypter Häuser anfüllen, wie es deine Väter und Vorväter nie gesehen haben, seitdem sie im Lande sind, bis auf diesen Tag. Und er wandte sich und ging vom Pharao hinaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Da sprachen die Knechte des Pharao zu ihm: Wie lange soll uns dieser zum Fallstrick sein? Laß die Leute gehen, daß sie dem HERRN, ihrem Gott, dienen; merkst du noch nicht, daß Ägypten zugrunde geht?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Da holte man Mose und Aaron wieder zum Pharao; der sprach zu ihnen: Geht hin, dienet dem HERRN, eurem Gott! Welche sind es aber, die hingehen werden?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mose sprach: Wir wollen mit unsern Jungen und Alten, mit unsern Söhnen und Töchtern, mit unsern Schafen und Rindern gehen; denn wir haben ein Fest des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Er sprach zu ihnen: Der HERR sei ebenso mit euch, wie ich euch samt euren Kindern ziehen lasse! Sehet da, ihr habt Böses im Sinn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nicht also, sondern ihr Erwachsenen geht hin und dienet dem HERRN; denn das habt ihr auch begehrt! Und man jagte sie weg vom Pharao.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da sprach der HERR zu Mose: Strecke deine Hand über Ägypten, damit die Heuschrecken über Ägypten kommen und alles Gewächs im Lande auffressen samt allem, was vom Hagel übriggeblieben ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Da streckte Mose seinen Stab über Ägyptenland aus, und der HERR ließ einen Ostwind über das Land wehen den ganzen Tag und die ganze Nacht; und am Morgen führte der Ostwind die Heuschrecken her.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Und die Heuschrecken kamen über ganz Ägyptenland und ließen sich nieder im ganzen Gebiet von Ägypten, so sehr viele, daß zuvor desgleichen niemals gewesen ist, noch künftig sein wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Denn sie bedeckten das ganze Land und verfinsterten es. Und sie fraßen alle Bodengewächse und alle Baumfrüchte, die vom Hagel übriggeblieben waren, und ließen nichts Grünes übrig an den Bäumen und an den Feldgewächsen in ganz Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Da ließ der Pharao Mose und Aaron eilends rufen und sprach: Ich habe mich versündigt an dem HERRN, eurem Gott, und an euch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Und nun vergib mir meine Sünde nur noch diesmal und bittet den HERRN, euren Gott, daß er diesen Tod von mir abwende!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Und er ging hinaus vom Pharao und bat den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Da wandte der HERR den Wind, daß er sehr stark aus dem Westen wehte und die Heuschrecken aufhob und sie ins Schilfmeer warf, so daß an allen Orten Ägyptens nicht eine übrig blieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Aber der HERR verstockte das Herz des Pharao, daß er die Kinder Israel nicht ziehen ließ.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Und der HERR sprach zu Mose: Strecke deine Hand gen Himmel, daß es im Ägyptenland so finster werde, daß man die Finsternis greifen kann!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Da streckte Mose seine Hand gen Himmel. Und es ward eine dicke Finsternis in ganz Ägyptenland, drei Tage lang,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'daß während drei Tagen niemand den andern sah, noch jemand von seinem Platz aufstand. Aber bei allen Kindern Israel war es hell in ihren Wohnungen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da ließ der Pharao Mose rufen und sprach: Geht hin, dienet dem HERRN; nur eure Schafe und Rinder sollen hier bleiben; lasset auch eure Kinder mit euch ziehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mose sprach: Du mußt auch Schlachtopfer und Brandopfer in unsere Hände geben, daß wir sie dem HERRN, unserm Gott, darbringen können;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'aber auch unser eigenes Vieh soll mit uns gehen, und nicht eine Klaue darf dahinten bleiben; denn von demselben werden wir nehmen zum Dienste des HERRN, unseres Gottes. Auch wissen wir nicht, womit wir dem HERRN dienen sollen, bis wir dorthin kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber der HERR verstockte das Herz des Pharao, daß er sie nicht ziehen lassen wollte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und Pharao sprach zu ihm: Gehe weg von mir und hüte dich, daß du nicht mehr vor mein Angesicht kommest; an welchem Tage du vor mein Angesicht kommst, sollst du sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mose antwortete: Wie du gesagt hast; ich will nicht mehr vor dein Angesicht kommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Und der HERR sprach zu Mose: Ich will noch eine Plage über den Pharao und über Ägypten bringen; darnach wird er euch fortziehen lassen; und wenn er euch ziehen läßt, so wird er euch sogar völlig wegtreiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'So sage nun zum Volk, daß ein jeder von seinem Nächsten und eine jede von ihrer Nachbarin silberne und goldene Geschirre fordere.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Und der HERR gab dem Volke Gunst in den Augen der Ägypter. So war auch Mose ein sehr großer Mann in Ägypten vor den Knechten des Pharao und vor dem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Und Mose sprach: So spricht der HERR: Ich will zu Mitternacht ausgehen mitten durch Ägypten,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'und alle Erstgeburt in Ägypten soll sterben; von dem Erstgeborenen des Pharao, der auf seinem Throne sitzt, bis an den Erstgeborenen der Magd, die hinter der Mühle ist; auch alle Erstgeburt unter dem Vieh.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Und es wird ein großes Geschrei in ganz Ägypten sein, desgleichen niemals gewesen ist, noch sein wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Aber bei allen Kindern Israel soll kein Hund die Zunge regen, weder gegen Menschen noch gegen das Vieh, auf daß ihr erfahret, was der HERR für einen Unterschied macht zwischen Ägypten und Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Dann werden alle diese deine Knechte zu mir herabkommen und mir zu Füßen fallen und sagen: Ziehe aus, du und alles Volk hinter dir her! Darnach werde ich ausziehen! Und er ging vom Pharao mit grimmigem Zorn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Der HERR aber hatte zu Mose gesagt: Der Pharao wird euch nicht hören, damit meiner Wunder in Ägypten viel geschehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Also hatten Mose und Aaron alle diese Wunder vor dem Pharao getan; aber der HERR verstockte das Herz des Pharao, daß er die Kinder Israel nicht aus seinem Lande entließ.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Und der HERR redete mit Mose und Aaron im Ägyptenland und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Dieser Monat soll euch der erste Monat sein, und von ihm sollt ihr die Monate des Jahres anheben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Saget der ganzen Gemeinde Israel und sprechet: Am zehnten Tage dieses Monats verschaffe sich jeder Hausvater ein Lamm, ein Lamm für jede Haushaltung;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'wenn aber die Haushaltung zu klein ist für ein Lamm, so nehme er es gemeinsam mit seinem Nachbar, welcher zunächst bei seinem Hause wohnt; dabei sollen sie für das Lamm die Zahl der Seelen berechnen, je nachdem ein jeder zu essen vermag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Dieses Lamm aber soll vollkommen sein, ein Männlein und einjährig. Von den Lämmern und Ziegen sollt ihr es nehmen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'und sollt es behalten bis auf den vierzehnten Tag dieses Monats. Und die ganze Versammlung der Gemeinde Israel soll es zwischen den Abendstunden schächten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Und sie sollen von dem Blut nehmen und beide Türpfosten und die Oberschwellen der Häuser, darin sie essen, damit bestreichen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Und sollen also in derselben Nacht das Fleisch essen, am Feuer gebraten, mit ungesäuertem Brot; mit bitteren Kräutern sollen sie es essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ihr sollt nichts davon roh essen, auch nicht im Wasser gesotten, sondern nur am Feuer gebraten, sein Haupt samt seinen Schenkeln und den innern Teilen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'und sollt nichts davon übriglassen bis zum andern Morgen. Wenn aber etwas übrigbleibt bis zum Morgen, sollt ihr es mit Feuer verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Also sollt ihr es aber essen: Um eure Lenden gegürtet, eure Schuhe an euren Füßen und eure Stäbe in euren Händen, und in Eile sollt ihr es essen; es ist des HERRN Passah.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Denn ich will in derselben Nacht durch Ägypten gehen und alle Erstgeburt in Ägypten schlagen, vom Menschen an bis auf das Vieh, und will an allen Göttern der Ägypter Gerichte üben, ich, der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Und das Blut soll euch zum Zeichen dienen an euren Häusern, darin ihr seid, daß, wenn ich das Blut sehe, ich an euch vorübergehe und euch die Plage nicht widerfahre, die euch verderbe, wenn ich die Ägypter schlagen werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Und dieser Tag soll euch zum Gedächtnis sein, und ihr sollt ihn feiern als ein Fest des HERRN in allen euren Geschlechtern; als ewige Ordnung sollt ihr ihn feiern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage lang sollt ihr ungesäuertes Brot essen, darum sollt ihr am ersten Tag den Sauerteig aus euren Häusern entfernen. Denn wer gesäuertes Brot ißt vom ersten Tage an bis auf den siebenten Tag, dessen Seele soll ausgerottet werden aus Israel!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Ihr sollt aber am ersten Tage eine heilige Versammlung halten, desgleichen am siebenten Tage eine heilige Versammlung. Keine Arbeit sollt ihr tun; außer was zur Speise nötig ist für alle Seelen, das allein darf von euch besorgt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Und beobachtet die Tage der ungesäuerten Brote! Denn eben an demselben Tage habe ich euer Heer aus Ägypten geführt; darum sollt ihr diesen Tag als ewige Ordnung beobachten in allen euren Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Am vierzehnten Tage des ersten Monats, am Abend, sollt ihr ungesäuertes Brot essen bis an den einundzwanzigsten Tag des Monats, am Abend,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'daß man sieben Tage lang keinen Sauerteig in euren Häusern finde. Denn wer gesäuertes Brot ißt, dessen Seele soll ausgerottet werden aus der Gemeinde Israel, er sei ein Fremdling oder Einheimischer im Lande.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'So esset kein gesäuertes, sondern ungesäuertes Brot in allen euren Wohnungen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Und Mose berief alle Ältesten in Israel und sprach zu ihnen: Machet euch auf und nehmet euch Lämmer für eure Familien und schächtet das Passah!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Und nehmet einen Büschel Ysop und tauchet ihn in das Blut im Becken und bestreicht mit diesem Blut im Becken die Oberschwelle und die zwei Türpfosten; und kein Mensch von euch gehe zu seiner Haustüre hinaus bis an den Morgen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Denn der HERR wird umhergehen und die Ägypter schlagen. Und wenn er das Blut an der Oberschwelle und an den beiden Pfosten sehen wird, so wird er, der HERR, an der Tür vorübergehen und den Verderber nicht in eure Häuser kommen lassen, zu schlagen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Und ihr sollt diese Verordnung beobachten als eine Satzung, welche dir und deinen Kindern auf ewig gilt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Und wenn ihr in das Land kommt, das euch der HERR geben wird, wie er geredet hat, so haltet diesen Dienst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Und wenn eure Kinder zu euch sagen werden: Was habt ihr da für einen Dienst?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'So sollt ihr sagen: Es ist das Passah-Opfer des HERRN, der an den Häusern der Kinder Israel vorüberschritt in Ägypten, als er die Ägypter schlug und unsere Häuser errettete.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Da neigte sich das Volk und betete an. Und die Kinder Israel gingen hin und taten solches; wie der HERR Mose und Aaron geboten hatte, also taten sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Und es begab sich zu Mitternacht, da schlug der HERR alle Erstgeburt in Ägypten, von dem ersten Sohne des Pharao, der auf dem Throne saß, bis auf den ersten Sohn der Gefangenen, die in dem Gefängnisse waren, auch alle Erstgeburt des Viehes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Da stand der Pharao auf in derselben Nacht, er und alle seine Knechte und alle Ägypter; und es war ein großes Geschrei in Ägypten, denn es gab kein Haus, darin nicht ein Toter war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Und er berief Mose und Aaron in der Nacht und sprach: Machet euch auf und ziehet aus von meinem Volke, ihr und die Kinder Israel, und gehet hin, dienet dem HERRN, wie ihr gesagt habt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Nehmet auch eure Schafe und eure Rinder mit euch, wie ihr gesagt habt, und gehet hin und segnet mich auch!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Und die Ägypter drangen sehr in das Volk, daß sie dasselbe eilends aus dem Lande trieben; denn sie sprachen: Wir sind alle des Todes!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Und das Volk trug seinen Teig, ehe er gesäuert war, nämlich ihre Backtröge in ihre Kleider gebunden, auf ihren Achseln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Und die Kinder Israel taten, wie Mose sagte, und forderten von den Ägyptern silberne und goldene Geschirre und Kleider.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Dazu gab der HERR dem Volke bei den Ägyptern Gunst, daß sie ihrem Begehren willfahrten; und sie beraubten Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Also zogen die Kinder Israel aus von Raemses gen Sukkot, bei sechshunderttausend Mann Fußvolk, die Kinder nicht inbegriffen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Auch zogen mit ihnen viele Mischlinge und Schafe und Rinder und sehr viel Vieh.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Und sie machten aus dem Teige, den sie aus Ägypten brachten, ungesäuerte Kuchen; denn er war nicht gesäuert, weil sie aus Ägypten vertrieben wurden und nicht verziehen konnten; und sie hatten sich sonst keine Zehrung zubereitet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Die Zeit aber, welche die Kinder Israel in Ägypten gewohnt haben, beträgt vierhundertunddreißig Jahre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Als nun die vierhundertunddreißig Jahre verflossen waren, an eben diesem Tag ging das ganze Heer des HERRN aus Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Darum wird diese Nacht dem HERRN gefeiert, weil er sie aus Ägypten geführt hat. Diese Nacht sollen alle Kinder Israel dem HERRN feiern, auch ihre künftigen Geschlechter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Und der HERR sprach zu Mose und Aaron: Dies ist die Ordnung des Passah: Kein Fremder soll davon essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Wer aber ein um Geld erkaufter Knecht ist, den beschneide man; alsdann esse er davon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Beisasse und Taglöhner soll nicht davon essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem Hause soll man es essen. Ihr sollt vom Fleisch nichts vor das Haus hinaustragen, und kein Knochen werde ihm zerbrochen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde Israel soll es feiern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Wo sich aber ein Fremdling bei dir aufhält und dem HERRN das Passah halten will, der beschneide alles, was männlich ist; und dann erst mache er sich herzu, daß er es feiere und sei wie ein Einheimischer des Landes; denn kein Unbeschnittener soll davon essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Einerlei Gesetz soll dem Einheimischen und dem Fremdling gelten, der unter euch wohnt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Und alle Kinder Israel taten solches; wie der HERR dem Mose und Aaron geboten hatte, also taten sie;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'aber der HERR führte an eben diesem Tag die Kinder Israel nach ihren Heerscharen aus Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Heilige mir alle Erstgeburt bei den Kindern Israel, von Menschen und Vieh; denn sie sind mein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Da sprach Mose zum Volk: Gedenket an diesen Tag, an dem ihr aus Ägypten, aus dem Diensthause, gegangen seid, daß der HERR euch mit mächtiger Hand von dannen ausgeführt hat: darum sollt ihr nichts Gesäuertes essen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute seid ihr ausgezogen, im Monat Abib.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Wenn dich nun der HERR in das Land der Kanaaniter, Hetiter, Amoriter, Heviter und Jebusiter bringen wird, wie er deinen Vätern geschworen hat, dir ein Land zu geben, das von Milch und Honig fließt, so sollst du diesen Dienst in diesem Monat halten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage lang sollst du ungesäuertes Brot essen, und am siebenten Tag ist das Fest des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Man soll diese sieben Tage lang ungesäuertes Brot essen, daß bei dir kein Sauerteig gesehen werde; in allen deinen Grenzen soll kein gesäuertes Brot gesehen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Und du sollst deinem Sohne an jenem Tage erklären und sagen: Es ist um deswillen, was der HERR an mir getan, als ich aus Ägypten zog.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und es soll dir zum Zeichen sein in deiner Hand und zum Denkmal vor deinen Augen, daß des HERRN Gesetz in deinem Munde sei, weil der HERR dich mit mächtiger Hand aus Ägypten geführt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Darum sollst du die Ordnung beobachten, zur bestimmten Zeit, Jahr für Jahr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Wenn dich nun der HERR in das Land der Kanaaniter gebracht, wie er dir und deinen Vätern geschworen, und es dir gegeben hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'so sollst du dem HERRN alle Erstgeburt aussondern, auch jeden ersten Wurf vom Vieh, den du bekommst; alles, was männlich ist, soll dem HERRN gehören.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Aber jede Erstgeburt vom Esel sollst du mit einem Schaf lösen; wenn du es aber nicht lösest, so brich ihm das Genick. Desgleichen alle Erstgeburt von Menschen unter deinen Kindern sollst du lösen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Und wenn dich künftig dein Sohn fragen wird: Was ist das? So sollst du ihm sagen: Der HERR hat uns mit mächtiger Hand aus Ägypten, aus dem Diensthause, geführt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Denn es begab sich, als der Pharao sich hart widersetzte, uns freizulassen, da erschlug der HERR alle Erstgeburt in Ägypten, von der Menschen Erstgeburt bis an die Erstgeburt des Viehes: darum opfere ich dem HERRN alle männliche Erstgeburt; alle Erstgeburt aber meiner Söhne löse ich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und das soll dir zum Zeichen in deiner Hand und zum Denkmal vor deinen Augen sein, daß uns der HERR mit mächtiger Hand aus Ägypten geführt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Als nun der Pharao das Volk gehen ließ, führte sie Gott nicht auf die Straße durch der Philister Land, wiewohl sie die nächste war; denn Gott gedachte, es möchte das Volk gereuen, wenn es Krieg sähe, und möchte wieder nach Ägypten umkehren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Darum führte Gott das Volk den Umweg durch die Wüste am Schilfmeer. Und die Kinder Israel zogen gerüstet aus Ägypten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Und Mose nahm die Gebeine Josephs mit sich; denn er hatte einen Eid von den Kindern Israel genommen und gesagt: Gott wird euch gewiß heimsuchen; dann führet meine Gebeine mit euch von hinnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Also zogen sie aus von Sukkot und lagerten sich in Etam, am Wüstenrand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Und der HERR zog vor ihnen her, am Tage in einer Wolkensäule, daß er sie den rechten Weg führete, und des Nachts in einer Feuersäule, daß er ihnen leuchtete, damit sie bei Tag und bei Nacht wandeln konnten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Die Wolkensäule wich nimmer vom Volk des Tages, noch die Feuersäule des Nachts.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Sage den Kindern Israel, daß sie sich herumwenden und sich vor Pi-Hahiroth, zwischen Migdol und dem Meer, lagern; gerade gegenüber von Baal-Zephon lagert euch am Meer!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Denn der Pharao wird von den Kindern Israel sagen: Sie sind im Lande verirrt, die Wüste hat sie eingeschlossen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Und ich will sein Herz verstocken, daß er ihnen nachjage, und will mich am Pharao und an seiner ganzen Macht verherrlichen; und die Ägypter sollen erfahren, daß ich der HERR bin!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Als nun dem König von Ägypten angezeigt ward, daß das Volk fliehe, wandte sich sein und seiner Knechte Herz gegen das Volk; und sie sprachen: Warum haben wir das getan, daß wir Israel haben ziehen lassen, daß sie uns nicht mehr dienen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Und er spannte seinen Wagen an und nahm sein Volk mit sich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Er nahm auch sechshundert auserlesene Wagen und alle Wagen in Ägypten und Wagenkämpfer auf jedem.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Denn der HERR verstockte das Herz des Pharao, des Königs von Ägypten, daß er denn Kindern Israel nachjagte, obwohl sie durch eine hohe Hand auszogen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Also jagten ihnen die Ägypter nach mit allen Rossen, Wagen und Reitern des Pharao und mit seiner Macht und ereilten sie, als sie sich am Meere, bei Pi-Hahiroth, Baal-Zephon gegenüber, gelagert hatten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Und als der Pharao nahe zu ihnen kam, erhoben die Kinder Israel ihre Augen und siehe, die Ägypter zogen hinter ihnen her; und sie fürchteten sich sehr. Da schrieen die Kinder Israel zum HERRN');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'und sprachen zu Mose: Sind etwa keine Gräber in Ägypten, daß du uns genommen hast, damit wir in der Wüste sterben? Warum hast du uns das angetan, daß du uns aus Ägypten geführt hast?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Haben wir dir nicht in Ägypten schon gesagt: Laß ab von uns, daß wir den Ägyptern dienen? Denn es wäre uns ja besser, den Ägyptern zu dienen, als in der Wüste zu sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mose sprach zum Volk: Fürchtet euch nicht, tretet hin und sehet, was für ein Heil der HERR heute an euch tun wird; denn diese Ägypter, die ihr heute sehet, sollt ihr nimmermehr sehen ewiglich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Der HERR wird für euch streiten, und ihr sollt stille sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Der HERR sprach zu Mose: Was schreist du zu mir? Sage den Kindern Israel, daß sie ziehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Du aber hebe deinen Stab auf und strecke deine Hand über das Meer und zerteile es, daß die Kinder Israel mitten durch das Meer auf dem Trockenen gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ich aber, siehe, ich will das Herz der Ägypter verstocken, daß sie ihnen nachlaufen; dann will ich mich verherrlichen am Pharao und an seiner ganzen Macht, an seinen Wagen und an seinen Reitern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Und die Ägypter sollen erfahren, daß ich der HERR bin, wenn ich mich am Pharao, an seinen Wagen und an seinen Reitern verherrliche.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Da erhob sich der Engel Gottes, der vor dem Heer Israels herzog, und trat hinter sie; und die Wolkensäule machte sich auch auf von ihrem Angesicht weg und trat hinter sie');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'und kam zwischen das Heer der Ägypter und das Heer Israels; und sie war für die einen Wolke und Finsternis, und für die andern erleuchtete sie die Nacht, so daß diese und jene die ganze Nacht nicht zusammenkamen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Als nun Mose seine Hand über das Meer streckte, ließ der HERR dasselbe die ganze Nacht durch einen starken Ostwind ablaufen und machte das Meer trocken, und die Wasser teilten sich voneinander.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Und die Kinder Israel gingen hinein mitten in das Meer auf dem Trockenen, und das Wasser war ihnen wie Mauern zu ihrer Rechten und zu ihrer Linken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Und die Ägypter jagten nach und gingen hinein ihnen nach, alle Rosse des Pharao, seine Wagen und seine Reiter, mitten ins Meer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Als nun die Morgenwache kam, schaute der HERR aus der Feuersäule und Wolke auf der Ägypter Heer und verwirrte das Heer der Ägypter');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'und stieß die Räder von ihren Wagen und brachte sie ins Gedränge. Da sprachen die Ägypter: Lasset uns vor Israel fliehen, denn der HERR streitet für sie wider die Ägypter!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Da sprach der HERR zu Mose: Strecke deine Hand aus über das Meer, damit das Wasser wieder zurückkehre über die Ägypter, über ihre Wagen und über ihre Reiter!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Da streckte Mose seine Hand aus über das Meer, und das Meer kam beim Anbruch des Morgens wieder in seine Strömung, und die Ägypter flohen ihm entgegen. Also stürzte der HERR die Ägypter ins Meer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Denn das Wasser kam wieder und bedeckte die Wagen und Reiter der ganzen Macht des Pharao, die ihnen ins Meer nachgefolgt waren, daß nicht einer aus ihnen übrigblieb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Aber die Kinder Israel gingen trocken mitten durchs Meer, und das Wasser diente ihnen als Mauern zu ihrer Rechten und zu ihrer Linken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Also half der HERR Israel an jenem Tage von der Ägypter Hand. Und Israel sah die Ägypter tot am Gestade des Meeres.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Als nun Israel die große Hand sah, die der HERR an den Ägyptern bewiesen hatte, fürchtete das Volk den HERRN, und sie glaubten dem HERRN und seinem Knecht Mose.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Damals sangen Mose und die Kinder Israel dem HERRN diesen Lobgesang und sprachen: Ich will dem HERRN singen, denn er hat sich herrlich erwiesen: Roß und Reiter hat er ins Meer gestürzt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Der HERR ist meine Kraft und mein Psalm, und er ward mir zum Heil! Das ist mein starker Gott, ich will ihn preisen; er ist meines Vaters Gott, ich will ihn erheben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Der HERR ist ein Kriegsmann, HERR ist sein Name.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Wagen des Pharao und seine Macht warf er ins Meer. Seine auserlesenen Wagenkämpfer sind im Schilfmeer versunken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Die Tiefe hat sie bedeckt, sie fielen zu Grunde wie Steine.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'HERR, deine Rechte Hand ist mit Kraft geschmückt; HERR, deine Rechte Hand hat den Feind erschlagen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Und mit deiner großen Macht hast du deine Widersacher vertilgt; du ließest deinen Grimm ausgehen, der verzehrte sie wie Stoppeln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Durch den Hauch deines Zornes türmte das Wasser sich auf; es standen die Wogen wie ein Damm. Die Fluten erstarrten mitten im Meer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Der Feind sprach: Ich will sie jagen, ich will sie ergreifen, ich will den Raub verteilen, will meinen Mut an ihnen kühlen, ich will mein Schwert ausziehen, meine Hand soll sie vertilgen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Als du aber mit deinem Winde wehtest, da bedeckte sie das Meer, sie versanken wie Blei im mächtigen Wasser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'HERR, wer ist dir gleich unter den Göttern, wer ist in der Heiligkeit so herrlich, mit Lobgesängen so hoch zu verehren und so wundertätig wie du?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Als du deine rechte Hand ausstrecktest, verschlang sie die Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du leitest in deiner Gnade das Volk, das du erlöst hast, und bringst sie durch deine Kraft zur Wohnung deines Heiligtums.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Wenn das die Völker hören, so erzittern sie, Angst kommt die Philister an;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'es erschrecken die Fürsten Edoms, Zittern befällt die Gewaltigen Moabs; alle Einwohner Kanaans werden verzagt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Laß durch deinen großen Arm Schrecken und Furcht über sie fallen, daß sie erstarren wie Steine, bis dein Volk, HERR, hindurchziehe, bis dein Volk hindurchziehe, das du erworben hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Bring sie hinein und pflanze sie auf den Berg deines Erbteils, an den Ort, den du, HERR, zu deiner Wohnung gemacht hast, zu dem Heiligtum, o HERR, welches deine Hände bereitet haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Der HERR wird herrschen immer und ewig!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Denn der Pharao ging ins Meer hinein mit Rossen, mit seinen Wagen und Reitern, und der HERR ließ das Meer wieder über sie kommen; aber die Kinder Israel gingen trocken mitten durchs Meer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Und Mirjam, die Prophetin, Aarons Schwester, nahm die Handpauke in ihre Hand, und alle Weiber folgten ihr nach mit Handpauken und im Reigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Und Mirjam antwortete ihnen: Lasset uns dem HERRN singen, denn er hat sich herrlich erwiesen: Roß und Reiter hat er ins Meer gestürzt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Darnach ließ Mose die Israeliten vom Schilfmeer aufbrechen, daß sie zur Wüste Sur zogen; und sie wanderten drei Tage lang in der Wüste und fanden kein Wasser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Da kamen sie nach Mara; aber sie konnten das Wasser von Mara nicht trinken, denn es war sehr bitter. Daher hieß man es Mara.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Da murrte das Volk wider Mose und sprach: Was sollen wir trinken?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Er aber schrie zum HERRN, und der HERR zeigte ihm ein Holz, das warf er ins Wasser, da ward das Wasser süß. Daselbst legte er ihnen Pflicht und Recht vor, und daselbst versuchte er sie und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Wirst du der Stimme des HERRN, deines Gottes, gehorchen und tun, was vor ihm recht ist, und seine Gebote zu Ohren fassen und alle seine Satzungen halten, so will ich der Krankheiten keine auf dich legen, die ich auf Ägypten gelegt habe; denn ich, der HERR, bin dein Arzt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Und sie kamen nach Elim, da waren zwölf Wasserbrunnen und siebzig Palmbäume, und sie lagerten sich daselbst am Wasser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Darnach zog die ganze Gemeinde der Kinder Israel von Elim weg in die Wüste Sin, die zwischen Elim und Sinai liegt, am fünfzehnten Tag des zweiten Monats, nachdem sie aus Ägypten gezogen waren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Und die ganze Gemeinde der Kinder Israel murrte wider Mose und Aaron in der Wüste.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Und die Kinder Israel sprachen zu ihnen: Wären wir doch durch des HERRN Hand in Ägypten gestorben, als wir bei den Fleischtöpfen saßen und Brot die Fülle zu essen hatten. Denn ihr habt uns darum in diese Wüste ausgeführt, daß ihr diese ganze Gemeinde Hungers sterben lasset!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sprach der HERR zu Mose: Siehe, ich will euch Brot vom Himmel regnen lassen; dann soll das Volk hinausgehen und täglich sammeln, was es bedarf, damit ich erfahre, ob es in meinem Gesetze wandeln wird oder nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Am sechsten Tage aber sollen sie zubereiten, was sie eingebracht haben, und zwar doppelt so viel als sie täglich sammeln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Da sprachen Mose und Aaron zu allen Kindern Israel: Am Abend sollt ihr erfahren, daß euch der HERR aus Ägypten geführt hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'und am Morgen werdet ihr des HERRN Herrlichkeit sehen, denn er hat euer Murren wider den HERRN gehört. Aber was sind wir, daß ihr wider uns murret?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Weiter sprach Mose: Der HERR wird euch am Abend Fleisch zu essen geben und am Morgen Brot die Fülle; denn er, der HERR, hat euer Murren gehört, womit ihr wider ihn gemurrt habt. Denn was sind wir? Euer Murren ist nicht wider uns, sondern wider den HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Und Mose sprach zu Aaron: Sage der ganzen Gemeinde der Kinder Israel: Kommt herzu vor den HERRN, denn er hat euer Murren gehört!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Und als Aaron zu der ganzen Gemeinde der Kinder Israel redete, wandten sie sich gegen die Wüste und siehe, die Herrlichkeit des HERRN erschien in einer Wolke.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und der HERR sprach zu Mose:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ich habe das Murren der Kinder Israel gehört. Sage ihnen: Um den Abend sollt ihr Fleisch zu essen haben und am Morgen mit Brot gesättigt werden; also sollt ihr erfahren, daß ich der HERR, euer Gott bin!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Als es nun Abend war, kamen Wachteln herauf und bedeckten das Lager, und am Morgen lag der Tau um das Lager her.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Und als der Tau, der da lag, verschwunden war, siehe, da lag etwas in der Wüste, rund und klein, so fein wie der Reif auf der Erde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Und als es die Kinder Israel sahen, sprachen sie untereinander: Was ist das? denn sie wußten nicht, was es war. Mose aber sprach zu ihnen: Es ist das Brot, das euch der HERR zu essen gegeben hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Das ist aber der Befehl, welchen der HERR gegeben hat: Ein jeder sammle davon, soviel er essen mag, einen Gomer für den Kopf, nach der Zahl eurer Seelen; ein jeder nehme für die, die in seiner Hütte sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Und die Kinder Israel taten also und sammelten, einer viel, der andere wenig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Aber als man es mit dem Gomer maß, hatte der, welcher viel gesammelt hatte, keinen Überfluß, und dem, der wenig gesammelt hatte, mangelte nichts, sondern ein jeder hatte für sich gesammelt, soviel er essen mochte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Und Mose sprach zu ihnen: Niemand lasse etwas davon übrigbleiben bis zum andern Morgen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie gehorchten Mose nicht; denn etliche ließen davon übrigbleiben bis zum Morgen. Da wuchsen Würmer darin, und es ward stinkend. Und Mose ward zornig über sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Sie sammelten aber von demselben alle Morgen für sich, soviel ein jeder essen mochte; wenn aber die Sonne heiß schien, zerschmolz es.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Und am sechsten Tage sammelten sie doppelt so viel Brot, zwei Gomer für jede Person. Da kamen alle Obersten der Gemeinde und verkündigten es Mose.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Und er sprach zu ihnen: Das ist\'s, was der HERR gesagt hat: Morgen ist der Sabbat der heiligen Ruhe des HERRN; was ihr backen wollt, das backet, und was ihr kochen wollt, das kochet; was aber übrig ist, das hebet auf, damit es bis morgen erhalten bleibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Und sie ließen es bis an den Morgen bleiben, wie Mose geboten hatte; da ward es nicht stinkend und war auch kein Wurm darin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Da sprach Mose: Esset das heute, denn heute ist der Sabbat des HERRN; ihr werdet es heute nicht auf dem Felde finden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage sollt ihr es sammeln, aber am siebenten Tag ist der Sabbat, da wird keines zu finden sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Es begab sich aber am siebenten Tage, daß etliche vom Volke hinausgingen zu sammeln und nichts fanden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sprach der HERR zu Mose: Wie lange weigert ihr euch, meine Gebote und meine Satzungen zu halten?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Sehet, der HERR hat euch den Sabbat gegeben; darum gibt er euch am sechsten Tage für zwei Tage Brot; so bleibe nun jeder an seinem Platz und niemand gehe am siebenten Tage heraus von seinem Ort!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Also feierte das Volk am siebenten Tag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Und das Haus Israel nannte es Manna. Es war aber wie Koriandersamen, weiß, und hatte einen Geschmack wie Honigkuchen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Und Mose sprach: Das ist\'s, was der HERR geboten hat: Fülle einen Gomer davon und behalte ihn auf für eure Nachkommen, daß man das Brot sehe, womit ich euch in der Wüste gespeist habe, als ich euch aus Ägypten führte!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Und Mose sprach zu Aaron: Nimm ein Gefäß und tue einen Gomer voll Manna hinein und stelle es vor den HERRN, zur Aufbewahrung für eure Nachkommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Wie der HERR dem Mose geboten hatte, also stellte es Aaron daselbst vor das Zeugnis, zur Aufbewahrung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Und die Kinder Israel aßen das Manna vierzig Jahre lang, bis sie zu dem Lande kamen, darin sie wohnen sollten; bis sie an die Grenze Kanaans kamen, aßen sie das Manna.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ein Gomer ist der zehnte Teil eines Epha.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Und die ganze Gemeinde der Kinder Israel zog aus der Wüste Sin ihre Tagereisen, nach dem Befehl des HERRN, und lagerte sich in Raphidim; da hatte das Volk kein Wasser zu trinken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Darum zankten sie mit Mose und sprachen: Gebt uns Wasser, daß wir trinken! Mose sprach zu ihnen: Was zankt ihr mit mir? Warum versucht ihr den HERRN?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Als nun das Volk daselbst nach Wasser dürstete, murrten sie wider Mose und sprachen: Warum hast du uns aus Ägypten heraufgeführt, daß du uns und unsere Kinder und unser Vieh vor Durst sterben lässest?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mose schrie zum HERRN und sprach: Was soll ich mit diesem Volke tun? Es fehlt wenig, sie werden mich noch steinigen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Der HERR sprach zu Mose: Gehe hin vor das Volk und nimm etliche Älteste von Israel mit dir und nimm den Stab, mit dem du den Fluß schlugest, in deine Hand und gehe hin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Siehe, ich will daselbst vor dir auf einem Felsen in Horeb stehen; da sollst du den Felsen schlagen, so wird Wasser herauslaufen, daß das Volk trinke. Mose tat also vor den Ältesten Israels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Da hieß man den Ort Massa und Meriba, wegen des Zanks der Kinder Israel, und daß sie den HERRN versucht und gesagt hatten: Ist der HERR mitten unter uns oder nicht?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Da kam Amalek und stritt wider Israel in Raphidim.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Und Mose sprach zu Josua: Erwähle uns Männer und ziehe aus, streite wider Amalek! Morgen will ich auf des Hügels Spitze stehen und den Stab Gottes in meiner Hand haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Josua tat, wie Mose ihm sagte, daß er wider Amalek stritt. Mose aber und Aaron und Hur stiegen auf die Spitze des Hügels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Und solange Mose seine Hände aufhob, siegte Israel; wenn er aber seine Hände sinken ließ, siegte Amalek.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Aber die Hände Moses wurden schwer, darum nahmen sie einen Stein und legten denselben unter ihn, daß er sich darauf setzte. Aaron aber und Hur unterstützten seine Hände, auf jeder Seite einer. Also blieben seine Hände fest, bis die Sonne unterging.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Und Josua besiegte den Amalek und sein Volk durch die Schärfe des Schwertes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Da sprach der HERR zu Mose: Schreibe das zum Gedächtnis in ein Buch und lege es Josua in die Ohren, nämlich: ich will das Gedächtnis Amaleks unter dem Himmel ganz austilgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Und Mose baute dem HERRN einen Altar und hieß ihn: Der HERR ist mein Panier.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Und er sprach: Weil eine Hand auf dem Throne des HERRN erhoben ist, soll der Krieg des HERRN wider Amalek währen, von Geschlecht zu Geschlecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Und als Jethro, der Priester in Midian, Moses Schwiegervater, alles hörte, was Gott Mose und seinem Volk Israel getan, wie der HERR Israel aus Ägypten geführt hatte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'nahm Jethro, Moses Schwiegervater, die Zippora, das Weib Moses, die er zurückgesandt hatte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'und ihre zwei Söhne (der eine hieß Gersom; denn er sprach: Ich bin ein Fremdling in einem fremden Lande geworden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'und der andere Elieser; denn der Gott meines Vaters ist meine Hilfe gewesen und hat mich von dem Schwert des Pharao errettet)');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'und Jethro, Moses Schwiegervater, und seine Söhne und sein Weib kamen zu Mose in die Wüste, als er sich an dem Berge Gottes gelagert hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Und er ließ Mose sagen: Ich, Jethro, dein Schwiegervater, bin zu dir gekommen und dein Weib und ihre beiden Söhne mit ihr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da ging Mose hinaus, seinem Schwiegervater entgegen, und bückte sich vor ihm und küßte ihn. Und als sie einander gegrüßt hatten, gingen sie in die Hütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Da erzählte Mose seinem Schwiegervater alles, was der HERR dem Pharao und den Ägyptern um Israels willen getan hatte, und alle Mühsal, die ihnen auf dem Wege begegnet war, und wie der HERR sie errettet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jethro aber freute sich über alles Gute, das der HERR an Israel getan, und daß er sie von der Ägypter Hand errettet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro sprach: Gelobt sei der HERR, der euch von der Hand der Ägypter und von der Hand des Pharao errettet hat, ja, der sein Volk von der Hand der Ägypter errettet hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun weiß ich, daß der HERR größer ist als alle Götter; denn eben mit dem, womit sie Hochmut getrieben, ist er über sie gekommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Und Jethro, Moses Schwiegervater, nahm Brandopfer und Schlachtopfer, Gott zu opfern. Da kamen Aaron und alle Ältesten von Israel, um mit Moses Schwiegervater vor Gott das Brot zu essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Am andern Morgen setzte sich Mose, das Volk zu richten; und das Volk stand um Mose her bis an den Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Als aber Moses Schwiegervater alles sah, was er mit dem Volke tat, sprach er: Was machst du dir da für Umstände mit dem Volk? Warum sitzest du allein, und alles Volk steht um dich her vom Morgen bis zum Abend?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose antwortete seinem Schwiegervater: Das Volk kommt zu mir, Gott um Rat zu fragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Denn wenn sie eine Sache haben, kommen sie zu mir, daß ich entscheide, wer von beiden recht hat, und damit ich ihnen Gottes Ordnung und seine Gesetze kundtue.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Aber Moses Schwiegervater sprach zu ihm: Es ist nicht gut, was du tust!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du wirst müde und kraftlos, zugleich du und das Volk, das bei dir ist; denn das Geschäft ist dir zu schwer, du kannst es allein nicht ausrichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'So höre auf meine Stimme; ich will dir raten, und Gott wird mit dir sein. Tritt du für das Volk vor Gott');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'und erkläre ihnen die Ordnungen und Gesetze, daß du ihnen den Weg kundtuest, darauf sie zu wandeln haben, und die Werke, die sie tun sollen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Sieh dich aber unter allem Volk nach wackern Männern um, die gottesfürchtig, wahrhaftig und dem Geize feind sind; die setze über sie zu Obern über tausend, über hundert, über fünfzig und über zehn,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'daß sie das Volk allezeit richten; alle wichtigen Sachen aber sollen sie vor dich bringen, und alle geringen Sachen sollen sie selbst richten; so wird es dir leichter werden, wenn sie die Bürde mit dir tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Wirst du das tun, und gebietet es dir Gott, so magst du bestehen; und dann kann auch all dieses Volk in Frieden an seinen Ort kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mose folgte der Stimme seines Schwiegervaters und tat alles, was er sagte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Denn er erwählte wackere Männer aus ganz Israel und machte sie zu Häuptern über das Volk, zu Obern über tausend, über hundert, über fünfzig und über zehn,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'damit sie das Volk allezeit richteten; schwere Sachen sollten sie vor Mose bringen, die kleinen Sachen aber selber richten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Darauf ließ Mose seinen Schwiegervater ziehen, und er kehrte in sein Land zurück.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Im dritten Monat nach dem Auszug der Kinder Israel aus Ägypten kamen sie an demselben Tag in die Wüste Sinai.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Denn sie waren von Raphidim ausgezogen und in die Wüste Sinai gekommen und lagerten sich in der Wüste; Israel lagerte sich daselbst dem Berg gegenüber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Und Mose stieg hinauf zu Gott; denn der HERR rief ihm vom Berge und sprach: Also sollst du zum Hause Jakobs sagen und den Kindern Israel verkündigen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Ihr habt gesehen, was ich den Ägyptern getan, und wie ich euch auf Adlersflügeln getragen und euch zu mir gebracht habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Werdet ihr nun meiner Stimme Gehör schenken und gehorchen und meinen Bund bewahren, so sollt ihr vor allen Völkern mein besonderes Eigentum sein; denn die ganze Erde ist mein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'ihr aber sollt mir ein Königreich von Priestern und ein heiliges Volk sein! Das sind die Worte, die du den Kindern Israel sagen sollst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mose kam und berief die Ältesten des Volkes und legte ihnen alle diese Worte vor, die der HERR geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Da antwortete das ganze Volk miteinander und sprach: Alles, was der HERR gesagt hat, das wollen wir tun! Und Mose überbrachte dem HERRN die Antwort des Volkes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Da sprach der HERR zu Mose: Siehe, ich will in einer dicken Wolke zu dir kommen, daß das Volk meine Worte höre, die ich mit dir rede, und auch dir ewiglich glaube. Und Mose verkündigte dem HERRN die Rede des Volkes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Da sprach der HERR zu Mose: Geh zum Volk und heilige sie heute und morgen; und sie sollen ihre Kleider waschen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'und bereit sein auf den dritten Tag; denn am dritten Tage wird der HERR vor dem ganzen Volk auf den Berg Sinai herabsteigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Und mache dem Volke ein Gehege ringsum und sprich zu ihnen: Hütet euch davor, auf den Berg zu steigen und seinen Fuß anzurühren! Denn wer den Berg anrührt, der soll des Todes sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Niemandes Hand soll ihn anrühren, sonst soll er gesteinigt oder mit einem Geschoß erschossen werden; es sei ein Tier oder ein Mensch, so soll er nicht leben. Wenn aber das Horn ertönt, so sollen sie zum Berge kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mose stieg vom Berg herab zum Volk und heiligte sie. Und sie wuschen ihre Kleider.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Und er sprach zum Volk: Seid bereit auf den dritten Tag, keiner nahe sich zum Weibe!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Als nun der dritte Tag kam und es noch frühe war, erhob sich ein Donnern und Blitzen und eine dicke Wolke auf dem Berg und der Ton einer sehr starken Posaune. Da erschrak das ganze Volk, das im Lager war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Und Mose führte das Volk aus dem Lager, Gott entgegen, und sie stellten sich unten am Berge auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Aber der ganze Berg Sinai rauchte davon, daß der HERR im Feuer auf ihn herabstieg. Und sein Rauch ging auf, wie der Rauch eines Schmelzofens, und der ganze Berg erbebte sehr.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und der Ton der Posaune ward je länger je stärker. Mose redete, und Gott antwortete ihm mit lauter Stimme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Als nun der HERR auf den Berg Sinai, oben auf die Spitze des Berges herabgekommen war, rief er Mose hinauf auf die Spitze des Berges. Und Mose stieg hinauf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Da sprach der HERR zu Mose: Steig hinab und bezeuge dem Volk, daß sie nicht zum HERRN durchbrechen, um zu sehen, und viele von ihnen fallen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Auch die Priester, die dem HERRN nahen, sollen sich heiligen, daß der HERR nicht einen Riß unter ihnen mache.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mose aber sprach zum HERRN: Das Volk kann nicht auf den Berg Sinai steigen, denn du hast uns bezeugt und gesagt: Mache ein Gehege um den Berg und heilige ihn!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Der HERR sprach zu ihm: Gehe hin, steige hinab! Darnach sollst du und Aaron mit dir hinaufsteigen; aber die Priester und das Volk sollen nicht durchbrechen, um zum Herrn heraufzusteigen, damit er nicht einen Riß unter ihnen mache!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Und Mose stieg zum Volke hinunter und sagte es ihnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Da redete Gott alle diese Worte und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ich bin der HERR, dein Gott, der ich dich aus Ägyptenland, aus dem Diensthause, geführt habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keine andern Götter neben mir haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir kein Bildnis noch irgend ein Gleichnis machen, weder dessen, das oben im Himmel, noch dessen, das unten auf Erden, noch dessen, das in den Wassern, unterhalb der Erde ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Bete sie nicht an und diene ihnen nicht; denn ich, der HERR, dein Gott, bin ein eifriger Gott, der da heimsucht der Väter Missetat an den Kindern bis in das dritte und vierte Glied derer, die mich hassen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'und tue Barmherzigkeit an vielen Tausenden, die mich lieben und meine Gebote halten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen des HERRN, deines Gottes, nicht mißbrauchen; denn der HERR wird den nicht ungestraft lassen, der seinen Namen mißbraucht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke des Sabbattages, daß du ihn heiligest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und alle deine Werke verrichten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'aber am siebenten Tag ist der Sabbat des HERRN, deines Gottes; da sollst du kein Werk tun; weder du, noch dein Sohn, noch deine Tochter, noch dein Knecht, noch deine Magd, noch dein Vieh, noch dein Fremdling, der in deinen Toren ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat der HERR Himmel und Erde gemacht, und das Meer und alles, was darinnen ist, und ruhte am siebenten Tag; darum segnete der HERR den Sabbattag und heiligte ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Du sollst deinen Vater und deine Mutter ehren, auf daß du lange lebest im Lande, das dir der HERR, dein Gott, geben wird!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht töten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst kein falsches Zeugnis reden wider deinen Nächsten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Laß dich nicht gelüsten deines Nächsten Hauses! Laß dich nicht gelüsten deines Nächsten Weibes, noch seines Knechtes, noch seiner Magd, noch seines Ochsen, noch seines Esels, noch alles dessen, was dein Nächster hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Und alles Volk sah den Donner und Blitz und den Ton der Posaunen und den rauchenden Berg. Als nun das Volk solches sah, zitterte es und stand von ferne');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'und sprach zu Mose: Rede du mit uns, wir wollen zuhören; aber Gott soll nicht mit uns reden, wir müssen sonst sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mose aber sprach zum Volk: Fürchtet euch nicht, denn Gott ist gekommen, euch zu prüfen, und damit seine Furcht euch vor Augen sei, damit ihr nicht sündiget!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Und das Volk stand von ferne; Mose aber machte sich hinzu in das Dunkel, darinnen Gott war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Und der HERR sprach zu Mose: Also sollst du den Kindern Israel sagen: Ihr habt gesehen, daß ich mit euch vom Himmel her geredet habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Darum sollt ihr keine andern Götter neben mir machen; silberne oder goldene Götter sollt ihr euch nicht machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Altar von Erde sollst du mir machen, darauf du deine Brandopfer und deine Dankopfer, deine Schafe und deine Rinder opferst; an jedem Ort, wo ich meines Namens Gedächtnis stifte, daselbst will ich zu dir kommen und dich segnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Und so du mir einen steinernen Altar machen willst, sollst du ihn nicht von gehauenen Steinen bauen; denn wenn du mit deinem Eisen darüber führest, so würdest du ihn entweihen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Du sollst auch nicht auf Stufen zu meinem Altar steigen, damit deine Blöße vor ihm nicht aufgedeckt werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Das sind die Rechte, die du ihnen vorlegen sollst:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'So du einen hebräischen Knecht kaufst, soll er sechs Jahre lang dienen, und im siebenten soll er unentgeltlich freigelassen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ist er allein gekommen, so soll er auch allein entlassen werden; ist er aber verehelicht gekommen, so soll sein Weib mit ihm ausgehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hat ihm aber sein Herr ein Weib gegeben, und diese hat ihm Söhne oder Töchter geboren, so soll das Weib samt ihren Kindern seinem Herrn gehören; er aber soll allein entlassen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Spricht aber der Knecht: Ich habe meinen Herrn, mein Weib und meine Kinder lieb,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'ich will nicht freigelassen werden, so bringe ihn sein Herr vor Gott und stelle ihn an die Tür oder den Pfosten und durchbohre ihm seine Ohren mit einem Pfriem, daß er ihm diene ewiglich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Verkauft jemand seine Tochter als Magd, so soll sie nicht wie die Knechte freigelassen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Mißfällt sie ihrem Herrn, also daß er sie nicht heiratet, so lasse er sie loskaufen; aber unter ein fremdes Volk sie zu verkaufen hat er keine Macht, wenn er ihr untreu wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Vermählt er sie aber seinem Sohne, so soll er nach der Töchter Recht mit ihr handeln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Nimmt er sich aber eine andere, so soll er jener an Nahrung, Kleidung und der ehelichen Pflicht nichts abbrechen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Tut er diese drei Stücke nicht an ihr, so soll sie umsonst, unentgeltlich frei werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen Menschen schlägt, daß er stirbt, der soll des Todes sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hat er ihm aber nicht nachgestellt, sondern hat Gott es seiner Hand widerfahren lassen, so will ich dir einen Ort bestimmen, dahin er fliehen mag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Wenn aber jemand gegen seinen Nächsten so aufgebracht war, daß er ihn vorsätzlich umgebracht hat, so sollst du ihn von meinem Altar wegnehmen, damit er sterbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Wer seinen Vater oder seine Mutter schlägt, der soll des Todes sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Wer einen Menschen stiehlt und ihn verkauft, oder so, daß man ihn noch in seiner Hand findet, der soll des Todes sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Auch wer seinem Vater oder seiner Mutter flucht, soll des Todes sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Wenn Männer miteinander hadern, und einer schlägt den andern mit einem Stein oder mit der Faust, daß er nicht stirbt, aber zu Bette liegen muß;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'und wenn er soweit wieder hergestellt wird, daß er auf einen Stock gestützt ausgehen kann, so soll der, welcher ihn geschlagen hat, unschuldig sein; nur soll er ihn für die Versäumnis entschädigen und ihn vollständig heilen lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Und wer seinen Knecht oder seine Magd mit einem Stocke schlägt, so daß sie ihm unter der Hand sterben, der soll bestraft werden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'stehen sie aber nach einem oder zwei Tagen wieder auf, so soll er nicht bestraft werden, weil es sein eigener Schade ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Wenn Männer sich zanken und stoßen ein schwangeres Weib, daß eine Fehlgeburt entsteht, aber sonst kein Schade, so muß eine Geldstrafe erlegt werden, wie sie der Ehemann des Weibes festsetzt; und man soll sie auf richterliche Entscheidung hin geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Wenn aber ein Schaden entsteht, so sollst du ihn ersetzen; Seele um Seele,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandmal um Brandmal, Wunde um Wunde, Beule um Beule.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Wenn jemand seinem Knecht oder seiner Magd ein Auge ausschlägt, so soll er sie freilassen zur Entschädigung für das Auge.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Desgleichen, wenn er dem Knecht oder der Magd einen Zahn ausschlägt, soll er sie auch freilassen für den Zahn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Wenn ein Ochs einen Mann oder eine Frau zu Tode stößt, so soll man ihn steinigen und sein Fleisch nicht essen; der Eigentümer des Ochsen aber bleibe unbestraft.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Ist aber der Ochs seit mehreren Tagen stößig gewesen und wurde sein Herr deshalb verwarnt, hat ihn aber doch nicht in Verwahrung getan, so soll der Ochs, der einen Mann oder eine Frau getötet hat, gesteinigt werden, und auch sein Herr soll sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wird ihm aber ein Lösegeld auferlegt, so soll er zur Erlösung seiner Seele soviel geben, als man ihm auferlegt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Stößt er einen Sohn oder eine Tochter, so soll man ihn auch nach diesem Rechte behandeln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Wenn aber der Ochs einen Knecht stößt oder eine Magd, so soll man ihrem Herrn dreißig silberne Schekel bezahlen; der Ochs aber muß gesteinigt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Wenn jemand eine Zisterne abdeckt oder eine solche gräbt und deckt sie nicht zu, und es fällt ein Ochs oder Esel hinein,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'so hat der Zisternenbesitzer den Eigentümer des Viehes mit Geld zu entschädigen, das Aas aber mag er behalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Wenn jemandes Ochs den Ochsen eines anderen zu Tode stößt, so sollen sie den lebendigen Ochsen verkaufen und das Geld teilen und das Aas auch teilen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Wußte man aber, daß der Ochs schon seit etlichen Tagen stößig war und hat sein Herr ihn doch nicht in Verwahrung getan, so soll er den Ochsen ersetzen und das Aas behalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, 'Wenn jemand einen Ochsen stiehlt oder ein Schaf und schlachtet oder verkauft das Tier, so soll er fünf Ochsen für einen erstatten und vier Schafe für eins.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wird ein Dieb beim Einbruch ertappt und geschlagen, daß er stirbt, so ist man des Blutes nicht schuldig;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'wäre aber die Sonne über ihm aufgegangen, so würde man des Blutes schuldig sein. Der Dieb soll Ersatz leisten; hat er aber nichts, so verkaufe man ihn um den Wert des Gestohlenen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Wird das Gestohlene noch lebend bei ihm vorgefunden, es sei ein Ochs, ein Esel oder ein Schaf, so soll er es doppelt wiedererstatten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Wenn jemand das Feld oder den Weinberg abweiden läßt, und er läßt dem Vieh freien Lauf, daß es auch das Feld eines andern abweidet, so soll er das Beste seines eigenen Feldes und das Beste seines Weinbergs dafür geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Bricht Feuer aus und ergreift eine Dornhecke und frißt einen Garbenhaufen oder das stehende Gewächs oder das ganze Feld, so soll der, welcher den Brand verursacht hat, den Schaden vergüten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Gibt einer seinem Nächsten Geld oder Hausrat zu verwahren, und es wird aus dem Hause des Betreffenden gestohlen, so soll der Dieb, wenn er erwischt wird, es doppelt ersetzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Ist aber der Dieb nicht zu finden, so soll man den Hausherrn vor Gott bringen und ihn darüber verhören, ob er sich nicht vergriffen habe an seines Nächsten Gut.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Wird irgend etwas gestohlen, sei es ein Ochs, ein Esel, ein Schaf, ein Kleid, oder was sonst abhanden gekommen sein mag, wovon einer behauptet: Der hat\'s! So soll beider Aussage vor Gott gelangen; wen Gott schuldig spricht, der soll es seinem Nächsten doppelt ersetzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn jemand seinem Nächsten einen Esel oder einen Ochsen oder ein Schaf oder irgend ein Vieh zu hüten gibt, und es kommt um oder nimmt Schaden oder wird geraubt, ohne daß es jemand sieht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'so soll ein Eid bei dem HERRN zwischen beiden entscheiden, daß jener sich nicht vergriffen habe an seines Nächsten Gut; und der Eigentümer soll ihn annehmen und keine Entschädigung erhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Ist es ihm aber gestohlen worden, so soll er es dem Eigentümer ersetzen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'wenn es aber von einem wilden Tier zerrissen worden ist, so soll er das Zerrissene zum Beweis beibringen; bezahlen muß er es nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Entlehnt jemand etwas von seinem Nächsten, und es wird beschädigt oder kommt um, ohne daß der Eigentümer dabei ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'so muß er es ersetzen; ist der Eigentümer dabei, so braucht jener es nicht zu ersetzen; ist er ein Tagelöhner, so ist es inbegriffen in seinem Lohn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Wenn ein Mann eine Jungfrau überredet, die noch unverlobt ist, und bei ihr liegt, so soll er sie sich durch Bezahlung des Kaufpreises zum Eheweib nehmen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Will aber ihr Vater sie ihm durchaus nicht geben, so soll er ihm soviel bezahlen, als der Kaufpreis für eine Jungfrau beträgt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Eine Zauberin sollst du nicht leben lassen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Wer bei einem Vieh liegt, soll des Todes sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Wer den Göttern opfert und nicht dem Herrn allein, der soll in den Bann getan werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Den Fremdling sollst du nicht bedrängen noch bedrücken; denn ihr seid auch Fremdlinge gewesen in Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Ihr sollt keine Witwen noch Waisen bedrücken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Wirst du sie dennoch bedrücken und sie schreien zu mir, so werde ich ihr Schreien gewiß erhören,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'und es wird alsdann mein Zorn ergrimmen, daß ich euch mit dem Schwert umbringe, damit eure Weiber zu Witwen und eure Kinder zu Waisen werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Wenn du meinem Volk Geld leihst, einem Armen, der bei dir wohnt, so sollst du ihn nicht wie ein Wucherer behandeln, du sollst ihm keinen Zins auferlegen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du von deinem Nächsten das Kleid als Pfand nimmst, so sollst du es ihm bis zum Sonnenuntergang wiedergeben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'denn es ist seine einzige Decke, das Kleid, das er auf der bloßen Haut trägt! Worin soll er schlafen? Schreit er aber zu mir, so erhöre ich ihn; denn ich bin gnädig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Gott sollst du nicht lästern, und dem Obersten deines Volkes sollst du nicht fluchen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Deinen Überfluß und dein Bestes sollst du nicht zurückbehalten; deinen erstgeborenen Sohn sollst du mir geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Desgleichen sollst du tun mit deinem Ochsen und deinem Schaf; sieben Tage mag es bei seiner Mutter bleiben, am achten Tag sollst du es mir geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Und ihr sollt mir heilige Leute sein; darum sollt ihr kein Fleisch essen, das auf dem Feld von wilden Tieren zerrissen worden ist, sondern sollt es den Hunden vorwerfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du sollst kein falsches Gerücht verbreiten! Leihe keinem Gottlosen deine Hand, daß du durch dein Zeugnis einen Frevel unterstützest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst nicht der Mehrheit folgen zum Bösen und sollst vor Gericht deine Aussagen nicht nach der Mehrheit richten, um zu verdrehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Du sollst den Armen nicht beschönigen in seinem Prozeß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Wenn du den Ochsen oder Esel deines Feindes antriffst, der sich verlaufen hat, so sollst du ihm denselben wiederbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Siehst du den Esel deines Feindes unter seiner Last erliegen, könntest du es unterlassen, ihm zu helfen? Du sollst ihm samt jenem aufhelfen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst das Recht deines Armen nicht beugen in seinem Prozeß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Von falscher Anklage halte dich fern und bringe keinen Unschuldigen und Gerechten um; denn ich spreche keinen Gottlosen gerecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Und nimm kein Geschenk! Denn das Geschenk macht die Sehenden blind und verkehrt die Sache der Gerechten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Und bedrücke den Fremdling nicht; denn ihr wißt, wie es den Fremdlingen zumute ist; denn ihr seid Fremdlinge gewesen in Ägyptenland.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sechs Jahre sollst du dein Land besäen und seinen Ertrag einsammeln;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'aber im siebenten sollst du es brach liegen und sich ausruhen lassen, daß sich die Armen deines Volkes davon nähren, und was sie übriglassen, mögen die Tiere des Feldes fressen; desgleichen sollst du mit deinem Weinberg und Olivengarten tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage sollst du deine Werke verrichten, aber am siebenten Tag sollst du feiern, damit dein Ochs und dein Esel ausruhen und deiner Magd Sohn und der Fremdling sich erholen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Befolget alles, was ich euch befohlen habe, und erwähnet die Namen der fremden Götter nicht; die sollen gar nicht über eure Lippen kommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal im Jahr sollst du mir ein Fest feiern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest der ungesäuerten Brote sollst du halten: sieben Tage sollst du ungesäuertes Brot essen zur bestimmten Zeit im Monat Abib, wie ich dir befohlen habe; denn in demselben bist du aus Ägypten ausgezogen. Man erscheine aber nicht leer vor mir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Und das Erntefest, da du deine ersten Erzeugnisse darbringst von dem, was du auf dem Felde gesät hast; und das Fest der Einsammlung am Ausgang des Jahres, wenn du deine Erzeugnisse vom Felde eingesammelt hast.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahr soll alle deine Mannschaft vor dem Herrscher, dem HERRN, erscheinen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst das Blut meiner Opfer nicht zusammen mit Sauerteig darbringen, und das Fett meiner Festopfer soll nicht bleiben bis zum andern Morgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Die frühesten Erstlinge deines Ackers sollst du in das Haus des HERRN, deines Gottes, bringen. Du sollst das Böcklein nicht in der Milch seiner Mutter kochen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Siehe, ich sende einen Engel vor dir her, dich zu behüten auf dem Weg und dich an den Ort zu bringen, den ich bereitet habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Hüte dich vor ihm und gehorche seiner Stimme und sei nicht widerspenstig gegen ihn; denn er wird eure Übertretungen nicht ertragen; denn mein Name ist in ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Wirst du aber seiner Stimme gehorchen und alles tun, was ich sage, so will ich deine Feinde befehden und deinen Widersachern widerwärtig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Wenn nun mein Engel vor dir hergeht und dich zu den Amoritern, Hetitern, Pheresitern, Kanaanitern, Hevitern und Jebusitern bringt und ich sie vertilge,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'so sollst du ihre Götter nicht anbeten, noch ihnen dienen, und sollst es nicht machen wie sie; sondern du sollst ihre Säulen niederreißen und sie gänzlich zerstören.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Und ihr sollt dem HERRN, eurem Gott, dienen, so wird er dein Brot und dein Wasser segnen; und ich will die Krankheit aus deiner Mitte tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Es soll keine Kinderlose und keine Unfruchtbare in deinem Lande sein; ich will die Zahl deiner Tage voll machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Ich will meinen Schrecken vor dir hersenden und will alle Völker in Verwirrung bringen, zu welchen du kommst, und will machen, daß alle deine Feinde dir den Rücken kehren sollen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Ich will Hornissen vor dir hersenden, damit sie die Heviter, die Kanaaniter und Hetiter vor dir her vertreiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Ich will sie aber nicht in einem Jahre vor dir her vertreiben, damit das Land nicht zur Wüste werde und die wilden Tiere sich nicht zu deinem Schaden vermehren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Nach und nach will ich sie vor dir vertreiben, in dem Maß, wie du zunimmst und das Land ererben kannst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und ich setze deine Grenze vom Schilfmeer bis zum Philistermeer und von der Wüste bis zum Strom Euphrat; denn ich will die Bewohner des Landes in eure Hand geben, daß du sie vor dir her vertreibest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du sollst mit ihnen und mit ihren Göttern keinen Bund schließen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'sie sollen nicht in deinem Lande wohnen, damit sie dich nicht zur Sünde gegen mich verleiten; denn du würdest ihren Göttern dienen, und sie würden dir zum Fallstrick werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Er hatte aber zu Mose gesagt: Steige herauf zum HERRN, du und Aaron, Nadab und Abihu und siebzig von den Ältesten Israels, und betet an von ferne!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Aber Mose allein nahe sich zum HERRN; jene sollen sich nicht nahen, und das Volk soll nicht mit ihnen heraufkommen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mose kam und erzählte dem Volk alle Worte des HERRN und alle die Verordnungen. Da antwortete das Volk einstimmig und sprach: Alles, was der HERR gesagt hat, wollen wir tun!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Da schrieb Mose alle Worte des HERRN nieder und stand des Morgens frühe auf und baute einen Altar unten am Berg und zwölf Malsteine nach den zwölf Stämmen Israels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Und Mose sandte israelitische Jünglinge, daß sie Brandopfer darbrächten und Farren opferten zum Dankopfer dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Und Mose nahm die Hälfte des Blutes und tat es in Becken; aber die andere Hälfte des Blutes sprengte er auf den Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Darauf nahm er das Buch des Bundes und las es vor den Ohren des Volkes. Und sie sprachen: Alles, was der HERR gesagt hat, das wollen wir tun und befolgen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Da nahm Mose das Blut und sprengte es auf das Volk und sprach: Sehet, das ist das Blut des Bundes, den der HERR mit euch gemacht hat über allen diesen Worten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Da stiegen Mose und Aaron, Nadab und Abihu und siebzig von den Ältesten Israels hinauf;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'und sie sahen den Gott Israels; und unter seinen Füßen war ein Boden wie von Saphirsteinen und so klar wie der Himmel selbst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Und er legte seine Hand nicht an die Auserwählten der Kinder Israel. Und als sie Gott gesehen hatten, aßen und tranken sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Und der HERR sprach zu Mose: Steige zu mir herauf auf den Berg und bleibe daselbst, so will ich dir die steinernen Tafeln geben und das Gesetz und das Gebot, das ich geschrieben habe, um sie zu unterweisen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Da machte sich Mose auf samt seinem Diener Josua und stieg auf den Berg hinauf zu Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Zu den Ältesten aber hatte er gesagt: Erwartet uns hier, bis wir wieder zu euch kommen; sehet, Aaron und Hur sind bei euch; wer eine Angelegenheit hat, der wende sich an sie!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Als nun Mose auf den Berg stieg, bedeckte eine Wolke den Berg.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und die Herrlichkeit des HERRN wohnte auf dem Berg Sinai, und die Wolke bedeckte ihn sechs Tage lang; am siebenten Tage aber rief er Mose von der Wolke aus zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Und die Herrlichkeit des HERRN erschien den Kindern Israel wie ein verzehrendes Feuer oben auf dem Gipfel des Berges.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Mose aber ging mitten in die Wolke hinein, da er den Berg bestieg; und Mose blieb vierzig Tage und vierzig Nächte auf dem Berge.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Sage den Kindern Israel, daß sie mir freiwillige Gaben bringen, und nehmet dieselben von jedermann, den sein Herz dazu treibt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Das sind aber die Gaben, die ihr von ihnen nehmen sollt:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Gold, Silber, Erz, Stoffe von blauem und rotem Purpur und Karmesinfarbe, von feiner weißer Baumwolle und Ziegenhaaren,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'rötliche Widderfelle, Seehundsfelle und Akazienholz,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Öl zum Leuchter, Spezerei zum Salböl und zu gutem Räucherwerk,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Schohamsteine und eingefaßte Steine zum Brustkleid und zum Brustschildlein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Und sie sollen mir ein Heiligtum machen, daß ich mitten unter ihnen wohne!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Durchaus, wie ich dir ein Vorbild der Wohnung und aller ihrer Geräte zeigen werde, also sollt ihr es machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Macht eine Lade von Akazienholz, dreieinhalb Ellen soll ihre Länge sein, anderthalb Ellen ihre Breite und anderthalb Ellen ihre Höhe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Die sollst du mit reinem Gold überziehen, inwendig und auswendig; und mache ringsum einen goldenen Kranz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Du sollst auch vier goldene Ringe dazu gießen und sie an ihre vier Ecken setzen; also, daß zwei Ringe auf einer Seite und zwei Ringe auf der andern Seite seien;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'und mache Stangen von Akazienholz und überziehe sie mit Gold');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'und stecke sie in die Ringe an der Seite der Lade, daß man sie damit trage.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Aber die Stangen sollen in den Ringen der Lade bleiben und nicht daraus entfernt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Und du sollst das Zeugnis, das ich dir geben werde, in die Lade legen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Du sollst auch einen Sühndeckel machen von reinem Gold; dreieinhalb Ellen soll seine Länge und anderthalb Ellen seine Breite sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Und du sollst zwei Cherubim machen von Gold; von getriebener Arbeit sollst du sie machen, an beiden Enden des Sühndeckels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Also, daß du den einen Cherub an dem einen Ende machest und den andern Cherub an dem andern Ende; die Cherubim sollt ihr machen an den beiden Enden des Sühndeckels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Und die Cherubim sollen ihre Flügel darüber ausbreiten, daß sie mit ihren Flügeln den Sühndeckel schirmen und des einen Angesicht gegen das des andern gerichtet sei, und ihre Angesichter sollen auf den Sühndeckel sehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Und du sollst den Sühndeckel oben über die Lade legen und das Zeugnis, das ich dir geben werde, in die Lade tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Daselbst will ich mit dir zusammenkommen und mit dir reden von dem Sühndeckel herab, zwischen den beiden Cherubim auf der Lade des Zeugnisses, über alles, was ich dir für die Kinder Israel befehlen will.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Du sollst auch einen Tisch machen von Akazienholz; zwei Ellen soll seine Länge und eine Elle seine Breite und anderthalb Ellen seine Höhe sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Und sollst ihn überziehen mit reinem Gold und ihn ringsum mit einem goldenen Kranz versehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Auch eine Leiste sollst du machen um ihn her und sie an den vier Ecken seiner Füße anbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Und sollst vier goldene Ringe daran machen, welche du an den vier Ecken seiner vier Füße anbringen sollst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Dicht unter der Leiste sollen die Ringe sein, daß man die Stangen darein tue und den Tisch trage.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Du sollst aber die Stangen von Akazienholz machen und sie mit Gold überziehen, daß der Tisch damit getragen werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Du sollst auch seine Schüsseln machen, seine Schalen, seine Kannen und seine Becher, daß man mit ihnen die Trankopfer ausgieße; aus reinem Golde sollst du sie machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Und du sollst allezeit Schaubrote auf den Tisch legen vor mein Angesicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Du sollst auch einen Leuchter von reinem Golde machen; in getriebener Arbeit soll dieser Leuchter gemacht werden; sein Fuß, sein Schaft, seine Kelche, Knoten und Blumen sollen aus einem Stück mit ihm sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sechs Arme sollen aus den Seiten des Leuchters herauskommen, drei Arme aus einer Seite des Leuchters und drei Arme aus der andern Seite des Leuchters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Ein jeder Arm soll drei Kelche wie Mandelblüten, Knoten und Blumen haben. Auf diese Weise sollen die sechs Arme aus dem Leuchter gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Aber der Leuchter soll vier Kelche wie Mandelblüten, dazu seine Knoten und Blumen haben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'nämlich einen Knoten unter zwei Armen, und wieder einen Knoten unter zwei Armen; so bei den sechs Armen, die aus dem Leuchter gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Denn ihre Knoten und Arme sollen aus ihm herauskommen, und von getriebener Arbeit und aus reinem Gold sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Und du sollst ihm sieben Lampen machen, und man zünde die Lampen an, daß sie Licht geben nach vorn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Und ihre Lichtscheren und Löschnäpflein sollen aus reinem Golde sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Aus einem Zentner reinen Goldes soll man ihn machen mit allen diesen Geräten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Und siehe zu, daß du es machest nach dem Vorbilde, das dir auf dem Berge gezeigt worden ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Die Wohnung sollst du machen von zehn Teppichen, von gezwirnter weißer Baumwolle, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe. Cherubim sollst du künstlich darein wirken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Die Länge eines Teppichs soll achtundzwanzig Ellen sein und die Breite desselben vier Ellen; diese Teppiche alle sollen einerlei Maß haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Fünf Teppiche sollen zusammengefügt sein, einer an den andern, und wieder fünf Teppiche.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Und du sollst Schleifen machen von blauem Purpur an den Enden eines jeden Teppichs, da sie sollen zusammengefügt sein, daß je zwei und zwei an ihren Enden zusammengeheftet werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Du sollst fünfzig Schleifen an dem Ende des einen Teppichs machen und fünfzig Schleifen an dem äußersten Ende des andern Teppichs, wo sie zusammengefügt werden; von diesen Schleifen soll je eine der andern gegenüberstehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Und sollst fünfzig goldene Haften machen und damit die Teppiche zusammenheften einen an den andern, daß die Wohnung ein Ganzes werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Du sollst auch Teppiche machen aus Ziegenhaaren zum Zelte über die Wohnung; elf solche Teppiche sollst du machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Die Länge eines Teppichs soll dreißig Ellen sein, die Breite aber vier Ellen. Und alle elf sollen gleich sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fünf solcher Teppiche sollst du aneinander fügen und sechs auch aneinander, und sollst den sechsten Teppich zweifältig legen, vorne an der Hütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Und sollst fünfzig Schleifen machen am Ende des ersten Teppichs und fünfzig Schleifen am Ende des andern Teppichs, wo sie zusammengefügt sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Und sollst fünfzig eherne Haften machen und die Haften in die Schleifen tun, und die Hütte zusammenfügen, also daß sie ein Ganzes werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Aber von dem Überschuß der Teppiche der Hütte sollst du die Hälfte überhängen lassen hinten an der Wohnung,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'eine Elle auf dieser und eine Elle auf der anderen Seite von dem Überschuß an der Länge der Teppiche der Hütte; es soll etwas vorschießen auf beiden Seiten der Wohnung, um dieselbe auf beiden Seiten zu bedecken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Über diese Decke sollst du für die Hütte eine Decke von rötlichen Widderfellen machen. Dazu eine Decke von Seehundsfellen oben darüber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Und du sollst die Bretter der Wohnung von Akazienholz machen, aufrechtstehend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Zehn Ellen soll die Länge eines jeden Brettes sein und anderthalb Ellen eines jeden Breite.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Zwei Zapfen soll ein Brett haben, einer dem andern gegenüberstehend. Also sollst du alle Bretter zur Wohnung machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Und du sollst für die Wohnung zwanzig Bretter machen auf der Seite gegen Mittag, südwärts.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Und du sollst unter die zwanzig Bretter vierzig silberne Füße machen, je zwei Füße unter ein Brett für seine beiden Zapfen; und wieder zwei Füße unter ein Brett für seine zwei Zapfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Ebenso auf der andern Seite der Wohnung gegen Mitternacht sollen auch zwanzig Bretter stehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Und ihre vierzig silbernen Füße, je zwei Füße unter ein Brett.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Aber du sollst sechs Bretter machen an der Seite der Wohnung gegen Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Dazu sollst du zwei Bretter machen hinten an die beiden Ecken der Wohnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Die sollen doppelt sein von unten auf und sich oben zusammenfügen mit einem Ring; also sollen beide sein; an beiden Ecken sollen sie stehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Daß da im ganzen acht Bretter seien mit ihren silbernen Füßen, sechzehn Füße, je zwei unter einem Brett.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Und du sollst Riegel machen von Akazienholz, fünf zu den Brettern auf einer Seite der Wohnung,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'und fünf zu den Brettern auf der andern Seite der Wohnung, und fünf zu den Brettern auf der hintern Seite der Wohnung gegen Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Und der mittlere Riegel soll inwendig durch die Bretter hindurchgehen von einem Ende zum andern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Und sollst die Bretter mit Gold überziehen und ihre Ringe von Gold machen, daß man die Riegel darein stecke; du sollst auch die Riegel mit Gold überziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Also sollst du die Wohnung aufrichten nach der Weise, wie du auf dem Berge gesehen hast.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Du sollst auch einen Vorhang machen aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle, und sollst Cherubim künstlich darein wirken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Und sollst ihn hängen an vier Säulen von Akazienholz, die mit Gold überzogen sind und goldene Haken und vier silberne Füße haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Und sollst den Vorhang unter die Haften hängen und die Lade des Zeugnisses innerhalb des Vorhangs setzen, daß der Vorhang euch eine Scheidewand bilde zwischen dem Heiligen und dem Allerheiligsten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Und sollst den Sühndeckel auf die Lade des Zeugnisses in dem Allerheiligsten legen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Den Tisch aber stelle außerhalb des Vorhanges auf und den Leuchter dem Tisch gegenüber auf der Südseite der Wohnung, daß der Tisch gegen Mitternacht stehe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Und du sollst einen Vorhang machen in die Türe der Hütte aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle in Buntwirkerarbeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und sollst für den Vorhang fünf Säulen machen von Akazienholz, mit Gold überzogen, mit goldenen Haken. Und sollst ihnen fünf eherne Füße gießen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Und du sollst einen Altar machen von Akazienholz, fünf Ellen lang und fünf Ellen breit, daß er viereckig sei, und drei Ellen hoch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Du sollst Hörner an seine vier Ecken machen; seine Hörner sollen aus ihm hervorgehen, und du sollst ihn mit Erz überziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Mache Aschentöpfe, Schaufeln, Sprengbecken, Gabeln und Kohlenpfannen. Alle seine Geschirre sollst du von Erz machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Du sollst ihm auch ein ehernes Gitter machen wie ein Netz, und sollst an das Gitter vier eherne Ringe an seinen vier Ecken machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Und sollst dasselbe unter die Einfassung des Altars setzen, unterhalb. Und das Gitter soll reichen bis zur halben Höhe des Altars.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Und sollst Stangen machen für den Altar, von Akazienholz, mit Erz überzogen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Und sollst die Stangen in die Ringe stecken, daß die Stangen an beiden Seiten des Altars seien, damit man ihn tragen kann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Von Tafeln sollst du ihn machen, inwendig hohl; wie dir auf dem Berge gezeigt worden ist, so soll man ihn machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Du sollst der Wohnung auch einen Vorhof machen: Auf der rechten Seite gegen Mittag Vorhänge von gezwirnter weißer Baumwolle, hundert Ellen lang auf der einen Seite.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Und zwanzig Säulen auf zwanzig ehernen Füßen und ihre Haken mit ihren Querstangen von Silber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Also auch gegen Mitternacht sollen Vorhänge sein, hundert Ellen lang, und zwanzig Säulen auf zwanzig ehernen Füßen und ihre Haken mit ihren Querstangen von Silber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Aber gegen Abend soll die Breite der Vorhänge des Vorhofs fünfzig Ellen betragen; und es sollen zehn Säulen auf zehn Füßen sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Gegen Morgen aber, gegen Aufgang, soll die Breite des Vorhofs fünfzig Ellen betragen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'und zwar sollen fünfzehn Ellen Vorhänge auf die eine Seite kommen, dazu drei Säulen auf drei Füßen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'desgleichen fünfzehn Ellen auf die andere Seite, dazu drei Säulen auf drei Füßen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Aber in dem Tor des Vorhofs soll ein Vorhang sein, zwanzig Ellen breit, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und gezwirnter weißer Baumwolle in Buntwirkerarbeit, dazu vier Säulen auf ihren Füßen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Säulen um den Vorhof her sollen silberne Querstangen und silberne Haken und eherne Füße haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Und die Länge des Vorhofs soll hundert Ellen sein, die Breite fünfzig Ellen, die Höhe fünf Ellen; die Umhänge von gezwirnter weißer Baumwolle; und seine Füße sollen ehern sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Auch alle Geräte der Wohnung zu allerlei Dienst und alle ihre Nägel und alle Nägel des Vorhofs sollen ehern sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Gebiete auch den Kindern Israel, daß sie zu dir bringen lauteres, gestoßenes Olivenöl für den Leuchter, um beständig Licht zu unterhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'In der Stiftshütte außerhalb des Vorhangs, der vor dem Zeugnis hängt, sollen Aaron und seine Söhne es zurichten, vom Abend bis zum Morgen, vor dem HERRN. Das ist ein ewiger Gebrauch, der von den Kindern Israel jederzeit zu beobachten ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Und du sollst deinen Bruder Aaron und seine Söhne mit ihm zu dir nahen lassen aus den Kindern Israel, daß er mein Priester sei, nämlich Aaron und seine Söhne, Nadab, Abihu, Eleasar und Itamar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Und du sollst deinem Bruder Aaron heilige Kleider machen zur Ehre und zur Zierde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Und sollst reden mit allen, die eines weisen Herzens sind, die ich mit dem Geist der Weisheit erfüllt habe, daß sie dem Aaron Kleider machen, ihn zu heiligen und mir zum Priester zu weihen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Das sind aber die Kleider, welche sie machen sollen: Ein Brustschildlein, ein Ephod, einen Rock und einen Leibrock von gewürfeltem Stoff, Kopfbund und Gürtel. Also sollen sie deinem Bruder Aaron und seinen Söhnen heilige Kleider machen, daß er mein Priester sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Dazu sollen sie Gold nehmen und Stoffe von blauem und rotem Purpur und Karmesinfarbe und von weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Das Ephod sollen sie machen von Gold und aus Stoff von blauem und rotem Purpur und Karmesinfarbe und gezwirnter weißer Baumwolle, künstlich gezwirnt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Zwei verbundene Schulterstücke soll es haben, an seinen beiden Enden verbunden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Die künstliche Arbeit aber seines Gürtels, welcher darauf liegt, soll von der gleichen Arbeit sein, von Gold, aus Stoff von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Und du sollst zwei Schohamsteine nehmen und die Namen der Kinder Israel darauf graben,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sechs Namen derselben auf den einen Stein und die sechs übrigen Namen auf den andern Stein, nach ihren Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Steinschneiderarbeit soll es sein, von Siegelstechern; die Namen der Kinder Israel sollst du auf die beiden Steine stechen und sie mit Gold einfassen lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Und sollst sie auf die Schulterstücke des Ephod heften, daß sie Steine des Gedächtnisses seien für die Kinder Israel; daß Aaron ihre Namen auf seinen beiden Schultern trage vor dem HERRN, zum Gedächtnis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Und du sollst goldene Einfassungen machen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und zwei gewundene Ketten von reinem Gold, und sollst die zwei gewundenen Ketten an der Einfassung befestigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Das Brustschildlein für die Rechtspflege soll ein Kunstwerk sein wie das Ephod, von Gold, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und gezwirnter weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Viereckig soll es sein und zweifach, eine Spanne lang und eine Spanne breit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Und du sollst es mit vier Reihen von Steinen besetzen. Die erste Reihe sei ein Rubin, ein Topas und ein Smaragd;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'die zweite Reihe ein Granat, ein Saphir und ein Diamant;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'die dritte Reihe ein Opal, ein Achat, ein Amethyst;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'die vierte Reihe ein Chrysolith, ein Schoham und ein Jaspis. In Gold sollen sie gefaßt sein bei ihrer Einsetzung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Und diese Steine sollen nach den zwölf Namen der Kinder Israel lauten und von Steinschneidern gestochen sein, ein Stein für jeden Namen der zwölf Stämme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Und du sollst für das Brustschildlein gewundene Ketten machen von lauterem Golde,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'und zwei goldene Ringe, also daß du dieselben beiden Ringe an zwei Ecken des Brustschildes heftest');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'und die beiden goldenen, gewundenen Ketten in die zwei Ringe tuest, die an den beiden Enden des Brustschildleins sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Aber die beiden andern Enden der zwei gewundenen Ketten sollst du in die beiden Einfassungen tun und sie einander gegenüber auf die Schulterstücke des Ephod heften.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Und du sollst zwei andere goldene Ringe machen und sie an die andern beiden Ecken des Brustschildleins heften, nämlich an seinen Saum, welcher inwendig dem Ephod zugekehrt ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Und sollst noch zwei goldene Ringe machen und sie auf die beiden Schulterstücke des Ephod heften, unterhalb, einander gegenüber, dort wo das Ephod zusammengeht, oben an dem Gürtel des Ephod.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Und man soll das Brustschildlein mit seinen Ringen mit einer Schnur von blauem Purpur an die Ringe des Ephod knüpfen, daß es an dem Gürtel des Ephod hart anliege und das Brustschildlein sich nicht von dem Ephod losmache.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Also soll Aaron die Namen der Kinder Israel in dem Brustschildlein für die Rechtspflege auf seinem Herzen tragen, wenn er in das Heilige geht, zum Gedächtnis vor dem HERRN, allezeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Und du sollst in das Brustschildlein für die Rechtspflege das Licht und Recht legen, daß sie auf dem Herzen Aarons seien, wenn er hineingeht vor dem HERRN; und also soll Aaron die Rechtspflege der Kinder Israel allezeit auf seinem Herzen tragen vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Du sollst auch den Rock zum Ephod ganz von blauem Purpur machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Und oben in der Mitte soll eine Öffnung sein, und ein Saum um die Öffnung her gewoben, wie der Saum eines Panzers, damit er nicht zerreiße.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Und unten, an seinem Saum, sollst du Granatäpfel machen aus Stoffen von blauem und rotem Purpur und Karmesinfarbe, ringsum, und goldene Schellen zwischen dieselben, auch ringsum,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'daß eine goldene Schelle sei, darnach ein Granatapfel, und wieder eine goldene Schelle, darnach ein Granatapfel, ringsum an dem Saum des Rocks.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Und Aaron soll ihn tragen, wenn er dient, daß man seinen Klang höre, wenn er hineingeht in das Heiligtum vor dem HERRN und wenn er hinausgeht, auf daß er nicht sterbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Du sollst auch ein Stirnblatt von reinem Golde machen und darein graben in Siegelschrift: Heilig dem HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'und sollst dasselbe anheften mit einer Schnur von blauem Purpur, daß es an dem Kopfbunde sei; vorn am Kopfbund soll es sein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'und es soll auf Aarons Stirne sein, damit Aaron die Verschuldung trage in betreff der heiligen Gaben, welche die Kinder Israel weihen, welcherlei heilige Opfergaben sie auch darbringen mögen. Und es soll allezeit auf seiner Stirne sein, um sie wohlgefällig zu machen vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Den Leibrock sollst du weben von weißer Baumwolle und einen gestickten Gürtel machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Gleicherweise sollst du den Söhnen Aarons Leibröcke, Gürtel und Kopfbünde machen zur Ehre und zur Zierde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Und sollst sie deinem Bruder Aaron samt seinen Söhnen anlegen, und sie salben und ihre Hände füllen und sie weihen, daß sie meine Priester seien.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Und sollst ihnen leinene Beinkleider machen, die Blöße zu bedecken, von den Lenden bis an die Hüften.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Und Aaron und seine Söhne sollen sie tragen, wenn sie in die Stiftshütte gehen oder zum Altare treten, zum Dienst am Heiligtum, damit sie keine Schuld auf sich laden und nicht sterben müssen. Das sei eine ewige Ordnung für ihn und seinen Samen nach ihm!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Das ist aber die Verordnung, welche du befolgen sollst, daß sie mir zu Priestern geweiht werden. Nimm einen jungen Farren und zwei fehllose Widder');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'und ungesäuertes Brot und ungesäuerte Kuchen, mit Öl gemengt, und ungesäuerte Fladen, mit Öl gesalbt; von Weizenmehl sollst du es alles machen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'und lege es in einen Korb und bringe es in dem Korbe herzu samt dem Farren und den beiden Widdern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Alsdann sollst du Aaron und seine Söhne vor die Türe der Stiftshütte führen und sie mit Wasser waschen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'und die Kleider nehmen und dem Aaron den Leibrock anziehen, und den Rock zu dem Ephod, auch das Ephod und das Brustschildlein; und du sollst ihn gürten mit dem Gürtel des Ephod;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'und den Kopfbund auf sein Haupt setzen, und das heilige Diadem an den Kopfbund heften.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Und du sollst das Salböl nehmen und auf sein Haupt gießen und ihn salben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Und seine Söhne sollst du auch herzubringen und ihnen die Leibröcke anlegen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Und beide, Aaron und seine Söhne, mit Gürteln gürten und ihnen die Kopfbünde aufbinden, daß ihnen das Priesteramt zur ewigen Ordnung werde. Auch sollst du Aaron und seinen Söhnen die Hände füllen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Darnach sollst du den Farren herzubringen vor die Stiftshütte. Und Aaron und seine Söhne sollen ihre Hände auf des Farren Kopf legen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Und du sollst den Farren schächten vor dem HERRN, vor der Tür der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Und du sollst von des Farren Blut nehmen und mit deinem Finger auf die Hörner des Altars tun, alles übrige Blut aber an den Fuß des Altars schütten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Und du sollst alles Fett nehmen, welches die Eingeweide bedeckt, und das Fett über der Leber und die beiden Nieren mit dem Fett, das daran ist, und sollst es auf dem Altar anzünden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Aber des Farren Fleisch, Haut und Mist sollst du draußen vor dem Lager mit Feuer verbrennen; denn es ist ein Sündopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Darnach sollst du den einen Widder nehmen und Aaron und seine Söhne sollen ihre Hände auf seinen Kopf legen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Und du sollst ihn schächten und von seinem Blut nehmen und auf den Altar sprengen ringsumher.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Aber den Widder sollst du in Stücke zerlegen und seine Eingeweide und seine Schenkel waschen und sollst sie zu den Stücken und zu seinem Kopf legen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'und auf dem Altar den ganzen Widder anzünden; denn es ist ein Brandopfer dem HERRN; eine süßer Geruch, ein Feueropfer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Desgleichen sollst du den andern Widder nehmen, und wenn Aaron und seine Söhne ihre Hände auf seinen Kopf gelegt haben,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'sollst du ihn schächten und von seinem Blute nehmen und davon dem Aaron und seinen Söhnen auf das rechte Ohrläpplein tun und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes; das Blut aber sollst du ringsumher auf den Altar sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Und sollst von dem Blut auf dem Altar und vom Salböl nehmen und den Aaron und seine Kleider, seine Söhne und ihre Kleider besprengen, so wird er und seine Kleider, seine Söhne und ihre Kleider dadurch geheiligt sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Darnach sollst du das Fett von dem Widder nehmen und den Fettschwanz und das Fett, das die Eingeweide bedeckt, das Fett über der Leber und die beiden Nieren mit dem Fett, das daran ist, und die rechte Schulter; denn es ist ein Widder der Einweihung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Und nimm einen Laib Brot und einen Ölkuchen und einen Fladen aus dem Korb mit dem ungesäuerten Brot, der vor dem HERRN steht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'und lege alles auf die Hände Aarons und auf die Hände seiner Söhne und webe es zum Webopfer vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Darnach nimm es von ihren Händen und zünde es an auf dem Altar zum Brandopfer, zum süßen Geruch vor dem HERRN; es ist ein Feueropfer des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Du sollst ferner die Brust nehmen vom Widder der Einweihung Aarons und sollst sie vor dem HERRN weben zum Webopfer; das soll dein Teil sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Und sollst also heiligen die Webebrust und die Hebeschulter, die von dem Widder der Einweihung Aarons und seiner Söhne gewebet und gehoben sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Und das soll Aarons und seiner Söhne ewige Gebühr sein von den Kindern Israel; denn es ist ein Hebopfer, und soll erhoben werden von den Kindern Israel, von ihren Dankopfern, als ihr Hebopfer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aber die heiligen Kleider Aarons sollen seine Söhne nach ihm bekommen, daß sie darin gesalbt und ihre Hände darin gefüllt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Welcher unter seinen Söhnen an seiner Statt Priester wird, daß er in die Stiftshütte gehe, zu dienen im Heiligtum, der soll sie sieben Tage lang tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Du sollst aber den Widder der Einweihung nehmen und sein Fleisch an einem heiligen Orte kochen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Und Aaron mit seinen Söhnen soll das Fleisch desselben Widders essen samt dem Brot im Korbe, vor der Tür der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Sie sollen das essen, womit die Sühne für sie bewirkt wurde, als man ihre Hände füllte, sie zu weihen. Kein Fremder soll es essen, denn es ist heilig!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Wenn aber etwas von dem Fleisch der Einweihung und von dem Brot bis zum Morgen übrigbleibt, sollst du das Übrige mit Feuer verbrennen und nicht essen lassen; denn es ist heilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Und sollst also mit Aaron und seinen Söhnen alles tun, was ich dir geboten habe. Sieben Tage sollst du ihre Hände füllen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'und sollst täglich einen Farren zum Sündopfer schlachten um der Sühnung willen; und sollst den Altar entsündigen, indem du ihn versühnst, und sollst ihn salben, daß er geweiht werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage sollst du den Altar versühnen und ihn weihen, so wird der Altar hochheilig sein. Was mit dem Altar in Berührung kommt, das wird heilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Das ist es aber, was du auf dem Altar herrichten sollst: Zwei einjährige Lämmer sollst du beständig, Tag für Tag, darauf opfern;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'ein Lamm am Morgen, das andere in den Abendstunden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'und zum ersten Lamm einen Zehntel Semmelmehl, gemengt mit einem Viertel Hin gestoßenen Öls und einem Viertel Hin Wein zum Trankopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Das andere Lamm sollst du in den Abendstunden zurichten; und mit dem Speis und Trankopfer sollst du es halten wie am Morgen; zum lieblichen Geruch, zum Feueropfer des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Das soll das beständige Brandopfer eurer Geschlechter sein vor dem HERRN, vor der Tür der Stiftshütte, wo ich mit euch zusammenkommen will, um mit dir zu reden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'ja, ich will mich daselbst bei den Kindern Israel einstellen, und sie soll geheiligt werden durch meine Herrlichkeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Und ich will die Stiftshütte heiligen samt dem Altar und mir Aaron samt seinen Söhnen heiligen zum Priesterdienst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Und ich will mitten unter den Kindern Israel wohnen und ihr Gott sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Und sie sollen erfahren, daß ich, der HERR, ihr Gott bin, der sie aus Ägypten geführt hat, damit ich unter ihnen wohne, ich, der HERR, ihr Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Du sollst auch einen Räucheraltar machen zum Räucherwerk; von Akazienholz sollst du ihn machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Eine Elle lang und eine Elle breit soll er sein, viereckig und zwei Ellen hoch, und seine Hörner sollen aus ihm heraus-gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Und du sollst ihn mit reinem Gold überziehen, seine Platte und seine Wände ringsum und seine Hörner, und sollst ringsum einen Kranz von reinem Gold machen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'und je zwei goldene Ringe unter dem Kranz; neben seinen beiden Ecken sollst du sie machen zu seinen beiden Seiten, daß man Stangen darein stecken und ihn damit tragen kann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Die Stangen sollst du auch von Akazienholz machen und sie mit Gold überziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Und du sollst ihn setzen vor den Vorhang, der vor der Lade des Zeugnisses hängt, und vor den Sühndeckel, der auf dem Zeugnis ist, da ich mit dir zusammenkommen will.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Und Aaron soll alle Morgen wohlriechendes Räucherwerk darauf anzünden; wenn er die Lampen zurichtet, soll er räuchern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Desgleichen, wenn er in den Abendstunden die Lampen anzündet, soll er auch solches Räucherwerk anzünden. Es soll ein beständiges Räucherwerk sein vor dem HERRN in euren künftigen Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ihr sollt kein fremdes Räucherwerk darbringen darauf und auch kein Brandopfer, kein Speisopfer und kein Trankopfer darauf opfern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Aber einmal im Jahr soll Aaron auf seinen Hörnern die Sühne vollziehen; mit dem Blut des Versöhnungsopfers soll er einmal jährlich darauf Sühne leisten für eure Geschlechter; er ist dem HERRN hochheilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Wenn du die Zahl der Kinder Israel ermittelst, so soll ein jeder dem HERRN ein Lösegeld für seine Seele geben, wenn man sie zählt; damit ihnen nicht eine Plage widerfahre, wenn sie gezählt werden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'und zwar soll jeder, der durch die Musterung geht, einen halben Schekel geben, nach dem Schekel des Heiligtums; ein Schekel gilt zwanzig Gera. Der halbe Schekel ist eine Abgabe an den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Wer durch die Musterung geht im Alter von zwanzig Jahren und darüber, der soll dem HERRN die Abgabe entrichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Der Reiche soll nicht mehr und der Arme nicht weniger als einen halben Schekel geben bei der Entrichtung der Abgabe an den HERRN zur Sühnung eurer Seelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Und du sollst das Sühnegeld von den Kindern Israel nehmen und es für den Dienst der Stiftshütte geben, daß es den Kindern Israel zum Gedächtnis diene vor dem HERRN, zur Sühnung für eure Seelen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Weiter redete der HERR mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Du sollst auch ein ehernes Becken machen mit einem ehernen Fuß, zum Waschen, und sollst es aufstellen zwischen der Stiftshütte und dem Altar, und Wasser darein tun,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'daß Aaron und seine Söhne ihre Hände und Füße waschen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Wenn sie in die Stiftshütte gehen wollen, so sollen sie sich mit Wasser waschen, damit sie nicht sterben; desgleichen wenn sie zum Altar nahen, um zu dienen und anzuzünden die Feueropfer des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Und zwar sollen sie ihre Hände und ihre Füße waschen, damit sie nicht sterben. Das soll ihnen eine ewig gültige Ordnung sein, ihm und seinem Samen, für ihr Geschlecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Der HERR redete weiter mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Nimm dir wohlriechende, auserlesene Spezereien: fünfhundert Schekel selbstausgeflossene Myrrhen und halb so viel Zimmet, also zweihundertundfünfzig, und wohlriechenden Kalmus, auch zweihundertundfünfzig,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'dazu fünfhundert Schekel Kassia, nach dem Schekel des Heiligtums, und ein Hin Olivenöl; daraus mache ein heiliges Salböl,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'nach der Kunst des Salbenbereiters gemengt; ein heiliges Salböl soll es sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Und du sollst damit die Stiftshütte und die Lade des Zeugnisses salben');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'und den Tisch mit allem seinem Gerät, den Leuchter mit seinem Gerät, den Räucheraltar,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'den Brandopferaltar mit allem seinem Gerät und das Becken mit seinem Fuß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Und sollst sie also weihen, daß sie hochheilig seien; alles, was damit in Berührung kommt, wird heilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Auch Aaron und seine Söhne sollst du salben und sie mir zu Priestern weihen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Und du sollst zu den Kindern Israel sagen: Das soll mir ein heiliges Salböl sein für alle Zeiten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf Menschenleiber soll es nicht gegossen werden; du sollst auch in der gleichen Zusammensetzung keines für euch machen; denn es ist heilig, darum soll es euch heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wer es nachmacht oder einem Fremden davon gibt, der soll von seinem Volk ausgerottet werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Und der HERR sprach zu Mose: Nimm dir Spezereien: wohlriechendes Harz, Räucherklaue, Galbanum und reinen Weihrauch, zu gleichen Teilen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'und mache Räucherwerk daraus, nach der Kunst des Salbenbereiters gemengt, gesalzen, rein und heilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Und zerreibe etwas davon ganz fein und lege etwas davon vor das Zeugnis in der Stiftshütte, wo ich mit dir zusammenkommen will. Das soll euch hochheilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Und von dem Räucherwerk, das nach diesen Vorschriften gemacht wird, sollt ihr euch keines machen, sondern es soll dem HERRN heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Wer es nachmacht, um daran zu riechen, der soll von seinem Volk ausgerottet werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Siehe, ich habe mit Namen berufen Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'und habe ihn mit dem Geiste Gottes erfüllt, mit Weisheit und Verstand und Erkenntnis und mit allerlei Fertigkeit,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Erfindungen zu machen und sie auszuführen in Gold, Silber und Erz,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'und künstlich Steine zu schneiden und einzusetzen und künstlich zu zimmern am Holz, zu machen allerlei Werke.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Und siehe, ich habe ihm beigegeben Oholiab, den Sohn Ahisamachs, vom Stamme Dan, und habe allen Weisen die Weisheit ins Herz gegeben, daß sie alles, was ich dir geboten habe, machen sollen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Die Stiftshütte, die Lade des Zeugnisses, den Sühndeckel darauf und alle Geräte der Hütte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'den Tisch und seine Geräte, den reinen Leuchter und alle seine Geräte, den Räucheraltar,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'den Brandopferaltar mit allen seinen Geräten, das Becken mit seinem Fuß,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'die Amtskleider und die heiligen Kleider des Priesters Aaron und die Kleider seiner Söhne, priesterlich zu dienen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'und das Salböl und das Räucherwerk von Spezerei zum Heiligtum; ganz so, wie ich dir geboten habe, sollen sie es machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Sage den Kindern Israel und sprich: Beobachtet nur ja meine Sabbate! Denn sie sind das Zeichen zwischen mir und euch für alle eure Geschlechter, damit man wisse, daß ich der HERR bin, der euch heiligt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Und zwar sollt ihr den Sabbat beobachten, weil er euch heilig sein soll. Wer ihn entheiligt, der soll des Todes sterben; wer an demselben eine Arbeit verrichtet, dessen Seele soll ausgerottet werden aus seinem Volk!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage soll man arbeiten; aber am siebenten Tage ist der Sabbat, die heilige Ruhe des HERRN. Wer am Sabbattag eine Arbeit verrichtet, der soll des Todes sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Und zwar sollen die Kinder Israel den Sabbat halten, damit sie ihn für alle ihre Geschlechter zum ewigen Bunde machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Er ist ein ewiges Zeichen zwischen mir und den Kindern Israel; denn in sechs Tagen machte der HERR Himmel und Erde; aber am siebenten Tage ruhte er und erquickte sich.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Als er mit Mose auf dem Berge Sinai zu Ende geredet hatte, gab er ihm die beiden Tafeln des Zeugnisses; die waren steinern und mit dem Finger Gottes beschrieben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Als aber das Volk sah, daß Mose vom Berg zu kommen verzog, sammelte es sich um Aaron und sprach zu ihm: Auf, mache uns Götter, die uns vorangehen! Denn wir wissen nicht, was diesem Manne Mose widerfahren ist, der uns aus Ägypten geführt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aaron sprach zu ihnen: Reißet die goldenen Ohrringe ab, die an den Ohren eurer Weiber, eurer Söhne und eurer Töchter sind, und bringet sie zu mir!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da riß alles Volk seine goldenen Ohrringe ab, welche an ihren Ohren waren, und brachten sie zu Aaron.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Und er nahm sie von ihren Händen und bildete es mit dem Meißel und machte ein gegossenes Kalb. Da sprachen sie: Das sind deine Götter, Israel, die dich aus Ägypten geführt haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Als Aaron solches sah, baute er einen Altar vor demselben und ließ ausrufen und sprach: Morgen ist ein Fest für den HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Da standen sie am Morgen früh auf und opferten Brandopfer und brachten dazu Dankopfer; darnach setzte sich das Volk nieder, um zu essen und zu trinken, und sie standen auf, um zu spielen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da sprach der HERR zu Mose: Geh, steig hinab; denn dein Volk, das du aus Ägypten geführt hast, hat Verderben angerichtet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Sie sind eilends von dem Wege abgewichen, den ich ihnen geboten habe; sie haben sich ein gegossenes Kalb gemacht und haben es angebetet und ihm geopfert und gesagt: Das sind deine Götter, Israel, die dich aus Ägypten geführt haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Und der HERR sprach zu Mose: Ich habe dieses Volk beobachtet, und siehe, es ist ein halsstarriges Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'So laß mich nun, daß mein Zorn über sie ergrimme und ich sie verzehre, so will ich dich zu einem großen Volk machen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mose aber besänftigte das Angesicht des HERRN, seines Gottes, und sprach: Ach HERR, warum will dein Zorn über dein Volk ergrimmen, das du mit so großer Kraft und starker Hand aus Ägypten geführt hast?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollen die Ägypter sagen: Zum Unglück hat er sie ausgeführt, daß er sie im Gebirge erwürgte und von der Erde vertilgte? Kehre dich von dem Grimm deines Zorns und laß dich des Übels reuen, das du deinem Volk zugedacht hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenke deiner Diener, Abraham, Isaak und Israel, denen du bei dir selbst geschworen und zu denen du gesagt hast: Ich will euren Samen mehren wie die Sterne am Himmel, und dieses ganze Land, das ich versprochen habe, will ich eurem Samen geben, und sie sollen es ewiglich besitzen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Da reute den HERRN des Übels, das er seinem Volke anzutun gedroht hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mose aber wandte sich und stieg vom Berg hinab und hatte die zwei Tafeln des Zeugnisses in seiner Hand; die waren auf beiden Seiten beschrieben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Und die Tafeln waren Gottes Werk, und die Schrift war Gottes Schrift, darein gegraben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Als nun Josua das Geschrei des Volkes hörte, das jauchzte, sprach er zu Mose: Es ist ein Kriegsgeschrei im Lager!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Er aber antwortete: Man singt da weder von Sieg noch Niederlage, sondern ich höre einen Wechselgesang!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Als er aber nahe zum Lager kam und das Kalb und den Reigen sah, entbrannte Moses Zorn, so daß er die Tafeln wegwarf und sie unten am Berg zerschmetterte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Und er nahm das Kalb, das sie gemacht hatten, und verbrannte es mit Feuer und zermalmte es zu Pulver und stäubte es auf das Wasser und gab es den Kindern Israel zu trinken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Zu Aaron aber sprach Mose: Was hat dir dieses Volk angetan, daß du eine so große Sünde über sie gebracht hast?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Mein Herr lasse seinen Zorn nicht ergrimmen; du weißt, daß dieses Volk bösartig ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Sie sprachen zu mir: Mache uns Götter, die uns vorangehen, denn wir wissen nicht, was aus diesem Mann Mose geworden ist, der uns aus Ägypten geführt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Da sprach ich zu ihnen: Wer Gold hat, der reiße es ab! Da gaben sie mir\'s, und ich warf es ins Feuer; daraus ist das Kalb geworden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Als nun Mose sah, daß das Volk zügellos geworden war (denn Aaron hatte ihm die Zügel schießen lassen, seinen Widersachern zum Spott),');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'stellte er sich unter das Tor des Lagers und sprach: Her zu mir, wer dem HERRN angehört! Da sammelten sich zu ihm alle Kinder Levis.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Und er sprach zu ihnen: So spricht der HERR, der Gott Israels: Gürte jeder sein Schwert an seine Lenden und gehet hin und her, von einem Tor zum andern im Lager, und erwürge ein jeder seinen Bruder, seinen Freund und seinen Nächsten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Die Kinder Levis taten, wie ihnen Mose gesagt hatte, so daß an demselben Tage vom Volke bei dreitausend Männer fielen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Und Mose sprach: Füllet heute eure Hände dem HERRN, ein jeder für seinen Sohn und für seinen Bruder, daß heute der Segen über euch gegeben werde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Am Morgen sprach Mose zum Volk: Ihr habt eine große Sünde getan! Und nun will ich zu dem HERRN hinaufsteigen, vielleicht kann ich Vergebung erlangen für eure Sünde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Als nun Mose wieder zum HERRN kam, sprach er: Ach, das Volk hat eine große Sünde getan, daß sie sich goldene Götter gemacht haben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Und nun vergib ihnen doch ihre Sünde; wo nicht, so tilge mich aus deinem Buch, das du geschrieben hast!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Der HERR sprach zu Mose: Ich will den aus meinem Buche tilgen, der an mir sündigt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'So gehe nun hin und führe das Volk dahin, wovon ich dir gesagt habe. Siehe, mein Engel soll vor dir hergehen. Aber am Tage meiner Heimsuchung will ich ihre Sünde an ihnen heimsuchen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Also plagte der HERR das Volk wegen dessen, was sie mit dem Kalb getan, welches Aaron gemacht hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Der HERR sprach zu Mose: Gehe hin, ziehe von dannen, du und das Volk, das du aus Ägypten geführt hast, in das Land, das ich Abraham, Isaak und Jakob geschworen und von dem ich gesagt habe: Deinem Samen will ich es geben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ich aber will einen Engel vor dir hersenden und die Kanaaniter, Amoriter, Hetiter, Pheresiter, Heviter und Jebusiter ausstoßen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'in das Land, das von Milch und Honig fließt; denn ich will nicht mit dir hinaufziehen, weil du ein halsstarriges Volk bist; ich würde dich sonst unterwegs verzehren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Als das Volk diese harte Rede hörte, trug es Leid, und niemand legte seinen Schmuck an.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Und der HERR sprach zu Mose: Sage den Kindern Israel: Ihr seid ein halsstarriges Volk! Wenn ich nur einen Augenblick in deiner Mitte hinaufzöge, müßte ich dich vertilgen. Und nun lege deinen Schmuck von dir, so will ich sehen, was ich dir tun will!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Da rissen die Kinder Israel ihren Schmuck von sich ab beim Berge Horeb.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mose aber nahm die Hütte und schlug sie draußen auf, ferne von dem Lager, und hieß sie eine Hütte der Zusammenkunft. Und wer den HERRN fragen wollte, mußte vor das Lager hinaus zur Hütte der Zusammenkunft gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Und wenn Mose zu der Hütte hinausging, so stand alles Volk auf, und jedermann blieb stehen unter der Tür seines Zeltes und sah Mose nach, bis er in die Hütte hineinging.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Und wenn Mose in die Hütte hineinging, so kam die Wolkensäule herab und stand in der Tür der Hütte, und der HERR redete mit Mose.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Und wenn alles Volk die Wolkensäule in der Tür stehen sah, so standen sie alle auf und verneigten sich, ein jeder in der Tür seines Zeltes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Der HERR aber redete mit Mose von Angesicht zu Angesicht, wie ein Mann mit seinem Freunde redet; und wenn er wieder ins Lager zurückkehrte, so wich sein Diener Josua, der Sohn Nuns, der Jüngling, nicht aus der Hütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Und Mose sprach zum HERRN: Siehe, du sprichst zu mir: Führe das Volk hinauf; und du lässest mich nicht wissen, wen du mit mir senden willst, und doch hast du gesagt: Ich kenne dich mit Namen, und du hast Gnade vor meinen Augen gefunden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Habe ich nun vor deinen Augen Gnade gefunden, so laß mich doch deinen Weg wissen und dich erkennen, damit ich vor deinen Augen Gnade finde; und siehe doch das an, daß dieses Volk dein Volk ist!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Er sprach: Soll ich selbst gehen und dich zur Ruhe führen?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Er sprach zu ihm: Wenn du nicht selbst mitgehst, so führe uns nicht von hier hinauf!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Denn woran soll doch erkannt werden, daß ich und dein Volk vor deinen Augen Gnade gefunden haben, als daran, daß du mit uns gehst, so daß ich und dein Volk ausgezeichnet werden vor allem Volk, das auf dem Erdboden ist?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Der HERR sprach zu Mose: Was du jetzt gesagt hast, das will ich auch tun; denn du hast vor meinen Augen Gnade gefunden, und ich kenne dich mit Namen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Er aber sprach: So laß mich deine Herrlichkeit sehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Und er sprach: Ich will vor deinem Angesicht alle meine Güte vorüberziehen lassen und will den Namen des HERRN vor dir ausrufen; und wem ich gnädig bin, dem bin ich gnädig, und wessen ich mich erbarme, dessen erbarme ich mich;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'aber mein Angesicht (sprach er) kannst du nicht sehen, denn kein Mensch wird leben, der mich sieht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Doch sprach der HERR: Siehe, es ist ein Ort bei mir, da sollst du auf dem Felsen stehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Wenn dann meine Herrlichkeit vorübergeht, so stelle ich dich in die Felsenkluft und will dich mit meiner Hand solange decken, bis ich vorübergegangen bin.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Wenn ich dann meine Hand zurückziehe, so magst du mir hinten nachsehen; aber mein Angesicht soll man nicht sehen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Und der HERR sprach zu Mose: Haue dir zwei steinerne Tafeln, wie die ersten waren, daß ich die Worte darauf schreibe, die auf den ersten Tafeln waren, welche du zerbrochen hast,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'und sei morgen bereit, daß du früh auf den Berg Sinai steigest und daselbst zu mir auf die Spitze des Berges tretest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Und laß niemand mit dir hinaufsteigen, daß niemand um den ganzen Berg her gesehen werde; laß auch keine Schafe noch Rinder gegen diesen Berg weiden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Und Mose machte zwei steinerne Tafeln, wie die ersten waren, und stand am Morgen früh auf und stieg auf den Berg Sinai, wie ihm der HERR geboten hatte, und nahm die zwei steinernen Tafeln in seine Hand.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Da kam der HERR herab in einer Wolke und trat daselbst zu ihm und rief den Namen des HERRN aus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Und als der HERR vor seinem Angesicht vorüberging, rief er: Der HERR, der HERR, der starke Gott, der barmherzig und gnädig ist, langsam zum Zorn und von großer Gnade und Treue;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'welcher Tausenden Gnade bewahrt und Missetat, Übertretung und Sünde vergibt, aber keineswegs ungestraft läßt, sondern heimsucht der Väter Missetat an den Kindern und Kindeskindern bis in das dritte und vierte Glied!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Da neigte sich Mose eilends zur Erde, betete an und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'O Herr, habe ich vor deinen Augen Gnade gefunden, so ziehe mein Herr mitten unter uns, wiewohl es ein halsstarriges Volk ist; du aber wollest unserer Missetat und Sünde gnädig sein und uns zum Erbteil annehmen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Da sprach er: Siehe, ich mache einen Bund: vor deinem ganzen Volk will ich Wunder tun, dergleichen nicht geschehen sind in allen Ländern und unter allen Völkern; und das ganze Volk, darunter du bist, soll das Werk des HERRN sehen; denn wunderbar soll es sein, was ich mit dir tun will.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Hüte dich vor dem, was ich dir heute verbiete! Siehe, ich will vor dir her ausstoßen die Amoriter, Kanaaniter, Hetiter, Pheresiter, Heviter und Jebusiter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich, mit den Einwohnern des Landes, in das du kommst, einen Bund zu machen, daß sie dir zum Fallstrick werden in deiner Mitte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'sondern ihr sollt ihre Altäre umstürzen und ihre Säulen zerbrechen und ihre Astartenbilder ausrotten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Denn du sollst keinen andern Gott anbeten. Denn der HERR heißt ein Eiferer und ist ein eifersüchtiger Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Daß du nicht etwa mit den Einwohnern des Landes einen Bund machest, und wenn sie ihren Göttern nachbuhlen und ihren Göttern opfern, sie dich einladen und du von ihrem Opfer essest,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'und nehmest deinen Söhnen ihre Töchter zu Weibern und dieselben alsdann ihren Göttern nachbuhlen und machen, daß deine Söhne auch ihren Göttern nachbuhlen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Du sollst dir keine gegossenen Göttern machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesäuerten Brote sollst du halten. Sieben Tage lang sollst du ungesäuertes Brot essen, wie ich dir geboten habe, um die bestimmte Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten gezogen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alle Erstgeburt ist mein, auch alle männliche Erstgeburt unter deinem Vieh, es sei ein Ochs oder ein Schaf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Aber den Erstling des Esels sollst du mit einem Schafe lösen; wenn du ihn aber nicht lösest, so brich ihm das Genick. Alle Erstgeburt deiner Söhne sollst du lösen. Man soll nicht leer erscheinen vor meinem Angesicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage sollst du arbeiten, aber am siebenten Tage sollst du ruhen; mit Pflügen und Ernten sollst du ruhen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Das Fest der Wochen sollst du halten, mit den Erstlingen der Weizenernte und das Fest der Einsammlung, wenn das Jahr vergangen ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Alles, was männlich ist, soll dreimal im Jahr vor dem Herrscher, dem HERRN, dem Gott Israels, erscheinen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Wenn ich die Heiden vor dir ausstoßen und deine Landmarken erweitern werde, soll niemand deines Landes begehren, während du hinaufgehst, um dreimal im Jahr zu erscheinen vor dem HERRN, deinem Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst das Blut meines Opfers nicht neben dem Sauerteig opfern. Und das Opfer des Passahfestes soll nicht über Nacht bis zum Morgen bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Die Erstlinge von den ersten Früchten deines Ackers sollst du in das Haus des HERRN, deines Gottes, bringen. Du sollst das Böcklein nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und der HERR sprach zu Mose: Schreibe diese Worte; denn nach diesen Worten habe ich mit dir und mit Israel einen Bund gemacht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Und er war daselbst bei dem HERRN vierzig Tage und vierzig Nächte lang und aß kein Brot und trank kein Wasser. Und er schrieb auf die Tafeln die Worte des Bundes, die zehn Worte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Als nun Mose vom Berge Sinai hinabstieg und die beiden Tafeln des Zeugnisses in der Hand hielt, als er vom Berge herabstieg, da wußte er nicht, daß die Haut seines Angesichts strahlte davon, daß er mit Ihm geredet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Und Aaron und alle Kinder Israel sahen Mose, und siehe, die Haut seines Angesichtes strahlte; da fürchteten sie sich, ihm zu nahen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Aber Mose rief sie; da wandten sie sich zu ihm, Aaron und alle Obersten der Gemeinde; und Mose redete mit ihnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Darnach traten alle Kinder Israel näher zu ihm. Und er befahl ihnen alles, was der HERR mit ihm auf dem Berge Sinai geredet hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Als nun Mose aufhörte mit ihnen zu reden, legte er eine Decke auf sein Angesicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Und wenn Mose hineinging vor den HERRN, mit ihm zu reden, tat er die Decke ab, bis er wieder herausging. Und er ging heraus und redete mit den Kindern Israel, was ihm befohlen war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Und die Kinder Israel sahen das Angesicht Moses, daß die Haut desselben strahlte, und Mose tat die Decke wieder auf sein Angesicht, bis er wieder hineinging, mit Ihm zu reden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Und Mose versammelte die ganze Gemeinde der Kinder Israel und sprach zu ihnen: Das sind die Worte, die der HERR geboten hat, daß ihr sie tun sollt:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage soll gearbeitet werden, aber der siebente Tag soll euch heilig sein, zu feiern die Sabbatruhe des HERRN. Wer da Arbeit verrichtet, der soll sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Am Sabbattag sollt ihr in allen euren Wohnungen kein Feuer anzünden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Mose redete weiter mit der ganzen Gemeinde der Kinder Israel und sprach: Das ist\'s, was der HERR geboten hat:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Bringt aus eurer Mitte Gaben für den HERRN; jeder, den sein Herz dazu treibt, der soll sie bringen, die Gabe des HERRN, nämlich Gold, Silber und Erz,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Stoffe von blauem und rotem Purpur und Karmesinfarbe, feine weiße Baumwolle und Ziegenhaare,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'rötliche Widderfelle, Seehundsfelle und Akazienholz,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'und Öl zum Leuchter und Spezerei zum Salböl und zu gutem Räucherwerk,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Schohamsteine und Steine zum Besatz für das Ephod und das Brustschildlein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und wer unter euch weisen Herzens ist, der komme und mache, was der HERR geboten hat:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Die Wohnung mit ihrer Hütte, ihre Decke, ihre Bretter, ihre Riegel, ihre Säulen und ihre Füße;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade mit ihren Stangen, den Sühndeckel und den Vorhang;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch mit seinen Stangen und allem seinem Gerät und die Schaubrote;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den Leuchter zur Beleuchtung samt seinen Geräten und Lampen und das Öl des Leuchters;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'den Räucheraltar mit seinen Stangen, das Salböl und die Spezerei zum Räucherwerk, den Vorhang der Tür beim Eingang der Wohnung;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Brandopferaltar mit seinem ehernen Gitter, mit seinen Stangen und allem seinem Gerät, das Becken mit seinem Fuß;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'die Vorhänge des Vorhofs mit seinen Säulen und Füßen, und den Vorhang des Tors am Vorhof;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'die Nägel der Wohnung und des Vorhofs mit ihren Seilen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'die Amtskleider zum Dienst im Heiligtum, die heiligen Kleider Aarons, des Priesters, und die Kleider seiner Söhne zum Priestertum.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Da ging die ganze Gemeinde der Kinder Israel von Mose hinweg.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Und ein jeder, dessen Geist willig war, kam und brachte dem HERRN Gaben für das Werk der Stiftshütte und all ihren Dienst und für die heiligen Kleider.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Es kamen aber die Männer samt den Frauen, alle die willigen Herzens waren, und brachten Nasenringe, Ohrringe, Fingerringe, Armbänder und allerlei goldene Geräte; alle, die dem HERRN Gold zum Webopfer brachten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Und wer bei sich Stoffe fand von blauem und rotem Purpur und Karmesinfarbe, feine weiße Baumwolle, Ziegenhaare, rötliche Widderfelle und Seehundsfelle, der brachte es.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Und wer Silber und Erz hatte, der brachte es dem HERRN zum Hebopfer. Und wer Akazienholz bei sich fand, der brachte es zu allerlei Werk des Dienstes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und alle Frauen, die weisen Herzens waren, spannen mit ihren Händen und brachten das Gesponnene, Stoffe von blauem und rotem Purpur und Karmesinfarbe und von feiner weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Und die Frauen, die ihr Herz dazu trieb und welche verständigen Sinnes waren, die spannen Ziegenhaare.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Die Fürsten aber brachten Schohamsteine und eingefaßte Steine zum Brustschildlein,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'und Spezerei und Öl für den Leuchter und für das Salböl und zu gutem Räucherwerk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Also brachten die Kinder Israel (alle Männer und Frauen, die willigen Herzens waren zu allerlei Werk beizutragen, das der HERR durch Mose zu machen befohlen hatte) dem HERRN freiwillige Gaben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Da sprach Mose zu den Kindern Israel: Seht, der HERR hat mit Namen berufen Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Und der Geist Gottes hat ihn erfüllt mit Weisheit, Verstand und Geschicklichkeit für allerhand Arbeit;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'auch daß er kunstreiche Arbeit erfinden kann zur Ausführung in Gold, Silber und Erz;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'im Schneiden und Einsetzen der Edelsteine, im Zimmern des Holzes, um allerlei kunstvolle Arbeit zu machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Auch hat er ihm ins Herz gegeben, daß er unterweisen kann; er und Oholiab, der Sohn Ahisamachs, vom Stamme Dan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat sie mit weisen Herzen erfüllt, zu machen allerlei Werk eines Künstlers und Erfinders und Buntwirkers in Stoffen von blauem und rotem Purpur und Karmesinfarbe und von feiner weißer Baumwolle, und eines Webers, daß sie allerlei Werke machen und sinnreiche Arbeit erfinden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Da arbeiteten Bezaleel und Oholiab und alle Männer, die weisen Herzens waren, denen der HERR Weisheit und Verstand gegeben hatte, zu wissen, wie sie allerlei Werke machen sollten zum Dienste des Heiligtums, nach allem dem, was der HERR geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Und Mose rief Bezaleel und Oholiab und alle Männer, die weisen Herzens waren, denen der HERR Weisheit ins Herz gegeben hatte, auch alle, die ihr Herz dazu trieb, daß sie hinzutraten, um an dem Werke zu arbeiten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Und sie empfingen von Mose alle Gaben, welche die Kinder Israel brachten zu dem Werke des Dienstes am Heiligtum, daß es gemacht werde; und sie brachten immer noch alle Morgen ihre freiwilligen Gaben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da kamen alle Weisen, die am Werke des Heiligtums arbeiteten, ein jeder von seiner Arbeit, die sie machten,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und redeten mit Mose und sprachen: Das Volk bringt zu viel, mehr als zum Werke dieses Dienstes notwendig ist, das der HERR zu machen geboten hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da gebot Mose, daß man durch das Lager ausrufen und sagen ließe: Niemand, es sei Mann oder Weib, soll mehr etwas anfertigen zur Abgabe an das Heiligtum! Also ward dem Volke gewehrt zu bringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'denn des Stoffes war genug und noch übrig zu allerlei Werk, das zu machen war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'So machten nun alle Männer, die weisen Herzens waren unter den Arbeitern am Werke, die Wohnung, zehn Teppiche von gezwirnter weißer Baumwolle, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe, mit Cherubim künstlich durchwirkt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Die Länge eines Teppichs war achtundzwanzig Ellen und seine Breite vier Ellen, und sie hatten alle einerlei Maß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Und er heftete je fünf Teppiche zusammen, einen an den andern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Und er machte Schleifen von blauem Purpur am Ende der beiden Teppiche, am Ende, da sie zusammengefügt wurden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen machte er an jedem Teppich, damit eine die andere faßte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Und er machte fünfzig goldene Haften und fügte die Teppiche mit den Haften zusammen, einen an den andern, so daß die Wohnung ein Ganzes wurde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Und er machte elf Teppiche von Ziegenhaaren zum Zelte über die Wohnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Dreißig Ellen lang und vier Ellen breit war jeder Teppich, alle elf nach einem Maß;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'und er fügte fünf besonders zusammen und sechs besonders,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'und machte je fünfzig Schleifen am Ende eines jeden Teppichs, damit sie zusammengeheftet würden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Dazu machte er fünfzig eherne Haften, damit die Decke zu einem Ganzen zusammengefügt würde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Und machte über die Hütte eine Decke von rötlichen Widderfellen und darüber noch eine Decke von Seehundsfellen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Er machte auch Bretter zu der Wohnung von Akazienholz, aufrechtstehend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Zehn Ellen lang und anderthalb Ellen breit war ein jedes;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'und an jedem zwei Zapfen, einer dem andern gegenüberstehend; also tat er mit allen Brettern zu der Wohnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Er machte aber die Bretter zur Wohnung also, daß zwanzig derselben auf der Seite gegen Mittag standen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'und machte vierzig silberne Füße unter die zwanzig Bretter, unter ein jedes Brett zwei Füße für die beiden Zapfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Desgleichen zur andern Seite der Wohnung, gegen Mitternacht, machte er auch zwanzig Bretter');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'und vierzig silberne Füße, unter ein jedes Brett zwei Füße.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Aber hinten an der Wohnung, gegen Abend, machte er sechs Bretter,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'und zwei andere hinten an den beiden Ecken der Wohnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Diese waren also doppelt von unten auf, und oben zusammengefügt mit einem Ringe: Also machte er sie beide, an beiden Ecken,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'so daß acht Bretter wurden und sechzehn silberne Füße, unter jedem Brett zwei Füße.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Und er machte Riegel von Akazienholz, fünf zu den Brettern auf einer Seite der Wohnung,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'und fünf auf der andern Seite derselben, und fünf hinten, gegen Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Und machte den Mittelriegel, daß er inwendig durch die Bretter hindurchging von einem Ende zum andern,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'und er überzog die Bretter mit Gold; auch die Ringe für die Riegel machte er von Gold, und er überzog die Riegel mit Gold.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Und machte den Vorhang aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und gezwirnter weißer Baumwolle, und machte Cherubim daran, künstlich gewirkt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Und machte zu denselben vier Säulen von Akazienholz und überzog sie mit Gold, und machte ihre Haken von Gold, und goß dazu vier silberne Füße.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Und machte einen Vorhang für die Tür der Hütte aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle, in Buntwirkerarbeit,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'und fünf Säulen dazu mit ihren Haken, und überzog ihre Köpfe und ihre Querstangen mit Gold, und machte fünf eherne Füße dazu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Und Bezaleel machte die Lade von Akazienholz, dreieinhalb Ellen lang und anderthalb Ellen breit und anderthalb Ellen hoch,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'und überzog sie mit reinem Gold inwendig und auswendig, und machte ihr einen goldenen Kranz ringsum.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Und goß vier goldene Ringe an ihre vier Ecken, auf jeder Seite zwei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Und machte Stangen von Akazienholz und überzog sie mit Gold');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'und tat sie in die Ringe an den Seiten der Lade, daß man sie tragen konnte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Und machte den Sühndeckel von reinem Golde, dreieinhalb Ellen lang und anderthalb Ellen breit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Und machte zwei Cherubim von getriebenem Gold an die beiden Enden des Sühndeckels,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'einen Cherub an diesem Ende und den andern an jenem Ende; zwei Cherubim machte er an beiden Enden des Sühndeckels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Und die Cherubim breiteten ihre Flügel aus von oben her und deckten damit den Sühndeckel, und ihre Angesichter waren einander zugekehrt und sahen auf den Sühndeckel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Und er machte den Tisch von Akazienholz zwei Ellen lang, eine Elle breit und anderthalb Ellen hoch,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'und überzog ihn mit reinem Gold und machte ihm einen goldenen Kranz ringsum,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'und machte ihm eine Leiste ringsum, eine Handbreit hoch, und machte einen goldenen Kranz um die Leiste her,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'und goß dazu vier goldene Ringe und tat sie an die vier Ecken, an seine vier Füße,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'dicht unter die Leiste, daß man die Stangen darein tun und so den Tisch tragen konnte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Und machte die Stangen von Akazienholz und überzog sie mit Gold, um den Tisch damit zu tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Und machte auch von reinem Golde die Geräte auf dem Tisch, seine Schüsseln, seine Schalen, seine Becher und seine Kannen, um mit ihnen Trankopfer zu spenden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Und er machte den Leuchter von reinem getriebenem Gold, daran war der Schaft mit Armen, Kelchen, Knoten und Blumen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sechs Arme gingen von seinen Seiten aus, von jeder Seite drei Arme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'An jedem Arm waren drei Kelche wie Mandelblüten, dazu ihre Knoten und Blumen; auf diese Weise gingen die sechs Arme aus dem Leuchter hervor.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'An dem Schaft aber waren vier Kelche wie Mandelblüten mit Knoten und Blumen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'unter je zwei Armen ein Knoten, bei allen sechs Armen, die aus dem Leuchter gingen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knoten und Arme gingen aus ihm hervor, und es war alles getriebenes reines Gold.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Er machte auch sieben Lampen mit ihren Lichtscheren und Pfannen von reinem Gold.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Zentner reinen Goldes machte er ihn und alle seine Geräte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Er machte auch den Räucheraltar von Akazienholz, eine Elle lang und eine Elle breit, viereckig, und zwei Ellen hoch mit seinen Hörnern, die aus ihm hervorgingen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'und überzog ihn mit reinem Golde, seine Platte und seine Wände ringsum und seine Hörner und machte ihm einen Kranz ringsum von reinem Gold;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'und zwei goldene Ringe unter dem Kranz zu beiden Seiten, daß man Stangen darein tue, um ihn zu tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Aber die Stangen machte er von Akazienholz und überzog sie mit Gold.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'und er machte das heilige Salböl und Räucherwerk von reiner Spezerei, nach der Kunst des Salbenbereiters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Darnach machte er auch den Brandopferaltar von Akazienholz, fünf Ellen lang und fünf Ellen breit, viereckig, und drei Ellen hoch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Und machte vier Hörner, die aus ihm hervorgingen an seinen vier Ecken, und überzog ihn mit Erz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Und machte alle Geräte zu dem Altar, Aschentöpfe, Schaufeln, Becken, Gabeln und Kohlenpfannen: alles machte er von Erz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Und machte am Altar ein Gitter, wie ein Netz, von Erz, unter seiner Einfassung, von unten auf bis zur halben Höhe des Altars,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'und goß vier Ringe an die vier Enden des ehernen Gitters zur Aufnahme der Stangen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Dieselben machte er von Akazienholz und überzog sie mit Erz');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'und tat sie in die Ringe an den Seiten des Altars, daß man ihn damit trage. Und er machte ihn hohl, von Brettern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Und er machte das Becken von Erz und seinen Fuß auch von Erz, aus den Spiegeln der dienenden Weiber, die vor der Tür der Stiftshütte Frondienst taten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Und er machte einen Vorhof: Auf der rechten Seite, gegen Mittag, einen Vorhang dazu, hundert Ellen lang, von gezwirnter weißer Baumwolle,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'mit seinen zwanzig Säulen und zwanzig Füßen von Erz; aber ihre Haken und Querstangen von Silber;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'desgleichen gegen Mitternacht hundert Ellen mit zwanzig Säulen und zwanzig Füßen von Erz; aber ihre Haken und Querstangen von Silber;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'gegen Abend aber fünfzig Ellen mit zehn Säulen und zehn Füßen; und ihre Haken und Querstangen von Silber;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'gegen Morgen aber fünfzig Ellen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'fünfzehn Ellen auf der einen Seite mit ihren drei Säulen und drei Füßen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'und fünfzehn Ellen auf der andern Seite, also daß auf beiden Seiten des Tores am Vorhof gleichviele waren, drei Säulen und drei Füße.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Es waren aber alle Vorhänge des Vorhofs ringsum von gezwirnter weißer Baumwolle,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'und die Füße der Säulen von Erz und ihre Haken und Querstangen von Silber und ihre Köpfe mit Silber überzogen; die Querstangen waren silbern an allen Säulen des Vorhofs.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Und den Vorhang im Tore des Vorhofs machte er in Buntwirkerarbeit aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle, zwanzig Ellen lang und fünf Ellen hoch in der Breite, nach dem Maße der Vorhänge des Vorhofs;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'dazu vier Säulen und vier Füße von Erz, und ihre Haken von Silber und ihre Köpfe überzogen und ihre Querstangen silbern;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'und alle Nägel der Wohnung und des Vorhofs ringsum waren von Erz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Dies ist die Berechnung der Kosten der Wohnung, der Wohnung des Zeugnisses, welche auf Befehl Moses gemacht wurde, mit Hilfe der Leviten durch die Hand Itamars, des Sohnes Aarons, des Priesters,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'nachdem Bezaleel, der Sohn Uris, des Sohns Hurs, vom Stamme Juda, alles gemacht, wie der HERR Mose geboten hatte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Oholiab, der Sohn Ahisamachs, vom Stamme Dan, ein Meister im Steinschneiden, in künstlicher Arbeit und im Buntwirken von Stoffen von blauem und rotem Purpur und Karmesinfarbe und in feiner weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alles Gold, das verarbeitet wurde in diesem ganzen Werke des Heiligtums, das zum Webopfer gegeben ward, betrug neunundzwanzig Zentner und siebenhundertdreißig Schekel, nach dem Schekel des Heiligtums.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Das Silber aber von den Gezählten der Gemeinde war hundert Zentner und 1775 Schekel, nach dem Schekel des Heiligtums.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'So manches Haupt, so mancher halbe Schekel, nach dem Schekel des Heiligtums, von allen, die gezählt wurden, von zwanzig Jahren an und darüber, 603550 Mann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Aus den hundert Zentnern Silber goß man die Füße des Heiligtums und die Füße des Vorhangs, hundert Füße aus hundert Zentnern, je einen Zentner zu einem Fuß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Aber aus den 1775 Schekeln wurden die Haken der Säulen gemacht und ihre Köpfe überzogen und mit ihren Querstangen verbunden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Das Webopfer aber des Erzes war siebzig Zentner und zweitausendvierhundert Schekel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Daraus wurden die Füße der Tür der Hütte des Zeugnisses gemacht, und der eherne Altar und das eherne Gitter daran und alle Geräte des Altars;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'dazu die Füße des Vorhofs ringsumher, und die Füße des Tors am Vorhof, alle Nägel der Wohnung und alle Nägel des Vorhofs ringsumher.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Und aus den Stoffen von blauem und rotem Purpur und Karmesinfarbe machten sie die Amtstracht zum Dienst im Heiligtum und verfertigten die heiligen Kleider für Aaron, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Und er machte das Ephod von Gold und aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Das Gold aber schlugen sie dünn zu Blechen und schnitten es zu Fäden, daß man es künstlich wirken konnte in die Stoffe von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Sie machten auch Schulterstücke daran, um das Brustkleid an beiden Enden zu verbinden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Das künstliche Werk seines Gurts aber, womit man es gürtete, hing mit ihm zusammen und war von derselben Arbeit, von Gold, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und gezwirnter weißer Baumwolle, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Und sie machten Schohamsteine, in Gold gefaßt, wie Siegel gestochen auf die Namen der Kinder Israel;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'die hefteten sie auf die Schulterstücke des Brustkleides, daß sie Steine des Gedächtnisses wären für die Kinder Israel, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Sie machten auch das Brustschildlein, ein Kunstwerk, wie das Brustkleid von Gold, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe und von gezwirnter weißer Baumwolle.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Und machten dasselbe viereckig und doppelt gelegt, eine Spanne lang und eine Spanne breit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Und füllten es mit vier Reihen von Steinen: Die erste Reihe war ein Rubin, ein Topas und ein Smaragd;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'die zweite Reihe ein Granat, ein Saphir und ein Diamant;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'die dritte Reihe ein Opal, ein Achat und ein Amethyst;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'die vierte Reihe ein Chrysolit, ein Schoham und ein Jaspis, bei ihrer Einsetzung in Gold gefaßt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Und die Steine lauteten nach den Namen der Kinder Israel; auf ihre zwölf Namen waren sie wie Siegel gestochen, ein jeder auf einen Namen der zwölf Stämme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Und sie machten an das Brustschildlein gewundene Ketten von geflochtener Arbeit von reinem Gold,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'auch zwei goldene Einfassungen und zwei goldene Ringe, und setzten die beiden Ringe an die beiden Ecken des Brustschildleins.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Und die beiden gewundenen goldenen Ketten taten sie in die beiden Ringe an den Ecken des Brustschildleins.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Die beiden andern Enden aber der gewundenen Ketten taten sie an die beiden Einfassungen und setzten sie auf die beiden Schulterstücke des Ephod, einander gegenüber.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Und sie machten zwei andere goldene Ringe und setzten sie an die beiden andern Ecken des Brustschildleins, nämlich an seinem Rande, welcher inwendig dem Ephod zugekehrt war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Noch zwei andere goldene Ringe machten sie, die taten sie auf die beiden Schulterstücke des Ephod, unterhalb, einander gegenüber, wo das Ephod zusammengeheftet wird, oberhalb des Gürtels des Ephod.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Und sie banden das Brustschildlein mit seinen Ringen an die Ringe des Ephod mit einer Schnur von blauem Purpur, daß es auf dem Ephod hart anlag und sich nicht von dem Ephod losmachte; wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Desgleichen machte er den Rock des Ephod, ganz von blauem Purpur gewoben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'und seine Öffnung oben mitten darin, und einen Saum um die Öffnung, wie den Saum eines Panzers, daß sie nicht zerreiße.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Und sie machten an seinem untern Saum Granatäpfel, aus Stoffen von blauem und rotem Purpur und Karmesinfarbe gezwirnt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Und machten Schellen von reinem Gold; die taten sie zwischen die Granatäpfel ringsum an den Saum des Rockes,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'je einen Granatapfel und eine Schelle, ringsum, um darin zu dienen, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Und sie machten auch die Leibröcke, von weißer Baumwolle gezwirnt, für Aaron und seine Söhne,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'und den Kopfbund von weißer Baumwolle und die hohen Mützen von weißer Baumwolle und die Unterkleider von gezwirnter weißer Baumwolle;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'und den Gürtel von gezwirnter weißer Baumwolle und aus Stoffen von blauem und rotem Purpur und Karmesinfarbe, Arbeit des Buntwirkers, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Sie machten auch das Stirnblatt, das heilige Diadem, von reinem Gold und schrieben darauf in gestochener Siegelschrift: Heilig dem HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Und banden eine Schnur von blauem Purpur daran, um es oben am Hut zu befestigen, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Also ward das ganze Werk der Wohnung, der Stiftshütte, vollendet. Und die Kinder Israel machten alles, wie der HERR Mose geboten hatte; so machten sie es.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Und sie brachten die Wohnung zu Mose, die Hütte und alle ihre Geräte, ihre Haften, Bretter, Riegel, Säulen, Füße;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'die Decke von rötlichen Widderfellen, die Decke von Seehundsfellen und den Vorhang der Decke;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Lade des Zeugnisses mit ihren Stangen, den Sühndeckel;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch und alle seine Geräte und die Schaubrote;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den Leuchter von reinem Golde, seine Lampen, die geordneten Lampen und alle seine Geräte und das Öl des Leuchters;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'den goldenen Altar, das Salböl, das gute Räucherwerk und den Vorhang zu der Tür der Hütte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den ehernen Altar und sein ehernes Gitter mit seinen Stangen und allen seinen Geräten, das Becken samt seinem Fuß;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Vorhänge des Vorhofs mit seinen Säulen und Füßen, den Vorhang im Tor des Vorhofs mit seinen Seilen und Nägeln und allen Geräten zum Dienst der Wohnung, der Stiftshütte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die Amtstracht zum Dienst im Heiligtum, die heiligen Kleider des Priesters Aaron und die Kleider seiner Söhne, um das Priesteramt zu verwalten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'ganz, wie der HERR Mose geboten hatte, so hatten die Kinder Israel das Werk vollbracht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Und Mose sah die ganze Arbeit an, und siehe, sie hatten dieselbe gemacht, wie der HERR geboten hatte; so hatten sie es gemacht. Und Mose segnete sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Du sollst die Wohnung, die Stiftshütte, aufrichten am ersten Tage des ersten Monats.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Und du sollst die Lade des Zeugnisses darein setzen und den Vorhang vor die Lade hängen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Und du sollst den Tisch hineinbringen und darauf legen, was darauf gehört, und den Leuchter hineinbringen und die Lampen darauf setzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Und du sollst den goldenen Räucheraltar vor die Lade des Zeugnisses setzen und den Vorhang in der Tür der Wohnung aufhängen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Den Brandopferaltar aber sollst du vor die Tür der Wohnung, der Stiftshütte, setzen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'und das Becken zwischen die Stiftshütte und den Altar, und sollst Wasser hineintun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Und du sollst den Vorhof ringsum aufrichten und den Vorhang in das Tor des Vorhofs hängen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Und du sollst das Salböl nehmen und die Wohnung salben, samt allem, was darin ist, und du sollst sie weihen und alle ihre Geräte, daß sie heilig sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Und du sollst den Brandopferaltar mit allen seinen Geräten salben und ihn weihen, daß er hochheilig sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Du sollst auch das Becken salben samt seinem Fuß und es weihen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Und du sollst Aaron und seine Söhne vor die Tür der Stiftshütte führen und sie mit Wasser waschen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'und Aaron die heiligen Kleider anziehen und ihn salben und weihen, daß er mein Priester sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Auch seine Söhne sollst du herzuführen und ihnen die Leibröcke anziehen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'und sie salben, wie du ihren Vater gesalbt hast, daß sie meine Priester seien. Und diese Salbung soll ihnen ein ewiges Priestertum verschaffen auf alle ihre Geschlechter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Mose tat alles, wie ihm der HERR geboten hatte; so machte er\'s.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Also ward die Wohnung aufgerichtet im zweiten Jahr, am ersten Tage des ersten Monats.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Und als Mose dieselbe aufgerichtet hatte, setzte er die Füße und die Bretter und Riegel, und richtete die Säulen auf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Und breitete das Zelt aus über die Wohnung und legte die Decke des Zeltes oben darauf, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Und er nahm das Zeugnis und legte es in die Lade, und tat die Stangen an die Lade;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'und brachte die Lade in die Wohnung und hing den Vorhang vor die Lade des Zeugnisses, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Und er setzte den Tisch in die Stiftshütte, an die Seite der Wohnung gegen Mitternacht, außerhalb des Vorhangs,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'und ordnete die Brote darauf vor dem HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Er stellte auch den Leuchter in die Stiftshütte, dem Tisch gegenüber, an die Seite der Wohnung gegen Mittag,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'und setzte Lampen darauf vor dem HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Und er stellte den goldenen Altar in die Stiftshütte, vor den Vorhang,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'und räucherte darauf mit gutem Räucherwerk, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Und er hängte den Vorhang in die Tür der Wohnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Aber den Brandopferaltar setzte er vor die Tür der Wohnung, der Stiftshütte, und opferte darauf Brandopfer und Speisopfer, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Das Becken aber setzte er zwischen die Stiftshütte und den Altar und tat Wasser darein zum Waschen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Und Mose, Aaron und seine Söhne wuschen ihre Hände und Füße damit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Sie mußten sich waschen, wenn sie in die Stiftshütte gingen und zum Altar traten, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Und er richtete den Vorhof auf um die Wohnung und um den Altar her und hängte den Vorhang in das Tor des Vorhofs. Also vollendete Mose das ganze Werk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Da bedeckte die Wolke die Stiftshütte, und die Herrlichkeit des HERRN erfüllte die Wohnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Mose konnte nicht in die Stiftshütte gehen, solange die Wolke darauf blieb und die Herrlichkeit des HERRN die Wohnung erfüllte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Wenn sich aber die Wolke von der Wohnung erhob, so brachen die Kinder Israel auf, während aller ihrer Reisen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Wenn sich aber die Wolke nicht erhob, so brachen sie nicht auf bis zu dem Tag, da sie sich erhob.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn die Wolke des HERRN war bei Tag auf der Wohnung, und des Nachts war Feuer darauf vor den Augen des ganzen Hauses Israel, während aller ihrer Reisen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Und er rief Mose, und der HERR redete zu ihm von der Stiftshütte aus und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Will jemand von euch dem HERRN ein Opfer bringen, so soll euer Opfer, das ihr darbringet, vom Vieh, von Rindern oder Schafen genommen sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ist seine Gabe ein Brandopfer von Rindern, so soll er ein tadelloses männliches Tier darbringen; zur Tür der Stiftshütte soll er es bringen, daß es ihn angenehm mache vor dem HERRN;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'und er soll seine Hand auf den Kopf des Brandopfers stützen, so wird es ihm wohlgefällig aufgenommen und für ihn Sühne erwirken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Dann soll er den jungen Ochsen schächten vor dem HERRN; die Söhne Aarons aber, die Priester, sollen das Blut darbringen und es ringsum an den Altar sprengen, der vor der Tür der Stiftshütte steht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Er aber soll dem Brandopfer die Haut abziehen und es in Stücke zerlegen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'und die Söhne Aarons, des Priesters, sollen Feuer auf den Altar tun und Holz aufschichten über dem Feuer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'auf das Holz aber über dem Feuer sollen die Priester, die Söhne Aarons, die Fleischstücke legen, dazu den Kopf und das Fett;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'sein Eingeweide aber und seine Schenkel soll man mit Wasser waschen; und der Priester soll das Ganze auf dem Altar verbrennen als ein Brandopfer, ein wohlriechendes Feuer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Entnimmt er aber seine Opfergabe dem Kleinvieh, so bringe er zum Brandopfer ein tadelloses männliches Tier von den Lämmern oder Ziegen dar');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'und schächte es an der nördlichen Seite des Altars vor dem HERRN, und die Söhne Aarons, die Priester, sollen das Blut ringsum an den Altar sprengen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'er aber zerlege es in Stücke, und der Priester lege sie samt dem Kopf und dem Fett ordentlich auf das Holz über dem Feuer auf dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Aber das Eingeweide und die Schenkel soll man mit Wasser waschen; und der Priester soll das Ganze darbringen und verbrennen auf dem Altar; es ist ein Brandopfer, ein wohlriechendes Feuer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Soll aber seine Brandopfergabe für den HERRN aus Geflügel bestehen, so bringe er von Turteltauben oder von jungen Tauben sein Opfer dar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Dieses soll der Priester zum Altar bringen und ihm den Kopf abkneifen und ihn auf dem Altar verbrennen; sein Blut aber soll an der Wand des Altars ausgepreßt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Den Kropf aber samt dem Unrat soll er entfernen und ihn auf den Aschenhaufen werfen, östlich vom Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Sodann soll er den Vogel an den Flügeln einreißen, sie aber nicht abtrennen, und der Priester soll ihn auf dem Altar verbrennen, auf dem Holz über dem Feuer; es ist ein Brandopfer, ein wohlriechendes Feuer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Will aber eine Seele dem HERRN ein Speisopfer bringen, so soll ihre Opfergabe aus Semmelmehl sein, und man soll Öl darüber gießen und Weihrauch darauf tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Also soll man sie zu den Söhnen Aarons, zu den Priestern bringen, und er soll davon eine Handvoll nehmen, von dem Semmelmehl und dem Öl, samt allem Weihrauch, und der Priester soll dieses Gedächtnisopfer auf dem Altar verbrennen als ein wohlriechendes Feuer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Das Übrige aber vom Speisopfer gehört Aaron und seinen Söhnen, als ein hochheiliger Anteil an den Feueropfern des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Willst du aber ein Speisopfer darbringen von dem, was im Ofen gebacken wird, so nimm ungesäuerte Semmelkuchen, mit Öl gemengt, und ungesäuerte Fladen, mit Öl gesalbt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ist aber dein Speisopfer in der Pfanne bereitet, so soll es von ungesäuertem Semmelmehl sein, mit Öl gemengt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'du sollst es in Brocken zerbrechen und Öl darauf gießen, so ist es ein Speisopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Willst du aber ein gekochtes Speisopfer darbringen, so bereite man es von Semmelmehl mit Öl;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'und du sollst das Speisopfer, das von solchem bereitet ist, zum HERRN bringen und sollst es dem Priester übergeben, der trage es zum Altar;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'und der Priester soll von dem Speisopfer abheben, was davon zum Gedächtnis bestimmt ist, und soll es auf dem Altar verbrennen zu einem wohlriechenden Feuer vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Das Übrige aber vom Speisopfer gehört Aaron und seinen Söhnen, als hochheiliger Anteil an den Feueropfern des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Kein Speisopfer, das ihr dem HERRN darbringet, soll gesäuert werden; denn ihr sollt dem HERRN weder Sauerteig noch Honig verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Als eine Erstlingsgabe mögt ihr solches dem HERRN darbringen; aber auf den Altar soll es nicht kommen zum lieblichen Geruch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Dagegen sollst du alle deine Speisopfergaben mit Salz würzen und sollst das Bundessalz deines Gottes nicht fehlen lassen in deinem Speisopfer; sondern zu allen deinen Opfergaben sollst du Salz darbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Willst du aber dem HERRN, deinem Gott, ein Erstlingsopfer darbringen, so sollst du am Feuer geröstete Ähren, geschrotete Körner als Erstlingsspeisopfer bringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'und sollst Öl darauf tun und Weihrauch darauf legen, so ist es ein Speisopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Und der Priester soll, was davon zum Gedächtnis bestimmt ist, verbrennen, von der Grütze und vom Öl, dazu allen Weihrauch, daß es ein Feuer sei für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Ist aber seine Gabe ein Dankopfer, und bringt er es von den Rindern dar, es sei ein Ochs oder eine Kuh, so soll er ein tadelloses Tier herbringen vor den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Und er soll seine Hand stützen auf seines Opfers Haupt und es schächten vor der Tür der Stiftshütte, und Aarons Söhne, die Priester, sollen sein Blut ringsum an den Altar sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Dann soll er von dem Dankopfer zur Verbrennung für den HERRN das Fett herzubringen, welches das Eingeweide bedeckt, auch alles Fett, das am Eingeweide hängt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'dazu die beiden Nieren samt dem Fett daran, das an den Lenden ist, und was über die Leber hervorragt; oberhalb der Nieren soll er es wegnehmen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Und Aarons Söhne sollen es verbrennen auf dem Altar, über dem Brandopfer, auf dem Holz, das über dem Feuer liegt, als ein wohlriechendes Feuer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Besteht aber seine Gabe, die er dem HERRN zum Dankopfer darbringt, in Kleinvieh, es sei ein Männchen oder Weibchen, so soll es tadellos sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Bringt er ein Lamm zum Opfer dar, so bringe er es vor den HERRN');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'und stütze seine Hand auf des Opfers Haupt und schächte es vor der Stiftshütte; die Söhne Aarons aber sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Darnach bringe er von dem Dankopfer das Fett dem HERRN zur Verbrennung dar, dazu das Fett, welches das Eingeweide bedeckt, samt allem Fett an den Eingeweiden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'auch die beiden Nieren mit dem Fett daran, das an den Lenden ist, samt dem, was über die Leber hervorragt; oberhalb der Nieren soll er es wegnehmen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'und der Priester soll es auf dem Altar verbrennen als Nahrung für das Feuer des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Besteht aber sein Opfer in einer Ziege, so bringe er sie vor den HERRN');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'und stütze seine Hand auf ihr Haupt und schächte sie vor der Stiftshütte; die Söhne Aarons aber sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Darnach bringe er sein Opfer dar zur Verbrennung für den HERRN, nämlich das Fett, welches das Eingeweide bedeckt, samt allem Fett, das am Eingeweide hängt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'dazu die beiden Nieren mit dem Fett daran, das an den Lenden ist, samt dem, was über die Leber hervorragt; oberhalb der Nieren soll er es wegnehmen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Das soll der Priester auf dem Altar verbrennen als Nahrung für das Feuer, zum lieblichen Geruch. Alles Fett gehört dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Das ist eine ewige Satzung für eure Geschlechter an allen euren Wohnorten, daß ihr weder Fett noch Blut essen sollt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Sage zu den Kindern Israel und sprich: Wenn sich eine Seele aus Versehen versündigt gegen irgend eines der Gebote des HERRN, also daß sie etwas von dem tut, was man nicht tun soll, so gelte folgende Vorschrift:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Wenn der gesalbte Priester sündigt, sodaß er sich am Volk verschuldet, so soll er für seine Sünde, die er begangen hat, einen jungen, tadellosen Farren dem HERRN zum Sündopfer darbringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'und zwar soll er den Farren zur Tür der Stiftshütte bringen, vor den HERRN, und seine Hand stützen auf des Farren Haupt und ihn schächten vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Und der gesalbte Priester soll von dem Blut des Farren nehmen und es in die Stiftshütte bringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'und der Priester soll seinen Finger in das Blut tauchen und von dem Blut siebenmal an die Vorderseite des Vorhangs im Heiligtum sprengen, vor dem Angesicht des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Auch soll der Priester von dem Blut auf die Hörner des wohlriechenden Räucheraltars tun, der in der Stitshütte ist vor dem HERRN; alles übrige Blut des Farren aber soll er an den Fuß des Brandopferaltars gießen, der vor der Tür der Stiftshütte ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Und alles Fett des Sündopferfarren soll er von ihm ablösen, das Fett, welches das Eingeweide bedeckt, und alles Fett, das am Eingeweide hängt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'dazu die beiden Nieren, samt dem Fett daran, das an den Lenden ist, auch das, was über die Leber hervorragt; oberhalb der Nieren soll er es wegnehmen, gleich wie man es von dem Stier des Dankopfers abhebt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'und der Priester soll es auf dem Brandopferaltar verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Aber das Fell des Farren und all sein Fleisch samt seinem Kopf, seinen Schenkeln, seinen Eingeweiden und seinem Mist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'kurz den ganzen Farren soll man hinaus vor das Lager führen, an einen reinen Ort, wohin man die Asche zu schütten pflegt, und ihn bei einem Holzfeuer verbrennen; am Aschenplatz soll er verbrannt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Wenn sich aber die ganze Gemeinde Israel vergeht, und es ist vor den Augen der Versammlung verborgen, daß sie etwas getan, davon der HERR geboten hat, daß man es nicht tun soll, sodaß sie sich verschuldet hat;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'sie kommt aber zur Erkenntnis der Sünde, die sie begangen hat wider dasselbe Gebot, so soll die Versammlung einen jungen Farren darbringen und ihn vor die Stiftshütte führen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Dann sollen die Ältesten der Gemeinde ihre Hände auf des Farren Haupt stützen vor dem HERRN, und man soll den Farren schächten vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Der gesalbte Priester aber soll von dem Blut des Farren in die Stiftshütte bringen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'und der Priester soll seinen Finger in das Blut tauchen und davon siebenmal an die Vorderseite des Vorhangs sprengen vor dem HERRN;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'und er soll von dem Blut auf die Hörner des Altars tun, der vor dem HERRN in der Stiftshütte steht; alles übrige Blut aber soll er an den Fuß des Brandopferaltars gießen, der vor der Tür der Stiftshütte steht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Aber all sein Fett soll er von ihm ablösen und es auf dem Altar verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Er soll diesen Farren behandeln, wie er den Farren des Sündopfers behandelt hat; ganz gleich soll auch dieser behandelt werden, und der Priester soll sie versühnen, und es soll ihr vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Und man soll den Farren hinaus vor das Lager schaffen und ihn verbrennen, wie man den ersten Farren verbrannt hat. Er ist ein Sündopfer der Gemeinde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Kommt es aber vor, daß ein Fürst sündigt und aus Versehen irgend etwas tut, wovon der HERR, sein Gott, geboten, daß man es nicht tun soll, und sich also verschuldet,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'man hält ihm aber seine Sünde vor, die er daran begangen hat, so soll er einen tadellosen Ziegenbock zum Opfer bringen');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'und soll seine Hand auf des Bockes Haupt stützen und ihn schächten an dem Ort, da man das Brandopfer zu schächten pflegt vor dem HERRN; es ist ein Sündopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Und der Priester soll mit seinem Finger von dem Blut des Sündopfers nehmen und es auf die Hörner des Brandopferaltars tun; das übrige Blut aber soll er an den Fuß des Brandopferaltars gießen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'und all sein Fett soll er auf dem Altar verbrennen, gleich dem Fett des Dankopfers. Also soll der Priester ihm Sühne erwirken für seine Sünde, und es wird ihm vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Wenn aber jemand vom Landvolk aus Versehen sündigt, indem er etwas tut, davon der HERR geboten hat, daß man es nicht tun soll, und sich verschuldet,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'man hält ihm aber seine Sünde vor, die er begangen hat, so soll er eine tadellose Ziege zum Opfer bringen für seine Sünde, die er begangen hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'und er soll seine Hand auf des Sündopfers Haupt stützen und das Sündopfer schächten an der Stätte des Brandopfers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Der Priester aber soll mit seinem Finger von dem Blut der Ziege nehmen und es auf die Hörner des Brandopferaltars tun und alles übrige Blut an den Fuß des Brandopferaltars gießen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Alles Fett aber soll er von ihr nehmen, wie das Fett von dem Dankopfer genommen wird, und der Priester soll es auf dem Altar verbrennen zum lieblichen Geruch dem HERRN. Also soll der Priester für ihn Sühne erwirken, und es wird ihm vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Will er aber ein Lamm darbringen zum Sündopfer, so soll es ein tadelloses Weibchen sein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'und er soll seine Hand stützen auf des Sündopfers Haupt und es schächten als Sündopfer an dem Ort, wo man das Brandopfer zu schächten pflegt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Und der Priester soll mit seinem Finger von dem Blut des Sündopfers nehmen und es auf die Hörner des Brandopferaltars tun, alles übrige Blut aber an den Fuß des Altars gießen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Und er soll alles Fett davon nehmen, wie das Fett von dem Lamm des Dankopfers genommen wird, und der Priester soll es auf dem Altar verbrennen, über den Feuerflammen des HERRN, und also soll er ihm Sühne erwirken wegen seiner Sünde, die er begangen hat, so wird ihm vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Wenn eine Seele dadurch sündigt, daß sie etwas nicht anzeigt, wiewohl sie die Beschwörung vernommen hat und Zeuge ist, daß sie es entweder gesehen oder erfahren hat, so daß sie nun ihre Missetat trägt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'oder wenn eine Seele irgend etwas Unreines anrührt, sei es das Aas eines unreinen Wildes oder das Aas eines unreinen Viehs oder das Aas eines unreinen Reptils, und es ist ihr verborgen gewesen, sie fühlt sich nun aber unrein und schuldig;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'oder wenn jemand menschliche Unreinheit anrührt, irgend etwas von alledem, womit man sich verunreinigen kann, und es ist ihm verborgen gewesen, er hat es aber nun erkannt und fühlt sich schuldig;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'oder wenn eine Seele leichtfertig mit ihren Lippen schwört, Gutes oder Böses tun zu wollen, irgend etwas von dem, was so ein Mensch leichtfertig schwören mag, und es war ihm verborgen, er erkennt es aber nun und fühlt sich einer dieser Sachen schuldig');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'ist er nun wirklich in einem dieser Punkte schuldig, so bekenne er, woran er sich versündigt hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'und bringe dem HERRN als Schuldopfer für seine Sünde, die er begangen hat, ein Weibchen vom Kleinvieh, ein Lamm oder eine Ziege zum Sündopfer, und der Priester soll ihm damit Sühne erwirken wegen seiner Sünde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Kann er aber nicht soviel zusammenbringen, daß es zu einem Schäflein langt, so bringe er dem HERRN zu seinem Schuldopfer, das er schuldig ist, zwei Turteltauben oder zwei junge Tauben, eine zum Schuldopfer, die andere zum Brandopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Er soll sie zum Priester bringen; dieser aber soll zuerst die zum Sündopfer bestimmte darbringen und ihr unterhalb des Genicks den Kopf abkneifen, ihn aber nicht abtrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Und vom Blut des Sündopfers sprenge er an die Wand des Altars, das übrige Blut aber soll an den Fuß des Altars ausgepreßt werden, weil es ein Sündopfer ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Aus der andern aber soll er ein Brandopfer machen, wie es verordnet ist. Also soll der Priester für ihn Sühne erwirken wegen seiner Sünde, die er begangen hat, so wird ihm vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Vermag er aber auch die zwei Turteltauben oder die zwei jungen Tauben nicht, so bringe er zu seinem Opfer, das er schuldig ist, ein Zehntel Epha Semmelmehl als Sündopfer. Er soll aber weder Öl daran tun, noch Weihrauch darauf legen, weil es ein Sündopfer ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Er soll es zum Priester bringen, und der Priester nehme eine Handvoll davon, soviel als zum Gedächtnis bestimmt ist, und verbrenne es auf dem Altar über dem Feuer des HERRN. Es ist ein Sündopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Also soll ihm der Priester Sühne erwirken wegen seiner Sünde, die er begangen hat in einem jener Fälle, so wird ihm vergeben werden. Das Opfer aber soll dem Priester gehören wie das Speisopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Wenn sich eine Seele aus Versehen vergreift und versündigt an heiligen Dingen des HERRN, so soll sie dem HERRN ihr Schuldopfer bringen, nämlich einen tadellosen Widder von der Herde, nach deiner Schätzung im Wert von zwei Schekeln, nach dem Schekel des Heiligtums, zum Schuldopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Den Schaden aber, den er dem Heiligtum zugefügt hat, soll er vergüten und einen Fünftel dazufügen und es dem Priester geben; der soll für ihn Sühne erwirken mit dem Widder des Schuldopfers, so wird ihm vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Und wenn eine Seele sündigt und irgend etwas von alledem tut, was der HERR verboten hat und man nicht tun soll, hat es aber nicht gewußt und fühlt sich nun schuldig und trägt ihre Missetat;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'so soll der Betreffende dem Priester einen tadellosen Widder von seiner Herde nach deiner eigenen Schätzung zum Schuldopfer bringen, und der Priester soll ihm Sühne erwirken wegen seines Versehens, das er unwissentlich begangen hat; so wird ihm vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Es ist ein Schuldopfer, das er dem HERRN schuldig ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, 'Wenn sich jemand dadurch versündigt und vergreift am HERRN, daß er seinem Volksgenossen etwas Anvertrautes oder Hinterlegtes ableugnet oder gewalttätigerweise raubt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'oder wenn er etwas Verlorenes gefunden hat und es ableugnet und schwört einen falschen Eid wegen irgend etwas von alledem, womit sich ein Mensch versündigen mag;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'wenn er nun, nachdem er also gesündigt hat, sich schuldig fühlt, so soll er den Raub, den er genommen hat, oder das erpreßte Gut, das er sich gewalttätigerweise angeeignet hat, oder das anvertraute Gut, das ihm anvertraut worden, oder das Verlorene, das er gefunden hat, wiedergeben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'auch alles, worüber er einen falschen Eid geschworen hat, soll er nach seinem vollen Wert zurückerstatten und noch einen Fünftel dazulegen; und zwar soll er es dem geben, dem es gehört, an dem Tage, da er sein Schuldopfer entrichtet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Sein Schuldopfer aber soll er dem HERRN bringen, einen tadellosen Widder von der Herde nach deiner Schätzung als Schuldopfer, zum Priester.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'Und der Priester soll ihm Sühne erwirken vor dem HERRN, so wird ihm vergeben werden, was irgend er getan hat von alledem, womit man sich verschulden kann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Und der HERR redete zu Mose und sprach: Gebiete Aaron und seinen Söhnen und sprich:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Dies ist das Gesetz vom Brandopfer: Das Brandopfer soll auf seiner Glut auf dem Altar die ganze Nacht bis zum Morgen verbleiben, daß das Feuer des Altars dadurch genährt werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Und der Priester soll ein leinenes Kleid anziehen und sein Fleisch in die leinenen Beinkleider hüllen und soll die Asche abheben, nachdem das Feuer auf dem Altar das Brandopfer verzehrt hat, und sie neben den Altar tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Dann lege er seine Kleider ab und ziehe andere Kleider an und schaffe die Asche hinaus vor das Lager an einen reinen Ort.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Aber das Feuer auf dem Altar soll auf demselben brennend erhalten werden; es soll nicht erlöschen; darum soll der Priester alle Morgen Holz darauf anzünden und das Brandopfer darauf zurichten und das Fett der Dankopfer darauf verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Ein beständiges Feuer soll auf dem Altar brennen; es soll nie erlöschen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Und dies ist das Gesetz vom Speisopfer: Die Söhne Aarons sollen es vor dem HERRN darbringen, vor dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Und dann hebe einer davon eine Handvoll ab, von dem Semmelmehl des Speisopfers und von seinem Öl, auch allen Weihrauch, der auf dem Speisopfer ist, und verbrenne also, was davon zum Gedächtnis bestimmt ist, auf dem Altar zum lieblichen Geruch dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Das Übrige aber sollen Aaron und seine Söhne essen; ungesäuert soll es gegessen werden an einem heiligen Ort; im Vorhof der Stiftshütte sollen sie es essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Es soll ungesäuert gebacken werden. Ich habe es ihnen gegeben als ihren Anteil an meinen Feueropfern; es ist hochheilig wie das Sündopfer und wie das Schuldopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Alles, was männlich ist unter Aarons Nachkommen, darf davon essen; es ist ein auf ewig festgesetzter Anteil an den Feueropfern des HERRN für alle eure Geschlechter. Jeder, der es anrührt, soll heilig sein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Dies ist die Opfergabe Aarons und seiner Söhne, welche sie dem HERRN darbringen sollen am Tage seiner Salbung. Ein Zehntel Epha Semmelmehl als beständiges Speisopfer, die eine Hälfte am Morgen, die andere am Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Es soll in der Pfanne mit Öl angemacht werden, durcheinandergerührt soll man es darbringen, in Kuchenform, in Bissen zerlegt soll man das Speisopfer darbringen zum lieblichen Geruch dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Und zwar soll es der Priester, der an Aarons Statt aus seinen Söhnen gesalbt wird, bereiten, dem HERRN zum ewigen Recht; es soll gänzlich verbrannt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Jedes Speisopfer eines Priesters soll ganz verbrannt werden; es darf nicht gegessen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Sage zu Aaron und zu seinen Söhnen und sprich: Dies ist das Gesetz vom Sündopfer: Am gleichen Ort, da man das Brandopfer schächtet, soll auch das Sündopfer geschächtet werden vor dem HERRN, weil es hochheilig ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Der Priester, der das Sündopfer darbringt, darf es essen; es soll aber an heiliger Stätte gegessen werden, im Vorhof der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Jeder, der sein Fleisch anrührt, soll heilig sein! Wenn aber etwas von seinem Blut auf ein Kleid spritzt, so sollst du das, was bespritzt worden ist, an heiliger Stätte waschen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Ist es in einem irdenen Geschirr gekocht worden, so soll man dasselbe zerbrechen, wenn aber in einem ehernen, so muß es gescheuert und mit Wasser gespült werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Alles, was männlich ist unter den Priestern, darf davon essen; es ist hochheilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Dagegen soll man kein Sündopfer essen, von dessen Blut in die Stiftshütte hineingebracht wird, um Sühne zu erwirken im Heiligtum; es soll mit Feuer verbrannt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Und dies ist das Gesetz vom Schuldopfer, welches hochheilig ist:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Am gleichen Ort, wo man das Brandopfer schächtet, soll man auch das Schuldopfer schächten und sein Blut ringsum an den Altar sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Auch soll man von ihm all sein Fett darbringen, den Fettschwanz samt dem Fett, welches die Eingeweide bedeckt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'dazu die beiden Nieren mit dem Fett daran, das an den Lenden ist, samt dem, was über die Leber hervorragt; über den Nieren soll man es wegnehmen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Und der Priester soll es auf dem Altar verbrennen, daß solches Schuldopfer zu einem Feuer werde für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alles, was männlich ist unter den Priestern, darf es essen; es soll aber an heiliger Stätte gegessen werden, weil es hochheilig ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie das Sündopfer, so das Schuldopfer; für beide gilt ein und dasselbe Gesetz: Es gehört dem Priester, der die Sühne damit vollzieht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Dem Priester, der jemandes Brandopfer darbringt, gehört auch das Fell des Brandopfers, welches er dargebracht hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Desgleichen alle Speisopfer, die im Ofen gebacken, im Topf gekocht oder auf der Pfanne bereitet werden, fallen dem Priester zu, der sie darbringt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Alle Speisopfer, seien sie nun mit Öl vermengt oder trocken, gehören allen Söhnen Aarons, einem wie dem andern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und dies ist das Gesetz des Dankopfers, das man dem HERRN darbringen soll:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Will er es zum Lobe opfern, so bringe er zu seinem Lob-Schlachtopfer hinzu ungesäuerte Kuchen dar, mit Öl gemengt, und ungesäuerte Fladen, mit Öl bestrichen, und eingerührtes Semmelmehl, mit Öl gemengte Kuchen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Auf einem gesäuerten Brotkuchen soll er seine Opfergabe darbringen, zum Schlachtopfer seines Lob und Dankopfers hinzu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Von allen Opfergaben aber soll er dem HERRN je ein Stück als Hebe darbringen; das soll dem Priester gehören, der das Blut der Dankopfer sprengt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Es soll aber das Fleisch des Lob und Dankopfers am Tage seiner Darbringung gegessen werden; man darf nichts davon übriglassen bis zum Morgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Beruht aber das Opfer, das er darbringt, auf einem Gelübde, oder ist es freiwillig, so soll es am Tage seiner Darbringung gegessen werden und am folgenden Tag, so daß, was davon übrigbleibt, gegessen werden darf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Was aber vom Opferfleisch bis zum dritten Tag übrigbleibt, das soll man mit Feuer verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Sollte aber trotzdem am dritten Tage von dem Fleisch seines Dankopfers gegessen werden, so würde der, welcher es dargebracht hat, nicht angenehm sein; es würde ihm nicht zugerechnet, sondern für verdorben gelten, und die Seele, die davon äße, müßte ihre Schuld tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Auch wenn das Fleisch mit irgend etwas Unreinem in Berührung kommt, so darf man es nicht essen, sondern muß es mit Feuer verbrennen; sonst aber darf jedermann von diesem Fleisch essen, wenn er rein ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Eine Seele aber, die ihre Unreinigkeit an sich hat und doch von dem Fleisch des Dankopfers ißt, das dem HERRN gehört, die soll ausgerottet werden aus ihrem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Auch wenn eine Seele irgend etwas Unreines anrührt, es sei die Unreinigkeit eines Menschen oder ein unreines Vieh oder irgend ein unreines Reptil, und ißt doch von dem Fleisch des Dankopfers, das dem HERRN gehört, so soll eine solche Seele ausgerottet werden von ihrem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Sage den Kindern Israel und sprich: Ihr sollt kein Fett essen von Ochsen, Lämmern und Ziegen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Das Fett von Aas oder Zerrissenem darf zu allerlei Zwecken verwendet werden, aber essen sollt ihr es nicht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Denn wer Fett ißt von dem Vieh, von welchem man dem HERRN Feueropfer darzubringen pflegt, der soll ausgerottet werden aus seinem Volk!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ihr sollt auch kein Blut essen in allen euren Wohnungen, weder von Geflügel noch vom Vieh;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'jede Seele, die irgendwelches Blut ißt, soll ausgerottet werden aus ihrem Volk!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Sage zu den Kindern Israel und sprich: Wer dem HERRN ein Dankopfer darbringen will, der lasse dem HERRN seine Gabe zukommen von seinem Dankopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Eigenhändig soll er herzubringen, was dem HERRN verbrannt werden soll: Das Fett samt dem Kern stück der Brust soll er bringen, den Brustkern, um ihn als Webopfer vor dem HERRN zu weben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Der Priester aber soll das Fett auf dem Altar verbrennen; und der Brustkern fällt Aaron und seinen Söhnen zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Dazu sollt ihr die rechte Keule von euren Dankopfern dem Priester als Hebe geben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'und zwar soll derjenige von Aarons Söhnen, der das Blut der Dankopfer und das Fett darbringt, die rechte Keule zum Anteil erhalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Denn ich habe die Webebrust und die Hebekeule von den Kindern Israel, von ihren Dankopfern genommen und habe sie dem Priester Aaron und seinen Söhnen gegeben zum ewigen Anrecht, das sie zu beanspruchen haben von den Kindern Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Das ist das Salbungsgeschenk, welches Aaron und seinen Söhnen gemacht wurde von den Feueropfern des HERRN an dem Tage, da er sie herzunahen ließ, dem HERRN Priesterdienst zu tun,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'davon der HERR am Tage ihrer Salbung befahl, daß es ihnen gegeben werde von den Kindern Israel als ewiges Recht in ihren Geschlechtern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Dies ist das Gesetz vom Brandopfer, vom Speisopfer, vom Sündopfer, vom Schuldopfer, vom Einweihungsopfer und vom Dankopfer,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'welches der HERR Mose auf dem Berge Sinai gegeben hat, des Tages, da er den Kindern Israel befahl, dem HERRN ihre Opfer darzubringen, in der Wüste Sinai.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Nimm Aaron und seine Söhne mit ihm, dazu die Kleider und das Salböl und einen Farren zum Sündopfer, zwei Widder und einen Korb mit ungesäuertem Brot,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'und versammle die ganze Gemeinde vor der Tür der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mose tat, wie ihm der HERR befahl, und versammelte die Gemeinde vor der Tür der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Und Mose sprach zu der Gemeinde: Das ist\'s, was der HERR zu tun geboten hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Und Mose brachte Aaron und seine Söhne herzu und wusch sie mit Wasser.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Und er legte ihm den Leibrock an und gürtete ihn mit dem Gürtel des Ephod und befestigte es damit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Darnach legte er ihm das Brustschildlein an und tat in das Brustschildlein das Licht und das Recht;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'und er setzte ihm den Hut auf das Haupt und heftete an den Hut, vorn an seine Stirne, das goldene Stirnblatt, das heilige Diadem, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Und Mose nahm das Salböl und salbte die Wohnung und alles, was darin war, und weihte es.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Auch sprengte er davon siebenmal auf den Altar und salbte den Altar samt allen seinen Geräten, auch das Becken samt seinem Fuß, um es zu weihen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Und er goß von dem Salböl auf das Haupt Aarons und salbte ihn, um ihn zu weihen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Er brachte auch die Söhne Aarons herzu und zog ihnen Leibröcke an und gürtete sie mit dem Gürtel und band ihnen hohe Mützen auf, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Und ließ einen Farren herzuführen zum Sündopfer; und Aaron und seine Söhne stützten ihre Hände auf den Kopf des Farren, des Sündopfers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Und Mose schächtete ihn und nahm das Blut und tat es mit seinem Finger auf die Hörner des Altars ringsum; also entsündigte er den Altar und goß das übrige Blut an den Grund des Altars und weihte ihn, indem er ihm Sühne erwirkte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Sodann nahm er alles Fett am Eingeweide und was über die Leber hervorragt und die beiden Nieren mit dem Fett daran, und Mose verbrannte es auf dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Aber den Farren samt seinem Fell und seinem Fleisch und Mist verbrannte er mit Feuer außerhalb des Lagers, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Er brachte auch den Widder herzu zum Brandopfer. Und Aaron und seine Söhne stützten ihre Hände auf des Widders Kopf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Und Mose schächtete ihn und sprengte das Blut ringsrum an den Altar');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'und zerlegte den Widder in seine Stücke, und Mose verbrannte den Kopf, die Stücke und das Fett,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'und wusch die Eingeweide und die Schenkel mit Wasser; also verbrannte Mose den ganzen Widder auf dem Altar. Das war ein Brandopfer zum lieblichen Geruch, ein Feueropfer dem HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Er brachte auch den andern Widder herzu, den Widder des Einweihungsopfers. Und Aaron und seine Söhne stützten ihre Hände auf des Widders Kopf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Mose aber schächtete ihn und nahm von seinem Blut, und tat es Aaron auf sein rechtes Ohrläpplein und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'und er brachte auch Aarons Söhne herzu und tat von dem Blut auf ihr rechtes Ohrläpplein und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes und sprengte das Blut ringsum an den Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Und er nahm das Fett und den Fettschwanz und alles Fett am Eingeweide und was über die Leber hervorragt und die beiden Nieren mit dem Fett daran und die rechte Keule;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'dazu nahm er aus dem Korbe mit dem ungesäuerten Brot vor dem HERRN einen ungesäuerten Kuchen und einen Brotkuchen mit Öl und einen Fladen und legte es auf die Fettstücke und auf die rechte Keule,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'und legte das alles auf die Hände Aarons und auf die Hände seiner Söhne und webte es zum Webopfer vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Darnach nahm Mose das alles wieder von ihren Händen und verbrannte es auf dem Altar über dem Brandopfer. Das war das Einweihungsopfer zum lieblichen Geruch, ein Feueropfer dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Und Mose nahm die Brust und webte sie zum Webopfer vor dem HERRN; das war Moses Anteil von dem Widder des Einweihungsopfers, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Und Mose nahm von dem Salböl und von dem Blut auf dem Altar und sprengte es auf Aaron und seine Kleider, auf seine Söhne und ihre Kleider und weihte also Aaron und seine Kleider und mit ihm seine Söhne und seiner Söhne Kleider.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Und Mose sprach zu Aaron und zu seinen Söhnen: Kocht das Fleisch vor der Tür der Stiftshütte und esset es daselbst, wie ich geboten und gesagt habe: Aaron und seine Söhne sollen es essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Was aber vom Fleisch und Brot übrigbleibt, das sollt ihr mit Feuer verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Und ihr sollt sieben Tage lang nicht hinausgehen vor die Tür der Stiftshütte, bis an den Tag, an welchem die Tage eures Weihopfers erfüllt sind; denn sieben Tage lang soll man euch die Hände füllen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Was man heute getan hat, das hat der HERR zu tun befohlen, um für euch Sühne zu erwirken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Sieben Tage lang sollt ihr Tag und Nacht an der Tür der Stiftshütte bleiben und die Anordnungen des HERRN befolgen, daß ihr nicht sterbet; denn also ist es mir geboten worden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Und Aaron und seine Söhne taten alles, was der HERR durch Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Und am achten Tage rief Mose den Aaron und seine Söhne und die Ältesten von Israel und sprach zu Aaron:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Nimm dir ein Stierkalb zum Sündopfer und einen Widder zum Brandopfer, beide tadellos, und bringe sie vor den HERRN');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'und sage zu den Kindern Israel und sprich: Nehmt einen Ziegenbock zum Sündopfer und ein Kalb und ein Schaf, beide ein Jahr alt und tadellos, zum Brandopfer,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'ferner einen Ochsen und einen Widder zum Dankopfer, vor dem HERRN zu opfern, und ein mit Öl gemengtes Speisopfer; denn heute wird euch der HERR erscheinen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Und sie brachten, was Mose geboten hatte, vor die Tür der Stiftshütte, und die ganze Gemeinde trat herzu und stand vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Da sprach Mose: Was der HERR geboten hat, das sollt ihr tun, so wird euch die Herrlichkeit des HERRN erscheinen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Und Mose sprach zu Aaron: Tritt zum Altar und verrichte dein Sündopfer und dein Brandopfer und erwirke Sühne für dich und das Volk. Darnach bringe das Opfer des Volkes dar und erwirke Sühnung für sie, wie der HERR geboten hat!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Da trat Aaron zum Altar und schächtete das Kalb zum Sündopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Und die Söhne Aarons brachten das Blut zu ihm, und er tauchte seinen Finger in das Blut und tat es auf die Hörner des Altars und goß das übrige Blut an den Grund des Altars.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Aber das Fett und die Nieren und was von der Leber des Sündopfers hervorragt, verbrannte er auf dem Altar, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Und das Fleisch und das Fell verbrannte er mit Feuer außerhalb des Lagers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Darnach schächtete er das Brandopfer, und die Söhne Aarons brachten das Blut zu ihm, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Und sie brachten das Brandopfer, in seine Stücke zerlegt, samt dem Kopf, zu ihm, und er verbrannte es auf dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Und er wusch die Eingeweide und die Schenkel und verbrannte es über dem Brandopfer auf dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Darnach brachte er das Opfer des Volkes herzu und nahm den Bock, das Sündopfer des Volkes, und schächtete ihn und machte ein Sündopfer daraus, wie das vorige.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Darnach brachte er das Brandopfer herzu und verrichtete es nach Vorschrift.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Er brachte auch das Speisopfer herzu und nahm eine Handvoll davon und verbrannte es auf dem Altar, außer dem Brandopfer des Morgens.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Darnach schächtete er den Ochsen und den Widder zum Dankopfer des Volks. Und die Söhne Aarons brachten ihm das Blut; das sprengte er ringsum an den Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Aber die Fettstücke vom Ochsen und vom Widder, den Fettschwanz und das Fett, welches die Eingeweide bedeckt, und die Nieren und was über die Leber hervorragt,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'alle diese Fettstücke legten sie auf die Brust; und er verbrannte die Fettstücke auf dem Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Aber die Brust und die rechte Schulter webte Aaron zum Webopfer vor dem HERRN, wie Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Darnach streckte Aaron seine Hand aus gegen das Volk und segnete es und stieg herab, nachdem er das Sündopfer, das Brandopfer und das Dankopfer dargebracht hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Und Mose und Aaron gingen in die Stiftshütte hinein. Und als sie wieder herauskamen, segneten sie das Volk. Da erschien die Herrlichkeit des HERRN allem Volk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'und es ging Feuer aus von dem HERRN und verzehrte das Brandopfer und die Fettstücke auf dem Altar. Als alles Volk solches sah, jubelten sie und fielen auf ihre Angesichter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Aber die Söhne Aarons, Nadab und Abihu, nahmen ein jeder seine Räucherpfanne und taten Feuer hinein und legten Räucherwerk darauf und brachten fremdes Feuer vor den HERRN, das er ihnen nicht geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da ging Feuer aus von dem HERRN und verzehrte sie, daß sie starben vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sprach Mose zu Aaron: Das hat der HERR gemeint, als er sprach: Ich will geheiligt werden durch die, welche zu mir nahen, und geehrt werden vor allem Volk! Und Aaron schwieg still.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mose aber rief Misael und Elzaphan, die Söhne Ussiels, des Oheims Aarons, und sprach zu ihnen: Tretet herzu und traget eure Brüder vom Heiligtum hinweg, vor das Lager hinaus!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Und sie traten herzu und trugen sie in ihren Leibröcken vor das Lager hinaus, wie Mose befohlen hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Da sprach Mose zu Aaron und seinen Söhnen Eleasar und Itamar: Ihr sollt eure Häupter nicht entblößen, noch eure Kleider zerreißen, damit ihr nicht sterbet und der Zorn über die ganze Gemeinde komme. Lasset eure Brüder, das ganze Haus Israel, weinen über diesen Brand, den der HERR angezündet hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ihr aber sollt nicht vor die Tür der Stiftshütte hinausgehen, auf daß ihr nicht sterbet; denn das Salböl des HERRN ist auf euch! Und sie taten, wie Mose sagte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'DER HERR aber redete mit Aaron und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Du und deine Söhne mit dir sollen keinen Wein noch starkes Getränk trinken, wenn ihr in die Stiftshütte geht, damit ihr nicht sterbet. Das sei eine ewige Ordnung für eure Geschlechter,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'damit ihr unterscheiden könnet zwischen heilig und gemein, zwischen unrein und rein,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'und damit ihr die Kinder Israel alle Rechte lehret, die der HERR zu ihnen durch Mose geredet hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Mose redete mit Aaron und mit seinen übrigen Söhnen, Eleasar und Itamar: Nehmt das Speisopfer, das von den Feueropfern des HERRN übrigbleibt, und esset es ungesäuert beim Altar, denn es ist hochheilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Ihr sollt es essen an heiliger Stätte; denn es ist das, was dir und deinen Söhnen bestimmt ist von den Feueropfern des HERRN; denn also ist es mir geboten worden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Desgleichen die Webebrust und die Hebeschulter sollst du und deine Söhne und deine Töchter mit dir an reiner Stätte essen. Denn solches ist dir und deinen Kindern bestimmt von den Dankopfern der Kinder Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Die Hebekeule und die Webebrust soll man mit den Feueropfern der Fettstücke herzubringen, daß man sie webe zum Webopfer vor dem HERRN. Solches soll dir und deinen Söhnen mit dir als ein ewiges Recht zufallen, wie der HERR geboten hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Und Mose suchte den Bock des Sündopfers; und siehe, er war verbrannt. Da ward er zornig über Eleasar und Itamar, die Söhne Aarons, die noch übrig waren, und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Warum habt ihr das Sündopfer nicht gegessen an heiliger Stätte? Denn es ist hochheilig, und er hat es euch gegeben, daß ihr die Missetat der Gemeinde traget, um für sie Sühne zu erwirken vor dem HERRN!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Siehe, sein Blut ist nicht in das Innere des Heiligtums hineingekommen; ihr hättet ihn im Heiligtum essen sollen, wie ich geboten habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Aaron aber sprach zu Mose: Siehe, heute haben sie ihr Sündopfer vor dem HERRN geopfert, und es ist mir solches widerfahren; sollte ich heute vom Sündopfer essen? Wäre es auch wohl getan in den Augen des HERRN?');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Als Mose solches hörte, war es wohlgefällig in seinen Augen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Und der HERR redete zu Mose und Aaron und sprach zu ihnen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Redet mit den Kindern Israel und sprechet: Das sind die Tiere, die ihr von allem Vieh auf Erden essen dürft:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alle Vielhufer, die ganz gespaltene Klauen haben und wiederkäuen, dürft ihr essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Aber von den Wiederkäuern und Vielhufern sollt ihr die folgenden nicht essen: das Kamel; denn obschon es wiederkäut, hat es doch keine gespaltenen Klauen; darum soll es euch unrein sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Desgleichen der Klippdachs; denn obschon er wiederkäut, hat er doch keine gespaltenen Klauen; darum ist er euch unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Auch der Hase, der zwar wiederkäut, aber er hat keine gespaltenen Klauen; darum ist er euch unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Ferner das Schwein; es ist zwar ein Vielhufer mit durchgespaltenen Klauen, aber kein Wiederkäuer; darum ist es euch unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Von ihrem Fleisch sollt ihr nicht essen, auch ihr Aas nicht anrühren, denn sie sind euch unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Folgende Tiere dürft ihr essen von allem, was in den Wassern ist: Alles, was Flossen und Schuppen hat im Wasser, im Meer und in Bächen, dürft ihr essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Aber alles, was keine Flossen und Schuppen hat, im Meer und in Bächen, unter allem Getier, das sich in den Wassern regt, und von allem, was im Wasser lebt, das soll euch ein Greuel sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ein Greuel sollen sie euch sein; von ihrem Fleisch sollt ihr nicht essen und vor ihrem Aas euch scheuen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alle Wassertiere, die keine Flossen und Schuppen haben, sollen euch ein Greuel sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Von den Vögeln aber sollt ihr folgende verabscheuen; man soll sie nicht essen, weil sie ein Greuel sind: Den Adler, den Lämmergeier und den Seeadler,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'die Weihe und das Falkengeschlecht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'die ganze Rabenfamilie,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'den Strauß, die Eule, die Möwe und die Habichtarten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'das Käuzchen, den Reiher, den Ibis,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'das Purpurhuhn, den Pelikan, den Schwan,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'den Storch, die verschiedenen Strandläufer, den Wiedehopf und die Fledermaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Jedes geflügelte Insekt, das auf vier Füßen geht, soll euch ein Greuel sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Doch dürft ihr von den geflügelten Insekten, welche auf vier Füßen gehen, diejenigen essen, welche oberhalb ihrer Füße zwei Schenkel haben, vermittelst deren sie über den Erdboden hüpfen können.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Von diesen dürft ihr essen die verschiedenen Arten der Wanderheuschrecke, der Feldheuschrecke, der Laubheuschrecke und der Fangheuschrecke.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Aber alle übrigen geflügelten Insekten mit vier Füßen sollen euch ein Greuel sein,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'und ihr würdet euch an ihnen verunreinigen; wer ihr Aas anrührt, der soll unrein sein bis zum Abend;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'wer aber eines ihrer Aase aufhebt, der soll seine Kleider waschen und bleibt unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Jeder Vielhufer, der nicht zugleich durchgespaltene Klauen hat und wiederkäut, soll euch unrein sein; wer ihn anrührt, wird unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Auch alles, was auf seinen Tatzen geht unter den Vierfüßlern, soll euch unrein sein; wer ihr Aas anrührt, wird unrein sein bis zum Abend;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'und wer ihr Aas aufhebt, der soll seine Keider waschen und bleibt unrein bis zum Abend; unrein sollen sie euch sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Auch diese sollen euch unrein sein von den Tieren, die auf der Erde kriechen: Das Wiesel, die Maus, die verschiedenen Eidechsenarten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'der Mauergeko, der Dornschwanz, der Schleuderschwanz, der Salamander und das Chamäleon.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Diese sollen euch unrein sein unter allem, was da kriecht; wer sie anrührt, wenn sie tot sind, bleibt unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Auch wird alles unrein, worauf eins von diesen Tieren fällt, wenn es tot ist, sei es ein hölzernes Gefäß oder ein Kleid, ein Fell oder ein Sack; ein Gerät aber, damit man Arbeit verrichtet, soll man ins Wasser legen, und es soll unrein bleiben bis zum Abend; dann wird es rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Fällt aber eines jener Tiere in ein irdenes Geschirr, so wird sein ganzer Inhalt unrein, und ihr müßt es zerbrechen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Kommt von dem Wasser an irgendeine Speise, die man essen will, so wird sie unrein, desgleichen jedes Getränk, das man aus einem solchen Gefäß trinken würde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Alles wird unrein, worauf ein solches Aas fällt; wäre es ein Backofen oder Kochherd, so müßte er eingerissen werden; denn er wäre unrein und müßte euch für unrein gelten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Nur ein Wassersammler, der von einer Quelle oder von einem Brunnen gespeist wird, bleibt rein; wer aber ein Aas anrührt, das hineinfällt, wird gleichwohl unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Auch wenn von solchem Aas auf irgendwelche Sämereien fällt, die man aussäen will, so bleiben sie rein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'wäre aber Wasser auf den Samen gegossen worden, und es fiele von solchem Aas darauf, so müßte er euch für unrein gelten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Stirbt ein Stück Vieh, das man sonst zu essen pflegt, so wird, wer sein Aas anrührt, unrein sein bis zum Abend;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'wer aber von seinem Aase ißt, der soll seine Kleider waschen und bleibt unrein bis zum Abend; auch wer sein Aas aufhebt, muß seine Kleider waschen und bleibt unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Alles, was auf der Erde kriecht, soll euch ein Greuel sein und darf nicht gegessen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Alles, was auf dem Bauche kriecht, samt allem, was auf vier und mehr Füßen geht von dem, was auf der Erde kriecht, das sollt ihr nicht essen, sondern es soll euch ein Greuel sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Macht eure Seelen nicht verabscheuungswürdig durch irgendein kriechendes Tier und verunreinigt euch nicht an ihnen, daß ihr durch sie verunreinigt werdet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn ich, der HERR, bin euer Gott; darum sollt ihr euch heiligen und sollt heilig sein; denn ich bin heilig; und ihr sollt eure Seelen nicht verunreinigen mit allerlei Gewürm, das auf der Erde kriecht!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn ich, der HERR, bin es, der euch aus Ägyptenland heraufgeführt hat, um euer Gott zu sein; darum sollt ihr heilig sein; denn ich bin heilig!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Dies ist das Gesetz von Vieh und Vögeln und allen lebendigen Wesen, die sich im Wasser regen und von allem Lebendigen, was auf Erden kriecht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'damit man unterscheide zwischen unrein und rein, zwischen dem, was man essen, und dem, was man nicht essen soll.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Und der HERR redete zu Mose und sprach: Sage zu den Kindern Israel und sprich:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Wenn ein Weib fruchtbar wird und ein Knäblein gebiert, so soll sie sieben Tage lang unrein sein, ebenso lange wie sie unrein ist, wenn sie unwohl wird, soll sie unrein sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Und am achten Tage soll man das Fleisch seiner Vorhaut beschneiden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Und sie soll daheim bleiben dreiunddreißig Tage lang im Blut ihrer Reinigung; sie soll nichts Heiliges anrühren und nicht kommen zum Heiligtum, bis die Tage ihrer Reinigung erfüllt sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Gebiert sie aber ein Mägdlein, so soll sie zwei Wochen lang unrein sein, wie bei ihrem Unwohlsein, und soll sechsundsechzig Tage lang daheim bleiben in dem Blut ihrer Reinigung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Und wenn die Tage ihrer Reinigung erfüllt sind für den Sohn oder für die Tochter, so soll sie dem Priester vor die Tür der Stiftshütte ein einjähriges Lamm zum Brandopfer und eine junge Taube oder eine Turteltaube zum Sündopfer bringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'der soll es vor dem HERRN opfern und für sie Sühne erwirken, so wird sie rein von ihrem Blutfluß. Das ist das Gesetz für die, welche ein Knäblein oder Mägdlein gebiert.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Vermag aber ihre Hand den Preis eines Schafes nicht, so nehme sie zwei Turteltauben oder zwei junge Tauben, eine zum Brandopfer und die andere zum Sündopfer, so soll der Priester für sie Sühne erwirken, daß sie rein werde.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Und der HERR redete zu Mose und Aaron und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Wenn sich bei einem Menschen an der Haut seines Fleisches eine Geschwulst oder ein Schorf oder ein weißer Fleck zeigt, als wollte sich ein Aussatz bilden an der Haut des Fleisches, so soll man ihn zum Priester Aaron oder zu einem seiner Söhne unter den Priestern führen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Und wenn der Priester das Mal an der Haut seines Fleisches besieht und findet, daß die Haare im Mal weiß geworden sind, und daß das Mal tieferliegend erscheint als die Haut seines Fleisches, so ist es der Aussatz; sobald der Priester das sieht, soll er ihn für unrein erklären!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Wenn aber der Fleck auf der Haut seines Fleisches weiß ist und nicht tieferliegend erscheint als die übrige Haut des Fleisches und seine Haare nicht weiß geworden sind, so soll der Priester das Mal sieben Tage lang einschließen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'und am siebenten Tag soll er es besichtigen. Ist das Mal gleich geblieben wie zuvor und hat nicht weitergefressen an der Haut, so soll es der Priester abermal sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Und wenn ihn der Priester am siebenten Tage nochmals besieht und findet, daß das Mal blässer ist und nicht weitergefressen hat an der Haut, so soll ihn der Priester für rein erklären, denn es ist ein Ausschlag; und er soll seine Kleider waschen, so ist er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Wenn aber der Ausschlag weiter um sich greift an der Haut, nachdem er vom Priester besehen worden ist zu seiner Reinigung, so soll er sich dem Priester nochmals zeigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Wenn dann der Priester sieht, daß der Ausschlag an der Haut weiter um sich gegriffen hat, so soll ihn der Priester für unrein erklären; denn es ist ein Aussatz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Zeigt sich ein Aussatzmal an einem Menschen, so soll man ihn zum Priester bringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'sieht dieser an der Haut eine weiße Geschwulst und daß die Haare weiß geworden sind und daß rohes Fleisch in der Geschwulst ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'so ist es ein alter Aussatz in der Haut seines Fleisches; darum soll ihn der Priester für unrein erklären und nicht einschließen; denn er ist schon unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Wenn aber der Aussatz an der Haut ausbricht und die ganze Haut des Betroffenen vom Kopf bis zu den Füßen bedeckt, soweit der Priester sehen kann,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'und der Priester sieht, daß der Aussatz das ganze Fleisch bedeckt, so soll er den Betroffenen für rein erklären, weil er ganz weiß geworden ist; dann ist er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Sobald sich aber rohes Fleisch an ihm zeigt, so ist er unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Und wenn der Priester das rohe Fleisch sieht, soll er ihn für unrein erklären; denn das rohe Fleisch ist unrein; es ist der Aussatz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Verwandelt sich aber das rohe Fleisch wieder und wird weiß, so soll er zum Priester kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Und wenn der Priester bei der Besichtigung findet, daß das Mal weiß geworden ist, so soll er den Betroffenen für rein erklären, denn er ist rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Wenn in jemandes Fleisch an der Haut ein Geschwür entsteht und wieder heilt,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'es bildet sich aber an der Stelle des Geschwürs eine weiße Geschwulst oder ein weiß-rötlicher Fleck, so soll er sich dem Priester zeigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Sieht aber der Priester, daß es tieferliegend erscheint als die übrige Haut und daß das Haar weiß geworden ist, so soll er ihn für unrein erklären; denn es ist ein Aussatzmal in dem Geschwür ausgebrochen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Sieht aber der Priester, daß die Haare nicht weiß sind, und daß es nicht tieferliegend ist als die übrige Haut, sondern blässer, so soll er ihn sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Greift es weiter um sich an der Haut, so soll er ihn für unrein erklären; denn es ist ein Aussatzmal.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Bleibt aber der weiße Fleck stehen und frißt nicht weiter, so ist es die Narbe des Geschwürs, und der Priester soll ihn für rein erklären.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Wenn jemandes Fleisch an der Haut eine Brandwunde erhält, und es bildet sich in der Brandwunde ein weißrötlicher oder weißer Fleck;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und wenn der Priester es besieht und findet, daß das Haar weiß geworden ist an dem Fleck und daß er tieferliegend erscheint als die übrige Haut, so ist ein Aussatz in der Brandwunde entstanden; darum soll ihn der Priester für unrein erklären; denn es ist ein Aussatzmal.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Sieht aber der Priester, daß die Haare an dem Fleck nicht weiß geworden sind und daß er nicht tieferliegend ist als die übrige Haut, so soll er ihn sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Und am siebenten Tage soll er ihn besichten; hat es weitergefressen an der Haut, so soll er ihn für unrein erklären; denn es ist ein Aussatzmal.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Ist aber der Fleck stehengeblieben und hat nicht weitergefressen an der Haut, so ist es eine Geschwulst des Brandmals, und der Priester soll ihn für rein erklären; denn es ist die Narbe des Brandmals.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Wenn ein Mann oder ein Weib auf dem Haupt oder am Bart ein Mal hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester das Mal besieht und findet, daß es tieferliegend erscheint als die übrige Haut, und das Haar daselbst goldgelb und dünn ist, so soll er ihn für unrein erklären; denn es ist der Grind, ein Aussatz am Haupt oder am Bart.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Sieht aber der Priester, daß der Grind nicht tieferliegend erscheint als die Haut, und daß das Haar nicht goldgelb ist, so soll er den, der das Mal hat, sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Und wenn er das Mal am siebenten Tage besieht und findet, daß der Grind nicht weitergefressen hat, und kein goldgelbes Haar da ist, und der Grind nicht tieferliegend erscheint als die übrige Haut,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'so soll er sich scheren lassen, und der Priester soll den Grindigen abermal sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Und wenn er ihn am siebenten Tage besieht und findet, daß der Grind in der Haut nicht weitergefressen hat und nicht tieferliegend erscheint als die übrige Haut, so soll ihn der Priester für rein erklären, und er soll seine Kleider waschen; denn er ist rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Frißt aber der Grind weiter an der Haut, nach seiner Reinigung,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und der Priester besieht ihn und findet, daß der Grind an der Haut weitergefressen hat, so soll er nicht mehr darnach fragen, ob die Haare goldgelb seien; denn er ist unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ist aber das Aussehen des Grindes gleich geblieben und schwarzes Haar darin gewachsen, so ist der Grind geheilt, und er ist rein; darum soll ihn der Priester für rein erklären.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Wenn sich bei einem Manne oder einem Weibe an der Haut ihres Fleisches weiße Flecken zeigen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und der Priester sieht nach und findet in der Haut ihres Fleisches blasse weiße Flecken, so ist es ein Ausschlag, der an der Haut ausgebrochen ist, und der Betreffende ist rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Wenn einem Mann die Haupthaare ausfallen, daß er hinten kahl wird, der ist rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Fallen sie ihm vorn am Haupt aus, daß er vorn eine Glatze hat, so ist er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Entsteht aber an der hintern oder vordern Glatze ein weißrötliches Mal, so ist ihm ein Aussatz ausgebrochen an seiner hintern oder vordern Glatze.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Darum soll ihn der Priester besehen, und wenn er findet, daß die Geschwulst des Males an seiner Hinter oder Vorderglatze weißrötlich ist, und wie ein Aussatz an der Haut des Fleisches anzusehen ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so ist er ein aussätziger Mann und unrein, und der Priester soll ihn für unrein erklären wegen des Mals auf seinem Kopf.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Es soll aber der Aussätzige, der ein Mal an sich hat, in zerrissenen Kleidern einhergehen, mit entblößtem Haupt und verhüllten Lippen, und er soll ausrufen: Unrein, unrein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Solange das Mal an ihm ist, soll er unrein bleiben, denn er ist unrein; er soll abgesondert wohnen und außerhalb des Lagers seine Wohnung haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Wenn an einem Kleide ein Aussatzmal ist, es sei wollen oder leinen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'am Zettel oder am Eintrag, es sei leinen oder wollen, oder an einem Fell, oder an irgend etwas, das aus Fellen gemacht wird;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und wenn das Mal grünlich oder rötlich ist am Kleid oder am Fell, oder am Zettel oder am Eintrag, oder an irgend etwas, das von Fellen gemacht wird, so ist es gewiß ein Aussatzmal. Darum soll es der Priester besehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Und wenn er das Mal besehen hat, soll er es sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Und wenn er am siebenten Tage sieht, daß das Mal weitergefressen hat am Kleid, am Zettel oder am Eintrag, am Fell oder an irgend etwas, das man aus Fellen macht, so ist es ein fressendes Aussatzmal und der Gegenstand ist unrein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'und er soll das Kleid verbrennen, oder den Zettel oder Eintrag, es sei wollen oder leinen, oder allerlei Fellwerk, darin ein solches Mal ist; denn es ist ein fressender Aussatz, und man soll es mit Feuer verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Sieht aber der Priester, daß das Mal nicht weitergefressen hat am Kleid oder am Zettel oder am Eintrag, oder an allerlei Fellwerk,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so soll er gebieten, daß man den Gegenstand, an welchem das Mal ist, wasche, und er soll es weitere sieben Tage lang einschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Und wenn der Priester sieht, nachdem das Mal gewaschen ist, daß das Mal seine Farbe nicht verändert und auch nicht weitergefressen hat, so ist es unrein; du sollst es mit Feuer verbrennen; es ist eine eingefressene Vertiefung an der hintern und vordern Seite.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Wenn aber der Priester sieht, daß das Mal, nachdem es gewaschen worden, verblaßt ist, so soll er es abreißen vom Kleid, vom Fell, vom Zettel oder vom Eintrag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Wird es aber noch gesehen am Kleid, am Zettel, am Eintrag oder an allerlei Fellwerk, so ist es ein ausbrechender Aussatz; und du sollst den Gegenstand, an welchem ein solches Mal ist, mit Feuer verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Das Kleid aber oder den Zettel oder den Eintrag oder allerlei Fellwerk, das gewaschen und wovon das Mal entfernt ist, soll man nochmals waschen, so ist es rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Das ist das Gesetz über das Aussatzmal an Kleidern, sie seien wollen oder leinen, am Zettel und am Eintrag und an allerlei Fellwerk, wonach sie für rein oder unrein zu erklären sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und der HERR redete zu Mose und sprach: Dieses Gesetz gilt für den Aussätzigen am Tage seiner Reinigung:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Er soll zum Priester kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Und der Priester soll hinaus vor das Lager gehen, und wenn er nachsieht und findet, daß das Mal des Aussätzigen heil geworden ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'so soll er gebieten, daß man für den, der sich reinigen läßt, zwei lebendige Vögel bringe, welche rein sind, und Zedernholz, Karmesin und Ysop;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'und der Priester soll gebieten, daß man den einen Vogel schächte über einem irdenen Geschirr, darin lebendiges Wasser ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Den lebendigen Vogel aber soll man nehmen samt dem Zedernholz, dem Karmesin und Ysop, und es samt dem lebendigen Vogel in des geschächteten Vogels Blut tauchen, das mit dem lebendigen Wasser vermischt worden ist;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'und soll denjenigen siebenmal besprengen, der sich vom Aussatz reinigen läßt; also reinige er ihn und lasse den lebendigen Vogel in das freie Feld fliegen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Der zu Reinigende aber soll seine Kleider waschen und alle seine Haare abschneiden und sich mit Wasser baden; so ist er rein. Darnach gehe er in das Lager; doch soll er sieben Tage lang außerhalb seiner Hütte bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Und am siebenten Tage soll er alle seine Haare abschneiden auf dem Haupte, am Bart und an den Augenbrauen, daß alle Haare abgeschoren seien, und soll seine Kleider waschen und sein Fleisch im Wasser baden, so ist er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Und am achten Tag soll er zwei tadellose Lämmer nehmen, und ein tadelloses jähriges Schaf, und drei Zehntel Semmelmehl zum Speisopfer, mit Öl gemengt, und ein Log Öl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Da soll dann der Priester, der die Reinigung vollzogen hat, den zu Reinigenden und diese Dinge vor den HERRN stellen, vor die Tür der Stiftshütte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'und er soll das eine Lamm nehmen und es zum Schuldopfer darbringen samt dem Log Öl, und soll solches vor dem HERRN hin und her weben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Darnach soll er das Lamm schächten an dem Ort, da man das Sündopfer und das Brandopfer schächtet, an heiliger Stätte. Denn wie das Sündopfer, also gehört auch das Schuldopfer dem Priester: es ist hochheilig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Und der Priester soll von dem Blut des Schuldopfers nehmen und dem, der gereinigt werden soll, auf das rechte Ohrläpplein tun und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Darnach soll er von dem Log Öl nehmen und auf des Priesters linke Hand gießen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'und der Priester soll mit seinem rechten Finger in das Öl tunken, das in seiner linken Hand ist, und mit seinem Finger von dem Öl siebenmal vor dem HERRN sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Das übrige Öl aber in seiner Hand soll er dem, der gereinigt werden soll, auf das rechte Ohrläpplein tun und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes, oben auf das Blut des Schuldopfers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Das übrige Öl aber in seiner Hand soll er auf des zu Reinigenden Haupt tun und ihn vor dem HERRN versühnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Und der Priester soll das Sündopfer zurichten und für den zu Reinigenden Sühne erwirken wegen seiner Unreinigkeit, und soll darnach das Brandopfer schächten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Und er soll es auf dem Altar opfern samt dem Speisopfer und ihm Sühne erwirken; so ist er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Ist er aber arm und vermag nicht so viel, so nehme er ein Lamm zum Schuldopfer, zum Webopfer, um für ihn Sühne zu erwirken, und einen Zehntel Semmelmehl, mit Öl gemengt, zum Speisopfer, und ein Log Öl,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'und zwei Turteltauben oder zwei junge Tauben, je nach seinem Vermögen, die eine zum Sündopfer, die andere zum Brandopfer,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'und bringe sie am achten Tage seiner Reinigung zum Priester, vor die Tür der Stiftshütte, vor den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Da soll der Priester das Lamm zum Schuldopfer nehmen, und das Öl, und soll beides vor dem HERRN zu einem Webopfer weben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Und er soll das Lamm des Schuldopfers schächten und das Blut von demselben nehmen und dem, der gereinigt werden soll, auf sein rechtes Ohrläpplein tun und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'und von dem Öl soll der Priester in seine linke Hand gießen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'und mit seinem rechten Finger vom Öl, das in seiner linken Hand ist, siebenmal vor dem HERRN sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Darnach soll der Priester vom Öl in seiner Hand dem, der gereinigt werden soll, auf sein rechtes Ohrläpplein und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes tun, oben auf das Blut des Schuldopfers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Das übrige Öl in seiner Hand aber soll er dem zu Reinigenden auf das Haupt tun, um für ihn Sühne zu erwirken vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Darnach soll er eine der Turteltauben oder der jungen Tauben (was seine Hand aufzubringen vermochte)');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'zum Sündopfer zubereiten und die andere zum Brandopfer, samt dem Speisopfer; so soll der Priester für den, der gereinigt werden soll, Sühne erwirken vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Das ist das Gesetz für den Aussätzigen, der mit seiner Hand nicht aufbringen kann, was zu seiner Reinigung gehört.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und der HERR redete zu Mose und Aaron:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Wenn ihr in das Land Kanaan kommt, das ich euch zur Besitzung gebe, und ich irgendein Haus des Landes eurer Besitzung mit einem Aussatz belege,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so soll der, dem das Haus gehört, kommen und es dem Priester anzeigen und sprechen: Es dünkt mich, als sei ein Aussatzmal an meinem Hause.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Dann soll der Priester gebieten, daß man das Haus ausräume, ehe der Priester hineingeht, das Mal zu besehen, damit nicht alles unrein werde, was im Hause ist; darnach soll der Priester hineingehen, das Haus zu besehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Wenn er nun das Mal besieht und findet, daß an der Wand des Hauses grüne oder rötliche Grüblein sind, die tieferliegend erscheinen als die übrige Wand,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so soll er zur Tür des Hauses hinausgehen und das Haus sieben Tage lang verschließen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Und wenn er am siebenten Tage wiederkommt und nachsieht und findet, daß das Mal an der Wand des Hauses weitergefressen hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so soll der Priester befehlen, daß man die Steine ausbreche, wo das Mal ist, und daß man sie vor die Stadt hinaus an einen unreinen Ort werfe;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'und er soll befehlen, das Haus inwendig ringsum abzuschaben, und man soll den Schutt, den man abgeschabt hat, vor die Stadt hinaus an einen unreinen Ort schütten');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'und andere Steine nehmen und an jene Stelle tun und andern Mörtel nehmen und das Haus bewerfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Wenn dann das Mal wieder kommt und am Hause ausbricht, nachdem man die Steine ausgebrochen und das Haus abgekratzt und neu beworfen hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so soll der Priester hineingehen; und wenn er sieht, daß das Mal am Hause weitergefressen hat, so ist es ein fressender Aussatz am Hause, und es ist unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Darum soll man das Haus abbrechen, seine Steine und sein Holz und allen Mörtel am Hause, und man soll es vor die Stadt hinaus an einen unreinen Ort führen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer in das Haus geht, solang es verschlossen ist, der ist unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Und wer darin liegt, der soll seine Kleider waschen; auch wer darin ißt, der soll seine Kleider waschen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Wenn aber der Priester beim Betreten des Hauses sieht, daß das Mal nicht weitergefressen hat am Hause, nachdem das Haus neu beworfen ist, so soll er es für rein erklären; denn das Mal ist heil geworden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Und er soll für das Haus zum Sündopfer zwei Vögel nehmen, Zedernholz, Karmesin und Ysop,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'und soll den einen Vogel schächten über einem irdenen Geschirr, darin lebendiges Wasser ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'und soll das Zedernholz nehmen, den Ysop und das Karmesin und den lebendigen Vogel, und es in des geschächteten Vogels Blut tauchen und in das lebendige Wasser, und soll das Haus siebenmal besprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Und soll also das Haus entsündigen mit dem Blut des Vogels, mit dem lebendigen Wasser, mit dem lebendigen Vogel, mit dem Zedernholz, dem Ysop und Karmesin,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'und soll den lebendigen Vogel vor die Stadt hinaus in das freie Feld fliegen lassen und für das Haus Sühne erwirken; so ist es rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Dies ist das Gesetz über allerlei Aussatzmale und über den Grind,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'auch über den Aussatz der Kleider und der Häuser');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'und über die Geschwulst, den Ausschlag und die weißen Flecken,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'um Belehrung zu geben für den Tag der Verunreinigung und der Reinigung. Es ist das Gesetz vom Aussatz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Und der HERR redete zu Mose und Aaron und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Redet mit den Kindern Israel und sprecht zu ihnen: Wenn ein Mann einen Ausfluß hat, der von seinem Fleische fließt, so ist er unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Und zwar ist er unrein an diesem Flusse, wenn sein Fleisch den Ausfluß frei fließen läßt; auch wenn sein Fleisch verstopft wird von dem Ausflusse, so ist er unrein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jedes Lager, worauf der mit einem Ausfluß Behaftete liegt, und alles, worauf er sitzt, wird unrein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'und wer sein Lager anrührt, soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'und wer sich auf etwas setzt, worauf der mit einem Ausfluß Behaftete gesessen hat, der soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Wer sein Fleisch anrührt, der soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Wenn aber der mit einem Ausfluß Behaftete seinen Speichel auswirft auf einen, der rein ist, so soll dieser seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Auch der Sattel und alles, worauf der mit einem Ausfluß Behaftete reitet, wird unrein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'und wer immer etwas anrührt, das unter ihm gewesen ist, der wird unrein sein bis zum Abend. Und wer etwas solches trägt, der soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Und wen der mit einem Ausfluß Behaftete anrührt, ohne daß er zuvor die Hände mit Wasser gewaschen hat, der soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Wenn er ein irdenes Geschirr anrührt, so soll man es zerbrechen; aber jedes hölzerne Geschirr soll man mit Wasser waschen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Und wenn er von seinem Ausfluß rein wird, so soll er sieben Tage zählen zu seiner Reinigung, und seine Kleider waschen und sein Fleisch mit lebendigem Wasser baden; so ist er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Und am achten Tage soll er zwei Turteltauben oder zwei junge Tauben nehmen und vor den HERRN kommen, vor die Tür der Stiftshütte, und soll sie dem Priester geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Und der Priester soll die eine zum Sündopfer, die andere zum Brandopfer machen und für ihn Sühne erwirken vor dem HERRN, wegen seines Ausflusses.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Wenn einem Mann der Same entgeht, so soll er sein ganzes Fleisch mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und jedes Kleid und jedes Fell, das mit solchem Samen befleckt ist, soll man mit Wasser waschen, und es bleibt unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Und wenn ein Mann bei einem Weibe liegt, daß ihm der Same entgeht, so sollen sie sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Wenn ein Weib ihres Fleisches Blutfluß hat, so soll sie sieben Tage lang in ihrer Unreinigkeit verbleiben. Wer sie anrührt, der bleibt unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Und alles, worauf sie in ihrer Unreinigkeit liegt, wird unrein; auch alles, worauf sie sitzt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Und wer ihr Lager anrührt, der soll seine Kleider waschen und sich mit Wasser baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und wer immer etwas anrührt, worauf sie gesessen hat, der soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Auch wer etwas anrührt, das auf ihrem Bette war oder worauf sie gesessen hat, soll unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn ein Mann bei ihr liegt, und es kommt ihre Unreinigkeit an ihn, der wird sieben Tage lang unrein sein, und das Lager, worauf er gelegen hat, wird unrein sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Wenn aber ein Weib ihren Blutfluß eine lange Zeit hat, nicht nur zur gewöhnlichen Zeit, sondern auch über die gewöhnliche Zeit hinaus, so wird sie unrein sein während der ganzen Dauer ihres Flusses; wie in den Tagen ihrer Unreinigkeit soll sie auch dann unrein sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Alles, worauf sie liegt während der ganzen Zeit ihres Flusses, soll sein wie das Lager ihrer monatlichen Unreinigkeit; auch alles, worauf sie sitzt, wird unrein sein, gleich wie zur Zeit ihrer monatlichen Unreinigkeit.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Wer etwas davon anrührt, der wird unrein und soll seine Kleider waschen und sich mit Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Wird sie aber rein von ihrem Flusse, so soll sie sieben Tage zählen, darnach soll sie rein sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Und am achten Tage soll sie zwei Turteltauben oder zwei junge Tauben nehmen und sie zum Priester bringen vor die Tür der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Und der Priester soll die eine zum Sündopfer, die andere zum Brandopfer machen und ihr wegen des Flusses ihrer Unreinigkeit Sühne erwirken vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Also sollt ihr die Kinder Israel absondern um ihrer Unreinigkeit willen, damit sie in ihrer Unreinigkeit nicht sterben, wenn sie meine Wohnung verunreinigen, die unter ihnen ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Dies ist das Gesetz über den, der einen Ausfluß hat, und über den, dem der Same entgeht, daß er unrein wird,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'und über die, welche an ihrer Unreinigkeit leidet, und über solche, die einen Fluß haben, es sei ein Mann oder ein Weib, und über einen Mann, der bei einer Unreinen liegt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Und der Herr redete mit Mose nach dem Tod der beiden Söhne Aarons, als sie vor den HERRN traten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Und der HERR sprach zu Mose: Sage deinem Bruder Aaron, daß er nicht zu allen Zeiten in das Heiligtum hineingehe hinter den Vorhang vor den Sühndeckel, der auf der Lade ist, damit er nicht sterbe; denn ich will auf dem Sühndeckel in einer Wolke erscheinen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Damit soll Aaron hineingehen in das Heiligtum: mit einem jungen Farren zum Sündopfer und mit einem Widder zum Brandopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'und er soll den heiligen leinenen Leibrock anziehen und soll ein leinenes Unterkleid an seinem Leibe haben und sich mit einem leinenen Gürtel gürten und einen leinenen Kopfbund umbinden (denn das sind die heiligen Kleider) und soll seinen Leib mit Wasser baden und sie anziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Dann soll er von der Gemeinde der Kinder Israel zwei Ziegenböcke nehmen zum Sündopfer und einen Widder zum Brandopfer.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Und Aaron soll den Farren zum Sündopfer für sich selbst herzubringen und sich und seinem Haus Sühne erwirken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Darnach soll er die beiden Böcke nehmen und sie vor den HERRN stellen, vor die Tür der Stiftshütte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'und soll das Los werfen über die beiden Böcke, ein Los für den HERRN und ein Los für den Asasel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Und Aaron soll den Bock, auf welchen des HERRN Los fällt, zum Sündopfer machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Aber den Bock, auf welchen das Los Asasels fällt, soll er lebendig vor den HERRN stellen, daß er über ihm die Sühne vollziehe und ihn zum Asasel in die Wüste jage.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Und Aaron soll den Farren des Sündopfers, das für ihn selbst bestimmt ist, herzubringen und sich und seinem Haus Sühne erwirken und soll den Farren schächten zum Sündopfer für sich selbst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Darnach nehme er die Pfanne voll Glut vom Altar, der vor dem HERRN steht, und eine Handvoll wohlriechenden zerstoßenen Räucherwerks und bringe es hinein hinter den Vorhang;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'und er tue das Räucherwerk auf das Feuer vor dem HERRN, damit die Wolke vom Räucherwerk den Sühndeckel, der auf dem Zeugnis ist, verhülle, damit er nicht sterbe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Er soll auch von dem Blut des Farren nehmen und mit seinem Finger gegen den Sühndeckel sprengen, gegen Aufgang. Siebenmal soll er also vor dem Sühndeckel mit seinem Finger vom Blute sprengen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Darnach soll er den Bock, das Sündopfer des Volkes schächten und von dessen Blut hinein hinter den Vorhang bringen, und soll mit dessen Blute tun, wie er mit des Farren Blut getan hat, und auch damit sprengen auf den Sühndeckel und vor denselben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Also soll er Sühne erwirken für das Heiligtum wegen der Unreinigkeiten der Kinder Israel und wegen ihrer Übertretungen und aller ihrer Sünden, und soll also tun mit der Stiftshütte, welche sich mitten unter ihren Unreinigkeiten befindet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Kein Mensch soll in der Stiftshütte sein, wenn er hineingeht, um im Heiligtum die Sühne zu vollziehen, bis er wieder hinausgeht und die Sühne erwirkt hat für sich und sein Haus und die ganze Gemeinde Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Und wenn er zum Altar herauskommt, der vor dem HERRN steht, so soll er von dem Blut des Farren und von dem Blut des Bocks nehmen und auf die Hörner des Altars tun, ringsum,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'und soll mit seinem Finger vom Blut siebenmal darauf sprengen und ihn reinigen und von der Unreinigkeit der Kinder Israel heiligen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Und wenn er die Sühne für das Heiligtum und die Stiftshütte und den Altar erwirkt hat, so soll er den lebendigen Bock herzu bringen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'und Aaron soll seine beiden Hände auf dieses lebendigen Bockes Kopf stützen und auf ihn alle Missetaten der Kinder Israel und alle ihre Übertretungen samt ihren Sünden bekennen, und soll sie dem Bock auf den Kopf legen und ihn durch einen Mann, der bereitsteht, in die Wüste jagen lassen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'daß also der Bock alle ihre Missetaten auf sich in eine Wildnis trage; und er soll ihn in der Wüste loslassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Und Aaron soll in die Stiftshütte gehen und die leinenen Kleider ausziehen, die er anzog, als er in das Heiligtum ging, und soll sie daselbst lassen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'und soll seinen Leib mit Wasser baden an heiliger Stätte und seine eigenen Kleider anziehen und hinausgehen und sein und des Volkes Brandopfer verrichten, und Sühnung tun für sich und das Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Und das Fett des Sündopfers soll er auf dem Altar verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Der aber, welcher den Bock zum Asasel gejagt hat, soll seine Kleider waschen und seinen Leib mit Wasser baden und darnach in das Lager kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Den Farren des Sündopfers aber und den Bock des Sündopfers, deren Blut zur Sühnung in das Heiligtum gebracht worden ist, soll man hinaus vor das Lager führen und mit Feuer verbrennen, ihre Haut und ihr Fleisch und ihren Mist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Und der sie verbrannt hat, soll seine Kleider waschen und seinen Leib mit Wasser baden und darnach in das Lager kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Und das soll euch eine ewig gültige Ordnung sein: Am zehnten Tage des siebenten Monats sollt ihr eure Seelen demütigen und kein Werk tun, weder der Einheimische noch der Fremdling, der unter euch weilt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Denn an diesem Tage wird für euch Sühne erwirkt, euch zu reinigen; von allen euren Sünden sollt ihr vor dem HERRN gereinigt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Darum soll es euch ein Ruhe-Sabbat sein, und ihr sollt eure Seelen demütigen. Das sei eine ewige Ordnung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Diese Sühne soll ein Priester vollziehen, den man gesalbt und dessen Hand man gefüllt hat, daß er an seines Vaters Statt Priester sei; und er soll die leinenen Kleider anziehen, die heiligen Kleider,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'und soll für das Heiligtum und die Stiftshütte und den Altar Sühne erwirken; auch den Priestern und der ganzen Volksgemeinde soll er Sühne schaffen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Das soll euch zur ewigen Gewohnheit weden, daß ihr für die Kinder Israel Sühne erwirkt wegen allen ihren Sünden, einmal im Jahr. Und man tat, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Sage Aaron und seinen Söhnen und allen Kindern Israel und sprich zu ihnen: Das ist\'s, was der HERR geboten hat, indem er sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Jedermann aus dem Hause Israel, der einen Ochsen, oder ein Lamm, oder eine Ziege im Lager oder außerhalb des Lagers schächtet,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'und es nicht vor die Tür der Stiftshütte bringt, daß es dem HERRN zum Opfer gebracht werde vor der Wohnung des HERRN, dem soll es für eine Blutschuld gerechnet werden; er hat Blut vergossen, und es soll derselbe Mensch aus seinem Volk ausgerottet werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Darum sollen die Kinder Israel fortan ihre Opfer, die sie jetzt noch auf freiem Felde opfern, vor den HERRN bringen, vor die Tür der Stiftshütte, zum Priester, um sie daselbst dem HERRN als Dankopfer darzubringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Und der Priester soll das Blut auf den Altar des HERRN sprengen vor der Tür der Stiftshütte und das Fett verbrennen zum lieblichen Geruch dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Und sie sollen forthin ihre Opfer nicht mehr den Dämonen opfern, denen sie nachbuhlen. Das soll ihnen eine ewig gültige Ordnung sein auf alle ihre Geschlechter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Und du sollst zu ihnen sagen: Welcher Mensch aus dem Hause Israel oder welcher Fremdling, der unter ihnen wohnt, ein Brandopfer oder sonst ein Schlachtopfer verrichten will');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und es nicht vor die Türe der Stiftshütte bringt, daß er es dem HERRN zurichte, der soll ausgerottet werden aus seinem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und wenn ein Mensch vom Hause Israel oder ein Fremdling, der unter ihnen wohnt, irgend Blut ißt, wider einen solchen, der Blut ißt, will ich mein Angesicht richten und ihn ausrotten aus seinem Volk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'denn die Seele des Fleisches ist im Blut, und ich habe es euch auf den Altar gegeben, um Sühne zu erwirken für eure Seelen. Denn das Blut ist es, das Sühne erwirkt durch die in ihm wohnende Seele.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum habe ich den Kindern Israel gesagt: Keine Seele unter euch soll Blut essen; auch kein Fremdling unter euch soll Blut essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und wenn ein Mensch von den Kindern Israel oder ein Fremdling, der unter ihnen wohnt, auf der Jagd ein Wildpret oder Geflügel erwischt, das man essen darf, der soll desselben Blut ausgießen und mit Erde bedecken;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'denn alles Fleisches Seele ist sein Blut; es ist mit seiner Seele verbunden. Darum habe ich den Kindern Israel gesagt: Ihr sollt keines Fleisches Blut essen; denn alles Fleisches Seele ist sein Blut. Wer es aber ißt, der soll ausgerottet werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Jeder aber, der ein Aas oder Zerrissenes genießt, er sei ein Einheimischer oder ein Fremdling, der soll seine Kleider waschen und sich mit Wasser baden und unrein bleiben bis zum Abend, dann wird er rein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Wenn er aber sein Kleid nicht waschen und sein Fleisch nicht baden wird, so soll er seine Schuld tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und der HERR redete zu Mose und sprach: Rede mit den Kindern Israel und sprich zu ihnen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Ich, der HERR, bin euer Gott!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ihr sollt nicht tun, wie man im Lande Ägypten tut, wo ihr gewohnt habt, und sollt auch nicht tun, wie man in Kanaan tut, dahin ich euch führen will, und ihr sollt nicht nach ihren Satzungen wandeln;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'sondern meine Rechte sollt ihr halten und meine Satzungen beobachten, daß ihr darin wandelt; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Und zwar sollt ihr meine Satzungen und meine Rechte beobachten, weil der Mensch, der sie tut, dadurch leben wird. Ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Niemand soll sich seiner Blutsverwandten nahen, ihre Scham zu entblößen; ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Du sollst die Scham deines Vaters und deiner Mutter nicht entblößen. Es ist deine Mutter, darum sollst du ihre Scham nicht entblößen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Du sollst die Scham des Weibes deines Vaters nicht entblößen; denn es ist die Scham deines Vaters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Du sollst die Scham deiner Schwester, die deines Vaters oder deiner Mutter Tochter ist, daheim oder draußen geboren, nicht entblößen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Die Scham der Tochter deines Sohns oder deiner Tochter Tochter, ihre Scham sollst du nicht entblößen, denn es ist deine Scham.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Du sollst die Scham der Tochter deines Vaters Weibes, die deinem Vater geboren und deine Schwester ist, nicht entblößen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Du sollst die Scham der Schwester deines Vaters nicht entblößen, denn sie ist deines Vaters nächste Blutsverwandte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Du sollst die Scham der Schwester deiner Mutter nicht entblößen; denn sie ist deiner Mutter nächste Blutsverwandte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du sollst die Scham des Bruders deines Vaters nicht entblößen, du sollst nicht zu seinem Weibe gehen; denn sie ist deine Base.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Du sollst die Scham deiner Sohnsfrau nicht entblößen; denn sie ist deines Sohnes Weib, darum sollst du ihre Scham nicht entblößen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Du sollst die Scham des Weibes deines Bruders nicht entblößen, denn es ist deines Bruders Scham.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Du sollst nicht zugleich die Scham eines Weibes und ihrer Tochter entblößen, noch ihres Sohnes Tochter oder ihrer Tochter Tochter nehmen, ihre Scham zu entblößen; denn sie ist ihre nächste Blutsverwandte; es wäre eine Schandtat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du sollst auch nicht ein Weib zu ihrer Schwester hinzunehmen, wodurch Eifersucht erregt würde, wenn du ihre Scham entblößtest, während jene noch lebt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du sollst nicht zum Weibe gehen während ihrer monatlichen Unreinigkeit, ihre Scham zu entblößen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Auch sollst du deines Nächsten Weib keinen Beischlaf gewähren, sie zu besamen, daß du dich mit ihr verunreinigest.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du sollst auch von deinen Kindern keines hergeben, daß es dem Moloch geopfert werde, damit du den Namen deines Gottes nicht entweihest; ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du sollst bei keiner Mannsperson liegen wie beim Weib; denn das ist ein Greuel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Auch sollst du den Beischlaf mit keinem Vieh vollziehen, daß du dich mit ihm verunreinigest. Und kein Weib soll sich zur Begattung vor ein Vieh stellen; das wäre abscheulich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ihr sollt euch durch nichts derartiges verunreinigen. Denn durch das alles haben sich die Heiden verunreinigt, die ich vor euch her ausstoßen will.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Und dadurch ist das Land verunreinigt worden. Darum will ich ihre Missetat an ihm heimsuchen, daß das Land seine Einwohner ausspeie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Ihr aber sollt meine Satzungen und Rechte beobachten und keinen dieser Greuel verüben, weder der Einheimische noch der Fremdling, der unter euch wohnt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'denn alle diese Greuel haben die Leute dieses Landes getan, die vor euch waren, wodurch das Land verunreinigt worden ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Damit euch nun das Land nicht ausspeie, wenn ihr es verunreiniget, wie es die Heiden ausgespieen hat, die vor euch gewesen sind,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'so soll jeder, der einen dieser Greuel tut, jede Seele, die dergleichen verübt, mitten aus ihrem Volk ausgerottet werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'So beobachtet denn meine Verordnungen, daß ihr keinen von den greulichen Gebräuchen übet, die man vor euch geübt hat, und euch dadurch nicht verunreiniget. Ich, der HERR, bin euer Gott!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Rede mit der ganzen Gemeinde der Kinder Israel und sprich zu ihnen: Ihr sollt heilig sein, denn Ich bin heilig, der HERR, euer Gott!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Jedermann fürchte seine Mutter und seinen Vater und beobachte meine Sabbate; denn Ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ihr sollt euch nicht an die Götzen wenden und sollt euch keine gegossenen Götter machen, denn ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und wenn ihr dem HERRN ein Dankopfer schlachten wollt, sollt ihr\'s so opfern, daß es euch angenehm macht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Es soll aber gegessen werden an dem Tage, da ihr es opfert, und am folgenden Tag; was aber bis zum dritten Tag übrigbleibt, das soll man mit Feuer verbrennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Wird aber am dritten Tage davon gegessen, so ist es ein Greuel und wird nicht angenehm sein;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'und wer davon ißt, wird seine Missetat tragen, weil er das Heiligtum des HERRN entheiligt hat, und eine solche Seele soll ausgerottet werden aus ihrem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Wenn ihr die Ernte eures Landes einbringt, sollst du den Rand deines Ackers nicht vollständig abernten und keine Nachlese nach deiner Ernte halten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Auch sollst du nicht Nachlese halten in deinem Weinberg, noch die abgefallenen Beeren deines Weinberges auflesen, sondern du sollst es den Armen und Fremdlingen lassen; denn ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt einander nicht bestehlen, nicht belügen noch betrügen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ihr sollt nicht falsch schwören bei meinem Namen und nicht entheiligen den Namen deines Gottes! Denn Ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinen Nächsten weder bedrücken noch berauben. Des Taglöhners Lohn soll nicht über Nacht bei dir bleiben bis zum Morgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst dem Tauben nicht fluchen. Du sollst dem Blinden nichts in den Weg legen, sondern sollst dich fürchten vor deinem Gott; denn Ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt keine Ungerechtigkeit begehen im Gericht; du sollst weder die Person des Geringen ansehen, noch die Person des Großen ehren; sondern du sollst deinen Nächsten recht richten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du sollst nicht als Verleumder umhergehen unter deinem Volk! Du sollst auch nicht auftreten wider deines Nächsten Blut!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Ich bin der HERR. Du sollst deinen Bruder nicht hassen in deinem Herzen; strafen sollst du deinen Nächsten, daß du nicht seinethalben Schuld tragen müssest!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst nicht Rache üben, noch Groll behalten gegen die Kinder deines Volkes, sondern du sollst deinen Nächsten lieben wie dich selbst! Denn ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meine Satzungen sollt ihr beobachten. Du sollst bei deinem Vieh nicht zweierlei Arten sich begatten lassen und dein Feld nicht besäen mit vermischtem Samen, und es soll kein Kleid auf deinen Leib kommen, das von zweierlei Garn gewoben ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Wenn ein Mann bei einem Weibe liegt und sie beschläft, die eine Dienstmagd und einem andern versprochen, doch nicht losgekauft ist und die Freiheit nicht erlangt hat, die sollen gestraft werden, aber sie sollen nicht sterben; denn sie ist nicht frei gewesen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Er soll aber für seine Schuld dem HERRN vor die Tür der Stiftshütte einen Widder zum Schuldopfer bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Und der Priester soll ihm Sühne erwirken mit dem Schuldopferwidder vor dem HERRN wegen der Sünde, die er begangen hat; so wird ihm seine Sünde, die er getan hat, vergeben werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Wenn ihr in das Land kommt und allerlei Bäume pflanzet, wovon man ißt, sollt ihr die ersten Früchte derselben als Vorhaut betrachten. Drei Jahre lang sollt ihr sie für unbeschnitten achten und nicht davon essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Im vierten Jahr aber sollen alle ihre Früchte heilig sein zu einer Jubelfeier für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Und im fünften Jahre sollt ihr die Früchte essen, daß der Ertrag umso größer werde; ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr sollt nichts mit Blut essen, ihr sollt keine Wahrsagerei, keine Zeichendeuterei treiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr sollt den Rand eures Haupthaares nicht rundum stutzen, auch sollst du den Rand deines Bartes nicht beschädigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ihr sollt keine Einschnitte an eurem Leibe machen für eine abgeschiedene Seele und sollt euch nicht tätowieren! Ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du sollst deine Tochter nicht preisgeben, sie zur Unzucht anzuhalten, damit das Land nicht Unzucht treibe und voller Laster werde!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Beobachtet meine Sabbattage und verehret mein Heiligtum! Ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ihr sollt euch nicht an die Totenbeschwörer wenden, noch an die Zeichendeuter; ihr sollt sie nicht fragen, auf daß ihr durch sie nicht verunreinigt werdet; denn ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor einem grauen Haupte sollst du aufstehen und alte Leute ehren und sollst dich fürchten vor deinem Gott; ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Wenn ein Fremdling bei dir in eurem Lande wohnen wird, so sollt ihr ihn nicht beleidigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Ihr sollt euch gegen den Fremdling, der sich bei euch aufhält, benehmen, als wäre er bei euch geboren, und du sollst ihn lieben wie dich selbst; denn ihr seid auch Fremdlinge in Ägypten gewesen. Ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt euch nicht vergreifen weder am Recht noch an der Elle, noch am Gewicht, noch am Maß.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Rechte Waage, gutes Gewicht, richtige Scheffel und rechte Eimer sollt ihr haben! Ich, der HERR, bin euer Gott, der ich euch aus Ägypten geführt habe;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'darum sollt ihr alle meine Satzungen und alle meine Rechte beobachten und tun; ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Und der HERR redete zu Mose und sprach: Sage den Kindern Israel:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Wer von den Kindern Israel oder den Fremdlingen, die in Israel wohnen, von seinem Samen dem Moloch gibt, der soll des Todes sterben; das Volk des Landes soll ihn steinigen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Und ich will mein Angesicht wider einen solchen Menschen setzen und ihn mitten aus seinem Volk ausrotten, weil er dem Moloch von seinem Samen gegeben und mein Heiligtum verunreinigt und meinen heiligen Namen entheiligt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wenn das Volk des Landes nachsichtig wäre gegen einen solchen Menschen, der von seinem Samen dem Moloch gegeben hat, daß es ihn nicht tötete,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so würde ich mein Angesicht wider jenen Menschen und wider sein Geschlecht richten und ihn und alle, die mit ihm dem Moloch nachgebuhlt haben, aus der Mitte ihres Volkes ausrotten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Auch wenn sich eine Seele zu den Totenbeschwörern und Zeichendeutern wendet und ihnen nachbuhlt, so will ich mein Angesicht wider diese Seele richten und sie aus der Mitte ihres Volkes ausrotten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Darum heiligt euch und seid heilig; denn ich, der HERR, bin euer Gott!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Darum beobachtet meine Satzungen und tut sie; denn ich, der HERR, bin es, der euch heiligt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Wer seinem Vater oder seiner Mutter flucht, der soll unbedingt sterben! Sein Blut sei auf ihm; er hat seinem Vater oder seiner Mutter geflucht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Wenn einer die Ehe bricht mit einem Eheweib, so sollen beide unbedingt sterben, der Ehebrecher und die Ehebrecherin, weil er mit seines Nächsten Weib die Ehe gebrochen hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Wer bei seines Vaters Weibe schläft, der hat die Scham seines Vaters entblößt; sie sollen beide unbedingt sterben; ihr Blut sei auf ihnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Wenn jemand bei seiner Sohnsfrau schläft, so sollen sie beide unbedingt sterben; sie haben einen Greuel begangen; ihr Blut sei auf ihnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Wenn ein Mann bei einer männlichen Person schläft, als wäre es ein Weib, die haben beide einen Greuel getan, und sie sollen unbedingt sterben; ihr Blut sei auf ihnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Wenn jemand ein Weib nimmt und ihre Mutter dazu, so ist das eine Schandtat; man soll ihn samt den beiden Weibern mit Feuer verbrennen, damit keine solche Schandtat unter euch sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Wenn ein Mann seinen Samen an ein Vieh abgibt, so soll er unbedingt sterben, und das Vieh soll man erwürgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Kommt ein Weib einem Vieh zu nahe, um sich mit ihm zu vermischen, so sollst du sie töten und das Vieh auch; sie sollen unbedingt sterben; ihr Blut sei auf ihnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Wenn jemand seine Schwester nimmt, seines Vaters Tochter oder seiner Mutter Tochter, und ihre Scham beschaut und sie wieder seine Scham, so ist das eine Blutschande. Sie sollen ausgerottet werden vor den Augen ihres Volkes. Er hat seiner Schwester Scham entblößt, so trage er seine Schuld.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Wenn ein Mann bei einer Frau liegt zur Zeit ihrer Krankheit und ihre Scham entblößt und ihren Brunnen aufdeckt, und sie den Brunnen ihres Blutes entblößt, so sollen beide aus ihrem Volk ausgerottet werden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Die Scham deiner Mutter Schwester und die Scham deines Vaters Schwester sollst du nicht entblößen; denn wer dies tut, hat seine Blutsverwandten entblößt; sie sollen ihre Schuld tragen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Wenn jemand bei der Frau des Bruders seines Vaters schläft, der hat die Scham seines Oheims entblößt; sie sollen ihre Sünde tragen, sie sollen kinderlos sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Wenn jemand seines Bruders Weib nimmt, so ist das eine schändliche Tat; sie sollen kinderlos bleiben, weil er die Scham seines Bruders entblößt hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'So beobachtet nun alle meine Satzungen und meine Rechte und tut sie, damit euch nicht das Land ausspeie, wohin ich euch führe, daß ihr darinnen wohnet!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Und wandelt nicht nach den Satzungen der Heiden, die ich vor euch her ausstoßen werde. Denn solches alles haben sie getan, daß mir vor ihnen ekelte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Euch aber habe ich gesagt: Ihr sollt ihr Land erblich besitzen; denn ich will euch dasselbe zum Erbe geben, ein Land, das von Milch und Honig fließt. Ich, der HERR, bin euer Gott, der ich euch von den Völkern abgesondert habe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'So sollt nun auch ihr das reine Vieh vom unreinen absondern und die unreinen Vögel von den reinen, und sollt eure Seelen nicht verabscheuungswürdig machen durch Vieh, Vögel und alles, was auf Erden kriecht, was ich euch als unrein abgesondert habe;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'sondern ihr sollt mir heilig sein, denn ich, der HERR, bin heilig, der ich euch von den Völkern abgesondert habe, daß ihr mir angehöret!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Wenn in einem Mann oder einem Weib ein Totenbeschwörer oder Wahrsagergeist steckt, so sollen sie unbedingt sterben. Man soll sie steinigen, ihr Blut sei auf ihnen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Und der HERR sprach zu Mose: Sage den Priestern, Aarons Söhnen, und sprich zu ihnen: Ein Priester soll sich an keinem Toten seines Volkes verunreinigen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'außer an seinem nächsten Blutsverwandten, der ihm zugehört; an seiner Mutter, an seinem Vater, an seinem Sohn, an seiner Tochter, an seinem Bruder,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'und an seiner Schwester, die noch eine Jungfrau ist, die ihm nahesteht, weil sie noch keines Mannes Weib gewesen ist, an dieser mag er sich verunreinigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Es soll sich der Vorgesetzte an seinem Volk nicht verunreinigen, damit er sich nicht entweihe.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie sollen sich keine Glatze scheren auf ihrem Haupt, noch die Enden ihres Bartes stutzen, noch an ihrem Leibe Einschnitte machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gott heilig sein und den Namen ihres Gottes nicht entheiligen; denn sie opfern des HERRN Feueropfer, das Brot ihres Gottes, darum sollen sie heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Sie sollen keine Hure zum Weibe nehmen, auch keine Entehrte, noch eine, die von ihrem Mann verstoßen ist; denn der Priester ist heilig seinem Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Darum sollst du ihn für heilig halten; denn er opfert das Brot deines Gottes. Er soll dir heilig sein; denn heilig bin ich, der HERR, der euch heiligt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Wenn eines Priesters Tochter sich durch Unzucht entweiht, so hat sie ihren Vater entweiht; man soll sie mit Feuer verbrennen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Wer aber Hoherpriester ist unter seinen Brüdern, auf dessen Haupt das Salböl gegossen worden, und dem man die Hand gefüllt hat bei der Einkleidung, der soll sein Haupt nicht entblößen und seine Kleider nicht zerreißen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Er soll auch zu keinem Toten kommen und soll sich weder an seinem Vater noch an seiner Mutter verunreinigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Er soll das Heiligtum nicht verlassen, noch das Heiligtum seines Gottes entheiligen; denn die Weihe des Salböls seines Gottes ist auf ihm; ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Er soll eine Jungfrau zum Weibe nehmen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Eine Witwe, oder eine Verstoßene, oder eine Entehrte, oder eine Hure soll er nicht nehmen; sondern eine Jungfrau aus seinem Volk soll er zum Weibe nehmen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'daß er seinen Samen nicht entweihe unter seinem Volk. Denn ich, der HERR, heilige ihn.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Rede mit Aaron und sprich: Sollte jemand von deinen Nachkommen in ihren künftigen Geschlechtern mit irgend einem Gebrechen behaftet sein, so darf er sich nicht herzunahen, das Brot seines Gottes darzubringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Nein, keiner, an dem ein Gebrechen ist, soll sich herzunahen, er sei blind oder lahm oder verstümmelt, oder habe ein zu langes Glied;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'auch keiner, der einen gebrochenen Fuß oder eine gebrochene Hand hat,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'oder der bucklig oder schwindsüchtig ist, oder der einen Fleck auf seinem Auge hat, oder die Krätze oder Flechten oder einen Hodenbruch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Wer nun von dem Samen Aarons, des Priesters, ein solches Gebrechen an sich hat, der soll sich nicht herzunahen, die Feueropfer des HERRN darzubringen; er hat ein Gebrechen; darum soll er das Brot seines Gottes nicht herzubringen, daß er es opfere.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Doch darf er das Brot seines Gottes essen, vom Heiligen und vom Allerheiligsten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Aber zum Vorhang soll er nicht kommen, noch sich dem Altar nahen, weil er ein Gebrechen hat, daß er mein Heiligtum nicht entweihe; denn ich, der HERR, heilige sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und Mose sagte es Aaron und seinen Söhnen und allen Kindern Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Und der HERR redete zu Mose und sprach: Sage Aaron und seinen Söhnen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'daß sie sich enthalten sollen der heiligen Gaben der Kinder Israel, und meinen heiligen Namen nicht entweihen, in den Dingen, die sie mir geheiligt haben, mir, dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'So sage ihnen nun: Wer von euren Nachkommen, der von eurem Samen ist, sich dem Heiligen naht, das die Kinder Israel dem HERRN geheiligt haben, während er eine Unreinigkeit an sich hat; eine solche Seele soll von meinem Angesicht ausgerottet werden; ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ist irgend jemand vom Samen Aarons aussätzig oder mit einem Ausfluß behaftet, so soll er von dem Heiligen nicht essen, bis er rein wird. Und wer etwas durch einen Entseelten Verunreinigtes anrührt, oder wem der Same entgeht,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'oder wer irgend ein Gewürm anrührt, durch das man unrein wird, oder einen Menschen, an dem man sich verunreinigen kann wegen irgend etwas, was ihn unrein macht;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'welche Seele solches anrührt, die ist unrein bis zum Abend und soll nicht von dem Heiligen essen, sondern soll zuvor ihren Leib mit Wasser baden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Und wenn die Sonne untergegangen und sie rein geworden ist, dann mag sie von dem Heiligen essen; denn es ist ihre Speise.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Kein Aas noch Zerrissenes soll er essen, daß er nicht unrein davon werde; ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Sie sollen meine Anordnungen beobachten, damit sie nicht Sünde auf sich laden und daran sterben, wenn sie dieselben entheiligen; denn ich, der HERR, heilige sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kein Fremdling soll von dem Heiligen essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Wenn aber der Priester eine Seele um Geld erkauft, so mag dieselbe davon essen. Und wer ihm in seinem Hause geboren wird, der mag auch von seinem Brot essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Wenn aber des Priesters Tochter eines Fremdlings Weib wird, soll sie nicht von dem Hebopfer des Heiligen essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Wird aber des Priesters Tochter eine Witwe oder eine Verstoßene und hat keine Kinder und kommt wieder in ihres Vaters Haus, wie in ihrer Jugend, so soll sie von ihres Vaters Brot essen. Aber kein Fremdling soll davon essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Wer sonst aber aus Versehen von dem Geheiligten ißt, der soll den fünften Teil dazutun und es dem Priester mit dem Geheiligten geben,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'damit sie nicht die heiligen Gaben der Kinder Israel entheiligen, welche diese dem HERRN heben,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'daß sie sich nicht mit Missetat und Schuld beladen, wenn sie ihr Geheiligtes essen; denn ich, der HERR, heilige sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Weiter redete der HERR zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Sage Aaron und seinen Söhnen und allen Kindern Israel und sprich zu ihnen: Wer vom Hause Israel oder von den Fremdlingen in Israel sein Opfer bringen will (sei es, daß sie es nach ihren Gelübden oder ganz freiwillig dem HERRN zum Brandopfer darbringen wollen),');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'der opfere, damit es euch angenehm mache, ein tadelloses Männlein, von den Rindern, Lämmern oder Ziegen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Nichts Gebrechliches sollt ihr opfern; denn es würde euch nicht angenehm machen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wenn jemand dem HERRN ein Dankopfer bringen will, sei es zur Erfüllung eines Gelübdes oder als freiwillige Gabe, von Rindern oder Schafen, so soll es tadellos sein, zum Wohlgefallen. Es soll keinen Mangel haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ein Blindes oder Gebrochenes oder Verwundetes oder eines, das Geschwüre oder die Krätze oder Flechten hat, sollt ihr dem HERRN nicht opfern und davon kein Feueropfer bringen auf den Altar des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Einen Ochsen, oder ein Schaf, das zu lange oder zu kurze Glieder hat, magst du als freiwillige Gabe opfern, aber zur Erfüllung eines Gelübdes wäre es nicht angenehm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ihr sollt auch dem HERRN kein Tier darbringen, welches verschnittene oder zerdrückte oder abgerissene oder abgeschnittene Hoden hat, und sollt in eurem Lande solches gar nicht tun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Auch von der Hand eines Fremdlings sollt ihr deren keines eurem Gott zur Speise darbringen; denn sie haben eine Verstümmelung, einen Makel an sich; sie werden euch nicht gnädig aufgenommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Wenn ein Rind oder ein Lamm, oder eine Ziege geboren wird, so soll es sieben Tage lang bei seiner Mutter bleiben; erst vom achten Tag an ist es angenehm zum Feueropfer für den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ihr sollt aber kein Rind noch Schaf zugleich mit seinem Jungen am gleichen Tag schächten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Wenn ihr aber dem HERRN ein Lobopfer darbringen wollt, so opfert es zu eurer Begnadigung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Ihr sollt es am gleichen Tag essen und nichts übriglassen bis zum Morgen; ich bin der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Ihr aber sollt meine Gebote beobachten und sie tun; ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Und ihr sollt meinen heiligen Namen nicht entheiligen; sondern ich will geheiligt werden unter den Kindern Israel, ich, der HERR, der euch heiligt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'der ich euch aus dem Lande Ägypten geführt habe, um euer Gott zu sein, ich, der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Und der HERR redete zu Mose und sprach: Sage den Kindern Israel und sprich zu ihnen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Das sind die Feste des HERRN, da ihr heilige Festversammlungen einberufen sollt; das sind meine Feste:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage lang soll man arbeiten, aber am siebenten Tag ist die Sabbatfeier, eine heilige Versammlung; da sollt ihr kein Werk tun; denn es ist der Sabbat des HERRN, in allen euren Wohnorten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Das sind aber die Feste des HERRN, die heiligen Versammlungen, die ihr zu festgesetzten Zeiten einberufen sollt:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Am vierzehnten Tag des ersten Monats, gegen Abend, ist das Passah des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Und am fünfzehnten Tage desselben Monats ist das Fest der ungesäuerten Brote des HERRN. Da sollt ihr sieben Tage lang ungesäuertes Brot essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tag sollt ihr eine heilige Versammlung halten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'da sollt ihr keine Werktagsarbeit verrichten und ihr sollt dem HERRN sieben Tage lang Feueropfer darbringen. Am siebenten Tag ist heilige Versammlung, da sollt ihr keine Werktagsarbeit verrichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Sage den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land kommt, das ich euch geben werde, und seine Ernte einheimset, so sollt ihr die Erstlingsgarbe von eurer Ernte zum Priester bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Der soll die Garbe weben vor dem HERRN, zu eurer Begnadigung; am Tage nach dem Sabbat soll sie der Priester weben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Ihr sollt aber an dem Tage, wenn eure Garbe gewebt wird, dem HERRN ein Brandopfer zurichten von einem tadellosen einjährigen Lamm;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'dazu sein Speisopfer, zwei Zehntel Semmelmehl, mit Öl gemengt, ein Feueropfer dem HERRN zum lieblichen Geruch; samt seinem Trankopfer, einem Viertel Hin Wein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Ihr sollt aber weder Brot noch geröstetes Korn noch zerriebene Körner essen bis zu dem Tag, da ihr eurem Gott diese Gabe darbringt. Das ist eine ewig gültige Ordnung für alle eure Geschlechter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Darnach sollt ihr vom Tage nach dem Sabbat, von dem Tage, da ihr die Webegarbe darbringt, sieben volle Wochen abzählen bis zum Tag,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'der auf den siebenten Sabbat folgt, nämlich fünfzig Tage sollt ihr zählen, und alsdann dem HERRN ein neues Speisopfer darbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Ihr sollt nämlich aus euren Wohnsitzen zwei Webebrote bringen, von zwei Zehntel Semmelmehl zubereitet; die sollen gesäuert und dem HERRN zu Erstlingen gebacken werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Zu dem Brot aber sollt ihr sieben einjährige, tadellose Lämmer darbringen und einen jungen Farren und zwei Widder; das soll des HERRN Brandopfer sein; dazu ihr Speisopfer und ihr Trankopfer; ein Feueropfer, dem HERRN zum lieblichen Geruch.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ihr sollt auch einen Ziegenbock zum Sündopfer und zwei einjährige Lämmer zum Dankopfer zurichten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'und der Priester soll sie samt den Erstlingsbroten weben, nebst den beiden Lämmern, als Webopfer vor dem HERRN. Die sollen dem HERRN heilig sein und dem Priester gehören.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und ihr sollt an demselben Tag ausrufen lassen: »Man soll eine heilige Versammlung abhalten und keine Werktagsarbeit verrichten!« Das ist eine ewig gültige Satzung für alle eure Wohnorte und Geschlechter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Wenn ihr aber die Ernte eures Landes einbringt, so sollst du dein Feld nicht bis an den Rand abernten und nicht selbst Nachlese halten, sondern es dem Armen und Fremdling überlassen. Ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Rede mit den Kindern Israel und sprich: Am ersten Tag des siebenten Monats sollt ihr einen Feiertag halten, einen Gedächtnistag unter Posaunenklang, eine heilige Versammlung.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ihr sollt keine Werktagsarbeit verrichten, sondern dem HERRN Feueropfer darbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Am zehnten Tag in diesem siebenten Monat ist der Versöhnungstag, da sollt ihr eine heilige Versammlung halten und eure Seelen demütigen und dem HERRN Feueropfer darbringen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'und ihr sollt an diesem Tage keine Arbeit verrichten; denn es ist der Versöhnungstag, zu eurer Versöhnung vor dem HERRN, eurem Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Welche Seele sich aber an diesem Tage nicht demütigt, die soll ausgerottet werden aus ihrem Volk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'und welche Seele an diesem Tag irgend eine Arbeit verrichtet, die will ich vertilgen mitten aus ihrem Volk.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ihr sollt keine Arbeit verrichten. Das ist eine ewig gültige Ordnung für eure Geschlechter an allen euren Wohnorten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ihr sollt Sabbatruhe halten und eure Seelen demütigen. Am neunten Tage des Monats, am Abend, sollt ihr die Feier beginnen, und sie soll währen von einem Abend bis zum andern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Rede mit den Kindern Israel und sprich: Am fünfzehnten Tage des siebenten Monats soll dem HERRN das Laubhüttenfest gefeiert werden, sieben Tage lang.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tage ist heilige Versammlung; da sollt ihr keine Arbeit verrichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sieben Tage lang sollt ihr dem HERRN Feueropfer darbringen und am achten Tag eine heilige Versammlung halten und dem HERRN Feueropfer darbringen; es ist Festversammlung; da sollt ihr keine Arbeit verrichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Das sind die Feste des HERRN, da ihr heilige Versammlungen einberufen sollt, um dem HERRN Feueropfer, Brandopfer, Speisopfer, Schlachtopfer und Trankopfer darzubringen, ein jedes an seinem Tag');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'außer den Sabbaten des HERRN und außer euren Gaben, den gelobten und freiwilligen Gaben, die ihr dem HERRN gebet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'So sollt ihr nun am fünfzehnten Tage des siebenten Monats, wenn ihr den Ertrag des Landes eingebracht habt, das Fest des HERRN halten, sieben Tage lang; am ersten Tag ist Feiertag und am achten Tag ist auch Feiertag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Ihr sollt aber am ersten Tag Früchte nehmen von schönen Bäumen, Palmenzweige und Zweige von dichtbelaubten Bäumen und Bachweiden, und sieben Tage lang fröhlich sein vor dem HERRN, eurem Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Und sollt also dem HERRN das Fest halten, sieben Tage lang im Jahr. Das soll eine ewige Ordnung sein für eure Geschlechter, daß ihr im siebenten Monat also feiert.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sieben Tage lang sollt ihr in Laubhütten wohnen; alle Landeskinder in Israel sollen in Laubhütten wohnen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'damit eure Nachkommen wissen, wie ich die Kinder Israel in Hütten wohnen ließ, als ich sie aus Ägypten führte; ich, der Herr, euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Mose erklärte den Kindern Israel die Feiertage des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Und der HERR redete zu Mose und sprach: Gebiete den Kindern Israel,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'daß sie zu dir bringen lauteres Öl aus zerstossenen Oliven für den Leuchter, um beständig Licht zu unterhalten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Draußen vor dem Vorhang des Zeugnisses, in der Stiftshütte, soll es Aaron zurichten, daß es stets brenne vor dem HERRN, vom Abend bis zum Morgen; eine ewige Ordnung für eure Geschlechter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Auf dem reinen Leuchter soll er die Lampen zurichten, vor dem HERRN, beständig.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Und du sollst Semmelmehl nehmen und davon zwölf Kuchen backen; ein Kuchen soll aus zwei Zehnteln bestehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Du sollst sie in zwei Schichten von je sechs Stück auf den reinen Tisch legen vor den HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Du sollst auf jede Schicht reinen Weihrauch legen, damit dieser die Brote in Erinnerung bringe, wenn er verbrannt wird vor dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Jeden Sabbat soll er sie stets vor dem HERRN aufschichten als Gabe von den Kindern Israel, laut ewigem Bund.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Und sie sollen Aaron und seinen Söhnen gehören; die sollen sie essen an heiliger Stätte; denn das ist ein hochheiliger, ewig festgesetzter Anteil für ihn von den Feueropfern des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Es ging aber der Sohn eines israelitischen Weibes, der einen ägyptischen Vater hatte, unter den Kindern Israel aus und ein. Dieser Sohn des israelitischen Weibes und ein Israelite zankten im Lager miteinander.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Da lästerte der Sohn des israelitischen Weibes den Namen Gottes und fluchte. Darum brachte man ihn zu Mose. Seine Mutter aber hieß Selomit und war die Tochter Dibris, vom Stamme Dan.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Und sie behielten ihn in Haft, bis ihnen Bescheid würde durch den Mund des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Führe den Flucher vor das Lager hinaus und laß alle, die es gehört haben, ihre Hand auf sein Haupt stützen, und die ganze Gemeinde soll ihn steinigen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Und sage den Kindern Israel und sprich: Wer seinem Gott flucht, der soll seine Sünde tragen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'und wer den Namen des HERRN lästert, der soll unbedingt sterben! Die ganze Gemeinde soll ihn steinigen, er sei ein Fremdling oder ein Einheimischer; wenn er den Namen lästert, so soll er sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Auch wenn jemand einen Menschen erschlägt, so soll er unbedingt sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Wer aber ein Vieh erschlägt, der soll es bezahlen; Seele um Seele!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Bringt aber einer seinem Nächsten eine Verletzung bei, so soll man ihm tun, wie er getan hat:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch, Auge um Auge, Zahn um Zahn; die Verletzung, die er dem andern zugefügt hat, soll man ihm auch zufügen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'also daß, wer ein Vieh erschlägt, der soll es bezahlen; wer aber einen Menschen erschlägt, der soll sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Ihr sollt ein einheitliches Recht haben für Fremdlinge und Einheimische; denn ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Mose aber sagte solches den Kindern Israel; die führten den Flucher vor das Lager hinaus und steinigten ihn. Also taten die Kinder Israel, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Und der HERR redete zu Mose auf dem Berge Sinai und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land kommt, das ich euch geben werde, so soll das Land dem HERRN einen Sabbat feiern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre lang sollst du dein Feld besäen und sechs Jahre lang deine Reben beschneiden und ihre Früchte einsammeln.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Aber im siebenten Jahr soll das Land seinen Ruhesabbat haben, den Sabbat des HERRN, da du dein Feld nicht besäen, noch deine Reben beschneiden sollst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Auch was nach deiner Ernte von sich selber wächst, sollst du nicht ernten; und die Trauben deines unbeschnittenen Weinstocks sollst du nicht ablesen, weil es ein Sabbatjahr des Landes ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Und dieser Landessabbat soll euch Nahrung bringen, dir und deinen Knechten und deiner Magd, deinem Taglöhner, deinen Beisaßen und deinem Fremdling bei dir;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'deinem Vieh und den Tieren in deinem Lande soll sein ganzer Ertrag zur Speise dienen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Und du sollst dir sieben solche Sabbatjahre abzählen, daß siebenmal sieben Jahre gezählt werden, und die Zeit der sieben Sabbatjahre beträgt neunundvierzig Jahre.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Da sollst du den Schall der Posaune ertönen lassen am zehnten Tage des siebenten Monats; am Tage der Versöhnung sollt ihr den Schall durch euer ganzes Land ergehen lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Und ihr sollt das fünfzigste Jahr heiligen und sollt ein Freijahr ausrufen im Lande allen, die darin wohnen, denn es ist das Jubeljahr. Da soll ein jeder bei euch wieder zu seiner Habe und zu seinem Geschlecht kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Denn das fünfzigste ist das Jubeljahr. Ihr sollt nicht säen, auch nicht ernten, was von sich selber wächst, auch den unbeschnittenen Weinstock nicht ablesen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Denn das Jubeljahr soll unter euch heilig sein; vom Feld weg dürft ihr essen, was es trägt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In diesem Jubeljahr soll jedermann wieder zu seinem Besitztum kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Wenn du nun deinem Nächsten etwas verkaufst oder demselben etwas abkaufst, so soll keiner seinen Bruder übervorteilen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'sondern nach der Zahl der Jahre, nach dem Jubeljahr sollst du es von ihm kaufen; und nach der Zahl des jährlichen Ertrages soll er es dir verkaufen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Nach der Menge der Jahre sollst du den Kaufpreis steigern, und nach der geringen Anzahl der Jahre sollst du den Kaufpreis verringern; denn eine bestimmte Anzahl von Ernten verkauft er dir.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'So übervorteile nun keiner seinen Nächsten; sondern fürchte dich vor deinem Gott; denn ich, der HERR, bin euer Gott!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Darum haltet meine Satzungen und beobachtet meine Rechte, daß ihr sie tut; so sollst du sicher wohnen im Lande,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'und das Land soll euch seine Früchte geben, daß ihr genug zu essen habt und sicher darin wohnt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und wenn ihr sagen würdet: Was sollen wir im siebenten Jahre essen? Denn wir säen nicht und sammeln auch keine Früchte ein!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'so will ich im sechsten Jahr meinem Segen gebieten, daß es euch Früchte für drei Jahre liefern soll;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'daß, wenn ihr im achten Jahre säet, ihr noch von den alten Früchten esset bis in das neunte Jahr; daß ihr von dem Alten esset bis wieder neue Früchte kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Ihr sollt das Land nicht als unablöslich verkaufen; denn das Land ist mein, und ihr seid Fremdlinge und Beisaßen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Und ihr sollt im ganzen Lande eurer Besitzung die Wiedereinlösung des Landes zulassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Wenn dein Bruder verarmt und dir etwas von seiner Habe verkauft, so soll derjenige als Löser für ihn eintreten, der sein nächster Verwandter ist; derselbe soll lösen, was sein Bruder verkauft hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Wenn aber jemand keinen Löser hat, kann aber mit seiner Hand so viel zuwege bringen, als zur Wiedereinlösung nötig ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so soll er die Jahre, die seit dem Verkauf verflossen sind, abrechnen und für den Rest den Käufer entschädigen, damit er selbst wieder zu seiner Habe komme.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Vermag er ihn aber nicht zu entschädigen, so soll das, was er verkauft hat, in der Hand des Käufers bleiben bis zum Jubeljahr; alsdann soll es frei ausgehen, und er soll wieder zu seiner Habe kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Wer ein Wohnhaus verkauft innerhalb der Stadtmauern, der hat zur Wiedereinlösung Frist bis zur Vollendung des Verkaufsjahres. Ein Jahr lang besteht für ihn das Rückkaufsrecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wenn es aber nicht gelöst wird bis zum Ablauf eines vollen Jahres, so sollen der Käufer und seine Nachkommen dasselbe Haus innerhalb der Stadtmauern als unablöslich behalten; es soll im Jubeljahr nicht frei ausgehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Dagegen sind die Häuser in den Dörfern ohne Ringmauern dem Ackerland gleich zu rechnen; sie sind ablösbar und sollen im Jubeljahr frei ausgehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Was aber die Levitenstädte anbetrifft, die Häuser in den Städten ihres Besitztums, so haben die Leviten das ewige Einlösungsrecht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Und wenn jemand etwas von den Leviten erwirbt, so geht das verkaufte Haus in der Stadt seines Besitztums im Jubeljahr frei aus; denn die Häuser in den Städten der Leviten sind ihr Besitztum unter den Kindern Israel;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'und die Weideplätze bei ihren Städten dürfen nicht verkauft werden, denn sie sind ihr ewiges Eigentum.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Wenn dein Bruder verarmt neben dir und sich nicht mehr zu halten vermag, so sollst du ihm Hilfe leisten, er sei ein Fremdling oder Beisaße, daß er bei dir leben kann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du sollst keinen Zins noch Wucher von ihm nehmen, sondern sollst dich fürchten vor deinem Gott, daß dein Bruder neben dir leben könne.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du sollst ihm dein Geld nicht auf Zins, noch deine Speise um Wucherpreise geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ich, der HERR, bin euer Gott, der ich euch aus Ägyptenland geführt habe, daß ich euch das Land Kanaan gebe und euer Gott sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Wenn dein Bruder neben dir verarmt und dir sich selbst verkauft, sollst du ihn im Dienst nicht als einen leibeigenen Knecht halten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'als Taglöhner und Beisaße soll er bei dir gelten und dir bis zum Jubeljahr dienen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Alsdann soll er frei von dir ausgehen, und seine Kinder mit ihm, und soll wieder zu seinem Geschlecht und zu seiner Väter Habe kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn auch sie sind meine Knechte, die ich aus Ägyptenland geführt habe. Darum soll man sie nicht wie Sklaven verkaufen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du sollst nicht mit Strenge über ihn herrschen, sondern sollst dich fürchten vor deinem Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Willst du aber leibeigene Knechte und Mägde haben, so sollst du sie kaufen von den Heiden, die um euch her sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Ihr könnt sie auch kaufen von den Kindern der Beisaßen, die sich bei euch aufhalten, und von ihren Geschlechtern bei euch, die in eurem Lande geboren sind; dieselben sollt ihr zu eigen haben,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'und sollst sie vererben auf eure Kinder nach euch zum leibeigenen Besitz, daß sie euch ewiglich dienen. Aber über eure Brüder, die Kinder Israel, sollt ihr nicht, einer über den andern, mit Strenge herrschen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Wenn die Hand eines Fremdlings oder Beisaßen bei dir etwas erwirbt, und dein Bruder neben ihm verarmt und sich dem Fremdling, welcher ein Beisaße bei dir ist, oder einem Abkömmling von seinem Stamm verkauft,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so soll er, nachdem er sich verkauft hat, das Loskaufsrecht behalten; einer von seinen Brüdern soll ihn lösen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'oder sein Vetter oder seines Vetters Sohn mag ihn lösen, oder sonst sein nächster Blutsverwandter aus seinem Geschlecht kann ihn lösen; oder wenn seine Hand so viel erwirbt, so soll er sich selbst lösen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Er soll aber mit seinem Käufer rechnen von dem Jahr an, da er sich ihm verkauft hat, bis zum Jubeljahr. Und der Preis seines Verkaufs soll nach der Zahl der Jahre berechnet werden, und er soll diese Zeit wie ein Taglöhner bei ihm sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Sind noch viele Jahre übrig, so soll er dementsprechend von dem Kaufpreis als Lösegeld zurückerstatten;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'sind aber wenig Jahre übrig bis zum Jubeljahr, so soll er darauf Rücksicht nehmen; nach der Zahl der Jahre soll er sein Lösegeld bezahlen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Wie ein Taglöhner soll er Jahr für Jahr bei ihm sein; er aber soll nicht mit Strenge über ihn herrschen vor deinen Augen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Löst er sich aber nicht auf einem dieser Wege, so soll er im Jubeljahr frei ausgehen und seine Kinder mit ihm;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'denn die Kinder Israel sind mir dienstbar; sie sind meine Knechte, die ich aus Ägypten geführt habe, ich, der HERR, euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ihr sollt keine Götzen machen, keine gemeißelten Bilder, und sollt euch keine Säulen aufrichten, auch keine Steinbilder setzen in eurem Lande, daß ihr euch davor bücket; denn ich, der HERR, bin euer Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Beobachtet meine Sabbate und verehret mein Heiligtum; ich bin der HERR!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Werdet ihr nun in meinen Satzungen wandeln und meine Gebote befolgen und sie tun,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so will ich euch Regen geben zu seiner Zeit, und das Land soll sein Gewächs geben und die Bäume auf dem Felde ihre Früchte bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Und die Dreschzeit wird reichen bis zur Weinlese, und die Weinlese bis zur Saatzeit, und ihr werdet euch von eurem Brot satt essen und sollt sicher wohnen in eurem Lande.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Denn ich will Frieden geben im Lande, daß ihr schlafet und euch niemand erschrecke. Ich will die bösen Tiere aus eurem Lande vertreiben, und es soll kein Schwert über euer Land kommen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Ihr werdet eure Feinde jagen, daß sie vor euch her durchs Schwert fallen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Euer fünf werden hundert jagen, und euer hundert werden zehntausend jagen, und eure Feinde werden vor euch her durchs Schwert fallen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Und ich will mich zu euch wenden und euch wachsen und zunehmen lassen und meinen Bund mit euch aufrechthalten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Und ihr werdet von dem Vorjährigen essen und das Vorjährige wegen der Menge des Neuen hinwegtun.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ich will meine Wohnung unter euch haben, und meine Seele soll euch nicht verwerfen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'und ich will unter euch wandeln und euer Gott sein, und ihr sollt mein Volk sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich, der HERR, bin euer Gott, der ich euch aus Ägypten geführt habe, daß ihr nicht ihre Knechte sein solltet; und ich zerbrach die Stäbe eures Joches und ließ euch aufrecht gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Werdet ihr mir aber nicht folgen und nicht alle diese Gebote erfüllen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'und werdet ihr meine Satzungen verachten, und wird eure Seele gegen meine Rechte einen Widerwillen haben, daß ihr nicht alle meine Gebote tut, sondern meinen Bund brechet,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so will auch ich euch solches tun: Ich will euch heimsuchen mit Schrecken, Schwindsucht und Fieberhitze, davon die Augen matt werden und die Seele verschmachtet. Ihr werdet eure Saat vergeblich bestellen; denn eure Feinde sollen sie essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Und ich will mein Angesicht gegen euch richten, daß ihr vor euren Feinden geschlagen werdet; und die euch hassen, sollen über euch herrschen, und ihr werdet fliehen, wenn euch niemand jagt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Werdet ihr mir aber daraufhin noch nicht gehorchen, so will ich euch noch siebenmal ärger strafen um eurer Sünden willen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'daß ich euren harten Stolz breche. Ich will euren Himmel machen wie Eisen und eure Erde wie Erz,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'daß eure Mühe und Arbeit vergeblich aufgewendet sei, und euer Land sein Gewächs nicht gebe und die Bäume des Landes ihre Früchte nicht bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Setzet ihr mir aber noch weitern Widerstand entgegen und wollt mir nicht gehorchen, so will ich euch noch siebenmal mehr schlagen, entsprechend euren Sünden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Und ich will wilde Tiere unter euch senden, die sollen euch euer Kinder berauben und euer Vieh verderben und euer weniger machen, und eure Straßen sollen wüste werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Werdet ihr euch aber dadurch noch nicht züchtigen lassen, sondern mir trotzig begegnen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'so will auch ich euch trotzig begegnen und euch siebenfältig schlagen um eurer Sünden willen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Und ich will ein Racheschwert über euch kommen lassen, eine Bundesrache! Da werdet ihr euch in euren Städten sammeln; ich aber will Pestilenz unter euch senden und euch in eurer Feinde Hand geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Und ich werde euch den Stab des Brotes zerbrechen, daß zehn Weiber euer Brot in einem Ofen backen mögen, und man wird euch das Brot nach dem Gewicht zuteilen; und ihr werdet es essen, aber nicht satt werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Werdet ihr aber auch dadurch noch nicht zum Gehorsam gegen mich gebracht, sondern mir trotzig begegnen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so will ich auch euch mit grimmigem Trotz begegnen und euch siebenfältig strafen um eurer Sünden willen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'daß ihr eurer Söhne und Töchter Fleisch fressen müßt!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Und ich will eure Höhen vertilgen und eure Sonnensäulen abhauen und eure Leichname auf die Leichname eurer Götzen werfen, und meine Seele wird euch verabscheuen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Und ich will eure Städte öde machen und eure heiligen Städte verwüsten und euren lieblichen Geruch verabscheuen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Also will ich das Land wüste machen, daß eure Feinde, die darinnen wohnen werden, sich davor entsetzen sollen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber will ich unter die Heiden zerstreuen und das Schwert hinter euch her ausziehen, daß euer Land zur Wüste und eure Städte zu Ruinen werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alsdann wird das Land seine Sabbate genießen, solange es wüste liegt, und ihr in eurer Feinde Land seid. Ja alsdann wird das Land feiern und seine Sabbate genießen dürfen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Solange es wüste liegt, wird es feiern, weil es nicht feiern konnte an euren Sabbaten, als ihr darin wohntet.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Denen aber, die von euch übrigbleiben, will ich das Herz verzagt machen in ihrer Feinde Land, daß ein rauschendes Blatt sie jagen wird; und sie werden davonfliehen, als jage sie ein Schwert, und fallen, ohne daß sie jemand verfolgt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Und sie sollen übereinander fallen; wie vor dem Schwert, obschon sie niemand jagt; und ihr werdet euren Feinden nicht widerstehen können,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'sondern werdet unter den Heiden umkommen, und eurer Feinde Land wird euch fressen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Welche von euch aber übrigbleiben, die sollen ob ihrer Missetat verschmachten, in eurer Feinde Land; und ob der Missetat ihrer Väter sollen sie verschmachten wie sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Werden sie aber ihre und ihrer Väter Missetat bekennen samt ihrer Übertretung, womit sie sich an mir vergriffen haben und mir trotzig begegnet sind,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'weswegen auch ich ihnen widerstand und sie in ihrer Feinde Land brachte; und wird sich alsdann ihr unbeschnittenes Herz demütigen, so daß sie dann ihre Schuld büßen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'so will ich gedenken an meinen Bund mit Jakob und an meinen Bund mit Isaak und an meinen Bund mit Abraham, und will des Landes gedenken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Aber das Land wird von ihnen verlassen sein und seine Sabbate genießen, indem es um ihretwillen wüste liegt, und sie werden ihre Schuld büßen, darum und deswegen, weil sie meine Rechte verachtet und ihre Seele meine Satzungen verabscheut hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Jedoch, wenn sie gleich in der Feinde Land sein werden, so will ich sie nicht gar verwerfen und sie nicht also verabscheuen, daß ich sie gar aufreibe oder meinen Bund mit ihnen breche; denn ich, der HERR, bin ihr Gott.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Und ich will für sie an meinen ersten Bund gedenken, als ich sie aus Ägypten führte vor den Augen der Heiden, daß ich ihr Gott wäre, ich, der HERR.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Das sind die Satzungen, die Rechte und Gesetze, die der HERR auf dem Berge Sinai durch die Hand Moses gegeben hat, daß sie zwischen ihm und den Kindern Israel bestehen sollten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Und der HERR redete zu Mose und sprach: Rede mit den Kindern Israel und sprich zu ihnen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Wenn jemand dem HERRN ein besonderes Gelübde tut, wenn er nach deiner Schätzung Seelen gelobt,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'so sollst du sie also schätzen: Einen Mann, vom zwanzigsten bis zum sechzigsten Jahr sollst du schätzen auf fünfzig Schekel Silber, nach dem Schekel des Heiligtums.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Ist es aber ein Weib, so sollst du sie auf dreißig Schekel schätzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Im Alter von fünf bis zwanzig Jahren sollst du ihn schätzen auf zwanzig Schekel, wenn es ein Knabe ist, aber auf zehn Schekel, wenn es ein Mädchen ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Im Alter von einem Monat bis zu fünf Jahren sollst du ihn schätzen auf fünf Schekel Silber, wenn es ein Knabe ist, aber auf drei Schekel Silber, wenn es ein Mädchen ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Im Alter von sechzig aber und darüber sollst du ihn auf fünfzehn Schekel schätzen, wenn es ein Mann ist, auf zehn Schekel, wenn es ein Weib ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Vermag er aber nicht soviel zu bezahlen, wie du ihn schätzest, so soll er sich vor den Priester stellen, und der Priester soll ihn schätzen nach dem Vermögen dessen, der das Gelübde getan hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Ist es aber ein Vieh, von dem, was man dem HERRN opfern kann, so soll jedes Stück, das man von solchem Vieh dem HERRN gibt, heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Man soll es nicht auswechseln noch vertauschen, ein gutes für ein schlechtes oder ein schlechtes für ein gutes; sollte es aber jemand auswechseln, ein Vieh für das andere, so würde es samt dem zur Auswechslung bestimmten Stück dem HERRN heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ist aber das Tier unrein, daß man es dem HERRN nicht opfern darf, so soll man es vor den Priester stellen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'und der Priester soll es schätzen, je nachdem es gut oder schlecht ist; und bei der Schätzung des Priesters soll es bleiben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Will es aber jemand lösen, so soll er den fünften Teil deiner Schätzung dazugeben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Wenn jemand sein Haus dem HERRN zum Heiligtum weiht, so soll es der Priester schätzen, je nachdem es gut oder schlecht ist; und wie es der Priester schätzt, so soll es gelten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Will es aber derjenige lösen, der es geheiligt hat, so soll er den fünften Teil dazulegen; dann gehört es ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Wenn jemand dem HERRN ein Stück Feld von seinem Erbgut weiht, so soll es von dir geschätzt werden nach dem Maß der Aussaat; der Raum für die Aussaat von einem Homer Gerste soll fünfzig Schekel Silber gelten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Weiht er sein Feld vor dem Jubeljahr, so soll es nach deiner Schatzung gelten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Weiht er aber das Feld nach dem Jubeljahr, so soll der Priester den Betrag berechnen nach den übrigen Jahren bis zum nächsten Jubeljahr und es je nachdem geringer schätzen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Wenn aber der, welcher das Feld geweiht hat, es lösen will, so soll er den fünften Teil über die Schatzungssumme dazulegen, dann bleibt es sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Will er es aber nicht lösen, sondern verkauft es einem andern, so kann es nicht mehr gelöst werden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'sondern es soll dasselbige Feld, wenn es im Jubeljahr frei ausgeht, dem HERRN heilig sein, wie ein mit dem Bann belegtes Feld; es fällt dem Priester als Erbgut zu.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Wenn aber jemand dem HERRN ein Stück Feld weiht, das er gekauft hat und das nicht sein Erbgut ist,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so soll ihm der Priester den Betrag nach deiner Schatzung berechnen bis zum Jubeljahr, und er soll an demselben Tage den Schatzungswert geben, daß es dem HERRN geweiht sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Aber im Jubeljahr soll das Feld wieder an den Verkäufer zurückfallen, nämlich an den, welchem das Land als Erbteil gehört.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Alle deine Schätzung aber soll nach dem Schekel des Heiligtums geschehen. Ein Schekel macht zwanzig Gera.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Doch soll niemand die Erstgeburt unter dem Vieh weihen, die dem HERRN schon als Erstgeburt gehört, es sei ein Ochs oder Schaf; es ist des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Ist es aber ein unreines Vieh, so soll man es lösen nach deiner Schätzung und den fünften Teil darüber geben. Will man es nicht lösen, so soll es nach deiner Schätzung verkauft werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Nur soll man kein mit dem Bann Belegtes verkaufen oder lösen, nichts, das jemand dem HERRN gebannt, von allem, was sein ist, es seien Menschen, Vieh oder Äcker seines Besitztums; denn alles Gebannte ist dem HERRN hochheilig!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Man soll auch keinen mit dem Bann belegten Menschen lösen, sondern er soll unbedingt sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Alle Zehnten des Landes, sowohl von der Saat des Landes als auch von den Früchten der Bäume, gehören dem HERRN und sollen dem HERRN heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Will aber jemand etwas von seinem Zehnten lösen, der soll den fünften Teil darübergeben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Und alle Zehnten von Rindern und Schafen, von allem, was unter dem Hirtenstab hindurchgeht, soll jedes zehnte Stück dem HERRN heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man soll nicht untersuchen, ob es gut oder schlecht sei, man soll es auch nicht auswechseln; sollte es aber jemand auswechseln, so würde es samt dem zur Auswechslung bestimmten Stück heilig sein und könnte nicht gelöst werden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Das sind die Gebote, die der HERR Mose befohlen hat an die Kinder Israel, auf dem Berge Sinai.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und der HERR redete mit Mose in der Wüste Sinai in der Stiftshütte am ersten Tag des zweiten Monats im zweiten Jahr, nachdem sie aus dem Lande Ägypten gezogen waren, und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Ermittelt die Zahl der ganzen Gemeinde der Kinder Israel, nach ihren Geschlechtern und ihren Vaterhäusern, nach der Zahl der Namen, alles, was männlich ist, Kopf für Kopf;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'von zwanzig Jahren an und darüber, alle wehrpflichtigen Männer in Israel; und zählet sie nach ihren Heerhaufen, du und Aaron.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Und es soll von jedem Stamm das Oberhaupt der Vaterhäuser seines Stammes bei euch sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Das sind aber die Namen der Männer, die euch zur Seite stehen sollen: Von Ruben Elizur, der Sohn Sedeurs;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'von Simeon Selumiel, der Sohn Zuri-Schaddais;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'von Juda Nahasson, der Sohn Amminadabs;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'von Issaschar Netaneel, der Sohn Zuars;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'von Sebulon Eliab, der Sohn Helons;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'von den Kindern Josephs, von Ephraim Elisama, der Sohn Ammihuds; von Manasse Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'von Benjamin Abidan, der Sohn Gideonis;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'von Dan Ahieser, der Sohn Ammi-Schaddais;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'von Asser Pagiel, der Sohn Ochrans;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'von Gad Eliasaph, der Sohn Deguels;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'von Naphtali Ahira, der Sohn Enans.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Das sind die Berufenen der Gemeinde, die Fürsten unter den Stämmen ihrer Väter; die Häupter über die Tausende Israels sind diese.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Und Mose und Aaron nahmen diese Männer, die mit Namen bezeichnet sind,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'und versammelten die ganze Gemeinde am ersten Tag des zweiten Monats, und sie ließen sich eintragen in die Geburtsregister, nach ihren Geschlechtern und ihren Vaterhäusern, unter Aufzählung der Namen, von zwanzig Jahren an und darüber, nach der Kopfzahl.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Wie der HERR Mose geboten hatte, so zählte er sie in der Wüste Sinai.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Und es waren der Kinder Ruben, des erstgeborenen Sohnes Israels, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern an Zahl der Namen, Haupt für Haupt, alle diensttauglichen Männer, von zwanzig Jahren und darüber,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'so viele ihrer gemustert wurden vom Stamm Ruben, 46500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Der Kinder Simeon, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, Haupt für Haupt, alle diensttauglichen Männer, von zwanzig Jahren und darüber,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'so viele ihrer vom Stamme Simeon gemustert wurden, 59300.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Der Kinder Gad, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'so viele ihrer vom Stamme Gad gemustert wurden, 45650.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Der Kinder Juda, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'so viele ihrer vom Stamme Juda gemustert wurden, 74600.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Der Kinder Issaschar, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'so viele ihrer vom Stamme Issaschar gemustert wurden, 54400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Der Kinder Sebulon, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an der Zahl, von zwanzig Jahren und darüber, was diensttauglich war;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'so viele ihrer vom Stamme Sebulon gemustert wurden, 57400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Der Kinder Joseph, nämlich von den Kindern Ephraim, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'so viele ihrer vom Stamme Ephraim gemustert wurden, 40500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Der Kinder Manasse, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'so viele ihrer vom Stamme Manasse gemustert wurden, 32200.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Der Kinder Benjamin, nach ihrer Abstammung, ihren Geschlechtern und Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'so viele ihrer vom Stamm Benjamin gemustert wurden, 35400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Der Kinder Dan, nach ihrer Abstammung, ihren Geschlechtern und Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'so viele ihrer vom Stamme Dan gemustert wurden, 62700.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Der Kinder Asser, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'so viele ihrer vom Stamme Asser gemustert wurden, 41500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Der Kinder Naphtali, nach ihrer Abstammung, ihren Geschlechtern und ihren Vaterhäusern, an Zahl der Namen, von zwanzig Jahren und darüber, was diensttauglich war,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'so viele ihrer vom Stamme Naphtali gemustert wurden, 53400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Das sind die Gemusterten, welche Mose und Aaron musterten samt den zwölf Fürsten Israels, deren je einer über die Vaterhäuser seines Stammes gesetzt war.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Alle Gemusterten aber der Kinder Israel, nach den Häusern ihrer Väter, von zwanzig Jahren und darüber, was unter Israel diensttauglich war, derer waren 603550.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Aber die Leviten mit ihrem väterlichen Stamm');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'waren in dieser Musterung nicht inbegriffen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Denn der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Nur den Stamm Levi sollst du nicht mustern und seine Zahl nicht rechnen unter die Kinder Israel;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'sondern du sollst die Leviten über die Wohnung des Zeugnisses setzen und über alle ihre Geräte und über alles, was dazu gehört. Sie sollen die Wohnung tragen samt allen ihren Geräten und sollen sie bedienen und sich um die Wohnung her lagern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Und wenn die Wohnung aufbricht, so sollen die Leviten sie abbrechen; wenn aber die Wohnung sich lagern soll, so sollen sie dieselbe aufschlagen; kommt ihr aber ein Fremder zu nahe, so muß er sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Die Kinder Israel sollen sich lagern, ein jeder in seinem Lager und bei dem Panier seines Heers.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Aber die Leviten sollen sich um die Wohnung des Zeugnisses her lagern, daß nicht ein Zorngericht über die Gemeinde der Kinder Israel komme; darum sollen die Leviten der Wohnung des Zeugnisses warten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Und die Kinder Israel taten so alles; was der HERR Mose geboten hatte, das taten sie.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Und der HERR redete zu Mose und Aaron und sprach: Die Kinder Israel sollen sich lagern,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'ein jeder bei seinem Panier und bei den Abzeichen ihrer Vaterhäuser; ringsum, der Stiftshütte gegenüber, sollen sie sich lagern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Gegen Morgen soll sich lagern das Panier des Lagers von Juda, nach seinen Heeren und der Fürst der Kinder Juda, Nahasson, der Sohn Amminadabs;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'samt seinem Heer und ihren Gemusterten, 74600.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Neben ihm soll sich lagern der Stamm Issaschar; ihr Fürst Netaneel der Sohn Zuars,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'samt seinem Heer und ihren Gemusterten, 54400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Dazu der Stamm Sebulon; ihr Fürst Eliab, der Sohn Helons,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'samt seinem Heer und ihren Gemusterten, 57400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle, die zum Lager Judas gezählt werden, sind 186400, nach ihren Heerscharen geordnet; sie sollen voranziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Gegen Mittag soll liegen das Panier Rubens mit seinem Heer; ihr Fürst Elizur, der Sohn Sedeurs,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'samt seinem Heer und seinen Gemusterten, 46500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Neben ihm soll sich lagern der Stamm Simeon; ihr Fürst Selumiel, der Sohn Zuri-Schaddais,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'samt seinem Heer und seinen Gemusterten, 59300.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Dazu der Stamm Gad; ihr Fürst Eliphas, der Sohn Reguels,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'samt seinem Heer und seinen Gemusterten, 45650.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle, die zum Lager Rubens gezählt werden, sind 151450, nach ihren Heerscharen geordnet. Diese sollen in zweiter Linie ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Darnach soll die Stiftshütte ziehen mit den Lagern der Leviten, mitten unter den Lagern; wie sie sich lagern, also sollen sie auch ziehen, ein jeglicher auf seiner Seite, bei seinem Panier.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Gegen Abend soll liegen das Panier Ephraims mit seinem Heer; ihr Fürst Elischama, der Sohn Ammihuds,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'samt seinem Heer und seinen Gemusterten, 40500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Neben ihm soll sich lagern der Stamm Manasse; ihr Fürst Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'samt seinem Heer und seinen Gemusterten, 32200.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Dazu der Stamm Benjamin; ihr Fürst Abidan, der Sohn Gideonis,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'samt seinem Heer und seinen Gemusterten, 35400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle, die zum Lager Ephraims gezählt werden, sind 108100, nach ihren Heerscharen geordnet. Diese sollen in dritter Linie ziehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Gegen Mitternacht soll liegen das Panier des Lagers von Dan mit seinem Heer; ihr Fürst Ahieser, der Sohn Ammi-Schaddais,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'samt seinem Heer und seinen Gemusterten, 62700.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Neben ihm soll sich lagern der Stamm Asser; ihr Fürst Pagiel, der Sohn Ochrans,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'samt seinem Heer und seinen Gemusterten, 41500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Dazu der Stamm Naphtali, ihr Fürst Ahira, der Sohn Enans,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'samt seinem Heer und seinen Gemusterten, 53400.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle, die zum Lager Dans gezählt werden, sind 157000. Sie sollen die letzten im Zuge sein mit ihren Panieren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Das sind die Gemusterten der Kinder Israel, eingeteilt nach ihren Vaterhäusern und ihren Heerlagern, 603550.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Aber die Leviten wurden nicht mit den Kindern Israel gemustert, wie der Herr Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Und die Kinder Israel taten alles, wie der HERR Mose geboten hatte; sie lagerten sich nach ihren Panieren, und zogen aus, ein jeder in seinem Geschlecht, bei seinem Vaterhaus.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Dies ist das Geschlecht Aarons und Moses, an dem Tag, als der HERR mit Mose redete auf dem Berge Sinai.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Und dies sind die Namen der Söhne Aarons: Der Erstgeborene Nadab, darnach Abihu, Eleasar und Itamar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Das sind die Namen der Söhne Aarons, der gesalbten Priester, denen man die Hände füllte zum Priesterdienst.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Aber Nadab und Abihu starben vor dem HERRN, als sie fremdes Feuer vor den HERRN brachten, in der Wüste Sinai, und sie hatten keine Söhne. Eleasar aber und Itamar taten Priesterdienst vor den Augen ihres Vaters Aaron.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Bring den Stamm Levi herzu, und stelle sie vor Aaron, den Priester, daß sie ihm dienen und besorgen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'was für ihn und für die ganze Gemeinde zu besorgen ist, vor der Stiftshütte, und so den Dienst an der Wohnung versehen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'daß sie alle Geräte der Stiftshütte hüten und der Hut der Kinder Israel warten, den Dienst an der Wohnung versehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Und du sollst die Leviten Aaron und seinen Söhnen zum Geschenk machen; geschenkt sind sie ihm von seiten der Kinder Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aber Aaron und seine Söhne sollst du beauftragen, ihres Priestertums zu warten. Wenn sich ein Fremder naht, so muß er sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Siehe, ich habe die Leviten unter den Kindern Israel genommen an Stelle aller Erstgeborenen unter den Kindern Israel, also daß die Leviten mein sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn alle Erstgeburt ist mein; an dem Tag, da ich alle Erstgeburt in Ägypten schlug, heiligte ich mir alle Erstgeburt in Israel, von den Menschen an bis auf das Vieh, daß sie mein sein sollen, mir, dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und der HERR redete zu Mose in der Wüste Sinai und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Mustere die Kinder Levis nach ihren Vaterhäusern und Geschlechtern, alles, was männlich ist, einen Monat alt und darüber!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Also musterte sie Mose nach dem Wort des HERRN, wie er geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und dies sind die Kinder Levis mit ihren Namen: Gerson, Kahat und Merari.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Die Namen aber der Kinder Gersons nach ihren Geschlechtern sind Libni und Simei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Die Kinder Kahats nach ihren Geschlechtern sind Amram, Jizhar, Hebron und Ussiel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Die Kinder Meraris nach ihren Geschlechtern sind Machli und Muschi. Das sind die Geschlechter Levis nach ihren Vaterhäusern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Von Gerson stammt das Geschlecht der Libniter und Simeiter. Das sind die Geschlechter der Gersoniter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Die Zahl ihrer Gemusterten männlichen Geschlechts, von einem Monat und darüber, betrug 7500.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Das Geschlecht der Gersoniter soll sich hinter der Wohnung gegen Abend lagern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Und der Fürst des Vaterhauses der Gersoniter sei Eliasaph, der Sohn Laels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Was aber die Kinder Gerson an der Stiftshütte zu besorgen haben, das ist die Wohnung und das Zelt, seine Decke, und den Vorhang in der Tür der Stiftshütte,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'und die Vorhänge am Vorhof, und den Vorhang in der Tür des Vorhofs, welcher rings um die Wohnung und um den Altar her ist, dazu die Zeltstricke und alles, was zu ihrem Dienst gehört.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Von Kahat stammt das Geschlecht der Amramiter, der Jizhariter, der Hebroniter und Ussieliter. Das sind die Geschlechter der Kahaliter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Was männlich war, einen Monat alt und darüber, belief sich an der Zahl auf 8600, die das Heiligtum besorgten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Geschlechter der Kinder Kahats sollen sich lagern an die Seite der Wohnung gegen Mittag.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Und der Fürst des Stammhauses der Kahatiter sei Elizaphan, der Sohn Ussiels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Und sie sollen warten der Lade, des Tisches, des Leuchters, der Altäre und der Geräte des Heiligtums, mit welchen sie dienen, auch des Vorhangs, und was zu diesem Dienst gehört.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Aber der oberste Fürst der Leviten soll sein Eleasar, der Sohn Aarons, des Priesters, mit der Aufsicht über die, welche des Heiligtums warten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Von Merari stammt das Geschlecht der Machliter und Muschiter. Das sind die Geschlechter der Merariter.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Die Zahl ihrer Gemusterten von allem, was männlich war, einen Monat alt und darüber, betrug 6200.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Und der Oberste des Stammhauses der Merariter sei Zuriel, der Sohn Abichails; und sie sollen sich lagern an der Seite der Wohnung gegen Mitternacht.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Und das Hüteramt der Merariter soll sein, zu warten der Bretter und Riegel und Säulen und der Füße der Wohnung, und aller ihrer Geräte und ihres ganzen Dienstes,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'dazu der Säulen um den Vorhof her, mit ihren Füßen und Nägeln und Seilen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Aber vor der Wohnung, vor der Stiftshütte, gegen Morgen, sollen sich lagern Mose und Aaron und seine Söhne, die Besorgung des Heiligtums zu überwachen, zur Bewahrung der Kinder Israel. Wenn ein Fremder naht, so muß er sterben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle gemusterten Leviten, welche Mose und Aaron musterten nach ihren Geschlechtern, nach dem Wort des Herrn, alles, was männlich war, einen Monat alt und darüber, derer waren 22000.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und der HERR sprach zu Mose: Mustere alle männliche Erstgeburt der Kinder Israel, von einem Monat an und darüber und zähle ihre Namen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Und du sollst die Leviten mir, dem HERRN, nehmen, an Stelle aller Erstgeburt unter den Kindern Israel, und der Leviten Vieh an Stelle aller Erstgeburt unter dem Vieh der Kinder Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Und Mose musterte, wie der HERR ihm geboten hatte, alle Erstgeburt unter den Kindern Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Da belief sich die Zahl der Namen aller männlichen Erstgeborenen von einem Monat an und darüber, auf 22273.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Nimm die Leviten für alle Erstgeburt unter den Kindern Israel, und das Vieh der Leviten für ihr Vieh, daß die Leviten mein seien, mir, dem HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Aber als Lösegeld für die 273 überzähligen Erstgeborenen der Kinder Israel über der Leviten Zahl,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'sollst du je fünf Schekel erheben für jeden Kopf, und zwar sollst du es erheben nach dem Schekel des Heiligtums (ein Schekel macht zwanzig Gera);');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'und du sollst dieses Geld als Lösegeld der Überzähligen Aaron und seinen Söhnen geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Da nahm Mose das Lösegeld von denen, die die Zahl der durch die Leviten Gelösten überstieg;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'von den Erstgeborenen der Kinder Israel erhob er 1365 Schekel, nach dem Schekel des Heiligtums.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Und Mose gab das Geld Aaron und seinen Söhnen, nach dem Wort des HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Und der HERR redete zu Mose und sprach: Stelle die Gesamtzahl der Kinder Kahat unter den Leviten fest,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'nach ihren Geschlechtern, nach ihren Vaterhäusern,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'von dreißig Jahren an und darüber, bis in das fünfzigste Jahr, alle Diensttauglichen für das Werk an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Das soll aber der Dienst der Kinder Kahat an der Stiftshütte sein: das Allerheiligste.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Wenn das Heer aufbricht, so sollen Aaron und seine Söhne hineingehen und den Vorhang abnehmen und die Lade des Zeugnisses damit bedecken,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'und sollen eine Decke von Seehundsfellen darauf tun und oben darüber ein Tuch von ganz blauem Purpur breiten und die Stangen einstecken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Auch über den Schaubrottisch sollen sie ein Tuch von blauem Purpur breiten und darauf setzen die Schüsseln, die Kellen, die Opferschalen und die Trankopferkannen; auch soll das beständige Brot darauf liegen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Und sie sollen ein Tuch von Karmesinfarbe darüber breiten und dasselbe mit einer Decke von Seehundsfellen bedecken und seine Stangen einstecken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Sie sollen auch ein Tuch von blauem Purpur nehmen und damit den Licht spendenden Leuchter bedecken und seine Lampen, samt seinen Lichtscheren und Löschnäpflein und allen Ölgeschirren, mit welchen er bedient wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Und sollen um alle diese Geräte eine Decke von Seehundsfellen tun und es auf ein Gestell legen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Also sollen sie auch über den goldenen Altar ein Tuch von blauem Purpur breiten, und ihn mit einer Decke von Seehundsfellen bedecken und seine Stangen einstecken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Alle Geräte des Dienstes, womit man im Heiligtum dient, sollen sie nehmen und ein Tuch von blauem Purpur darüber tun und sie mit einer Decke von Seehundsfellen decken und auf ein Gestell legen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Sie sollen auch den Altar von der Asche reinigen, und ein Tuch von rotem Purpur darüber breiten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Alle seine Geräte, womit sie auf demselben dienen, sollen sie darauf legen, Kohlenpfannen, Gabeln, Schaufeln und Sprengbecken, samt allen Geräten des Altars, und sollen eine Decke von Seehundsfellen darüber breiten und seine Stangen einstecken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Wen nun Aaron und seine Söhne solches ausgerichtet und das Heiligtum und alle seine Geräte bedeckt haben, und wenn das Heer aufbricht, dann sollen die Kinder Kahat hineingehen, um es zu tragen; und sie sollen das Heiligtum nicht anrühren, sonst würden sie sterben. Das ist die Arbeit der Kinder Kahat an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleasar aber, der Sohn Aarons, soll die Aufsicht haben über das Öl für den Leuchter, und über die Spezerei zum Räucherwerk, und über das beständige Speisopfer und das Salböl, dazu die Aufsicht über die ganze Wohnung und alles, was darin ist, über das Heiligtum und seine Geräte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und der HERR redete zu Mose und Aaron und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ihr sollt dafür sorgen, daß der Stamm des Geschlechts der Kahatiter nicht ausgerottet werde unter den Leviten!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Darum sollt ihr solches mit ihnen tun, damit sie leben und nicht sterben, wenn sie sich dem Allerheiligsten nahen: Aaron und seine Söhne sollen hineingehen und einem jeden seine Arbeit und seine Last anweisen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Jene aber sollen nicht hineingehen, um auch nur einen Augenblick das Heiligtum anzusehen, sonst würden sie sterben!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Stelle die Gesamtzahl der Kinder Gerson fest, nach ihren Vaterhäusern, nach ihren Familien;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'von dreißig Jahren an und darüber, bis zum fünfzigsten Jahr sollst du sie zählen, alle Diensttauglichen zur Arbeit an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Das soll aber das Amt des Geschlechts der Gersoniter sein, wo sie dienen und was sie tragen sollen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Sie sollen die Teppiche der Wohnung und die Stiftshütte tragen, ihre Decken und die Decke von Seehundsfellen, die oben darüber ist und den Vorhang in der Tür der Stiftshütte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'auch die Vorhänge des Vorhofs und den Vorhang der Tür des Tors am Vorhof, rings um die Wohnung und den Altar her, auch ihre Seile und ihre Dienstgeräte, samt allem, womit gearbeitet wird; das sollen sie besorgen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach dem Befehl Aarons und seiner Söhne soll der ganze Dienst der Gersoniter geschehen, alles, was sie zu tragen und was sie zu verrichten haben; ihr sollt ihnen alle ihre Aufgaben pünktlich anweisen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Das ist der Dienst des Geschlechts der Gersoniter in der Stiftshütte und was sie unter der Hand Itamars, des Sohnes Aarons, des Priesters zu besorgen haben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Auch die Kinder Merari sollst du mustern, nach ihrem Vaterhaus und ihren Familien.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Von dreißig Jahren an und darüber, bis ins fünfzigste Jahr sollst du sie zählen, alle Diensttauglichen zur Arbeit an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Ihre Aufgabe im Dienste der Stiftshütte ist, die Bretter der Wohnung, ihre Riegel, Säulen und Füße zu tragen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'dazu die Säulen des Vorhofs und ihre Füße, die Nägel und Seile, samt allen ihren Geräten und aller Zubehörde; ihr sollt ihnen die Geräte, die sie zu tragen haben, mit Namen nennen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Das ist der Dienst des Geschlechts der Kinder Merari, alles, was sie an der Stiftshütte zu besorgen haben unter der Hand Itamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Mose und Aaron samt den Fürsten der Gemeinde musterten die Kahatiter nach ihrem Vaterhaus und ihren Geschlechtern,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'von dreißig Jahren an und darüber, bis ins fünfzigste, alle Diensttauglichen zur Arbeit an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Und ihre Musterung nach ihren Geschlechtern ergab 2750.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das sind die Gemusterten des Geschlechts der Kahatiter, alle die, welche Dienst tun konnten an der Stiftshütte, welche Mose und Aaron musterten nach dem Wort des HERRN durch Mose.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Die Kinder Gerson wurden auch gemustert nach ihrem Vaterhaus und ihren Familien,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'von dreißig Jahren an und darüber, bis ins fünfzigste, alle Diensttauglichen für die Arbeit an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Und ihre Musterung nach ihrem Vaterhaus und Geschlecht ergab 2630.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Das sind die Gemusterten des Geschlechts der Kinder Gerson, welche tauglich waren für den Dienst an der Stiftshütte, welche Mose und Aaron musterten nach dem Wort des HERRN.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Die Kinder Merari wurden auch gemustert nach ihrem Vaterhaus und ihren Geschlechtern,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'von dreißig Jahren an und darüber, bis in das fünfzigste, alle Diensttauglichen zur Arbeit an der Stiftshütte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Und die Musterung nach ihren Geschlechtern ergab 3200.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das sind die Gemusterten des Geschlechts der Kinder Merari, welche Mose und Aaron einstellten nach dem Wort des HERRN durch Mose.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Alle Gemusterten, welche eingestellt wurden, als Mose und Aaron samt den Fürsten Israels die Leviten zählten nach ihren Geschlechtern und Vaterhäusern,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'von dreißig Jahren an und darüber, bis ins fünfzigste, alle, die da kamen zur Verrichtung irgend eines Dienstes oder um eine Last zu tragen an der Stiftshütte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'alle Gemusterten zählten 8580.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Nach dem Worte des HERRN bestellte man sie durch Mose, einen jeden zu seinem Dienst und zu seiner Last und an sein Amt, wie der HERR Mose geboten hatte.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Und der HERR redete zu Mose und sprach: Gebiete den Kindern Israel,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'daß sie aus dem Lager alle Aussätzigen wegschicken, und alle, die Eiterflüsse haben, und die an einem Toten unrein geworden sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Männer und Weiber sollt ihr vor das Lager hinausschicken, daß sie ihr Lager nicht verunreinigen, weil ich unter ihnen wohne.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Kinder Israel taten also und schickten sie vor das Lager hinaus; wie der HERR zu Mose gesagt hatte, also taten die Kinder Israel.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und der HERR redete zu Mose und sprach: Sage den Kindern Israel:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Wenn ein Mann oder ein Weib irgend eine menschliche Sünde tut und sich damit am HERRN vergeht und die betreffende Seele eine Schuld auf sich lädt;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'so sollen sie ihre Sünde bekennen, die sie getan haben, und sollen ihre Schuld in ihrem vollen Betrag wiedererstatten, und den fünften Teil dazufügen und es dem geben, dem sie es schuldig sind.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Ist aber kein nächster Blutsverwandter da, dem man die Schuld erstatten kann, so fällt die dem HERRN zu erstattende Schuld dem Priester zu, außer dem Widder der Versühnung, mit dem ihm Sühne erwirkt wird.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Desgleichen soll alles Hebopfer von allem, was die Kinder Israel heiligen und dem Priester bringen, ihm gehören;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'und was jemand heiligt, das soll ihm gehören; gibt jemand dem Priester etwas, so gehört es ihm.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Sage den Kindern Israel und sprich zu ihnen: Wenn jemandes Weib sich verginge und ihm untreu würde, und jemand sie beschliefe,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'und es bliebe vor den Augen ihres Mannes verborgen und versteckt, daß sie unrein geworden, und es wäre kein Zeuge vorhanden wider sie, sie wäre auch nicht ertappt worden;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'und es käme über ihn ein Geist der Eifersucht, daß er um sein Weib eiferte, weil sie unrein geworden ist (oder wenn der Eifersuchtsgeist über ihn käme, daß er um sein Weib eiferte, ob sie schon nicht unrein geworden ist)');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so soll der Mann sein Weib zum Priester führen und um ihretwillen ein Opfer für sie bringen, ein Zehntel Epha Gerstenmehl; er soll aber kein Öl darauf gießen, noch Weihrauch darauf tun; denn es ist ein Eiferopfer und ein Gedächtnisopfer, das die Schuld ins Gedächtnis ruft.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Und der Priester soll sie herzuführen und vor den HERRN stellen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Und der Priester soll heiliges Wasser nehmen in ein irdenes Geschirr und Staub vom Boden der Wohnung in das Wasser tun,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'und soll das Weib vor den HERRN stellen und ihr Haar auflösen und das Gedächtnisopfer, das ein Eiferopfer ist, auf ihre Hände legen. Und der Priester soll in seiner Hand das bittere, fluchbringende Wasser haben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'und er soll das Weib beschwören und zu ihr sagen: »Hat dich kein Mann beschlafen und hast du dich nicht vergangen und neben deinem Mann verunreinigt, so sollst du von diesem bitteren fluchbringenden Wasser unbeschädigt bleiben;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'bist du aber von deinem Mann abgewichen, und hast dich verunreinigt, indem dich jemand beschlafen hat außer deinem Mann;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'so soll der Priester in seinem Beschwörungsfluch zu dem Weibe sagen setze dich der HERR zum Fluch und zum Schwur unter deinem Volk, daß der HERR deine Hüfte schwinden und deinen Bauch anschwellen lasse!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'So gehe nun dieses fluchbringende Wasser in deinen Leib, daß dein Bauch anschwelle und deine Hüfte schwinde!« Und das Weib soll sagen: Amen, Amen!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Dann soll der Priester diese Flüche auf einen Zettel schreiben und mit dem bittern Wasser abwaschen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Und er soll dem Weibe von dem bittern, fluchbringenden Wasser zu trinken geben, daß das fluchbringende Wasser in sie eindringe und ihr bitter sei.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Darnach soll der Priester das Eiferopfer von ihrer Hand nehmen und zum Speisopfer weben vor dem HERRN und es zum Altar bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Und er soll eine Handvoll von dem Speisopfer nehmen, zum Gedächtnis, und es auf dem Altar verbrennen und darnach dem Weibe das Wasser zu trinken geben.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und wenn sie das Wasser getrunken hat, so wird, wenn sie unrein geworden ist und sich an ihrem Mann vergangen hat, das fluchbringende Wasser in sie eindringen und sie vergiften, so daß ihr Bauch anschwellen und ihre Hüfte schwinden wird, und das Weib wird unter ihrem Volk ein Fluch sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Ist aber das Weib nicht verunreinigt, sondern rein, so wird sie unbeschädigt bleiben, daß sie Samen empfangen kann.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Das ist das Eifergesetz: Wenn ein Weib neben ihrem Manne ausschweift und unrein wird,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'oder wenn der Geist der Eifersucht über einen Mann kommt, daß er um sein Weib eifert, so soll er sie vor den HERRN stellen, daß der Priester gänzlich mit ihr verfahre nach diesem Gesetz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Dann ist der Mann unschuldig; das Weib aber hat ihre Schuld zu tragen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Und der HERR redete mit Mose und sprach: Sage den Kindern Israel und sprich zu ihnen:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Wenn ein Mann oder ein Weib das besondere Gelübde eines Nasiräers tun will, um sich dem HERRN zu weihen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'so soll er sich des Weins und starken Getränkes enthalten; Essig von Wein und starkem Getränk soll er nicht trinken; er soll auch keinen Traubensaft trinken und darf weder grüne noch getrocknete Trauben essen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Solange seine Weihe währt, soll er nichts essen, was vom Weinstock gewonnen wird, weder Kern noch Hülse. Solange das Gelübde seiner Weihe währt, soll kein Schermesser auf sein Haupt kommen;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'bis die Zeit, die er dem HERRN geweiht hat, vergangen ist, soll er heilig sein; er soll das Haar auf seinem Haupt frei wachsen lassen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Während der ganzen Zeit, für welche er sich dem HERRN geweiht hat, soll er zu keinem Toten gehen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Er soll sich auch nicht verunreinigen an der Leiche seines Vaters, seiner Mutter, seines Bruders oder seiner Schwester; denn die Weihe seines Gottes ist auf seinem Haupt.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Während der ganzen Zeit seiner Weihe soll er dem HERRN heilig sein.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Und wenn jemand bei ihm unversehens und plötzlich stirbt und sein geweihtes Haupt verunreinigt wird, so soll er sein Haupt scheren am Tage seiner Reinigung; am siebenten Tage soll er es scheren.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Und am achten Tage soll er zwei Turteltauben oder zwei junge Tauben zum Priester, vor die Tür der Stiftshütte bringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Und der Priester soll die eine zum Sündopfer und die andere zum Brandopfer machen und ihm Sühne erwirken, weil er sich an einem Entseelten versündigt hat, und soll also sein Haupt an demselben Tage heiligen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'daß er dem HERRN die Tage seines Gelübdes halte, und er bringe ein einjähriges Lamm zum Schuldopfer. Aber die vorigen Tage fallen dahin, weil seine Weihe verunreinigt worden ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Und das ist das Gesetz des Nasiräers: Wenn die Zeit seines Gelübdes erfüllt ist, so soll man ihn vor die Tür der Stiftshütte führen,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'da soll er dem HERRN sein Opfer bringen, ein einjähriges, männliches, tadelloses Lamm zum Sündopfer, und einen tadellosen Widder zum Dankopfer,');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'und einen Korb mit ungesäuerten Kuchen von Semmelmehl, mit Öl gemengt, und ungesäuerte Fladen, mit Öl bestrichen, samt ihrem Speisopfer und ihren Trankopfern.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Und der Priester soll es vor den HERRN bringen und soll sein Sündopfer und sein Brandopfer zurichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Und er soll dem HERRN den Widder zum Dankopfer bereiten samt dem Korbe mit dem ungesäuerten Brot; auch soll der Priester sein Speisopfer und sein Trankopfer zurichten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Der Nasiräer aber soll sein geweihtes Haupt scheren vor der Tür der Stiftshütte, und soll sein geweihtes Haupthaar nehmen und es in das Feuer werfen, das unter dem Dankopfer ist.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Und der Priester soll von dem Widder die gekochte Vorderkeule nehmen und einen ungesäuerten Kuchen aus dem Korbe und einen ungesäuerten Fladen und soll es dem Nasiräer auf seine Hände legen, nachdem er sein geweihtes Haar abgeschoren hat.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Und der Priester soll es vor dem HERRN weben. Das ist dem Priester heilig, samt der Webebrust und der Hebekeule. Darnach mag der Nasiräer Wein trinken.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das ist das Gesetz für den Nasiräer, der ein Gelübde tut, und das Opfer, das er dem HERRN für seine Weihe darbringen soll, außer dem, das seine Hand sonst zu leisten vermag. Wie er gelobt hat, so soll er tun, nach seinem Weihegesetz.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Sage Aaron und seinen Söhnen und sprich: Also sollt ihr zu den Kindern Israel sagen, wenn ihr sie segnen wollt:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Der HERR segne dich und behüte dich!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Der HERR lasse dir sein Angesicht leuchten und sei dir gnädig!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Der HERR erhebe sein Angesicht auf dich und gebe dir Frieden!');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Also sollen sie meinen Namen auf die Kinder Israel legen, und ich will sie segnen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Es begab sich aber des Tages, da Mose die Wohnung völlig aufgerichtet und sie samt allen ihren Geräten gesalbt und geheiligt hatte, als er auch den Altar samt allen seinen Geräten gesalbt und geheiligt hatte;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da opferten die Fürsten Israels, die Häupter ihrer Vaterhäuser, jene Stammesfürsten, welche der Musterung vorstanden.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Sie brachten aber als ihre Opfergabe vor den HERRN: sechs bedeckte Wagen und zwölf Rinder, je einen Wagen von zwei Fürsten, und je ein Rind von jedem; die brachten sie vor der Wohnung dar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Und der HERR redete zu Mose und sprach:');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Nimm es von ihnen an, daß es verwendet werde zum Dienst an der Stiftshütte, und gib es den Leviten nach Bedürfnis ihres Dienstes.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Da nahm Mose die Wagen und Rinder und gab sie den Leviten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zwei Wagen und vier Rinder gab er den Kindern Gerson für ihren Dienst;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'und vier Wagen und acht Rinder gab er den Kindern Merari für ihren Dienst unter der Hand Itamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Aber den Kindern Kahat gab er nichts, weil sie den Dienst des Heiligtums auf sich hatten und auf ihren Schultern tragen mußten.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Und die Fürsten brachten das, was zur Einweihung des Altars dienen sollte am Tage, als er gesalbt ward; und sie brachten ihre Opfer herzu vor den Altar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Der HERR aber sprach zu Mose: Jeder Fürst soll an dem für ihn bestimmten Tag seine Opfergabe zur Einweihung des Altars darbringen.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Da brachte am ersten Tag seine Opfergabe herzu Nahasson, der Sohn Amminadabs, vom Stamme Juda.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Seine Opfergabe aber war: eine silberne Schüssel, hundertunddreißig Schekel schwer, ein silbernes Sprengbecken, siebzig Schekel schwer nach dem Schekel des Heiligtums; beide voll Semmelmehl, mit Öl gemengt, zum Speisopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'eine goldene Schale, zehn Schekel schwer, voll Räucherwerk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'ein junger Farre, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, und fünf einjährige Lämmer. Das war die Opfergabe Nahassons, des Sohnes Amminadabs.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage opferte Netaneel, der Sohn Zuars, der Fürst der Kinder Issaschar.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Er brachte als seine Opfergabe herzu: eine silberne Schüssel, hundertunddreißig Schekel schwer; ein silbernes Sprengbecken, siebzig Schekel schwer nach dem Schekel des Heiligtums; beide voll Semmelmehl, mit Öl gemengt, zum Speisopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'eine goldene Schale, zehn Schekel schwer, voll Räucherwerk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'und einen jungen Farren, einen Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'einen Ziegenbock zum Sündopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das ist das Opfer Netaneels, des Sohnes Zuars.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage opferte der Fürst der Kinder Sebulon, Eliab, der Sohn Helons.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Opfergabe war: eine silberne Schüssel, hundertunddreißig Schekel schwer; ein silbernes Sprengbecken, siebzig Schekel schwer nach dem Schekel des Heiligtums; beide voll Semmelmehl, mit Öl gemengt, zum Speisopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'eine goldene Schale, zehn Schekel schwer, voll Räucherwerk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'ein junger Farre, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das ist das Opfer Eliabs, des Sohnes Helons.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Am vierten Tage opferten der Fürst der Kinder Ruben, Elizur, der Sohn Sedeurs.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Seine Opfergabe war: eine silberne Schüssel, hundertunddreißig Schekel schwer; ein silbernes Sprengbecken, siebzig Schekel schwer nach dem Schekel des Heiligtums; beide voll Semmelmehl, mit Öl gemengt, zum Speisopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'eine goldene Schale, zehn Schekel schwer, voll Räucherwerk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'ein junger Farre, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das ist das Opfer Elizurs, des Sohnes Sedeurs.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Am fünften Tage opferte der Fürst der Kinder Simeon, Selumiel, der Sohn Zuri-Schaddais.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Seine Opfergabe war: eine silberne Schüssel, hundertunddreißig Schekel schwer; ein silbernes Sprengbecken, siebzig Schekel schwer nach dem Schekel des Heiligtums; beide voll Semmelmehl, mit Öl gemengt, zum Speisopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'eine Schale, zehn Schekel Goldes schwer, voll Räucherwerk;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'ein junger Farre, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das ist das Opfer Selumiels, des Sohnes Zuri-Schaddais.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Am sechsten Tage opferte der Fürst der Kinder Gad, Eliasaph, der Sohn Deguels.');
INSERT INTO `GerSch_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Seine Opfergabe war: eine silberne Schüssel, hundertunddreißig Schekel schwer; ein silbernes Sprengbecken, siebzig Schekel schwer nach dem Schekel des Heiligtums; beide voll Semmelmehl, mit Öl gemengt, zum Speisopfer;');
